ll modpow(int a, int b)
{
  if(b == 1)
    return a;
  else if(b % 2 == 0)
  {
    ll temp = modpow(a, b/2);
    return temp * temp % mod;
  }
  else
    return modpow(a, b-1) * a % mod;

}

int inv(int a) {
