int dfs(int cur, int pre)
{
  vector<int> vcounts;
  childs[cur] = 1;

  for(int i = 0; i < adj[cur].size(); i++)
    if(adj[cur][i] != pre)
    {
      vcounts.push_back(dfs(adj[cur][i], cur));
      childs[cur] += vcounts.back();
    }

  if(childs[cur] < n)
    vcounts.push_back(n-childs[cur]);

  ll p[3] = {(mod+1)/2, 0, 0};

  for(int i = 0; i < vcounts.size(); i++)
  {
    ll q[3] = {};
    int w = modpow((mod+1)/2, vcounts[i]);
    int b = (mod+1 - w) % mod;

    q[0] = (p[0] * w) % mod;
    q[1] = ((p[0] * b) % mod + (p[1] * w) % mod) % mod;
    q[2] = (p[2] + p[1] * b) % mod;

    swap(p, q);

    /*if(cur == 2)
