template <typename T>
T mod_expt(T a, std::int64_t n, T mod){
    T power {1};
    while(n > 0){
        if(n & 1){power = power * a % mod;}
        a = a * a % mod;
        n >>= 1;
    }
    return power;
}

constexpr ll MOD = 1'000'000'007;
constexpr ll HALF = 500'000'004;
int N;
std::vector<int> G[200100];
int size[200100];
std::vector<int> vec[200100];

void dfs(int v, int p){
    size[v] = 1;

    for(int w : G[v]){
        if(w == p){continue;}

        dfs(w, v);

        vec[v].emplace_back(size[w]);
        size[v] += size[w];
    }

    vec[v].emplace_back(N - size[v]);
}

int main(){
  std::cin.tie(nullptr);
  std::ios::sync_with_stdio(false);

  std::cin >> N;

  for(int i=0;i<N-1;++i){
      int a, b;
      std::cin >> a >> b;

      G[a].emplace_back(b);
      G[b].emplace_back(a);
  }

  dfs(1, -1);

  ll E = 0;

  for(int i=1;i<=N;++i){
      ll p = 0;
      p += mod_expt<ll>(2, N - 1, MOD);
      p += 1;
      for(int s : vec[i]){
          p += mod_expt<ll>(2, s, MOD) - 1;
      }
      p = (mod_expt<ll>(2, N, MOD) - p) % MOD;
      if(p < 0){p += MOD;}
      p = p * mod_expt<ll>(HALF, N, MOD) % MOD;
      E += p;
  }

  E %= MOD;

  std::cout << E << std::endl;
