long long const mod = 1000000007;

long long mod_pow(long long a, long long b){
    long long res = 1;
    a %= mod;
    while(b > 0){
        if(b%2 == 1) res = (res * a) % mod;
        a = (a * a) % mod;
        b /= 2;
    }
    return res;
}

long long mod_div(long long a){
    return mod_pow(a, mod-2);
}

vector< vector<int> > edg;
vector<int> cc, par;

int f(int v, int p){
    int res = 1;
    par[v] = p;
    for(int i=0;i<edg[v].size();i++){
        int w = edg[v][i];
        if(w == p) continue;
        res += f(w, v);
    }
    return cc[v] = res;
}

