    cc.assign(n, -1);
    par.assign(n, -1);
    f(0, -1);
    long long r2 = mod_div(2), pn = mod_pow(r2, n);
    for(int i=0;i<n;i++){
        long long res = r2 + mod - pn;
        if(edg[i].size() == 1) continue;
        if(i > 0){
            long long t = n-cc[i];
            res += mod - mod_pow(r2, n-t) + pn;
        }
        for(int j=0;j<edg[i].size();j++){
            if(edg[i][j] == par[i]) continue;
            long long t = cc[edg[i][j]];
            res += mod - mod_pow(r2, n-t) + pn;
        }
        ans += res % mod;
        ans %= mod;
    }
