    if(n & 1) ret = a * ret % MOD;
    a = a * a % MOD;
    n >>= 1;
  }

  return ret;
}
ll modminus(ll a, ll b) {
  ll ret = (a - b) % MOD;
  return (ret >= 0) ? ret : ret + MOD;
}

int dfs(int pos, int prev, std::vector<std::vector<int>> &from) {
  int ret = 1;
  for(auto b : from[pos]) {
    if(b == prev) {
      continue;
    }

    ret += dfs(b, pos, from);
  }

  return ret;
}

