long long modinv(long long a, long long mod) {
  long long b = mod, u = 1, v = 0;
  while (b) {
    long long t = a / b;
    a -= t * b; swap(a, b);
    u -= t * v; swap(u, v);
  }
  u %= mod;
  if (u < 0) u += mod;
  return u;
}

int dfs(Graph<int> &g, Graph<int> &child, int p, int v) {
  int ret = 1;
  for (auto nv : g[v]) {
    if (nv != p) {
      int tmp = dfs(g, child, v, nv);
      ret += tmp;
      child[v].push_back(tmp);
    }
  }
  int rem = g.size() - ret;
  if (rem) child[v].push_back(rem);
  return ret;
}

