  Graph<int> child(n);
  dfs(g, child, -1, 0);

  vi power(n+1);
  power[0] = 1;
  rep(i,n) power[i+1] = power[i] * 2 % MOD;

  int y = 0;
  rep(i,n) {
    if (child[i].size() == 1) continue;

    int cnt = 1;
    for (auto p : child[i]) {
      (cnt += power[p] - 1) %= MOD;
    }
    (y += power[n-1] - cnt + MOD) %= MOD;
  }

  int ans = modinv(power[n], MOD) * y % MOD;
  cout << ans << endl;
}


