}

#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
const int64 mod = 1000000007;

struct Combination {
	vector<int64_t> fact, rfact;
	Combination(int sz) : fact(sz + 1), rfact(sz + 1) {
		fact[0] = 1;
		for(int i = 1; i < fact.size(); i++){
			fact[i] = fact[i - 1] * i % mod;
		}
		rfact[sz] = inv(fact[sz]);
		for(int i = sz - 1; i >= 0; i--){
			rfact[i] = rfact[i + 1] * (i + 1) % mod;
		}
	}
	int64_t inv(int x) const {
		return pow(x, mod - 2);
	}
	int64_t pow(int64_t x, int64_t n) const {
		int64_t ret = 1;
		while(n > 0){
			if(n & 1) (ret *= x) %= mod;
			(x *= x) %= mod;
			n >>= 1;
		}
		return (ret);
	}
	int64_t P(int n, int r) const {
		if(r < 0 || n < r) return (0);
		return (fact[n] * rfact[n - r] % mod);
	}

	int64_t C(int p, int q) const {
		if(q < 0 || p < q) return (0);
		return (fact[p] * rfact[q] % mod * rfact[p - q] % mod);
	}

	int64_t H(int n, int r) const {
		if(n < 0 || r < 0) return (0);
		return (r == 0 ? 1 : C(n + r - 1, r));
	}
};

int64 n;
vector<int> G[200010];
Combination c(200010);
int64 ans = 0;

int dfs(int v, int p){
	int64 sz = 0;
	int64 pr = 0;
	for(auto u : G[v]){
		if(u == p) continue;
		int tmp = dfs(u, v);
		sz += tmp;
		pr += (c.pow(2, tmp) - 1 + mod) % mod * c.inv(c.pow(2, n - 1)) % mod;
		// cout << " " << v << " " << tmp << endl;
		ans %= mod;
	}
	int op = n - sz - 1;
	// cout << " " << v << " " << op << endl;
	if(op) pr += (c.pow(2, op) - 1 + mod) % mod * c.inv(c.pow(2, n - 1)) % mod;
	pr += c.inv(c.pow(2, n - 1));
	pr %= mod;
	ans += (1 - pr + mod) % mod * c.inv(2) % mod;
	ans %= mod; 
	// cout << v << ' ' << sz + 1 << endl;
	return sz + 1;
}

