const int MOD = 1e9 + 7;

int add(int a, int b) {
    int res = a + b;
    return res % MOD;
}

int sub(int a, int b) {
    int res = a - b;
    res %= MOD;
    res += MOD;
    return res % MOD;
}

int mul(int a, int b) {
    int res = a * b;
    return res % MOD;
}

int binpow(int a, int b) {
    int res = 1;
    while (b > 0) {
        if (b & 1) {
            res = mul(res, a);
        }
        a = mul(a, a);
        b /= 2;
    }
    return res;
}

int divv(int a, int b) {
    return mul(a, binpow(b, MOD - 2));
}

int n;

int solve(vector<int> soski) {
    if (soski.size() < 2) {
        return 0;
    }
    int none = 1;
    int one = 0;
    for (auto t : soski) {
        int other = 1;
        int we = sub(binpow(2, t), 1);
        one = add(one, mul(we, other));
    }
    return sub(binpow(2, n - 1), add(one, none));
}

