        if (t.adjList[i].size() == 1)
            continue;
        mint tmp = modpow(2, N - t.size[i]) - 1;
        for (auto [nxt, _] : t.adjList[i]) {
            if (nxt == t.parent[i])
                continue;
            tmp += modpow(2, t.size[nxt]) - 1;
        }
        ans += modpow(2, N - 1) - 1 - tmp;
    }
    cout << ans / modpow(2, N) << endl;
}

