int main()
{
    using mint  = modint<mod>;
    const int N = in<int>();
    graph g(N);
    for (int i = 0; i < N - 1; i++) {
        const auto u = in<int>() - 1;
        const auto v = in<int>() - 1;
        g.add_edge(u, v, true);
    }
    std::vector<int> sub(N, 0);
    mfp([&](auto&& self, const int s, const int p) -> int {
        sub[s] = 1;
        for (const int to : g[s]) {
            if (to == p) { continue; }
            sub[s] += self(self, to, s);
        }
        return sub[s];
    })(0, -1);
    mint ans = 0;
    mfp([&](auto&& self, const int s, const int p) -> void {
        std::vector<int> S;
        if (s != 0) { S.push_back(N - sub[s]); }
        for (const int to : g[s]) {
            if (to == p) { continue; }
            S.push_back(sub[to]);
            self(self, to, s);
        }
        mint no = (mint(2) ^ (N - 1)) - 1;
        for (const int s : S) { no -= ((mint(2) ^ s) - 1); }
        ans += no / (mint(2) ^ N);
    })(0, -1);
    outln(ans);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MAX = 3e5 + 5;
const int MOD = 1e9 + 7;
const int INV = 500000004;
int n, ans, pw[MAX], sz[MAX];
vector <int> g[MAX];

void dfs(int u, int p = -1) {
	int value = (1 - pw[n - 1] + MOD) % MOD;

	for(int v : g[u]) {
		if(v != p) {
			dfs(v, u);
			sz[u] += sz[v];

			int pk = (1 - pw[sz[v]] + MOD) % MOD;
			pk = 1LL * pk * pw[n - 1 - sz[v]] % MOD;
			value = (value - pk + MOD) % MOD;
		}
	}

	sz[u]++;

	int up = n - sz[u];

	int pk = (1 - pw[up] + MOD) % MOD;
	pk = 1LL * pk * pw[n - 1 - up] % MOD;
	value = (value - pk + MOD) % MOD;

	value = 1LL * value * INV % MOD;
	ans = (ans + value) % MOD;
}

int main() {
	scanf("%d", &n);

	pw[0] = 1;
	for(int i = 1; i <= n; i++)
		pw[i] = 1LL * pw[i - 1] * INV % MOD;

	for(int i = 1; i < n; i++) {
		int a, b; scanf("%d%d", &a, &b);
		g[a].push_back(b);
		g[b].push_back(a);
	}

	dfs(1);

	printf("%d\n", ans);
	return 0;
}

