int dfs(int u, int fa)
{
    int fi = -1, sum = 0;
    for (int i = 0, v; i < (int)e[u].size(); ++i) {
        v = e[u][i];
        if (v == fa) {
            fi = i;
            continue;
        }
        son[u][i] = dfs(v, u);
        sum += son[u][i];
    }
    if (fi != -1) son[u][fi] = n-1-sum;
    return sum+1;
}

