ll power(ll k, ll n, int M){
  if (n < 0) return 0;

  ll res = 1;
  while(n > 0) {
    if (n & 1) res = res * k % M;
    k = k * k % M;
    n /= 2;
  }
  return res;
}

int N;
vector<int> G[SIZE];
int num_child[SIZE];

ll ans1 = 0, ans2 = 0; // ans = ans1 / ans2

int dfs(int now, int back = -1) {
  int size = 1;

  for (int to : G[now]) {
    if (to == back) continue;

    size += dfs(to, now);
  }

  int r = N - size;

  ans1 = (ans1 + power(2, N - 1, mod) - 1) % mod;

  for (int to : G[now]) {
    if (to == back) {
      ans1 = (ans1 + mod - power(2, r, mod) + 1) % mod;
    } else {
      ans1 = (ans1 + mod - power(2, num_child[to], mod) + 1) % mod;
    }
  }

  return num_child[now] = size;
}

