template<qweqwe::i32 mod>
struct qweqwe::math::modint {
  i64 x;
  modint() : x(0) {}
  modint(i64 n) : x(n){
    if(x>=mod) x %= mod;
    else if(x<0) x = (x%mod + mod) % mod;
  }
  static int GetMod() { return mod; }
  operator i64() const { return x;}
  operator i32() const { return (i32)x;}
  constexpr modint &_setval(i64 v) { x = (v >= mod ? v % mod : v); return *this; }
  constexpr modint operator+(const modint &z) const { return modint()._setval((i64)x + z.x); }
  constexpr modint operator-(const modint &z) const { return modint()._setval((i64)x - z.x + mod); }
  constexpr modint operator*(const modint &z) const { return modint()._setval((i64)x * z.x % mod); }
  constexpr modint operator/(const modint &z) const { return modint()._setval((i64)x * z.inv() % mod); }
  constexpr modint operator-() const { return modint()._setval(mod - x); }
  constexpr modint &operator+=(const modint &z) { return *this = *this + z; }
  constexpr modint &operator-=(const modint &z) { return *this = *this - z; }
  constexpr modint &operator*=(const modint &z) { return *this = *this * z; }
  constexpr modint &operator/=(const modint &z) { return *this = *this / z; }
  static i32 get_primitive_root() {
    static i32 primitive_root = 0;
    if (!primitive_root) {
      primitive_root = [&](){
        std::set<i32> fac;
        i32 v = mod - 1;
        for (i64 i = 2; i * i <= v; i++) while (v % i == 0) fac.insert(i), v /= i;
        if (v > 1) fac.insert(v);
        for (i32 g = 1; g < mod; g++) {
          bool ok = true;
          for (auto i : fac) if (modint(g).power((mod - 1) / i) == 1) { ok = false; break; }
          if (ok) return g;
        }
        return -1;
      }();
    }
    return primitive_root;
  }
  constexpr i64 power(i64 n) const {
    i64 ans = 1, tmp = this->x;
    while (n) {
      if (n & 1) ans = ans * tmp % mod;
      tmp = tmp * tmp % mod;
      n /= 2;
    }
    return ans;
  }
  constexpr i64 inv() const { return this->power(mod - 2); }
  constexpr modint operator^(i64 n) const { return modint(this->power(n)); }
  constexpr modint &operator^=(i64 n) { return *this = *this ^ n; }
  bool operator<(const modint &z) const { return x < z.x; }  // To use std::map<ModInt, T>
  friend std::istream &operator>>(std::istream &is, modint &z) { i64 t; is >> t; z = modint(t); return is; }
  friend std::ostream &operator<<(std::ostream &os, const modint &z) { os << z.x;  return os; }
};


constexpr int mod = 1000000007;
void solve(){
  using namespace qweqwe::stdplus::iosplus;
  using namespace qweqwe::stdplus::math;
  using namespace qweqwe::math;
  using mint = modint<mod>;
  using Edge = pair<int,int>;
  using Edges = vector<Edge>;
  iosFast();
  int n;
  cin >> n;
  vector<Edges> graph(n); vector<int> unc_num(n,0);
  FOR(i,0,n-1){
    int a, b;
    cin >> a >> b;
    --a; --b;
    unc_num[a]++;
    unc_num[b]++;
    graph[a].push_back(Edge(b,0));
    graph[b].push_back(Edge(a,0));
  }
  set<int> unc_one, unc_large;
  FOR(i,0,n){
    if(unc_num[i]==1) unc_one.insert(i);
    else unc_large.insert(i);
  }
  vector<int> checked(n,0);
  int skiploop = 1;
  while(true){
    bool cont = true;
    for(auto i: unc_one){
      if(checked[i]==1) continue;
      cont = false;
      ll s = 0; int snum = 0, uc = 0;
      for(int j = 0; j<graph[i].size(); ++j){
        if(checked[graph[i][j].first]==1){
          s += graph[i][j].second;
        }else{
          snum++;
          uc = j;
        }
      }
      if(snum <= 1){
        checked[i] = 1;
        unc_one.erase(i);
        if(checked[graph[i][uc].first]==0){
          graph[i][uc].second = n - s - 1;
          for(int j = 0; j<graph[graph[i][uc].first].size();  ++j){
            if(graph[graph[i][uc].first][j].first==i){
              graph[graph[i][uc].first][j].second = s + 1;
              unc_num[graph[i][uc].first]--;
              if(unc_num[graph[i][uc].first]==1){
                unc_large.erase(graph[i][uc].first);
                unc_one.insert(graph[i][uc].first);
              }
              break;
            }
          }
        }
      }
    }
    if(cont) break;
  }
  vector<mint> pow2s(n+10,1); mint inv2n, two(2), one(1);
  FOR(i,0,n+5){
    pow2s[i+1] = two * pow2s[i];
  } 
  inv2n = pow2s[n].inv();
  mint ans(0);
  FOR(i,0,n){
    mint mini(0);
    for(auto x: graph[i]){
      mini += pow2s[x.second];
      mini -= one;
    }
    mini += one;
    mini = pow2s[n-1] - mini;
    ans += mini;
  }
  ans *= inv2n;
  cout << ans << endl;
}


