	long long int powa[65];
  	powa[0] = a; 
  	for(int j = 0; j < 64; ++j){
     		powa[j+1] = (powa[j] * powa[j]) % m; 
  	}
	int c = n; 
  	long long int Q = 1; int k = 0; 
	while(c > 0){
  		if(c & 1) Q = (Q * powa[k]) % m; 
		c >>= 1; k++; 
	}
	return Q;
}
