#define modulo 1000000007
#define mod(mod_x) ((((long long)mod_x+modulo))%modulo)
#define Inf 1000000000

int ans = 0;

int N;

//aのb乗
int beki(int a,int b){
	int x = 1;
	while(b!=0){
		if(b&1){
			x=mod(x*a);
		}
		a=mod(a*a);
		b>>=1;
	}
	return x;
}

//aの逆元
int gyakugen(int a){
	return beki(a,modulo-2);
}

void dfs(int now,int parent,vector<vector<int>> &E,vector<int> &cnt){
	int C = 1;
	for(int i=0;i<E[now].size();i++){
		int to = E[now][i];
		if(to==parent)continue;
		dfs(to,now,E,cnt);
		C += cnt[to];
	}
	cnt[now] = C;
}

void dfs2(int now,int parent,vector<vector<int>> &E,vector<int> &cnt){
	vector<int> B;
	int s = 0;
	for(int i=0;i<E[now].size();i++){
		int to = E[now][i];
		if(to==parent)continue;
		dfs2(to,now,E,cnt);
		B.push_back(cnt[to]);
		s += cnt[to];
	}
	s++;
	s = N-s;
	if(s!=0)B.push_back(s);

	int ho = beki(gyakugen(2),N-1);
	for(int i=0;i<B.size();i++){
		int A = beki(gyakugen(2),N-1-B[i]);
		int C=mod( 1 - beki(gyakugen(2),B[i]));
		ho = mod(ho + mod(A*C));
	}
	ho = mod(1 - ho);
	ho - mod(ho * gyakugen(2));
	ans = mod(ans + ho);

}

int main(){


	cin>>N;

	vector<vector<int>> E(N,vector<int>());

	for(int i=0;i<N-1;i++){
		int a,b;
		cin>>a>>b;
		a--;b--;
		E[a].push_back(b);
		E[b].push_back(a);
	}

	vector<int> cnt(N,0);

	dfs(0,-1,E,cnt);

	dfs2(0,-1,E,cnt);
	cout<<mod(gyakugen(2)*ans)<<endl;

    return 0;
}

