// ある整数の約数列挙
vector<long long> divisors(long long n) {
  vector<long long> res;
  for(long long i = 1; i*i <= n; ++i) {
    if(n % i != 0) continue;
    res.push_back(i);
    if(n/i == i) continue; // 上の行で追加済み。
    res.push_back(n/i);
  }
  sort(res.begin(), res.end());
  return res;
}


// 素因数分解
map<long long, long long> prime_factors(long long n) {
  map<long long, long long> res;
  if(n == 1) { // n=1 の素因数分解は n^1
    res[n] = 1;
    return res;
  }
  for(long long i = 2, _n = n; i*i <= _n; ++i) {
    while(n % i == 0) {
      ++res[i]; // 素数i^{res[i]}
      n /= i;
    }
  }
  if(n != 1) res[n] = 1;
  return res;
}


// 繰り返し 2 乗法
long long modpow(long long a, long long n) {
  long long res = 1;
  while (n > 0) {
    if (n & 1) res = res * a % MOD;
    a = a * a % MOD;
    n >>= 1;
  }
  return res;
}


// 逆元を求める. a と m は互いに素であることが要請される.
long long modinv(long long a, long long m) {
  long long b = m, u = 1, v = 0;
  while(b){
    long long t = a / b;
    a -= t * b; swap(a, b);
    u -= t * v; swap(u, v);
  }
  u %= m; 
  if (u < 0) u += m;
  return u;
}

long long fac[MAXN], finv[MAXN], inv[MAXN];

// 前処理 O(n)
void math_init(){
  fac[0] = fac[1] = 1;
  finv[0] = finv[1] = 1;
  inv[1] = 1;
  for(long long i = 2; i < MAXN; i++){
    fac[i] = fac[i - 1] * i % MOD;
    inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
    finv[i] = finv[i - 1] * inv[i] % MOD;
  }
}

// 二項係数計算 O(1)
long long COM(long long n, long long k){
  if (n < k) return 0;
  if (n < 0 || k < 0) return 0;
  return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}


// before your coding, you have to write a line "math_init()"

void dfs(int cur, int par, vector<vector<int>> &g, vector<int> &sz, vector<int> &p) {
  p[cur] = par;
  for (auto nxt : g[cur]) {
    if (nxt == par) continue;
    dfs(nxt, cur, g, sz, p);
  }

  int s = 1;
  for (auto nxt : g[cur]) {
    if (nxt == par) continue;
    s += sz[nxt];
  }

  sz[cur] = s;
}

int main() {

  math_init();
  int n; cin >> n;
  vector<vector<int>> g(n);
  for (int i = 0; i < n - 1; i++) {
    int a, b; cin >> a >> b;
    a--;
    b--;
    g[a].push_back(b);
    g[b].push_back(a);
  }

  vector<int> sz(n, -1);
  vector<int> par(n, -1);
  dfs(0, -1, g, sz, par);

  lint p = 1;

  // 1 / 2^n を計算する
  for (int i = 0; i < n; i++) {
    p *= inv[2];
    p %= MOD;
  }


  lint sum = 0;
  for (int v = 0; v < n; v++) {
    vector<int> childSize;
    int usedNodeCount = 0;
    for (auto c : g[v]) {
      if (c == par[v]) continue;
      usedNodeCount += sz[c];
      childSize.push_back(sz[c]);
    }

    // 自身を加える
    usedNodeCount++;

    // 親側の方を加える
    if (n - usedNodeCount > 0) {
      childSize.push_back(n - usedNodeCount);
    }


    // v が 白でカウントされる通り数を計算する

    // v が白とした塗り方の全通りは 2^{n - 1} - 1 （全部白は除外）
    lint all = (modpow(2, n - 1) - 1 + MOD) % MOD;

    // 余事象，隣接する c の部分木から黒を好きなだけとる（全部白は除く）

    for (auto csz : childSize) {
      lint sub = (modpow(2, csz) - 1 + MOD) % MOD;
      all = (all + MOD - sub) % MOD;
    }

    sum += all;
    sum %= MOD;
  }

  lint ans = (sum * p) % MOD;
  cout << ans << endl;

  return 0;
}

