        {
            ll sz = sub[x];

            ans = ( ( ans - po(2,sz) ) %mod + mod )%mod;
            dfs2(x,u);
        }
    }

    ll sz = (int)(adj[u].size());

    ans = ( ( ans + sz - 1 )%mod +mod )%mod;
}

int main()
{
    scanf("%lld",&n);
    for(int i=0;i<n-1;i++)
    {
        int a,b;
        scanf("%d%d",&a,&b);
        adj[a].push_back(b);
        adj[b].push_back(a);
    }

    dfs1(1,0);
    dfs2(1,0);

    printf("%lld\n",ans*modInv(po(2,n))%mod);
}

