int N;
vector<int> graph[mx];
vector<int> cnt[mx];
modint answer;

int calc(int v, int p){
    int res = 0;
    for(int u : graph[v]){
        if(u == p)cnt[v].push_back(0);
        else {
            int t = calc(u, v);
            res += t;
            cnt[v].push_back(t);
        }
    }
    return res + 1;
}

void propagate(int v, int p, int prop){
    int sz = graph[v].size(), sum = 0;
    modint plus1 = ~modint(2).power(N - 1), plus2;
    rep(i, sz){
        if(graph[v][i] == p){
            cnt[v][i] = prop;
        }
        sum += cnt[v][i];
        plus2 += ~modint(2).power(N - cnt[v][i] - 1) * (modint(1) - ~modint(2).power(cnt[v][i]));
    }
    answer += modint(1) - plus1 - plus2;
    rep(i, sz){
        int u = graph[v][i];
        if(u != p) propagate(u, v, sum - cnt[v][i] + 1);
    }
}

