        for(auto& nd : g){
            long long sub = (pow2[N-1] + MOD - 1) % MOD;
            for(auto& e : nd){
                sub = (sub + MOD - pow2[e.second]) % MOD;
                sub = (sub + 1) % MOD;
            }
            res += sub;
        }
        res = (res * calcInv(modPow(2, N))) % MOD;
        cout << res << endl;
    }
}

