#include <bits/stdc++.h>

using namespace std ;

const long long mod = 1e9 + 7ll ;
const int MAX = 2e5 + 10 ;

long long sz[MAX] , P[MAX] ;
int n ;

long long ans = 0ll ;

vector< vector<int> >adj(MAX) ;

long long powlog(long long base , long long power)
{
	if(power == 0)
		return 1ll ;
	long long x = powlog(base , power / 2ll) ;
	x = (x * x) % mod ;
	if(power & 1)
		x = (x * base) % mod ;
	x %= mod ;
	return x ;
}

void dfs(int node , int par)
{
	sz[node] = 1 ;
	for(auto &child : adj[node])
	{
		if(child == par)
			continue ;
		dfs(child , node) ;
		sz[node] += sz[child] ;
	}
	return ;
}

void dfs2(int node , int par)
{
	vector<long long>v ;
	long long sum = 0ll ;
	for(auto &child : adj[node])
	{
		if(child == par)
			continue ;
		dfs2(child , node) ;
		v.push_back(sz[child]) ;
		sum += sz[child] ;
	}
	long long x = (P[sz[node] - 1] - 1ll + mod) % mod ;
	long long y = (P[n - sz[node]] - 1ll + mod) % mod ;
	long long z = (x * y) % mod ;
	ans = (ans + z) % mod ;
	for(auto &i : v)
	{
		sum -= i ;
		x = (P[i] - 1ll + mod) % mod ;
		y = (P[sum] - 1ll + mod) % mod ;
		z = (x * y) % mod ;
		ans = (ans + z) % mod ;
	}
}

