		adj[x].push_back(y) ;
		adj[y].push_back(x) ;
	}
	dfs(1 , -1) ;
	dfs2(1 , -1) ;
	ans = (ans * powlog(P[n] , mod-2)) % mod ;
	ans %= mod ;
	cout<<ans<<"\n" ;
	return 0 ;
}

