void build_down(int u, int p) {
    int cnt = 0;
    inte tmp = 1;
    for (auto v : e[u])
        if (v != p)
            build_down(v, u), ++cnt, tmp *= 1 - down[v];
    down[u] = inte(1) / 2 + inte(1) / 2 * (1 - tmp);
}
inte ans = 0;
inte solve(vector<inte> a) {
    if (a.size() < 2)
        return 0;
    inte buzhai = 1;
    for (auto v : a)
        buzhai *= 1 - v;
    inte one = 0;
    for (auto v : a)
        one += buzhai / (1 - v) * v;
    return 1 - buzhai - one;
}
void build_up(int u, int p) {
    vector<inte> tt;
    if (p != -1)
        tt.push_back(up[u]);
    for (auto v : e[u])
        if (v != p)
            tt.push_back(down[v]);
    ans += solve(tt) / 2;
    inte tmp = 1;
    if (p != -1)
        tmp *= 1 - up[u];
    for (auto v : e[u])
        if (v != p)
            tmp *= 1 - down[v];
    for (auto v : e[u])
        if (v != p) {
            up[v] = inte(1) / 2 + inte(1) / 2 * (1 - tmp / (1 - down[v]));
            build_up(v, u);
        }
}
