struct DP {
    mint dp;
    mint all;
    lint sub;
    mint base;
    DP(mint dp=0,mint all=0,lint sub=0,mint base=2):dp(dp),all(all),sub(sub),base(base){}
    DP operator+(const DP& a) const {
        return DP(dp+base.pow(a.sub)-1,base.pow(sub+a.sub),sub+a.sub);
    }
    DP addRoot(int W){
        return DP(dp,all,sub+1,base);
    }
};

