		A[now].push_back(S[E[now].at(i)]); 
		tmp -= S[E[now].at(i)]; 
	}
	A[now].push_back(tmp); 
	for(int i = 0; i < E[now].size(); i++){
		if(E[now].at(i) == parent) continue; 
