{
    const long long MOD = 1e9 + 7;

    int N;
    cin >> N;

    Graph<long long> g(N);
    int A, B;
    for (int i = 0; i < N - 1; i++)
    {
        cin >> A >> B;
        g.add_edge(A, B);
        g.add_edge(B, A);
    }

    vector<vector<long long>> children(g.node);
    dfs(g, children, 0, 1);

    vector<Mod<MOD>> half(N, Mod<MOD>(1));
    for (int i = 1; i < N; i++)
    {
        half[i] = half[i - 1] / 2;
    }
    Mod<MOD> ans = 0;
    for (auto child : children)
    {
        if (child.size() <= 1)
        {
            continue;
        }
        Mod<MOD> tmp = Mod<MOD>(1);
        tmp -= half[N - 1];
        for (auto c : child)
        {
            tmp -= half[N - (c + 1)] * (Mod<MOD>(1) - half[c]);
        }
        ans += tmp * half[1];
    }
    cout << ans << endl;
}

