  modint ret = 0;
  vector< int > dp(N);
  auto rec = MFP([&](auto rec, int idx, int par) -> void {
    dp[idx] = 1;
    vector< int > sz;
    for(auto &to : g[idx]) {
      if(to != par) {
        rec(to, idx);
        dp[idx] += dp[to];
        sz.emplace_back(dp[to]);
      }
    }
