void add_self(int& a, int b) {
	a += b;
	if(a >= mod) a -= mod;
}

void sub_self(int& a, int b) {
	a -= b;
	if(a < 0) a += mod;
}

int mul(int a, int b) {
	return ll(a) * ll(b) % mod;
}

int mpow(int a, int m) {
	if(m == 0) return 1;
	int x = mpow(a, m/2);
	x = mul(x, x);
	if(m % 2 == 1) x = mul(x, a);
	return x;
}

int divide(int a, int b) {
	return mul(a, mpow(b, mod-2));
}

void dfs(int u, int p = -1) {
	sz[u] = 1;
	for(int v : g[u]) {
		if(v != p) {
			dfs(v, u);
			add_self(sz[u], sz[v]);
			adj[u].push_back(sz[v]);
		}
	}

	if(p != -1)	
		adj[u].push_back(n-sz[u]);
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	cin >> n;
	for(int rep = 0; rep < n - 1; rep++) {
		int u, v;
		cin >> u >> v;
		g[u].push_back(v);
		g[v].push_back(u);
	}

	dfs(1);
	int ans = 0;

	for(int i = 1; i <= n; i++) {
		if((int) adj[i].size() < 2) continue;
		int none = 1;
		for(int j : adj[i]) {
			none = mul(none, mpow(divide(1, 2), j));
		}
		int one = 0;
		for(int j : adj[i]) {
			int x = mul(none, mpow(2, j));
			int z = 1;
			sub_self(z, mpow(divide(1, 2), j));
			x = mul(x, z);
			add_self(one, x);
		}

		int contrib = 1;
		sub_self(contrib, none);
		sub_self(contrib, one); // need at least 2 black nodes
		contrib = divide(contrib, 2); // node must be white
		add_self(ans, contrib);
	}

	cout << ans << endl;
}

