mint inv2(500000004);

int main() {
    int N; cin >> N;
    vector< vector<int> > G(N);
    for(int i=0; i+1<N; i++) {
        int u, v; cin >> u >> v;
        u--; v--;
        G[u].emplace_back(v);
        G[v].emplace_back(u);
    }

    vector<int> sub(N), parent(N);
    auto dfs = [&](auto&& f, int cur, int par) -> void {
        sub[cur] = 1;
        parent[cur] = par;
        for(auto to : G[cur]) {
            if(to == par) continue;
            f(f, to, cur);
            sub[cur] += sub[to];
        }
    };
    dfs(dfs, 0, -1);

    mint ans(0);
    for(int i=0; i<N; i++) {
        vector<int> subs; int cur = i;
        for(auto to : G[cur]) {
            if(parent[cur] == to) subs.emplace_back(N - sub[cur]);
            else subs.emplace_back(sub[to]);
        }

        mint add(0);

        // どれも白の場合
        add += inv2.pow(N-1);

        // どれかひとつのみに黒が存在する場合
        for(auto s : subs) {
            add += inv2.pow(N-1-s) * (mint(1) - inv2.pow(s));
        }

        ans += (mint(1) - add) * inv2;
    }
    cout << ans << endl;
    return 0;
}

