struct Graph {
    struct Vertex { int n; };
    struct Edge { int i, n; };
    Graph(int n, int m) : v(n, { -1 }), e(m), n(n), m(0) {}
    void add_edge(int i, int j) {
        e[m] = { j, v[i].n };
        v[i].n = m;
        m++;
    }
    int dfs(int i, int p) {
        int c = 1;
        for (int j = v[i].n; j >= 0; j = e[j].n) {
            Edge& o = e[j];
            if (o.i == p) continue;
            int t = dfs(o.i, i);
            c += t;
            r -= a[t] - 1;
        }
        r -= a[n - c] - 1;
        r -= 1;
        r += a[n - 1];
        return c;
    }
    void solve() {
        r = 0;
        a = vector<int>(n + 1);
        a[0] = 1;
        for (int i = 0; i < n; i++) {
