const int MOD = 1e9 + 7;
int N;
const int MAX_N = 2e5;
vector<vector<int> > G;
vector<int> K[MAX_N];

long long modinv(long long a, long long m) {
    long long b = m, u = 1, v = 0;
    while (b) {
        long long t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= m; 
    if (u < 0) u += m;
    return u;
}//modinv(i,mod)でi^-1のmodをとる。

long long modpow(long long a, long long n, long long mod) {
    long long res = 1;
    while (n > 0) {
        if (n & 1) res = res * a % mod;
        a = a * a % mod;
        n >>= 1;
    }
    return res;
}

// 返り値で自分が根である部分木の要素数を返す
int dfs(int idx, int par){
    int sum = 1;
    for(int &to: G[idx]){
        if(to == par) continue;
        int tmp = dfs(to, idx);
        K[idx].push_back(tmp);
        sum += tmp;
    }
    if(par != -1){
        K[idx].push_back(N-1-(sum - 1));
    }
    return sum;
}

int main(){
    cin >> N;
    G.resize(N);
    rep(i, 0, N - 1){
        int a, b; cin >> a >> b; a--, b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }

    dfs(0, -1);
    ll sum = 0;

    rep(i, 0, N){
        ll tmp = 1;
        for(auto j: K[i]){
            tmp += modpow(2, j, MOD) -1;
        }
        sum += modpow(2, N- 1, MOD) - tmp;
        sum = (sum + MOD)%MOD;
    }
    cout << sum * modinv(modpow(2,N,MOD), MOD) % MOD << endl;
}

