int main() {
  std::cin.tie(0);
  std::ios::sync_with_stdio(false);

  ll n;
  std::cin>>n;

  std::vector<std::vector<ll>> graph(n);
  std::vector<ll> size(n,0),inv(n+1,1);

  ll ans=0;

  {
    ll two=pow_mod(2,MOD-2,MOD);
    rep(i,1,n+1)inv[i]=(inv[i-1]*two)%MOD;
    ans=MOD-(two*n%MOD);
  }

  rep(i,0,n-1){
    ll a,b;
    std::cin>>a>>b;
    a--;b--;
    graph[a].push_back(b);
    graph[b].push_back(a);
  }

  auto f=[&](auto f,ll now,ll par)->void{
    ll temp=0;
    for(ll next:graph[now]){
      if(next!=par){
        f(f,next,now);
        ans=(ans+(MOD+1-inv[size[next]])*(MOD+1-inv[n-size[next]])%MOD)%MOD;
        temp+=size[next];
      }
    }
    size[now]=temp+1;
  };

  f(f,0,-1);

  ans=(ans+(MOD+1-inv[n])%MOD)%MOD;

  std::cout<<ans<<"\n";

  return 0;
}

