void solve()
{
    int n;
    cin >> n;
    yukari<int> g(n);
    for (int i = 0; i < n - 1; i++)
    {
        int a, b;
        cin >> a >> b;
        a--, b--;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    Int ans = 0;
    auto dfs = [&](auto &&dfs, int v = 0, int p = -1) -> int {
        int sum = 1;
        Int res = 1;
        for (int nv : g[v])
        {
            if (p == nv)
            {
                continue;
            }
            int sz = dfs(dfs, nv, v);
            sum += sz;
            res += pow(Int(2), sz) - 1;
        }
        res += pow(Int(2), n - sum) - 1;
        ans += pow(Int(2), n - 1) - res;
        return sum;
    };
    dfs(dfs);
    ans /= pow(Int(2), n);
    cout << ans << endl;
}

