struct mint {
    ll x; // typedef long long ll;
    mint(ll x=0):x((x%mod+mod)%mod){}
    mint operator-() const { return mint(-x);}
    mint& operator+=(const mint a) {
        if ((x += a.x) >= mod) x -= mod;
        return *this;
    }
    mint& operator-=(const mint a) {
        if ((x += mod-a.x) >= mod) x -= mod;
        return *this;
    }
    mint& operator*=(const mint a) {
        (x *= a.x) %= mod;
        return *this;
    }
    mint operator+(const mint a) const {
        mint res(*this);
        return res+=a;
    }
    mint operator-(const mint a) const {
        mint res(*this);
        return res-=a;
    }
    mint operator*(const mint a) const {
        mint res(*this);
        return res*=a;
    }
    mint pow(ll t) const {
        if (!t) return 1;
        mint a = pow(t>>1);
        a *= a;
        if (t&1) a *= *this;
        return a;
    }

    // for prime mod
    mint inv() const {
        return pow(mod-2);
    }
    mint& operator/=(const mint a) {
        return (*this) *= a.inv();
    }
    mint operator/(const mint a) const {
        mint res(*this);
        return res/=a;
    }
};

vector<int> to[200005];
int buka[200005];
vector<int> branch[200005];

void dfs(int i, int n, int p) {
    if (to[i].size()==1 && p!=-1) {
        buka[i] = 0;
        branch[i].push_back(n-1);
        return;
    }
    for (int e: to[i]) {
        if (e==p) continue;
        dfs(e, n, i);
        buka[i] += (buka[e] + 1);
        branch[i].push_back(buka[e]+1);
    }
    if (buka[i]!=n-1) {
        branch[i].push_back(n-1-buka[i]);
    }
}

