using namespace std;
typedef pair<int, int> Rational;
const int BUF = 200005;
const int MOD = 1000000007;


int add(int a, int b) {
    return (a + b) % MOD;
}

int sub(int a, int b) {
    return (a + MOD - b) % MOD;
}

int mul(int a, int b) {
    return 1LL * a * b % MOD;
}

int modpow(int p, long long n) {
    if (n == 0) return 1;
    int t = modpow(p, n / 2);
    return n % 2 == 0 ? mul(t, t) : mul(mul(t, t), p);
}

Rational add(Rational a, Rational b) {
    return Rational(add(mul(a.nume, b.deno), mul(b.nume, a.deno)),  mul(a.deno, b.deno));
}

Rational mul(Rational a, Rational b) {
    return Rational(mul(a.nume, b.nume), mul(a.deno, b.deno));
}


int nNode;
vector<int> adj[BUF];

void read() {
    for (int i = 0; i < BUF; ++i) adj[i].clear();

    cin >> nNode;
    for (int i = 0; i < nNode - 1; ++i) {
        int s, t;
        cin >> s >> t;
        --s, --t;
        adj[s].push_back(t);
        adj[t].push_back(s);
    }
}


int getNumSubtreeNode(int node, int node2nSubtreeNode[BUF], map<int, int> edge2nSubtreeNode[BUF]) {
    int &ret = node2nSubtreeNode[node];
    ret = 1;

    for (int i = 0; i < adj[node].size(); ++i) {
        int nex = adj[node][i];
        if (node2nSubtreeNode[nex] != -1) continue;

        int nexNumSubtreeNode = getNumSubtreeNode(nex, node2nSubtreeNode, edge2nSubtreeNode);
        edge2nSubtreeNode[node][nex] = nexNumSubtreeNode;
        edge2nSubtreeNode[nex][node] = nNode - nexNumSubtreeNode;

        ret += nexNumSubtreeNode;
    }

    return ret;
}


Rational rec(int node, int childIdx, int nChose, vector< vector<Rational> > &dp, map<int, int> edge2nSubtreeNode[BUF]) {
    if (childIdx == adj[node].size()) {
        return nChose == 2 ? Rational(1, 1) : Rational(0, 1);
    }

    Rational &ret = dp[childIdx][nChose];
    if (ret.nume != -1) return ret;
    ret = Rational(0, 1);

    int nSubtreeNode = edge2nSubtreeNode[node][adj[node][childIdx]];

    // Choose at least one node from node's childIdx-th subtree
    ret = add(ret, mul(rec(node, childIdx + 1, min(nChose + 1, 2), dp, edge2nSubtreeNode),
                       Rational(sub(modpow(2, nSubtreeNode), 1), modpow(2, nSubtreeNode))));

    // Choose noting
    ret = add(ret, mul(rec(node, childIdx + 1, nChose, dp, edge2nSubtreeNode), Rational(1, modpow(2, nSubtreeNode))));

    return ret;
}


void work() {
    map<int, int> edge2nSubtreeNode[BUF];

    int node2nSubtreeNode[BUF];
    memset(node2nSubtreeNode, -1, sizeof(node2nSubtreeNode));
    getNumSubtreeNode(0, node2nSubtreeNode, edge2nSubtreeNode);

    Rational sum = Rational(0, 1);
    for (int i = 0; i < nNode; ++i) {
        vector<vector<Rational> > dp(adj[i].size(), vector<Rational>(3, Rational(-1, -1)));
        sum = add(sum, rec(i, 0, 0, dp, edge2nSubtreeNode));
    }
    sum.deno = mul(sum.deno, 2);

    cout << mul(sum.nume, modpow(sum.deno, MOD - 2)) << endl;
}


int main() {
    read();
    work();
    return 0;
}

