vector<int> ShortestPathTree(const vector<vector<int>>& g, int s) {
	int V = g.size();
	vector<int> dist(V);
	function<void(int, int, int)> dfs = [&](int v, int p, int depth) {
		dist[v] = depth;
		for (int e : g[v])if (e != p) {
			dfs(e, v, depth + 1);
		}
	};
	dfs(s, -1, 0);
	return dist;
}

int main() {
	int n = in;
	VVI g(n);
	VP edges;
	rep(i, n - 1) {
		int a = in--, b = in--;
		g[a].push_back(b);
		g[b].push_back(a);
		edges.emplace_back(a, b);
	}

	VI size(n);
	function<int(int, int)> dfs = [&](int v, int p) {
		int res = 0;
		for (int e : g[v])if (e != p) {
			res += dfs(e, v) + 1;
		}
		return size[v] = res;
	};
	dfs(0, -1);

	VI dist = ShortestPathTree(g, 0);

	mint e_cnt = 0;
	for (const auto& e : edges) {
		int cnt_v = 0;
		if (dist[e.first] < dist[e.second]) {
			cnt_v = size[e.second] + 1;
		} else {
			cnt_v = size[e.first] + 1;
		}

		mint p1 = mint(2).pow(cnt_v);
		mint p2 = mint(2).pow(n - cnt_v);
		e_cnt += (p1.pred() / p1) * (p2.pred() / p2);
	}
	e_cnt -= 1_m / mint(2).pow(n);
	e_cnt += 1;
	e_cnt -= mint(n) / 2;
	out(e_cnt);
}

