void dfs(int index)
{
	for (int i = 0; i < edge[index].size(); i++){
		if (par[index] == edge[index][i]){
			continue;
		}
		par[edge[index][i]] = index;
		dfs(edge[index][i]);
	}

	return;
}

int dfs_subsize(int index)
{
	int sum = 0;
	for (int i = 0; i < edge[index].size(); i++){
		if (par[index] == edge[index][i]){
			continue;
		}
		sum += dfs_subsize(edge[index][i]);
	}

	return subsize[index] = sum + 1;
}

void dfs_parsize(int index)
{
	for (int i = 0; i < edge[index].size(); i++){
		if (par[index] == edge[index][i]){
			continue;
		}
		parsize[edge[index][i]] = subsize[index] - subsize[edge[index][i]] + parsize[index];
		dfs_parsize(edge[index][i]);
	}

	return;
}

lli modpow(int val)
{
	if (0 == val){
		return 1;
	}
	if (0 == val % 2){
		lli tmp = modpow(val / 2);
		return (tmp*tmp) % MOD;
	}
	else{
		return (modpow(val - 1) * 2) % MOD;
	}
}

lli modpow(lli base, lli p)
{
	if (0 == p){
		return 1;
	}
	if (0 == p % 2){
		lli tmp = modpow(base,p/2);
		return (tmp*tmp) % MOD;
	}
	else{
		return (modpow(base,p - 1) * base) % MOD;
	}
}

void solv()
{
	int N; scanf("%d", &N);
	for (int i = 0; i < N - 1; i++){
		int A, B; scanf("%d%d", &A, &B);
		A--; B--;
		edge[A].push_back(B);
		edge[B].push_back(A);
	}

	par[0] = -1; parsize[0] = 0;
	dfs(0);
	dfs_subsize(0);
	dfs_parsize(0);

	lli sum = 0;
	sum = (sum + modpow(N - 1) - 1 + MOD) % MOD;
	for (int i = 0; i < edge[0].size(); i++){
		sum = (sum + MOD - modpow(subsize[edge[0][i]]) + 1) % MOD;
	}
	for (int i = 1; i < N; i++){
		sum = (sum + modpow(N - 1) - 1 + MOD) % MOD;
		sum = (sum + MOD - modpow(parsize[i]) + 1) % MOD;
		for (int j = 0; j < edge[i].size(); j++){
			if (par[i] == edge[i][j]){
				continue;
			}
			sum = (sum + MOD - modpow(subsize[edge[i][j]]) + 1) % MOD;
		}
	}

	printf("%lld", (sum * modpow(modpow(N), MOD - 2)) % MOD);

	return;
}

