    from[A[i]].push_back(B[i]);
    from[B[i]].push_back(A[i]);
  }

  std::vector<mint> pow(N + 1), inv(N + 1);
  pow[0] = 1;
  inv[0] = 1;
  rep(i, N) {
    pow[i + 1] = pow[i] * 2;
    inv[i + 1] = pow[i + 1].inv();
  }

  std::vector<int> cnt(N);
  dfs(0, 0, from, cnt);

  mint EV = 1;
  rep(i, N - 1) {
    int na = std::min(cnt[A[i]], cnt[B[i]]);
    int nb = N - na;

    EV += (mint(1) - inv[na]) * (mint(1) - inv[nb]);
  }

  mint ans = EV - inv[1] * N - inv[N];
  std::cout << ans.x << '\n';
}

