template <int MOD>
struct Mint {
  int n;
  constexpr Mint(int n = 0): n(n) {}
  constexpr Mint operator -() const {
    return n ? MOD - n: 0;
  }
  constexpr Mint operator ++() {
    n++;
    if(n == MOD) n = 0;
    return *this;
  }
  constexpr Mint operator --() {
    n--;
    if(n < 0) n = MOD - 1;
    return *this;
  }
  constexpr Mint &operator -= (const Mint &rhs){
    if(n >= rhs.n) n -= rhs.n;
    else n = MOD - (rhs.n - n);
    return *this;
  }
  constexpr Mint &operator += (const Mint &rhs){
    n += rhs.n;
    if(n >= MOD) n -= MOD;
    return *this;
  }
  constexpr Mint &operator *= (const Mint &rhs){
    n = (long long) n * rhs.n % MOD;
    return *this;
  }
  constexpr Mint &operator /= (const Mint &rhs){
    n = (long long) n * rhs.inv().n % MOD;
    return *this;
  }
  constexpr bool operator == (const Mint &rhs) const {
    return n == rhs.n;
  }
  constexpr bool operator != (const Mint &rhs) const {
    return n != rhs.n;
  }
  friend constexpr Mint operator - (const Mint &lhs, const Mint &rhs){
    Mint r = lhs;
    r -= rhs;
    return r;
  }
  friend constexpr Mint operator + (const Mint &lhs, const Mint &rhs){
    Mint r = lhs;
    r += rhs;
    return r;
  }
  friend constexpr Mint operator * (const Mint &lhs, const Mint &rhs){
    Mint r = lhs;
    r *= rhs;
    return r;
  }
  friend constexpr Mint operator / (const Mint &lhs, const Mint &rhs){
    Mint r = lhs;
    r /= rhs;
    return r;
  }
  constexpr Mint pow(int n) const {
    Mint r = 1;
    Mint x = *this;
    for(; n; n >>= 1){
      if(n & 1) r *= x;
      x *= x;
    }
    return r;
  }
  constexpr Mint inv() const {
    return pow(MOD - 2);
  }
};

/*
\sum_v E[v is punc] = 1/2 \sum_v Prob[v cut black nodes] = 1/2 \sum_v 1 - Prob[v does not cut black nodes]
= 1/2 \sum_v 1 - (\sum_{w -- v} 2^{-(n-Nw-1)} - (dv-1)2^{-(n-1)})
= 1/2 [n - (\sum_{(v,w)} 2^{-(n-Nw-1)} - \sum_v (dv-1)2^{-(n-1)})]
= 1/2 [n - \sum_{(v,w)} 2^{-(n-Nw-1)} + (n-2)*2^{-(n-1)}]
*/

long long int ans = 0;


template<int N, int Mod>
struct Powinv2 {
  static constexpr Mint<Mod> inv2 = (1+mod)/2;
  Mint<Mod> A[N+1];
  constexpr Powinv2(): A() {
    A[0] = 1;
    for(int i = 1; i <= N; i++){
      A[i] = A[i-1] * inv2;
    }
  }
};

