LL qpow(LL n, LL p) {
    LL base = n, ans = 1;
    while (p) {
        if (p % 2) ans = (ans * base) % MOD;
        p >>= 1;
        base = (base * base) % MOD;
    }
    return ans;
}

LL mul(LL a, LL b) {
    return (a * b) % MOD;
}

LL add(LL a, LL b) {
    LL ans = (a + b);
    if (ans >= MOD) ans -= MOD;
    return ans;
}

LL sub(LL a, LL b) {
    return (a - b + MOD) % MOD;
}

int dfs(int cur, int par, LL &ans, int N) {
    int sz = 1;
    LL cur_ans = 0;
    for (int i : G[cur]) {
        if (i == par) continue;
        int tmp = dfs(i, cur, ans, N);
        LL tmp_ans = mul(sub(1, invpw2[tmp]), invpw2[N - tmp - 1]);
        sz += tmp;
        cur_ans = add(cur_ans, tmp_ans);
    }
    LL tmp_ans = mul(sub(1, invpw2[N - sz]), invpw2[sz - 1]);
    cur_ans = add(cur_ans, tmp_ans);
    cur_ans = add(cur_ans, invpw2[N - 1]);
    cur_ans = sub(1, cur_ans);
    cur_ans = mul(cur_ans, invpw2[1]);
    ans = add(ans, cur_ans);
    return sz;
}

