void Sdfs(int now,int back) {
    //At least 2 must be black
    modint<MAX_MOD> dp[2];
    dp[0] = 1;
    dp[1] = 0;
    for (auto& x : vertexs[now]) {
        if (x == back) continue;
        Sdfs(x, now);
        modint<MAX_MOD> geko = 1;
        geko /= pows<modint<MAX_MOD>>(2LL, sizing[x]);
        dp[1] *= geko;
        dp[1] += dp[0] * (modint<MAX_MOD>(1) - geko);
        dp[0] *= geko;
    }
    if (sizing[now] != n) {
        int hoge = n - sizing[now];
        modint<MAX_MOD> geko = 1;
        geko /= pows<modint<MAX_MOD>>(2LL, hoge);
        dp[1] *= geko;
        dp[1] += dp[0] * (modint<MAX_MOD>(1) - geko);
        dp[0] *= geko;
    }
    modint<MAX_MOD> geko = modint<MAX_MOD>(1);
    geko -= dp[0];
    geko -= dp[1];
    geko /= modint<MAX_MOD>(2);
