struct UnWeightedGraph {
  struct Edge {
    int to;
    Edge(int to) : to(to) {}
  };
  vector<vector<Edge>> edges;
  int n;
  UnWeightedGraph(int n) : n(n) {
    edges.assign(n, vector<Edge>());
  }
  void add_edge(int v, int u) {
    edges[v].emplace_back(u);
  }
  vector<Edge> &operator[](int x) {
    return edges[x];
  }
};

void solve() {
  int n;
  cin >> n;
  UnWeightedGraph g(n);
  rep(i, n - 1) {
    int x, y;
    cin >> x >> y;
    x--, y--;
    g.add_edge(x, y);
    g.add_edge(y, x);
  }
  vector<vi32> dp(n);
  auto dfs = [&](auto dfs, int u, int p) -> int {
    int m = g[u].size();
    dp[u].resize(m);
    int c = 0;
    rep(i, m) {
      int v = g[u][i].to;
      if (v == p) continue;
      dp[u][i] = dfs(dfs, v, u);
      c += dp[u][i];
    }
    return c + 1;
  };
  vector<vi32> dpl(n);
  vector<vi32> dpr(n);
  auto bfs = [&](auto bfs, int u, int p, int c) -> void {
    int m = g[u].size();
    rep(i, m) {
      if (g[u][i].to == p) dp[u][i] = c;
    }
    dpl[u].resize(m + 1);
    dpr[u].resize(m + 1);
    rep(i, m) dpl[u][i + 1] += dpl[u][i] + dp[u][i];
    rrep(i, m) dpr[u][i] += dpr[u][i + 1] + dp[u][i];
    rep(i, m) {
      int v = g[u][i].to;
      if (v == p) continue;
      bfs(bfs, v, u, dpl[u][i] + dpr[u][i + 1] + 1);
    }
  };
  dfs(dfs, 0, -1);
  bfs(bfs, 0, -1, 0);

  mint ans = 0;
  rep(u, n) {
    int m = g[u].size();
    mint s = 1;
    s -= exp((mint) 1 / 2, dpl[u][m]);
    rep(i, m) {
      int white = dpl[u][i] + dpr[u][i + 1];
      int black = dp[u][i];
      s -= exp((mint) 1 / 2, white) * ((mint) 1 - exp((mint) 1 / 2, black));
    }
    ans += s / 2;
  }
  cout << ans << endl;
}

