vector<int> G[100010];

ll child[100010];
ll d2[100010];

ll modpow(ll x, ll y) {
	ll ans = 1;
	while (y) {
		if (y & 1)ans *= x;
		x *= x;
		x %= MOD;
		ans %= MOD;
		y /= 2;
	}
	return ans;
}

ll moddiv(ll x, ll y) {
	return x * modpow(y, MOD - 2) % MOD;
}

int dfs(int c, int p) {
	int ans = 0;
	for (int i : G[c]) {
		if (i == p)continue;
		ans += dfs(i, c);
	}
	child[c] = ans + 1;
	return ans + 1;
}

int main() {
	d2[0] = 1;
	for (int i = 1;i < 100010;i++) {
		d2[i] = d2[i - 1] * moddiv(1, 2);
		d2[i] %= MOD;
	}
	int N, s, t;
	cin >> N;
	for (int i = 1;i < N;i++) {
		cin >> s >> t;
		G[s].push_back(t);
		G[t].push_back(s);
	}

	dfs(1, -1);
	//for (int i = 1;i <= N;i++)cout << child[i] << endl;

	ll x, y, z, r, c;
	ll ans = 0;
	for (int i = 1;i <= N;i++) {
		if (G[i].size() == 1)continue;

		r = d2[N - 1];//自分以外すべてが白である確率

		for (int p : G[i]) {
			if (child[p] > child[i]) {
				x = N - child[i];

				r += (MOD + 1 - d2[x]) * d2[child[i] - 1];
				r %= MOD;
			}
			else {
				r += (MOD + 1 - d2[child[p]]) * d2[N - 1 - child[p]];
				r %= MOD;
			}
		}
		ans += MOD + 1 - r;
		ans %= MOD;
	}
	ans *= d2[1];
	ans %= MOD;
	cout << ans << endl;
}

