    modlong ans = 0;
    rrt();
    for (int i=0; i<n; i++) {
        if (rrt[i].size() == 1) continue;
        modlong sum = modPow(2, n-1) - 1;
        for (auto &ri:rrt[i]) {
            sum -= modPow(2, ri.data.toll()) - 1;
        }
        ans += sum;
    }
    cout << ans / modPow(2, n) << '\n';
    return 0;
}

