	ll p21 = mpow(half, N);
	// (2-2) 黒のある部分木がちょうど1つ
	//  ※黒のある部分木⇔「白が1つもない部分木」でない部分木
	ll p22 = 0;
	for (int kj : k[i]) {
		db(kj);
		ll temp = mmul(msub(1, mpow(half, kj)), mpow(half, N - kj));
		dbl(temp);
		p22 = madd(p22, temp);
	}	
	ll res = 1;
	res = msub(res, p1);
	res = msub(res, madd(p21, p22));
	dbt3(tl3(p1, p21, p22)); dbl(res);
	return res;
}

