class RerootingSum{
    vec2<int> edges;
    vec<Node> partials;  // partials[i]はiからEdge.to向きの部分木の部分解
    vec<set<int>> edgeMap;

    // upを上方として、downにNode情報をとる。
    Node fillFirst(int up, int down){
        if(edges.at(down).empty()){
            // 末尾
            partials.at(down) = Node{Zp<MOD>(0), 0};
            return partials.at(down);
        }

        Zp<MOD> resPow(0);
        ll resNum = 0;
        for(auto iter: edges.at(down)){
            if(iter == up){
                continue;
            }



            auto pRes = fillFirst(down, iter);
            resPow = resPow + Zp<MOD>(2).pow(pRes.num + 1);  // numは自信を含まない積算なので
            resNum += pRes.num + 1;
        }

        // partials.at(down)にこの部分での結果を保存
        partials.at(down) = Node{resPow, resNum};

        return partials.at(down);
    }

    // fillFirstだと子どもから親への部分木の情報がないのでそれを埋める
    void fillHoles(int up, int down){
        // downからupへの距離を追加する
        if(up != -1){
            // upでの(down向きを除いた)部分木たちの和をもとめる。
            auto res = partials.at(up);

            // resにはupからdownにいった分が余計に含まれているのでこれを削る。
            auto subRes = partials.at(down);

            auto resUp = Node{res.sumPow - Zp<MOD>(2).pow(subRes.num + 1), res.num - (subRes.num + 1)};


            // downのうちupむきの分がなかったのを足しこむ
            partials.at(down).sumPow = partials.at(down).sumPow + Zp<MOD>(2).pow(resUp.num + 1);
            partials.at(down).num += resUp.num + 1;
        }

        // 下に伝播
        for(auto iter: edges.at(down)){
            if(iter == up){
                continue;
            }
            fillHoles(down, iter);
        }
    }

    public:
    RerootingSum(vec2<int> edges){
        this->edges = edges;
        partials = vec<Node>(edges.size(), Node{Zp<MOD>(0), 0});
        fillFirst(-1, 0);
        fillHoles(-1, 0);
    }

    Zp<MOD> getResult(int pos){
        #ifdef DEBUG
        printf("*START: result\n");
        cout << pos << endl;
        for(auto iter: partials.at(pos)){
            cout << iter << ",";
        }
        cout << endl;
        printf("*END: result\n");
        #endif
        if(edges.at(pos).size() <= 1){
            return Zp<MOD>(0);
        }

        return Zp<MOD>(2).pow(partials.at(pos).num) - (partials.at(pos).sumPow - Zp<MOD>(edges.at(pos).size()) + Zp<MOD>(1));
    }
};


void solve(long long N, std::vector<long long> A, std::vector<long long> B){
    for(int i=0; i < N-1; i++){
        A.at(i)--;
        B.at(i)--;
    }

    vec2<int> edges(N);
    for(int i=0; i < N-1; i++){
        edges.at(A.at(i)).push_back(B.at(i));
        edges.at(B.at(i)).push_back(A.at(i));
    }

    RerootingSum rs(edges);

    auto res = Zp<MOD>(0);
    for(int i=0; i < N; i++){
        res = res + rs.getResult(i);
    }
    #ifdef DEBUG
    printf("*START: numbers\n");
    cout << res.raw() << endl;
    printf("*END: numbers\n");
    #endif
    res = res / Zp<MOD>(2).pow(N);

    cout << res.raw() << endl;
}

