long long int do_m(const std::vector<long long int>& happiness, const std::vector<long long int>& sum, const int min, const long long int m) {
	long long int count = 0, count_just = 0;
	long long int sum_upper = 0;
	for (const auto a : happiness) {
		auto lower = std::lower_bound(happiness.begin(), happiness.end(), min - a);
		auto upper = std::upper_bound(happiness.begin(), happiness.end(), min - a);
		count_just += std::distance(lower, upper);
		count += std::distance(upper, happiness.end());
		sum_upper += (sum.back() - sum[std::distance(happiness.begin(), upper)]) + std::distance(upper, happiness.end()) * a;
	}
	return sum_upper + (m - count + 0LL) * min;
}
bool can_make(const std::vector<long long int>& happiness, const int min, const long long int m) {
	long long int count = 0;
	for (const auto a : happiness) {
		auto lower = std::lower_bound(happiness.begin(), happiness.end(), min - a);
		count += std::distance(lower, happiness.end());
	}
	return count >= m;
}
int main() {
	int n; long long int m; std::cin >> n >> m;
	std::vector<long long int> happiness(n), sum{ 0LL }; for (auto& a : happiness) std::cin >> a;
	std::sort(happiness.begin(), happiness.end());
	for (auto a : happiness) sum.push_back(sum.back() + a);
	long long int min = 0;
	long long int max = happiness.back() * 2 + 1;
	while (min < max) {
		const auto mid = (min + max) / 2;
		if (can_make(happiness, mid, m)) {
			min = mid + 1;
		}
		else {
			max = mid;
		}
	}
	std::cout << do_m(happiness, sum, max - 1, m) << std::endl;
}

