ll check(ll sz) {
  return (pw2_inv[sz] - pw2_inv[n-1] + mod) % mod;
}

void zenhoui(ll num, ll par) {
  ll parSize = n - size[num];
  ll temp = pw2_inv[n-1];
  if (parSize != 0) {
    temp = (temp + check(n-1-parSize)) % mod;
  }
  for (ll i : e[num]) if (i != par) {
    temp = (temp + check(n-1-size[i])) % mod;
    zenhoui(i, num);
  }
  ans = (ans + (1 + mod - temp) * pw2_inv[1] % mod) % mod;
}

