int n;
void madd(int& a, int b) {
    a += b;
    if (a >= M) a -= M;
}
int mult(int a, int b) {
    return (1LL*a*b) % M;
}
int msub(int a, int b) {
    madd(a,M-b);
    return a;
}
int modexp(int a, int b) {
    int res = 1;
    while (b > 0) {
        if (b&1) res = mult(res,a);
        a = mult(a,a);
        b >>= 1;
    }
    return res;
}
int inverse(int x) {
    return modexp(x,M-2);
}

vector<int> adj[maxn];
int sz[maxn];
void dfs(int i, int p) {
    sz[i] = 1;
    for (int j: adj[i]) {
        if (j == p) continue;
        dfs(j,i);
        sz[i] += sz[j];
    }
}

int f(int i, int p, int k) {
    //cout << i << ' ' << p << ' ' << k << endl;
    //if color node i black
    int res = 0;
    for (int j: adj[i]) {
        if (j == p) continue;
        madd(res,f(j,i,1));
    }
    //if color node i white
    int r2 = 0;
    for (int j: adj[i]) {
        if (j == p) continue;
        madd(r2,f(j,i,k));
    }
    int s = sz[i]-1;
    if (k) {
        madd(r2,mult(msub(modexp(2,s),1),inverse(modexp(2,s))));
    }
    else {
        int pr = 1;
        pr = msub(pr,inverse(modexp(2,s)));
        for (int j: adj[i]) {
            if (j == p) continue;
            pr = msub(pr,mult(inverse(modexp(2,s-sz[j])),
                              mult(msub(modexp(2,sz[j]),1),inverse(modexp(2,sz[j])))));
        }
        madd(r2,pr);
    }
    madd(res,r2);
    res = mult(res,inverse(2));
    return res;
}

