ll MOD = 1000000007; ll HALF = 500000004;
ll n;
ll ans = 0;
vector<ll> pows(200000);
vector<vector<ll> > adj(200000);

ll dfs(ll x, ll p) {
	ll cnt = 1;
	ll tmp = 1 - pows[n-1] + MOD;
	for (auto v : adj[x])
	{
		if (v == p) continue;
		ll w = dfs(v, x);
		tmp -= pows[n-1-w] - pows[n-1] - MOD;
		cnt += w;
	}
	if (n > cnt) tmp -= pows[cnt-1] - pows[n-1] - MOD;
	tmp = (tmp * HALF) % MOD;
	ans = (ans + tmp) % MOD;

	return cnt;
}


