int pow(int a, int b) {
    if(b == 0) return 1;
    if(b%2) return a*pow(a, b-1)%mod;
    return pow(a*a%mod, b/2)%mod;
}

void fill_pow() {
    int cur = 1;
    for(int i = 0; i <= n; ++i) {
        pw[i] = cur;
        cur = (cur*2)%mod;
    }
}

void dfs(int cur, int par) {
    ct[cur] = 1;
    int to_add = pw[n-1] - 1;
    for(int child : graph[cur]) {
        if(child != par) {
            dfs(child, cur);
            int cct = ct[child];
            ct[cur] += cct;
            to_add -= pw[cct] - 1;
        }
    }
    to_add -= pw[n-ct[cur]] - 1;
    num = (num + to_add)%mod;
}

