class EulerTourForVertex{
public:
	vector<ll> leftindex, rightindex;
	vector<vector<ll>> g;
	ll pos;

	EulerTourForVertex() {}
	EulerTourForVertex(vector<vector<ll>> &g): leftindex(g.size()), rightindex(g.size()), g(g) {}
	EulerTourForVertex(ll n) : leftindex(n), rightindex(n), g(n) {}

	void dfs(ll v,ll p){
		leftindex[v]=pos++;
		for(ll nextv:g[v]){
			if(nextv==p) continue;
			dfs(nextv,v);
		}
		rightindex[v]=pos;
	}

	//u,v間に無向辺を追加
	void add_edge(ll u, ll v){
		g[u].emplace_back(v);
		g[v].emplace_back(u);
	}

	//オイラーツアー構築
	void build(ll v=0){
		pos=0;
		dfs(v,-1);
	}

	//オイラーツアー上での頂点vの始点indexを返す
	ll index(ll v){return leftindex[v];}

	//頂点vの行きがけ⇔帰りがけ区間(部分木)へ関数fを適用する
	//vの部分木に区間[leftindex[v], rightindex[v])が対応する
	template<typename F>
	void exec(ll v, F f){
		f(leftindex[v], rightindex[v]);
	}
};
