int main() {

    ios::sync_with_stdio(false); // stdioを使うときはコメントアウトすること
    cin.tie(nullptr);            // インタラクティブ問題ではコメントアウトすること

    ll n = inp1;
    vector<vector<ll>> g(n);
    REP(i, n-1) {
        ll a = inp1, b = inp1;
        a--; b--;
        g[a].push_back(b);
        g[b].push_back(a);
    }

    ll root = 0;

    vector<ll> depth(n, INF);
    {
        deque<ll> q = {root};
        depth[root] = 0;
        while (q.size()) {
            ll u = q.front(); q.pop_front();
            for (ll v : g[u]) {
                if (depth[v] == INF) {
                    depth[v] = depth[u] + 1;
                    q.push_back(v);
                }
            }
        }
    }

    vector<ll> toposo(n);
    iota(ALL_OF(toposo), 0);
    sort(ALL_OF(toposo), [&](ll i, ll j) {
        return depth[i] > depth[j];
    });

    vector<ll> offspring(n, 1); // 自身を含めた子孫ノードの数
    REP(_i, n) {
        ll i = toposo[_i];
        for (ll j : g[i]) if (depth[i] > depth[j]) {
            offspring[j] += offspring[i];
        }
    }

    ll ans = 0;
    REP(i, n) {
        vector<ll> branches;
        if (i == root) {
            for (ll j : g[i]) {
                branches.push_back(offspring[j]);
            }
        } else {
            branches.push_back(offspring[root] - offspring[i]);
            for (ll j : g[i]) if (depth[j] > depth[i]) {
                branches.push_back(offspring[j]);
            }
        }
        if (branches.size() < 2) continue;
        ll pb0 = powll(invll(2), n-1);
        ll pb1 = 0;
        for (ll sj : branches) {
            // pb1 += pb0 * (powll(2, sj) - 1);
            pb1 += (powll(2, sj) - 1 + pdiv) % pdiv * pb0 % pdiv;
            pb1 %= pdiv;
        }
        ans += (1 - pb0 - pb1 + pdiv * 2) % pdiv * invll(2) % pdiv;
        ans %= pdiv;
    }
    say(ans);

}

