long long powMod(long long x, long long n, long long mod) {
    long long res = 1;
    while (n > 0) {
        if (n & 1) res = res * x % mod;
        x = x * x % mod;
        n >>= 1;
    }
    return res;
}

int calc_size(int pos, int par){
    int ret = 1;
    for(auto e:G[pos]){
        if(e.to==par)continue;
        ret += calc_size(e.to, pos);
    }
    return sz[pos] = ret;
}

ll contain_black(int n){
    return (1 + MOD - powMod((MOD+1)/2, n, MOD)) % MOD;
}

ll all_white(int n){
    return powMod((MOD+1)/2, n, MOD);
}

void dfs(int pos, int par){
    ll prob = 1;
    ll white_only = all_white(N-1);
    prob += MOD - white_only;
    prob %= MOD;

    dump(pos, par, white_only, prob);


    for(auto e:G[pos]){
        ll aw, cb;
        if(e.to == par){
            aw = all_white(N-sz[pos]);
            cb = contain_black(N-sz[pos]);
        }else{
            aw = all_white(sz[e.to]);
            cb = contain_black(sz[e.to]);
        }
        ll sub = white_only * powMod(aw, MOD-2, MOD);
        sub %= MOD;
        sub *= cb;
        sub %= MOD;
        prob += MOD - sub;
        prob %= MOD;
    }
    (prob *= (MOD+1)/2) %= MOD;

    probabilities[pos] = prob;

    for(auto e:G[pos]){
        if(e.to == par)continue;
        dfs(e.to, pos);
    }
}

