ll memo[200050];
bool done[200050];

ll pow2(ll n, ll m){
  if(done[n]) return memo[n];
  done[n]=true;
  ll t = n;
  ll a =2LL;
  ll ret = 1LL;
  for (; n > 0LL; n >>= 1LL, a = a * a % m) {
	if (n % 2LL == 1LL) {
		ret = ret * a % m;
	}
  }
  memo[t]=ret;
  return ret;
}

ll pow(ll a, ll n, ll m) {
	ll ret = 1LL;
	for (; n > 0LL; n >>= 1LL, a = a * a % m) {
		if (n % 2LL == 1LL) {
			ret = ret * a % m;
		}
	}
	return ret;
}

graph children;
vector<bool> seen;
vector<ll> part;
ll N;

void dfs(const graph &g, ll x,ll parent){
  seen[x]=true;
  if(parent!=-1)children[parent].push_back(x);
  for(auto nx:g[x]){
    if(seen[nx]) continue;
    seen[nx]=true;
    dfs(g,nx,x);
  }
  if(parent!=-1) {
    part[parent]=0LL;
    for(auto c:children[parent]) part[parent]+=part[c];
    part[parent]++;
  }
}

ll f(const graph &g,ll i){
  if(children[i].empty()) return 0LL;
  ll ans = pow2(N-1LL,mod)-1LL;
  map<ll,ll> m;
  for(auto x:children[i]){
    m[part[x]]++;
  }
  m[N-part[i]]++;
  for(auto x:m){
    ans=(ans-((pow2(x.first,mod)-1)*x.second)%mod)%mod;
  }
  return ans;
}
