  }
  dfs(g,0,-1);
  ll ans = 0LL;
  for(ll i = 0LL; i < N; i++){
    ans =( ans + f(g,i))%mod;
  }
  if(ans<0) ans+=mod;
  ll y = pow2(N,mod);
  ans = (ans*pow(y,mod-2,mod))%mod;
  cout<<ans<<endl;
}

