    REP(i, n) {
        FOR(j, edges[i]) {
            if (j->first == -1) continue;
            ll x = modpow(2, j->first, MOD), y = modpow(2, n - (j->first), MOD);
            ex_numerator += (x-1) * (y-1) % MOD;
            ex_numerator %= MOD;
        }
    }
    ex_numerator += ex_denominator;
    ex_numerator %= MOD;
    ex_numerator += MOD - 1;
    ex_numerator %= MOD;
