template<long long mod>
class modint{
private:
  long long a;
public:
  constexpr modint(const long long x = 0) noexcept : a(x%mod) {}
  constexpr long long& value() noexcept { return a; }
  constexpr const long long& value() const noexcept { return a; }
  constexpr modint operator+(const modint rhs) const noexcept {
    return modint(*this) += rhs;
  }
  constexpr modint operator-(const modint rhs) const noexcept {
    return modint(*this) -= rhs;
  }
  constexpr modint operator*(const modint rhs) const noexcept {
    return modint(*this) *= rhs;
  }
  constexpr modint operator/(const modint rhs) const noexcept {
    return modint(*this) /= rhs;
  }
  constexpr modint& operator+=(const modint rhs) noexcept {
    a += rhs.a;
    if(a >= mod) a -= mod;
    return *this;
  }
  constexpr modint &operator-=(const modint rhs) noexcept {
    if(a < rhs.a) a += mod;
    a -= rhs.a;
    return *this;
  }
  constexpr modint& operator*=(const modint rhs) noexcept {
    a = a*rhs.a%mod;
    return *this;
  }
  constexpr modint& operator/=(modint rhs) noexcept {
    long long k = mod-2;
    while(k > 0){
      if(k&1){
        *this *= rhs;
      }
      rhs *= rhs;
      k /= 2;
    }
    return *this;
  }
  friend ostream& operator<<(ostream &os, const modint &X){
    return os << X.a;
  }
  friend istream& operator>>(istream &is, modint &X){
    is >> X.a;
    X.a %= mod;
    if(X.a < 0) X.a += mod;
    return is;
  }
};

using Graph = vector<vector<int>>;
using mint = modint<(int)1e9+7>;

int subtree_size(const Graph& G, int v, int p, vector<int> &S){
  for(auto v_ : G[v]){
    if(v_ == p) continue;
    S[v] += subtree_size(G,v_,v,S);
  }
  ++S[v];
  return S[v];
}

template<typename T>
T power(T x, long long k){
  T ret{1};
  while(k > 0){
    if(k&1) ret *= x;
    x *= x;
    k /= 2;
  }
  return ret;
}

mint dfs(const Graph& G, int v, int p, const vector<int> &S, int s){
  mint ret(0);
  int sum = 0;
  vector<int> T;
  for(auto v_ : G[v]){
    if(v_ == p) continue;
    sum += S[v_];
    T.push_back(S[v_]);
  }
  sum += s;
  T.push_back(s);
  mint one(1);
  ret += one/2;
  for(auto t : T){
    int s_ = sum - t;
    ret -= (one-power(one/2,t))*power(one/2,s_+1);
  }
  ret -= power(one/2,sum+1);
  for(auto v_ : G[v]){
    if(v_ == p) continue;
    int s_ = sum - S[v_] + 1;
    ret += dfs(G,v_,v,S,s_);
  }
  return ret;
}

