long long MOD = 1000000007, R, ANS = 0;

long long Calc(long long A, long long B) {
	if (B == 0) return 1;
	if (B % 2 == 0) {
		long long C = Calc(A, B / 2);
		return (C * C) % MOD;
	}
	return (A * Calc(A, B - 1)) % MOD;
}

long long DFS(long long P, long long Q) {
	long long COUNT = 0;
	for (int NP : V[P]) {
		if (NP != Q) {
			COUNT += DFS(NP, P);
		}
	}
	return X[P] = COUNT + 1;
}

int main() {
