	DFS(0, -1);
	for (int i = 0; i < N; i++) {
		vector<long long> W;
		for (int j : V[i]) {
			if (X[j] < X[i]) W.push_back(X[j]);
		}
		if (N != X[i]) W.push_back(N - X[i]);
		long long MUL = 1;
		for (int j = 0; j < W.size(); j++) {
			MUL *= Calc(R, W[j]);
			MUL %= MOD;
		}
		long long COUNT = 0;
		for (int j = 0; j < W.size(); j++) {
			COUNT += (MUL * Calc(2, W[j])) % MOD;
			COUNT %= MOD;
		}
		COUNT = (COUNT - (MUL * (W.size() - 1)) % MOD + MOD) % MOD;
		COUNT = (1 - COUNT + MOD) % MOD;
		ANS += COUNT;
		ANS %= MOD;
	}
	cout << (ANS * R) % MOD << endl;
}

