template <typename Monoid, typename UndirectedTree>
auto dp_on_tree(UndirectedTree const& g) {
  Monoid e{};
  size_t n = g.size();
  std::vector<size_t> parent(n, -1_zu);

  std::vector<std::vector<Monoid>> dp0(n), dp1(n);
  std::vector<Monoid> dp(n);
  for (size_t i = 0; i < n; ++i) {
    dp0[i].resize(g[i].size()+1, e);
    dp1[i].resize(g[i].size()+1, e);
  }

  make_fix_point([&](auto dfs0, size_t v, size_t p) -> Monoid {
      Monoid res = e;
      for (size_t i = 0; i < g[v].size(); ++i) {
        size_t u = g[v][i].target();
        if (u == p) {
          parent[v] = i;
          continue;
        }
        Monoid tmp = dfs0(u, v).f(g[v][i].weight());
        res.append(tmp);
        dp0[v][i+1] = dp1[v][i] = tmp;
      }
      return res;
  })(0, -1_zu);

  make_fix_point([&](auto dfs1, size_t v, size_t p, size_t pi) -> void {
      if (v != 0) {
        Monoid tmp = (dp0[p][pi] + dp1[p][pi+1]).f(g[p][pi].weight());
        dp0[v][parent[v]+1] = tmp;
        dp1[v][parent[v]] = tmp;
      }
      {
        for (size_t i = 1; i < dp0[v].size(); ++i)
          dp0[v][i].prepend(dp0[v][i-1]);
        for (size_t i = dp1[v].size()-1; i--;)
          dp1[v][i].append(dp1[v][i+1]);
        dp[v] = dp1[v][0];
      }
      for (size_t i = 0; i < g[v].size(); ++i) {
        size_t u = g[v][i].target();
        if (u != p) dfs1(u, v, i);
      }
  })(0, -1_zu, -1_zu);

  return dp;
}

class neko {
public:
  using value_type = mi;

private:
  value_type s = value_type(1);
  value_type p = value_type(0);

public:
  neko() = default;
  neko(neko const&) = default;
  neko(neko&&) = default;
  neko(value_type s, value_type p): s(s), p(p) {}

  neko& operator =(neko const&) = default;
  neko& operator =(neko&&) = default;

  neko& append(neko const& other) {
    s *= other.s;
    p += other.p;
    return *this;
  }
  neko& prepend(neko const& other) {
    return append(other);
  }
  neko operator +(neko const& other) const {
    return neko(*this).append(other);
  }
  template <typename Tp>
  neko f(Tp const&) const {
    return neko(s/2, (1-s/2)/(s/2));
  }
  value_type get() const {
    return (1-s-s*p) / 2;
  }
};

