struct rerooting{
  ll N,E;
  mat g,l,r,v;
  using func=function<ll(ll,ll)>;
  func merge,act;
  vector<int> vis,parid,solvelist;
  rerooting(mat &G,ll I,func p,func q):E(I),g(G),v(G),merge(p),act(q){
    N=G.size();
    vis.resize(N,0);
    parid.resize(N);
    l.resize(N);
    r.resize(N);
  }
  ll dfs(int id,int p){
    int i;
    parid[id]=p;
    vis[id]=1;
    ll res=E;
    rep(i,g[id].size()){
      if(vis[g[id][i]]){
        vis[id]+=i;
        continue;
      }
      solvelist.eb(g[id][i]);
      v[id][i]=dfs(g[id][i],i);
      res=merge(res,v[id][i]);
    }
    return res+1;
  }
  ll call(int i,int j){
    ll res=E;
    if(j)res=merge(l[i][j-1],res);
    if(j+1!=(int)g[i].size())res=merge(res,r[i][j+1]);
    return res+1;
  }
  mat solve(int start){
    int i;
    vec res(N,E);
    dfs(start,-1);
    r[start]=l[start]=v[start];
    rep1(i,g[start].size())l[start][i]=merge(l[start][i-1],l[start][i]);
    brep(i,(int)g[start].size()-1)r[start][i]=merge(r[start][i],r[start][i+1]);
    for(auto x:solvelist){
      v[x][vis[x]-1]=call(g[x][vis[x]-1],parid[x]);
      r[x]=l[x]=v[x];
      rep1(i,g[x].size())l[x][i]=merge(l[x][i-1],l[x][i]);
      brep(i,(int)g[x].size()-1)r[x][i]=merge(r[x][i],r[x][i+1]);
    }
    return v;
    // rep(i,N){
