template <typename T>
T ExtendedGcd(T a, T b, T &x, T &y) {
  if (b) {
    T d = ExtendedGcd(b, a % b, y, x);
    y -= a / b * x;
    return d;
  } else {
    x = 1;
    y = 0;
    return a;
  }
}

template <typename T>
T ModuloInverse(T a, T m) {
  T x, y;
  ExtendedGcd(a, m, x, y);
  return (x % m + m) % m;
}

