const int64_t MOD = 1e9+7;
void add(int64_t& a, int64_t b){
    a = (a+b) % MOD;
}
void mul(int64_t& a, int64_t b){
    a = a*b % MOD;
}

vector<int64_t> fact, seq_inv, fact_inv;

void create_fact_mod(int num){
    fact[0] = fact[1] = 1;
    for(int i=2; i<=num; i++) fact[i] = fact[i-1] * i % MOD;
}

void create_seq_inv_mod(int num){
    seq_inv[0] = seq_inv[1] = 1;
    for(int i=2; i<=num; i++) seq_inv[i] = (MOD - MOD/i) * seq_inv[MOD%i] % MOD;
}

void create_fact_inv_mod(int num){
    fact_inv[0] = fact_inv[1] = 1;
    for(int i=2; i<=num; i++) fact_inv[i] = fact_inv[i-1] * seq_inv[i] % MOD;
}

void create_mod_tables(int num){
    fact.resize(num+1);
    seq_inv.resize(num+1);
    fact_inv.resize(num+1);
    create_fact_mod(num);
    create_seq_inv_mod(num);
    create_fact_inv_mod(num);
}

int64_t comb_mod(int n, int k){
    return fact[n] * fact_inv[n-k] % MOD * fact_inv[k] % MOD;
}

int64_t perm_mod(int n, int k){
    return fact[n] * fact_inv[n-k] % MOD;
}

int64_t power_mod(int64_t num, int64_t power){
    int64_t prod = 1;
    num %= MOD;
    while(power > 0){
        if(power&1) prod = prod * num % MOD;
        num = num * num % MOD;
        power >>= 1;
    }
    return prod;
}

int64_t extgcd(int64_t a, int64_t b, int64_t& x, int64_t& y){
    int64_t d = a;
    if(b != 0){
        d = extgcd(b, a%b, y, x);
        y -= (a/b) * x;
    }else{
        x = 1; y = 0;
    }
    return d;
}

int64_t inv_mod(int64_t a){
    int64_t x, y;
    extgcd(a, MOD, x, y);
    return (MOD + x%MOD) % MOD;
}

int N;
vector<int> edges[200000];
int64_t inv2 = inv_mod(2);

int64_t nothing[200000];
void dfs1(int i, int p){
    nothing[i] = inv2;
    for(int j : edges[i]) if(j != p){
        dfs1(j, i);
        mul(nothing[i], nothing[j]);
    }
}

int64_t ans = 0;
void dfs2(int i, int p, int64_t top){
    if(edges[i].size() > 1){
        vector<int64_t> vals;
        vals.push_back(top);
        int64_t m = top;
        for(int j : edges[i]) if(j != p){
            vals.push_back(nothing[j]);
            mul(m, nothing[j]);
        }
        int64_t res = 1;
        add(res, MOD - m);
        for(int64_t v : vals){
            int64_t sub = m * inv_mod(v) % MOD * (MOD+1-v) % MOD;
            add(res, MOD - sub);
        }
        mul(res, inv2);
        add(ans, res);
    }
    for(int j : edges[i]) if(j != p){
        int64_t top2 = top;
        mul(top2, nothing[i]);
        mul(top2, inv_mod(nothing[j]));
        dfs2(j, i, top2);
    }
}

