#define forep(i, k, n) for (int i = k; i < n; i++)
const int MOD = 1000000007;

ll modpow(ll m, ll n)
{
  ll res = 1;
  while (n > 0)
  {
    if (n & 1)
    {
      res = res * m % MOD;
    }
    m = m * m % MOD;
    n >>= 1;
  }
  return res;
}

int n;
vector<vector<int>> to(200000);

ll ans = 0;
int dfs(int v, int p)
{
  vector<int> ts; // Tからvを除いて得られる各部分木のサイズ
  int res = 1;    // vを根とする部分木のサイズ
  // vの子孫である部分木のサイズを計算
  for (int nv : to.at(v))
  {
    if (nv == p)
    {
      continue;
    }
    int t = dfs(nv, v);
    res += t;
    ts.push_back(t);
  }
  // vの祖先である部分木のサイズを計算
  if (p != -1)
  {
    ts.push_back(n - res);
  }
  int now = (modpow(2, n - 1) - 1 + MOD) % MOD;
  for (int t : ts)
  {
    now = (now - modpow(2, t) + 1 + MOD) % MOD;
  }
  ans = (ans + now) % MOD;
  return res;
}

