int res;

void Traverse(int v, int p)
{
    int dp[3] = {1, 0, 0};
    cnt[v] = 1;
    for (int i = 0; i < neigh[v].size(); i++) {
        int u = neigh[v][i];
        if (u == p) continue;
        Traverse(u, v);
        cnt[v] += cnt[u];
        int my[2] = {inv2[cnt[u]], (1 - inv2[cnt[u]] + mod) % mod};
        for (int j = 2; j >= 0; j--) {
            int prob = dp[j]; dp[j] = 0;
            for (int k = 0; k < 2; k++) {
                int nj = min(2, j + k);
                dp[nj] = (dp[nj] + ll(prob) * my[k]) % mod;
            }
        }
    }
    if (cnt[v] < n) {
        int my[2] = {inv2[n - cnt[v]], (1 - inv2[n - cnt[v]] + mod) % mod};
        for (int j = 2; j >= 0; j--) {
            int prob = dp[j]; dp[j] = 0;
            for (int k = 0; k < 2; k++) {
                int nj = min(2, j + k);
                dp[nj] = (dp[nj] + ll(prob) * my[k]) % mod;
            }
        }
    }
    res = (res + ll(dp[2]) * inv2[1]) % mod;
}

