    vector<mint> pw(n+1);
    pw[0]=1;pw[1]=pw[0]/2;
    for (int i = 2; i <= n; i++) {
        pw[i] = pw[i-1]*pw[1];
    }

    vector<int> sz(n,1);
    mint res = 0;
    function<void(int,int)> dfs = [&](int u,int p){
        res += pw[1];
        for (int v: g[u])if(v!=p){
            dfs(v,u);
            res -= pw[n-sz[v]] * (1-pw[sz[v]]);
            sz[u] += sz[v];
        }
        res -= pw[sz[u]] * (1-pw[n-sz[u]]);
        res -= pw[n];
    };
    dfs(0,-1);

    cout << res;
}

