typedef long long LL;
const int SIZEN = 200010;
const LL mod = 1e9+7;
struct Link{
    int to,next;
}link[SIZEN << 1];
int head[SIZEN],tot = 0;
int size[SIZEN] = {0};
LL pw[SIZEN] = {0};
void add(int from,int to){
    link[++tot].to = to;
    link[tot].next = head[from];
    head[from] = tot;
}
int N;
LL ans = 0;
LL qpow(LL x,LL len){
    LL ret = 1;
    for(;len;len>>=1){
        if(len & 1)ret = ret * x % mod;
        x = x * x % mod;
    }
    return ret;
}
void dfs(int x,int fa){
    size[x] = 1;
    for(int i = head[x];i;i=link[i].next){
        int p = link[i].to;
        if(p == fa)continue;
        dfs(p,x);
        size[x] += size[p];
    }
    int tmp = N - size[x];
    for(int i = head[x];i;i=link[i].next){
        int p = link[i].to;
        if(p == fa)continue;
        ans = (ans + (pw[tmp] - 1)*(pw[size[p]] - 1)%mod)%mod;
        //printf("%lld,tmp = %d\n",ans,tmp);
        tmp += size[p];
    }   
}
int main(){
    scanf("%d",&N);
    pw[0] = 1;
    for(int i = 1;i <= N;i++)pw[i] = pw[i-1] * 2 % mod;
    for(int i = 1;i < N;i++){
        int x,y;
        scanf("%d%d",&x,&y);
        add(x,y);add(y,x);
    }
    ans = 0;
    dfs(1,0);
    ans = ans * qpow(pw[N],mod-2) % mod;
    printf("%lld\n",ans);
    return 0;
}

