vvll cinGraph(ll nodeNum, ll edgeNum, bool isDirected){//無向false、有向true
	vvll to(nodeNum);
	REP(i, edgeNum){
		ll v, u; cin >> v >> u;
		v--; u--;
		to[v].push_back(u);
		if (!isDirected) to[u].push_back(v);
	}
	return move(to);
}

ll N;
vvll to;
vll num; //num[v] v以下のサブ木のノード数
vmll Q;
vmll halfpow;

void dfs(ll v, ll p){
	EACH(u, to[v]){
		if (u==p) continue;
		dfs(u, v);
		num[v] += num[u];
	}
	num[v]++;

	if (sz(to[v])==1){
		Q[v] = mll(0);
		return;
	}

	mll P = halfpow[1] - halfpow[N] * (sz(to[v])-1);
	EACH(u, to[v]){
		if (u==p){
			P += halfpow[num[v]];
		}
		else{
			P += halfpow[N-num[u]];
		}
	}
	Q[v] = mll(1)-P;
}


void solve()
{
	cin >> N;
	to = cinGraph(N, N-1, false);
	num.resize(N);
	Q.resize(N);
	halfpow.resize(N+10);
	{
		halfpow[0] = 1;
		mll h = mll(1)/2;
		rep(i, 1, N+9){
			halfpow[i] = halfpow[i-1]*h;
		}
	}

	dfs(0, -1);

	mll ans = Sum(Q);
	cout << ans << '\n';
}

int main(){
#if 1
	solve();
#else
	ll t;  cin >> t;
	rep(i, 0, t-1){
		solve();
	}
#endif
	return 0;
}

