int dfs(int v, int r){
	int tmp = 1;
	rep(i, sz(G[v])){
		int u =G[v][i];
		if(u != r){
			int x = dfs(u, v);
			con[v].pb(x);
			tmp += x;
		}
	}
	return tmp;
}

void solve(){
	dfs(0, -1);
	rep1(i, N-1){
		int s = 0;
		rep(j ,sz(con[i])){
			s += con[i][j];
		}
		con[i].pb(N-1-s);
	}
}

void output(){

	ll half = pow2(N-1);
	ll ans = mod_inv(2 * half, MOD);
	ll tmp = 0;

	rep(i, N){
  		ll x = 1;
  		rep(j, sz(con[i])){
  		x = (x + (pow2(con[i][j]) - 1))% MOD;
 	 	}
  	tmp += (half - x + MOD)%MOD;
  	}
  	ans = (ans * tmp)%MOD;
 	 cout<<ans<<endl;
}

