ll two_inv[101010];

P dfs(Graph& graph, ll v, ll par) {
	P ret = { 0,1 };

	Array kid;
	REP(i, graph[v].size()) {
		ll to = graph[v][i].to;
		if (to != par) {
			P temp = dfs(graph, to, v);
			ret.second += temp.second;
			(ret.first += temp.first) %= MOD;
			kid.push_back(temp.second);
		}
	}
	if(ret.second!=graph.size())kid.push_back(graph.size() - ret.second);
	if (kid.size() <2)return ret;
	ll temp = (1 + MOD - two_inv[graph.size() - 1]) % MOD;
	REP(i, kid.size()) {
		ll a = two_inv[graph.size() - 1];
		(a *= mod_inv(two_inv[kid[i]], MOD)) %= MOD;
		a *= (1 + MOD - two_inv[kid[i]]) % MOD;
		a %= MOD;
		(temp += MOD - a) %= MOD;
	}
	(temp *= mod_inv(2, MOD)) %= MOD;
	(ret.first += temp) %= MOD;
	return ret;
}

