int N;

vector<vector<int>> E_list;
ll dp[200000 + 100];
vector<int> sons[200000 + 100];

void dfs(int pos, int bef) {
	dp[pos] = 1;
	for (int i = 0; i < E_list[pos].size(); i++) {
		int nxt = E_list[pos][i];
		if (nxt == bef)continue;
		dfs(nxt, pos);
		dp[pos] += dp[nxt];
		sons[pos].push_back(dp[nxt]);
	}
