int main() {
	cin >> N;
	E_list.resize(N);
	for (int i = 0; i < N - 1; i++) {
		int a, b;
		cin >> a >> b;
		a--, b--;
		E_list[a].push_back(b);
		E_list[b].push_back(a);
	}

	dfs(0, -1);

	mint ans = 0;
	for (int i = 0; i < N; i++) {
		//端点なら、白く塗られようが、穴あきにはならない。
		if (E_list[i].size() == 1)continue;
		mint tmp1 = mint(1) * mint(1) / (mint)2;//まず、穴あき度+1するのは、白く塗られた場合のみ
		//自分からつながる部分木で少なくとも2つ以上に、黒く塗られてるものがあればよい。
		mint tmp2 = 1;
		//すべての部分木において、白で塗られているならば、穴あきにならない
		tmp2 -= modpow(mint(1) / (mint)2, N - 1);
		//1つの部分木しか黒く塗られてない場合でも、穴あきにならない
		//sonsはこのるーぷいがいでみないので、親の成分もとりあえず入れておく
		sons[i].push_back(N - dp[i]);

		for (int j = 0; j < sons[i].size(); j++) {
			tmp2 -= (1 - modpow(mint(1) / mint(2), sons[i][j])) * modpow(mint(1) / mint(2), N - 1 - sons[i][j]);
		}

		ans += tmp1 * tmp2;
	}
	cout << ans << endl;
	return 0;
}

