    	// need at least 2 to contain black
    	int none_prob = 1;
    	for (auto &j : conn[i]) 
    		none_prob *= inv(pw[j]), none_prob %= M;
    	int one_prob = 0;
    	for (auto &j : conn[i]) {
    		auto here = none_prob * pw[j];
    		here %= M;
    		here *= ((1 - inv(pw[j]) + M)) % M;
    		here %= M;
    		one_prob += here;
    		if (one_prob >= M)
    			one_prob -= M;
    	}
    	int contrib = (1 - none_prob - one_prob + M + M) % M;
    	contrib *= inv(2), contrib %= M;
    	ans += contrib;
    	if (ans >= M)
    		ans -= M;
    }
    cout << ans;
}

