	FOR(i,0,N){
		ll sum = 0;
		for(auto ie:ss.Ge[i]){
			int s;
			if(i != ss.u[ie]){
				s = ss.usize(ie);
			}else{
				s = ss.vsize(ie);
			}
			sum += s;
			(ans += MOD - calc(2,s,MOD) + 1 ) %= MOD;
		}
		(ans += calc(2,sum,MOD)) %= MOD;
		(ans += MOD - 1) %= MOD;
	}
	(ans *= calc(calc(2,N,MOD),MOD-2,MOD)) %= MOD;
	cout << ans << endl;
}

