void dfs(int now) {
    SIZE[now] = 1;
    for(auto to : paths[now]) {
        if(to == parent[now]) continue;
        parent[to] = now;
        children[now].push_back(to);
        dfs(to);
        SIZE[now] += SIZE[to];
    }
}

ll beki(ll a, ll b) {
    if(b == 0) return 1 % mod;
    ll ret = beki(a, b / 2);
    ret = ret * ret % mod;
    if(b & 1) ret = ret * a % mod;
    return ret;
}

ll inv(ll a) {
    return beki(a, mod - 2);
}

void f(int now) {
    for(auto to : children[now]) f(to);
    vector<ll> v;
    for(auto to : children[now]) {
        v.push_back(SIZE[to]);
