int n;
int info[maxn],Prev[maxn<<1],to[maxn<<1],cnt_e;
void Node(int u,int v){ Prev[++cnt_e]=info[u],info[u]=cnt_e,to[cnt_e]=v; }
int Pow(int base,int k){
	int ret=1;
	for(;k;k>>=1,base=1ll*base*base%mod) if(k&1) ret=1ll*ret*base%mod;
	return ret;
}
int f[maxn],g[maxn],h[maxn],sf[maxn];
int ans;

void dfs(int u,int ff){
	for(int i=info[u],v;i;i=Prev[i])
		if((v=to[i])!=ff){
			dfs(v,u);
			ans = (ans + (mod+1ll)/2 * h[u] % mod * sf[v]) % mod;
			f[u] = (f[u] + (1ll - f[u]) * sf[v]) % mod;
			h[u] = ((1ll - h[u]) * sf[v] + (1ll - sf[v]) * h[u]) % mod;
		}
	sf[u] = ((mod+1)/2+(mod+1ll)/2*f[u])%mod; 	
}

void dfs2(int u,int ff){
	ans = (ans + (mod+1ll)/2 * h[u] % mod * g[u]) % mod;
	for(int i=info[u],v;i;i=Prev[i])
		if((v=to[i])!=ff){
			int p = (g[u] + (1ll - g[u]) * 1ll * (f[u] - sf[v]) % mod * Pow(1-sf[v],mod-2)) % mod;
			g[v] =((mod+1)/2 + (mod+1ll)/2 * p) % mod;
			dfs2(v,u);
		}
}

