struct Edge {//グラフ
	ll to, cap, rev;
	Edge(ll _to, ll _cap, ll _rev) {
		to = _to; cap = _cap; rev = _rev;
	}
};
typedef vector<Edge> Edges;
typedef vector<Edges> Graph;

void add_edge(Graph& G, ll from, ll to, ll cap, bool revFlag, ll revCap) {
	G[from].push_back(Edge(to, cap, (ll)G[to].size()));
	if (revFlag)G[to].push_back(Edge(from, revCap, (ll)G[from].size() - 1));
}



ll dfs(Graph& g, ll v, ll par) {
	//辺の先の頂点の数を数える
	ll sum = 1;
	for (auto e : g[v]) {
		if (e.to != par) {
			if (e.cap == -1) e.cap = dfs(g, e.to, v);			
			sum += e.cap;
		}
	}
	return sum;
}

ll n;
ll two_inv[201010];

ll p(Graph& g, ll v) {
	//頂点が、穴になる確率

	if (g[v].size() == 1)return 0;
	ll ans = (1 - two_inv[n-1] + MOD) % MOD;//全てが白の可能性を引く
	for (auto e : g[v]) {

		ll num = dfs(g, e.to, v);
		ans -= (((1 - two_inv[num] + MOD) % MOD) * two_inv[n - 1 - num])%MOD;//一辺のみ黒を含む場合を引く
		(ans += MOD) %= MOD;
	}
	return (ans*two_inv[1])%MOD;
}

ll mod_pow(ll x, ll n, ll mod) {
	ll res = 1LL;
	while (n > 0) {
		if (n & 1) res = res * x % mod;
		x = x * x % mod;
		n >>= 1;
	}
	return res;
}

ll mod_inv(ll x, ll mod) {
	return mod_pow(x, mod - 2, mod);
}



