    for (auto e: G[v]){
        //fprintf(stderr, " %d -> %d\n", v, e.to);
        if (seen[e.to]) continue; 
        res = dfs(e.to);

        x = mod_pow(2, res, mod);
        (y += mod - x) %= mod;

        tot += res;

    }
    res = N - 1 - tot;
    if (res > 0){
        x = mod_pow(2, res, mod);
        (y += mod - x) %= mod;
