        g[b].push_back(a);
    }
    h.resize(n + 1);
    sub.resize(n + 1);
    dfs_h(1, 0);
    dfs_sub(1);
    i64 ans = 0;
    for (int u = 1; u <= n; ++u) {
        if (g[u].size() >= 2) {
            ans += (mod + 1) / 2 - inv(ipow(2, n));
            i64 par = n - 1;
            for (int v : h[u]) {
                ans += mod - (inv(ipow(2, n - sub[v])) - inv(ipow(2, n)));
                par -= sub[v];
            }
            ans += mod - (inv(ipow(2, n - par)) - inv(ipow(2, n)));
            ans %= mod;
        }
    }
    cout << ans << endl;
    return 0;
}

