	ll S = 0;
	ll sub = 0;
	fore(x, E[now]) {
		if (x != p) {
			dfs(x, now);
			S += childcnt[x];
			sub += (modpow(2,childcnt[x])-1+mod);
			sub %= mod;
		}
	}
	sum[now] += (modpow(2,S)- 1 - sub + 5LL*mod)%mod;
	sum[now] += ((modpow(2,S)-1LL)*(modpow(2,N-1-S)-1LL))%mod;
	sum[now] %= mod;
	childcnt[now] = S + 1;
}

