	sum.resize(N);
	dfs(0,-1);


	ll bunboinv = modpow(2,mod-2);
	bunboinv = modpow(bunboinv,N);
	ll bunshi = 0;
	for (int i = 0; i < N; i++) {
		bunshi += sum[i];
		bunshi %= mod;
	}
	ll ans = bunboinv * bunshi;
	ans %= mod;
	puts(ans);

	return 0;
}

