vector<int> G[SIZE],ADJ[SIZE];

ll extgcd(ll a,ll b,ll &x,ll &y){
	ll d = a;
	if(b != 0){
		d = extgcd(b,a%b,y,x);
		y -= (a/b)*x;
	}else{
		x = 1;
		y = 0;
	}
	return d;
}

ll mod_pow(ll x,ll count, ll mod){

	if(count == 0)return 1;
	ll ret = mod_pow((x*x)%mod,count/2,mod);
	if(count%2 == 1){

		ret = (ret*x)%mod;
	}
	return ret;
}


ll mod_inverse(ll a,ll m){
    ll x,y;
    extgcd(a,m,x,y);
    return (m+x%m)%m;
}


ll dfs(int node_id,int pre){

	ll ret = 1; //部分木のサイズ
	ll tmp;

	for(int i = 0; i < G[node_id].size(); i++){

		int child = G[node_id][i];
		if(child == pre)continue;

		tmp = dfs(child,node_id);
		ret += tmp;

		ADJ[node_id].push_back(tmp); //子の部分木のサイズ
	}

	if(pre != -1){

		ADJ[node_id].push_back(N-ret); //根方向の部分木のサイズ
	}

	//余事象(含まれない数を数え上げ、それを全体から引く)で、node_idが白としてSに含まれる場合の数を求める
	tmp = mod_pow(2,N-1,MOD); //自分のノードは白、自分以外は2^(N-1)通り
	tmp--; //全て白
	if(tmp < 0){

		tmp += MOD;
	}

	for(int i = 0; i < ADJ[node_id].size(); i++){

		ll work = mod_pow(2,ADJ[node_id][i],MOD); //部分木に少なくとも1つ黒があり、他の部分木が全て白
		work--; //黒を含む部分木が全て白の場合を除く
		if(work < 0){

			work += MOD;
		}
		tmp -= work;
		if(tmp < 0){

			tmp += MOD;
		}
	}

	ans += tmp;
	ans %= MOD;

	return ret;
}

int main(){

	scanf("%lld",&N);

	int from,to;

	for(int i = 0; i < N-1; i++){

		scanf("%d %d",&from,&to);
		from--;
		to--;

		G[from].push_back(to);
		G[to].push_back(from);
	}

	ans = 0;
	dfs(0,-1);

	ll mult = mod_pow(2,N,MOD);
	mult = mod_inverse(mult,MOD);

	ans *= mult;
	ans %= MOD;

	printf("%lld\n",ans);

	return 0;
}

