template <class T>
struct Rerooting {
  function<T(T, T)> merge;
  function<T(T)> prop;
  T ident;
  vector<vector<int>> G;
  vector<vector<T>> dat, cuml, cumr;
  vector<T> val;
  vector<int> parent_id;
  Rerooting(vector<vector<int>> _G, function<T(T, T)> _merge,
            function<T(T)> _prop, T _ident)
      : G(_G),
        merge(_merge),
        prop(_prop),
        ident(_ident),
        dat(_G.size()),
        cuml(_G.size()),
        cumr(_G.size()),
        parent_id(_G.size()),
        val(_G.size()) {}
  T dfs1(int u, int par) {
    dat[u].resize(G[u].size());
    cuml[u].resize(G[u].size() + 1);
    cumr[u].resize(G[u].size() + 1);
    cuml[u].front() = cumr[u].back() = ident;
    for (int i = 0; i < G[u].size(); ++i) {
      if (G[u][i] == par) {
        parent_id[u] = i;
        continue;
      }
      dat[u][i] = dfs1(G[u][i], u);
      cuml[u][i + 1] = merge(cuml[u][i], dat[u][i]);
    }
    for (int i = (int)G[u].size() - 1; i > parent_id[u]; --i) {
      dat[u][i] = dfs1(G[u][i], u);
      cumr[u][i] = merge(cumr[u][i + 1], dat[u][i]);
    }
    T ret = par == -1 ? ident
                      : merge(cuml[u][parent_id[u]], cumr[u][parent_id[u] + 1]);
    return prop(ret);
  }
  void dfs2(int u, int par) {
    val[u] = cuml[u].back();
    for (int i = 0; i < G[u].size(); ++i) {
      int v = G[u][i];
      if (v != par) {
        dat[v][parent_id[v]] = prop(merge(cuml[u][i], cumr[u][i + 1]));
        for (int j = parent_id[v]; j < G[v].size(); ++j) {
          cuml[v][j + 1] = merge(cuml[v][j], dat[v][j]);
        }
        for (int j = parent_id[v]; j >= 0; --j) {
          cumr[v][j] = merge(cumr[v][j + 1], dat[v][j]);
        }
        dfs2(v, u);
      }
    }
  }
  void solve() {
    dfs1(0, -1);
    dfs2(0, -1);
  }
};

int main() {
  ll N;
  io.read(N);
  vector<vector<int>> G(N);
  REP(i, N - 1) {
    int A, B;
    io.read(A, B);
    G[A - 1].push_back(B - 1);
    G[B - 1].push_back(A - 1);
  }
  Rerooting<ll> rr(
      G, [](ll l, ll r) { return l + r; }, [](ll a) { return a + 1; }, 0);
  rr.solve();
  modint ans = 0;
  REP(i, N) {
    modint t = modint(2).pow(N - 1) - 1;
    REP(j, G[i].size()) t -= modint(2).pow(rr.dat[i][j]) - 1;
    ans += t;
  }
  ans /= modint(2).pow(N);
  io.writeln(ans.x);
  return 0;
}

