ll modularExponentiation(ll x,ll n)
{
    int result=1;
    while(n>0)
    {
        if(n % 2 ==1)
            result=(result * x)%MOD;
        x=(x*x)%MOD;
        n=n/2;
    }
    return result;
}

void dfs(ll id,ll p1)
{
    ll sum = 0;
    for(auto X:v[id])
    {
        if(X!=p1)
        {
            dfs(X,id);
            sum += sz[X];
        }
    }
    sz[id] = 1 + sum;
}
void dfs1(ll id,ll p1)
{
    ll sum = 1;
    ll cnt = 0;
    for(auto X:v[id])
    {
        ll temp = p[sz[X]] - 1;
        cnt = (cnt + temp)%MOD;
        sum = (sum * (temp+1))%MOD;
    }
    sum = (sum - cnt - 1 + MOD)%MOD;
    ans = (ans + sum)%MOD;
    for(auto X:v[id])
    {
        if(X!=p1) 
        {
            sz[id] -= sz[X];
            sz[X] = n;
            dfs1(X,id);
            sz[X] = n - sz[id];
            sz[id] += sz[X];
        }    
    }

}
