int dfs(int v, int prev, const vector< vector<int> >& g, vector< vector<int> >& dp){
    int res = 0;

    rep(i, g[v].size()){
        if(g[v][i] == prev){
            continue;
        }
        if(dp[v][i] == -1){
            dp[v][i] = dfs(g[v][i], v, g, dp) + 1;
        }
        res += dp[v][i];
    }

    return res;
}

template<class T>
T power(T x, unsigned long long n){
    T res = T(1);
    while(n){
        if(n & 1ull){
            res *= x;
        }
        x *= x;
        n >>= 1;
    }
    return res;
}

