        vec.push_back(sz[u]);
    }
    vec.push_back(n - sz[v]);
    int val = 0;
    for (int i : vec) {
        val = (val + Pow(X, n - i - 1) - Pow(X, n - 1) + MOD) % MOD;
    }
    val = (val + Pow(X, n - 1)) % MOD;
    ans = (ans + X * (1 - val + MOD)) % MOD;
}

