{
	/***** MOD 関数ライブラリ *****/

	struct NT_Mod
	{
		static long long Add(long long x, long long y, long long mod)
		{
			x = (x + y) % mod;
			if (x >= mod) x -= mod;
			return x;
		}

		static long long Sub(long long x, long long y, long long mod)
		{
			x = (x - y) % mod;
			if (x < 0) x += mod;
			return x;
		}

		static long long Mul(long long x, long long y, long long mod)
		{
			x = (unsigned long long) x * y % mod;
			return x;
		}

		static long long Div(long long x, long long y, long long mod)
		{
			x = x * Inv(y, mod) % mod;
			return x;
		}

		static long long Pow(long long x, long long n, long long mod)
		{
			long long res = 1;
			if (0 < n)
			{
				res = Pow(x, n / 2, mod);
				res = Mul(res, res, mod);
				if (n % 2 != 0) res = Mul(res, x, mod);
			}
			return res;
		}

		static long long Inv(long long a, long long mod)
		{
			long long b = mod, u = 1, v = 0;

			while (b)
			{
				long long t = a / b;
				a -= t * b; swap(a, b);
				u -= t * v; swap(u, v);
			}

			u %= mod;
			return (u < 0) ? u + mod : u;
		}
	};

	/***** MOD 型ライブラリ *****/

	template<long long mod> struct NT_ModLL
	{	// 非型テンプレートパラメータ
		long long x;

		// コンストラクタ
		NT_ModLL() { x = 0; }
		NT_ModLL(long long x_)
		{
			x = x_ % mod + mod;
			if (x >= mod)
				x -= mod;
		}

		// 符号
		NT_ModLL operator + () const { return x; }
		NT_ModLL operator - () const { return (-x < 0) ? mod - x : -x; }

		// 加減乗除演算子
		NT_ModLL& operator += (NT_ModLL r)
		{
			if ((x += r.x) >= mod) x -= mod;
			return *this;
		}
		NT_ModLL& operator -= (NT_ModLL r)
		{
			if ((x -= r.x) < 0) x += mod;
			return *this;
		}
		NT_ModLL& operator *= (NT_ModLL r)
		{
			x = (unsigned long long) x * r.x % mod;
			return *this;
		}
		NT_ModLL& operator /= (NT_ModLL r)
		{
			x = x * Inv(r.x, mod) % mod;
			return *this;
		}

		NT_ModLL operator + (NT_ModLL r) const { return NT_ModLL(*this) += r; }
		NT_ModLL operator - (NT_ModLL r) const { return NT_ModLL(*this) -= r; }
		NT_ModLL operator * (NT_ModLL r) const { return NT_ModLL(*this) *= r; }
		NT_ModLL operator / (NT_ModLL r) const { return NT_ModLL(*this) /= r; }

		// 逆元 x^{-1} (主に除算演算子で使用)
		long long Inv(long long a, long long m)
		{
			long long b = m, u = 1, v = 0;

			while (b)
			{
				long long t = a / b;
				a -= t * b; swap(a, b);
				u -= t * v; swap(u, v);
			}

			u %= m;

			return (u < 0) ? u + m : u;
		}

		// 比較演算子
		bool operator == (NT_ModLL& r) const { return x == r.x; }
		bool operator != (NT_ModLL& r) const { return x != r.x; }
		bool operator <  (NT_ModLL& r) const { return x < r.x; }
		bool operator <= (NT_ModLL& r) const { return x <= r.x; }
		bool operator >  (NT_ModLL& r) const { return x > r.x; }
		bool operator >= (NT_ModLL& r) const { return x >= r.x; }

		// 入出力演算子
		friend ostream& operator << (ostream& s, NT_ModLL<mod> a)
		{
			s << a.x;
			return s;
		}
		friend istream& operator >> (istream& s, NT_ModLL<mod>& a)
		{
			s >> a.x;
			return s;
		}

		static NT_ModLL Pow(long long x, long long n)
		{
			NT_ModLL res = 1;
			if (0 < n)
			{
				res = Pow(x, n / 2);
				res = res * res;
				if (n % 2 != 0) res *= x;
			}
			return res;
		}
	};
}

namespace NyaGadget
{
	/***** DFSライブラリ *****/

	struct GT_NyaaDFS
	{
		ll N;
		NT_ModLL< 1000000007 > ans = 0;

		/**
		@brief DFS処理関数
		@param r 頂点vの根
		@param v 現在の頂点
		@param g 隣接リストか隣接行列
		**/
		long long Run(long long r, long long v, const std::vector<std::vector<long long>>& g)
		{
			ll res = 1;
			vt<ll> tsize;
			for (auto e : g[v])
			{	// 後戻りしないようにする
				if (e == r) continue;
				ll nyaa = Run(v, e, g);
				res += nyaa;
				tsize.push_back(nyaa);
			}
			if (r != -1) tsize.push_back(N - res);

			using mll = NT_ModLL< 1000000007 >;
			mll test = mll::Pow(2, N - 1) - 1;
			each(i, e, tsize) test -= (mll::Pow(2, e) - 1);
			ans += test;
			return res;
		}
	};
}

