const int MAX = 200005;
const long long MOD = 1000000007;

vector<int> G_bi[MAX];
vector<int> G[MAX];
int pr[200005]={};

int c[MAX]={};
void dfs(int x){
    for(int y : G[x]) dfs(y);
    int ret = 1;
    for(int y : G[x]) ret += c[y];
    c[x] = ret;
    return;
}

long long inv2[MAX]={};

void init_pow2(){
    inv2[0] = 1;
    inv2[1] = (MOD+1)/2;
    for(int i=2; i<MAX; i++){
        inv2[i] = inv2[1]*inv2[i-1]%MOD;
    }
}

int main(){
    long long n;
    cin >> n;
    init_pow2();

    for(int i=1; i<n; i++){
        int x,y;
