        G_bi[x].push_back(y);
        G_bi[y].push_back(x);
    }

    pr[1] = 1;
    queue<int> que;
    que.push(1);
    while(!que.empty()){
        int x = que.front();
        que.pop();
        for(int y : G_bi[x]){
            if(pr[y]==0){
                pr[y] = x;
                G[x].push_back(y);
                que.push(y);
            }
        }
    }

    dfs(1);

    long long ans=(1+(MOD-inv2[n])+(MOD-(n*inv2[1])%MOD))%MOD;
    for(int x=1; x<=n; x++){
        //cout << c[x] << endl;
        long long z = (inv2[c[x]]-1)*(inv2[n-c[x]]-1)%MOD;
