	}
	vector<int>depth(N,MOD);
	Calculate_Depth(edge,depth,0);
	vector<int>sum(N,0);
	Search(edge,depth,sum,0);
	long long int ans=0;
	for(int i=0;i<N;i++){
		//cout<<i<<endl;
		int box=N-1;
		long long int add=1;
		add+=MOD-power(power(2,N-1,MOD),MOD-2,MOD);
		add%=MOD;
		for(auto j:edge[i]){
			//cout<<j<<" "<<sum[j]<<endl;
			if(depth[i]<depth[j]){
				add+=MOD-(power(2,sum[j],MOD)+MOD-1)*power(power(2,N-1,MOD),MOD-2,MOD)%MOD;
				add%=MOD;
				box-=sum[j];
			}
		}
		add+=MOD-(power(2,box,MOD)+MOD-1)*power(power(2,N-1,MOD),MOD-2,MOD)%MOD;
		add%=MOD;
		ans+=add;
	}
	cout<<ans*power(2,MOD-2,MOD)%MOD<<endl;
}

