void _main()
{
    ll n; llin(n);
    V<t2> ablist; llinl2(ablist, n-1);

    S V<ll> linklist[200005];
    make_linklist(ablist, linklist);

    S ll levels[200005];
    S ll parents[200005];
    S V<ll> children[200005];
    make_parental_relation(linklist, 1, n, parents, children, levels);

    S V<ll> desc_cnt[200005];
    S ll desc_sum[200005];
    memset(desc_sum, 0, sizeof(desc_sum));
    S ll children_cnt[200005];
    srep (i, 1, n+1) children_cnt[i] = children[i].size();

    queue<ll> q;

    srep (i, 1, n+1) {
        if (children_cnt[i] == 0LL) q.push(i);
    }

    while (!q.empty()) {
        ll v = q.front(); q.pop();
        ll pv = parents[v];

        if (pv == v) continue;

        desc_cnt[pv].pb(desc_sum[v] + 1LL);
        desc_sum[pv] += (desc_sum[v] + 1LL);
        children_cnt[pv]--;
        if (children_cnt[pv] == 0LL) q.push(pv);
    }

    debug_printf("---- desc_sum\n");
    debug_print(desc_sum, 10);
    debug_printf("---- desc_cnt[1]\n");
    debug_print(desc_cnt[1]);

    ll all_cnt = mod_pow(2LL, n, MOD);
    ll all_inv = mod_inv(all_cnt, MOD);
    S ll mod_pows[200005];
    rep (i, 200005) mod_pows[i] = mod_pow(2LL, i, MOD);

    ll ans = 0LL;

    srep (v, 1, n+1) {
        if (desc_sum[v] == 0) continue;
        if (desc_sum[v] == n-1 && desc_cnt[v].size() == 1) continue;
        ll out_cnt = 1LL + mod_pows[n-1];
        out_cnt %= MOD;
        for (auto desc : desc_cnt[v]) {
            out_cnt += (mod_pows[desc] - 1LL);
            out_cnt %= MOD;
        }
        out_cnt += (mod_pows[n-desc_sum[v]-1] - 1LL);
        out_cnt %= MOD;

        debug_printf("out_cnt=%lld\n", out_cnt);

        ll ok_cnt = (all_cnt - out_cnt);

        ll incr = ok_cnt * all_inv;
        incr %= MOD;
        ans += incr;
        ans %= MOD;
    }

    cout << ans << endl;
}

