int dfs(int v) {
    ret += calc_div(1, 2) - uku;
    ret = (ret + mod) % mod;

    int child = 0;
    for (auto nv:graph[v]) {
        if (!visited[nv]) {
            visited[nv] = true;
            int x = dfs(nv);
            ll y = uku * (calc_pow(2, x) - 1 + mod);
            y %= mod;
            ret -= y, ret = (ret + mod) % mod;
            child += x;
        }
