const Int MAX = 300000;
const Int INV2 = 500000004;
Int itwo[MAX];
void init() {
    itwo[0] = 1;
    for (Int i = 1; i < MAX; i++) {
        itwo[i] = itwo[i - 1] * INV2 % MOD;
    }
}
int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    init();
    int N; cin >> N;
    vector<vector<int>> G(N);
    for (int i = 0; i < N - 1; i++) {
        int a, b; cin >> a >> b; a--, b--;
        G[a].emplace_back(b);
        G[b].emplace_back(a);
    }
    vector<int> nodes(N);
    Int ans = 0;
    auto recur = [&](auto&& recur, int node, int prev) -> void {
        nodes[node] = 1;
        vector<int> A;
        for (int next : G[node]) if (next != prev) {
            recur(recur, next, node);
            A.push_back(nodes[next]);
            nodes[node] += nodes[next];
        }
        A.push_back(N - nodes[node]);
        Int prob = 1;
        prob = (prob + MOD - itwo[N - 1]) % MOD;
        for (auto a : A) {
            prob = (prob + MOD - itwo[N - 1 - a] + itwo[N - 1]) % MOD;
        }
        ans = (ans + INV2 * prob) % MOD;
    };
    recur(recur, 0, -1);
    cout << ans << '\n';
    return 0;
}

