int f(int x){
    visited[x] = true;
    if (sz(children[x]) == 1) return 1;
    vi nodes;
    for(auto v: children[x]){
        if (visited[v]) continue;
        nodes.pb(f(v));
    }
    int subtree = accumulate(all(nodes), 0LL) + 1;
    if (n-subtree) nodes.pb(n-subtree);

    // ^ -x = ^ mod-1-x
    int zerotree = powll(2,mod-n);
    int onetree = 0;
    for(auto nd: nodes){
        int lit = 1 - powll(2, mod-1-nd) + mod;
        int dim = powll(2, mod-(n-nd));
        onetree = (onetree + lit * dim) % mod;
    }
    ret = (ret + (1 - zerotree - onetree + 2 * mod) * powll(2,mod-2)) % mod;

    return subtree;
}

