const u64 MAXV = 10000;

u64 modPow(u64 n, u64 k){
    if (k == 0) return 1LL % mod;
    u64 r = modPow(n, k >> 1);
    r = r * r % mod;
    if (k & 1) r = r * n % mod;
    return r;
}

u64 modinv(u64 a, u64 m) {
    u64 b = m, u = 1, v = 0;
    while (b) {
        u64 t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= m;
    if (u < 0) u += m;
    return u;
}

const u64 ONE = 1, NONE = 0, OTHER = 2;
