        return Childnum[i];
    }
    if (Child[i].size()==0){
        Childnum[i]=0;
        return 0;
    }
    int res=0;
    for (auto&& j:Child[i]){
        res+=dp(j)+1;
    }
    Childnum[i]=res;
    return res;
}
