            res = a * res % mod;
        }

        a = a * a % mod;
        x >>= 1;
    }
    return res;
}

ll dfs(int v, int prev = -1)
{
    //cout << "iji" << endl;
    ll s = 1;
    vector<ll> t;

    for (int i = 0; i < g[v].size(); i++)
    {
        int u = g[v][i];
        if (u == prev)
        {
            continue;
        }

        ll tmp = dfs(u, v);
        t.push_back(tmp);
        s += tmp;
    }

    t.push_back(n - s);

    if (t.size() == 1)
        return s;

    ll res = (p(2, n - 1) - 1) % mod;

    for (int i = 0; i < t.size(); i++)
    {
        res = (res - p(2, t[i]) + 1 + mod) % mod;
    }
    ans = (ans + res) % mod;
    //cout << "v = " << v << "  ans = " << ans << endl;
    return s;
}

