ll N;
vector<vector<int>> G(200005);
vector<ll> cnt(200005,0),par(200005,-1);
vector<bool> used(200005,false);

int dfs(int v){
  int res = 0;
  for(auto nv:G[v]){
    if(used[nv]) continue;
    par[nv] = v;
    used[nv] = true;
    res += dfs(nv);
  }
  return cnt[v] = res + 1;
}

int main(){
  cin >> N;
  for(int i=0; i<N-1; i++){
    int a,b;
    cin >> a >> b;
    a--;
    b--;
    G[a].push_back(b);
    G[b].push_back(a);
  }
  used[0] = true;
  dfs(0);
  mint ans=0,two=2;
  for(int i=0; i<N; i++){
    mint now = 0;
    ll sum = 0;
    for(auto nv: G[i]){
      if(nv == par[i]) continue;
      sum += cnt[nv];
      now += two.pow(cnt[nv]) - 1;
    }
    if(par[i] != -1) now += two.pow(N-sum-1) - 1;
    ans += two.pow(N-1) - 1 - now;
  }
  ans /= two.pow(N);
  cout << ans.x << endl;
  return 0;
}

