ll nodeCount;    // 辺の配列
vector<vector<ll>> E;  // 普通の隣接している点の配列
vector<vector<ll>> indexE;  // adjacents[i][j](iのj番目の隣接頂点)にとって、iが何番目の隣接頂点か
vector<vector<T>> childSubtreeRes;  // iを親とし、adjacents[i][j]を根とした部分木の値 
vector<T> nodeRes;  // iを根としたときの結果結果
vector<ll> parents;  // 親
vector<ll> order; // 行きがけ順
stack<ll> Stk;  // dfs用のstack


int main(){
  ll N;
  // 初期化と入力と前処理
  cin >> N ;
  if(N==1){   // ここに気をつける
    cout << 1 << endl;
    return 0;
  }
  nodeCount=N;
  parents = vector<ll> (N);
  E = vector<vector<ll>> (nodeCount,vector<ll> (0));
  indexE = vector<vector<ll>> (nodeCount,vector<ll> (0));
  childSubtreeRes = vector<vector<T>> (nodeCount,vector<T> (0));
  nodeRes = vector<T> (nodeCount);
  rep(i,N-1){
    ll A,B;
    cin >> A >> B;
    A--;B--;
    indexE[A].pb(E[B].size());
    indexE[B].pb(E[A].size());
    E[A].pb(B);
    E[B].pb(A);
  }
  rep(i,N){
    childSubtreeRes[i]=vector<T> (E[i].size());
  }

  //0を根としたdfs　行きがけ順を保存する
  Stk.push(0);
  parents[0] = -1;
  while(Stk.size()){
    ll node = Stk.top();
    Stk.pop();
    order.pb(node);
    for(int i=0;i<E[node].size();i++){
      ll to = E[node][i];
      if( to == parents[node] ) continue;
      Stk.push(to);
      parents[to]=node;
    }
  }

  //帰りがけ順で部分木の値を求めていく
  for(int i=order.size()-1;i>=1;i--){
    ll node = order[i];
    ll parent = parents[node];
    T result = identity;
    ll parentIndex = -1;
    for (int j=0;j<E[node].size();j++){       //隣接する点を調べる
      //もし隣接する点が親だったら、親のindexの記録だけする
      if(E[node][j] == parent) {parentIndex = j; continue;}
      result = merge(result,childSubtreeRes[node][j]);
    }
    childSubtreeRes[parent][indexE[node][parentIndex]]=addNode(result,node);
  }

  //行きがけ順で頂点の値を確定させていく
  for(int i=0;i<order.size();i++){
    ll node = order[i];
    // 可換群ならさらに早くできる
    if (Commutative_group){}
    else {
      ll node = order[i];
      //後ろからの累積和を格納する配列
      vector<T> accumsFromTail(E[node].size());
      accumsFromTail[accumsFromTail.size() - 1] = identity;
      for(int j=accumsFromTail.size()-1;j>=1;j--) accumsFromTail[j-1] =merge(childSubtreeRes[node][j],accumsFromTail[j]);
      //前からの累積和を持つ変数
      T accum = identity;
      for(int j=0;j<accumsFromTail.size();j++){
        //adjacents[node][j]が親、nodeが子の部分木について計算する
        //累積をマージして子部分木の値をマージし終えた後、頂点を追加する
        T result = addNode(merge(accum,accumsFromTail[j]),node);
        //その値を、親が持っている配列に結果を格納する(親にとって自分が何番目の隣接頂点なのかを調べて格納)
        childSubtreeRes[E[node][j]][indexE[node][j]] = result;
        //累積を更新
        accum = merge(accum, childSubtreeRes[node][j]);
      }
      //最後まで累積しきったものはnodeの子部分木を全てマージしたものになっているので、それに頂点を追加するとnodeの値となる
      nodeRes[node] = addNode(accum, node);
    }
  }

  ll X,Y,Z;
  Z=modpow(2,N-1,MOD);
  rep(i,N){
    //cout << nodeRes[i].sc.sc << endl;
    Y+=(Z-nodeRes[i].sc.sc+MOD)%MOD;
    Y%=MOD;
  }
  X=modpow(2,N,MOD);
  auto P=gcd_ext(X,MOD);
  P.fr=(P.fr+MOD)%MOD;
  cout << (P.fr*Y)%MOD << endl;
}

