vector<vector<int>> child;
vector<int> ts;
vector<int> rs;

int calcrs(int now, int par = -1){
    ts.push_back(now);
    rs[now] = 1;
    for (int c : edge[now]) {
        if (c == par) continue;
        child[now].push_back(c);
        rs[now] += calcrs(c, now);
    }
    return rs[now];
}

int main(){
    cin >> N;
    edge.resize(N+1);
    child.resize(N+1);
    rs.resize(N+1);
