        edge[B].push_back(A);
    }
    calcrs(1, 0);

    vector<ll> pow(N+1, 1);
    for (int i = 1; i <= N; i++) pow[i] = pow[i-1]*2%mod;

    ll ans = 0;
    for (int i = 1; i <= N; i++) {
        ll t = pow[N-1]-1;
        t += mod-(pow[N-rs[i]]-1);
        for (int c : child[i]) {
            t += mod-(pow[rs[c]]-1);
        }
        ans += t;
        ans %= mod;
    }
    cout << ans*modinv(pow[N])%mod << endl;
