using ll = long long;

ll MOD = 1000000007;

ll modpow(ll a, ll n) {
    if (n == 0) return 1;
    if (n % 2 == 1) {
        return a * modpow(a, n-1) % MOD;
    }
    ll h = modpow(a, n/2);
    return h * h % MOD;
}

ll modinv(ll a) {
    return modpow(a, MOD-2);
}

int N;
vector<int> G[200010];
vector<int> lv[200010];

int dfs(int v, int p) {
    int acc = 1;
    for (int w : G[v]) {
        if (w == p) continue;
        int l = dfs(w, v);
        lv[v].push_back(l);
        acc += l;
    }
    if (acc < N)
        lv[v].push_back(N-acc);
    return acc;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> N;
    for (int i = 0; i < N-1; ++i) {
        int a, b;
        cin >> a >> b;
        --a; --b;

        G[a].push_back(b);
        G[b].push_back(a);
    }

    dfs(0, -1);

    ll ans = 0;
    for (int i = 0; i < N; ++i) {
        ll b0 = 1LL;
        for (int l : lv[i]) b0 = b0 * modinv(modpow(2, l)) % MOD;
        ll b1 = 0;
        for (int l : lv[i]) {
            b1 = (b1 + b0 * modpow(2, l) % MOD * (1 - modinv(modpow(2, l)) + MOD) % MOD) % MOD;
        }

        ll vi = (1 - b0 - b1 + 2 * MOD) % MOD * modinv(2) % MOD;
        ans = (ans + vi) % MOD;
    }
    cout << ans << endl;

    return 0;
}

