const ll MOD = 1000000007;
const ll INV2 = (MOD + 1) / 2;

ll modpow(ll x, ll n, ll mod = MOD) {
    ll res = 1;
    while (n > 0) {
        if (n & 1) res = res * x % mod;
        x = x * x % mod;
        n >>= 1;
    }
    return res;
}

void pre_dfs(int cur, int par, const Graph& g, vector<ll>& cnt) {
    cnt[cur] = 1;
    for (int nex : g[cur]) {
        if (nex == par) continue;
        pre_dfs(nex, cur, g, cnt);
        cnt[cur] += cnt[nex];
    }
}

void dfs(int cur, int par, const Graph& g, const vector<ll>& cnt, ll& ans) {
    cerr << cur << " " << cnt[cur] << endl;
    int n = g.size();
    ll par_cnt = n - 1;
    for (int nex : g[cur]) {
        if (nex == par) continue;
        par_cnt -= cnt[nex];
    }

    ll hoge = modpow(INV2, n - 1);
    ll res = (MOD + 1 - hoge) % MOD;
    res = (res + MOD - hoge * modpow(2, par_cnt) % MOD * (MOD + 1 - modpow(INV2, par_cnt)) % MOD) % MOD;
    for (int nex : g[cur]) {
        if (nex == par) continue;
        res = (res + MOD - hoge * modpow(2, cnt[nex]) % MOD * (MOD + 1 - modpow(INV2, cnt[nex])) % MOD) % MOD;
        dfs(nex, cur, g, cnt, ans);
    }   
    (res *= INV2) %= MOD;
    (ans += res) %= MOD;
}

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int n;
    cin >> n;

    Graph g(n);
    for (int i = 1; i < n; ++i) {
        int a, b;
        cin >> a >> b;
        --a; --b;

        g[a].push_back(b);
        g[b].push_back(a);
    }

    vector<ll> cnt(n, 0);
    pre_dfs(0, -1, g, cnt);

    ll ans = 0;
    dfs(0, -1, g, cnt, ans);
    cout << ans << "\n";
    return 0;
}

