        n >>= 1;
    }
    return unity;
}

constexpr int MOD = 1e9 + 7;
vector<int> childcnt;
vector<vector<int>> tree;
vector<mint<MOD>> ans;
int n;

int dfs1(int v, int p) {
    childcnt[v] = 0;
    for (int &u : tree[v]) {
        if (u == p) continue;
        childcnt[v] += dfs1(u, v);
    }
    return childcnt[v] + 1;
}

void dfs2(int v, int p) {
    ans[v] = 1;
    ans[v] -= mint<MOD>(1) * pow(pow(mint<MOD>(2), MOD - 2), n - 1);
    for (int &u : tree[v]) {
        if (u == p) {
            ans[v] -= (pow(mint<MOD>(2), n - childcnt[v] - 1) - mint<MOD>(1)) * pow(pow(mint<MOD>(2), MOD - 2), n - 1);
        }
        else {
            dfs2(u, v);
            ans[v] -= (pow(mint<MOD>(2), childcnt[u] + 1) - mint<MOD>(1)) * pow(pow(mint<MOD>(2), MOD - 2), n - 1);
        }
    }
    ans[v] *= pow(mint<MOD>(2), MOD - 2);
}

