ll mod_inv(ll x)
{
  ll m = MOD, ret = 1, v = 0;
  while (m != 0)
  {
    ll t = x / m;
    x -= t * m;
    swap(x, m);
    ret -= t * v;
    swap(ret, v);
  }
  ret %= MOD;
  if (ret < 0)
    ret += MOD;
  return ret;
}

ll mod_pow(ll x, ll n)
{
  ll ret = 1;
  while (n > 0)
  {
    if (n & 1)
      ret = ret * x % MOD;
    x = x * x % MOD;
    n >>= 1;
  }
  return ret;
}

