int N;
map<int,vector<int>> to;

int dfs(map<int,vector<int>> adhoc_to){
    int n=0;
    stack<int> container;
    map<int,bool> visited;
    for(int i=0;i<N;i++) visited[i]=false;
    container.push(0);
    while(!container.empty()){
        int x = container.top();
        container.pop();
        visited[x] = true;
        n++;
        for(auto t:adhoc_to[x]){
            if(!visited[t]){
                container.push(t);
                visited[t] = true;
            }
        }
    }
    return n;
}

