            h[i + j] += f[i] * g[j];
            h[i + j] %= p;
        }
    }
    return h;
}
vel rui_f(vel& f, int k) {
    if (k == 0) { vel ans(n + 1, 0); ans[0] = 1; return ans; }
    if (k == 1) { return f; }
    vel qans = rui_f(f, k / 2);
    vel ans=mul(qans, qans);
    if (k % 2 == 1) { ans = mul(f, ans); }
    return ans;
}
signed main(){
    int n; cin >> n;
    int u = 0;
    vvel way(n);
    rep(i, n - 1) {
        int a, b; cin >> a >> b;
        a--; b--;
        way[a].push_back(b);
        way[b].push_back(a);
    }
    queue<int> q;
    q.push(u);
    vel dist(n, -1); dist[u] = 0;
    while (!q.empty()) {
        int x = q.front(); q.pop();
        for (auto nex : way[x]) {
            if (dist[nex] == -1 || dist[nex] > dist[x] + 1) {
                dist[nex] = dist[x] + 1;
                q.push(nex);
            }
        }
    }
    vel pa(n, -1);
    vvel chi(n);
    rep(i, n) {
        for (auto x : way[i]) {
            if (dist[x] > dist[i]) { chi[i].push_back(x); }
            else { pa[i] = x; }
        }
    }
    vel dp(n, 0);
    solve(0, chi,dp);
    vel pr(n + 1, 0);
    rep(i, n + 1) {
        pr[i] = rui(2, i, p) - 1;
        pr[i] *= rui(modinv(2,p), i, p);
        pr[i] %= p;
    }
    int ans = 0;
    rep(i, n) {
        vel pri;
        for (auto x : chi[i]) {
            pri.push_back(pr[dp[x]]);
        }
        if (dp[i] != n) {
            pri.push_back(pr[n - dp[i]]);
        }
        int qans = 1;
        int qprd = 1;
        for (auto x : pri) {
            qprd *= (p+1-x); qprd %= p;
        }
        int qsum = 0;
        for (auto x : pri) {
            qsum += x * modinv(p+1-x, p);
            qsum %= p;
        }
        qsum *= qprd; qsum %= p;
        qans -= (qsum + qprd); qans %= p;
        qans += p;
        ans += qans; ans %= p;
    }
    cout << (ans*modinv(2,p))%p << endl;
    return 0;
}

