    FOR0(j, si)
    {
        int v = graph[i][j];
        if( v == p) continue;
        find_sizes(v, i);
        sizes[i] += sizes[v];
    }
}
void dfs(int i, int p)
{
    int j, si = graph[i].size();
    ll sum = fast_exp(2, sizes[0] - sizes[i]);
    ll mul = sum;
    FOR0(j, si)
    {
        int v = graph[i][j];
        if( v == p) continue;
        dfs(v, i);
        ll cur = fast_exp(2, sizes[v]);
        mul *= cur;
        mul %= MOD;
        sum += (cur - 1);
        sum += MOD;
        sum %= MOD;
    }
    mul -= sum;
    mul += 2*MOD;
    mul %= MOD;
    holy[i] = mul;
}
