vb r;

void dfs1(int u) {
	r[u] = true;
	for (int v : g[u]) {
		if (r[v]) continue;		
		ch[u].push_back(v);		
		dfs1(v);
		k[u].push_back(1 + dp1[v]);
		dp1[u] += 1 + dp1[v];
	}
}

void dfs2(int u) {
	for (int v : ch[u]) {
		dp2[v] = dp2[u] + dp1[u] - dp1[v];
		k[v].push_back(dp2[v]);
		dfs2(v);
	}
}

const ll half = inv(2);

ll solve(int i) {
	int d = k[i].size();
	assert(d > 0);
	if (d == 1) return 0; // 端点は穴になり得ない	
	// iが穴でない場合は以下(互いに排反)
	// (1) iが黒(確率1/2)
	ll p1 = half;
	// (2) iが白(確率1/2)で，かつ，
	// (2-1) どの部分木にも黒がない(すなわち他の頂点が全て白)
	ll p21 = mpow(half, N);
	// (2-2) 黒のある部分木がちょうど1つ
	//  ※黒のある部分木⇔「白が1つもない部分木」でない部分木
	ll p22 = 0;
	for (int kj : k[i]) {
		// db(kj);
		ll temp = mmul(msub(1, mpow(half, kj)), mpow(half, N - kj));
		// dbl(temp);
		p22 = madd(p22, temp);
	}	
	ll res = 1;
	res = msub(res, p1);
	res = msub(res, madd(p21, p22));
	// dbt3(tl3(p1, p21, p22)); dbl(res);
	return res;
}

