class Solver {
 public:
  int n;
  vector<vector<int>> t;
  vector<int> sub, dep;
  Solver(LL n) : n(n), t(n), sub(n), dep(n){};

  void solve() {
    for (int i = 0; i < n - 1; ++i) {
      int a, b;
      cin >> a >> b;
      t[--a].push_back(--b);
      t[b].push_back(a);
    }
    dfs(0, -1, 0);
    Modint<> ans(0);
    Modint<> half = Modint<>(1) / 2;
    for (int i = 0; i < n; ++i) {
      if (t[i].size() == 1) continue;
      vector<int> a;
      int tmp = n - 1;
      for (int v : t[i]) {
        if (dep[v] > dep[i]) {
          a.push_back(sub[v]);
          tmp -= sub[v];
        }
      }
      if (tmp > 0) a.push_back(tmp);
      Modint<> prod(1);
      Modint<> prob_white_i(0);
      for (auto x : a) {
        prod *= half.mpow(x);
      }
      prob_white_i += prod;
      for (auto x : a) {
        auto p2 = prod;
        prob_white_i += prod / half.mpow(x) * (1 - half.mpow(x));
      }
      ans += (1 - prob_white_i) / 2;
    }

    cout << ans << endl;
  }
  void dfs(int c, int p, int d) {
    int cnt = 1;
    for (auto v : t[c]) {
      if (v != p) {
        dfs(v, c, d + 1);
        cnt += sub[v];
      }
    }
    sub[c] = cnt;
    dep[c] = d;
  }
};

