template<typename T> 
vector<int> dfs(map<int,T> adhoc_to, int const& vi){
    vector<int> vec;
    stack<int> container;
    vector<bool> visited(N,false);
    visited[vi] = true;

    while(accumulate(visited.begin(),visited.end(),0)<N){
        int n=0;
        int v=0;
        while(visited[v]) v++;
        container.push(v);
        while(!container.empty()){
            int x = container.top();
            container.pop();
            visited[x] = true;
            n++;
            for(auto t:adhoc_to[x]){
                if(!visited[t]){
                    container.push(t);
                    visited[t] = true;
                }
            }
        }
        vec.push_back(n);
    }
    return vec;
}

