ll mod_pow(ll x, ll n, ll mod) {
	ll res = 1LL;
	while (n > 0) {
		if (n & 1) res = res * x % mod;
		x = x * x % mod;
		n >>= 1;
	}
	return res;
}

ll mod_inv(ll x, ll mod) {
	return mod_pow(x, mod - 2, mod);
}

ll n;
ll two_inv[201010];

P p(Graph& g, ll v, ll par) {
	P ret = make_pair(0,1);//期待値、頂点数のペア

	Array kids;
	for(auto e:g[v]){
		if(e.to!=par){
			P kid = p(g,e.to,v);
			(ret.first += kid.first)%=MOD;
			ret.second+=kid.second;
			kids.push_back(kid.second);
		}
	}

	if(ret.second==n) return ret;
	kids.push_back(n-ret.second);//親側にある頂点数
	ll ans = two_inv[1];//穴になるのは白の場合のみ
	(ans += MOD - two_inv[n])%=MOD; //全部白の確率をひく
	for(auto kid:kids){
		(ans += MOD - ((1-two_inv[kid]+MOD)%MOD * two_inv[n-kid])%MOD)%=MOD;//一辺だけ黒を含む確率をひく
	}
	(ret.first+=ans)%=MOD;
	return ret;
}





