            s.push_back(siz[j]);
        if(par[i] != -1)
            s.push_back(n - siz[i]);

        mint pat = mpow(mint(2), n - 1);
        for(auto& t : s){
            pat -= mpow(mint(2), t) - 1;
        }
        --pat;

        ans += pat;
    }

    ans *= mpow(mpow(mint(2), n), MOD - 2);
    cout << ans << endl;
}

