using namespace std;

// a^n mod を計算する
long long modpow(long long a, long long n, long long mod) {
    long long res = 1;
    while (n > 0) {
        if (n & 1) res = res * a % mod;
        a = a * a % mod;
        n >>= 1;
    }
    return res;
}

// a^{-1} mod を計算する
long long modinv(long long a, long long mod) {
    return modpow(a, mod - 2, mod);
}

const ll MOD = 1e9+7;

vector<ll> dp(200010);
vector<vector<ll>> edges(200010);

ll dfs(ll now,ll parent){
    ll tmp = 1;
    for (auto e : edges[now]) {
        if(e!=parent){
            tmp += dfs(e, now);
            tmp %= MOD;
        }
    }
    return dp[now]=tmp;
}

int main() {
    ll n;
    std::cin >> n;

    for (int i = 0; i < n-1; i++) {
        ll a,b;
        std::cin >> a>>b;
        a--;b--;
        edges[a].push_back(b);
        edges[b].push_back(a);
    }

    dfs(0,-1);

    ll ans = 0;

    for (int i = 0; i < n; i++) {
        ll tmp=1-1*modinv(modpow(2,n-1,MOD),MOD)%MOD+MOD;
        tmp += MOD;
        tmp %= MOD;
        if(edges[i].size()<2){
            continue;
        }
        for (auto e : edges[i]) {
            if(dp[i]>dp[e]){
                tmp -= 1*modinv(modpow(2,n-1-dp[e],MOD),MOD)    %MOD*(1-1*modinv(modpow(2,dp[e],MOD),MOD)%MOD    +MOD)%MOD;
                tmp += MOD;
            }else{
                tmp -= 1*modinv(modpow(2,n-1-(n-dp[i]),MOD),MOD)%MOD*(1-1*modinv(modpow(2,(n-dp[i]),MOD),MOD)%MOD+MOD)%MOD;
                tmp += MOD;
            }
            tmp %= MOD;
        }
        ans += tmp*modinv(2,MOD)%MOD;
        ans %= MOD;
    }

    std::cout << ans << std::endl;
}

