// n 個の頂点のうち少なくとも 1 つが黒である確率
// 余事象：n 個の頂点すべてが白である確率
ll calc1(int n){
    ll yo = 1LL*inverse(power(2LL, n, MOD), MOD);
    return (1LL-yo+MOD)%MOD;
}

// 各部分木に黒が存在する確率が v[i] であるとき，
// 部分木のうち少なくとも 2 つに黒が存在する確率
// 余事象：1 つも黒が存在しない or 1 つの部分木だけに存在する
ll calc2(vector<ll> v){
    ll product = 1;
    rep(i, v.size()){
        product *= (1-v[i]+MOD)%MOD;
        product %= MOD;
    }
    ll yo = product; //全部が黒である確率
    rep(i, v.size()){
        yo += product * inverse((1-v[i]+MOD)%MOD, MOD)%MOD * v[i]%MOD;
        yo %= MOD;
    }
    return (1LL-yo+MOD)%MOD;
}

