const ll mo=1000000007;
ll ret;

ll modpow(ll a, ll n = mo-2) {
	ll r=1;a%=mo;
	while(n) r=r*((n%2)?a:1)%mo,a=a*a%mo,n>>=1;
	return r;
}

int dfs(int cur,int pre) {
	C[cur]=1;
	vector<ll> B;
	FORR(e,E[cur]) if(e!=pre) {

		B.push_back(dfs(e,cur));
		C[cur]+=B.back();
	}
	if(C[cur]<N) B.push_back(N-C[cur]);

	ll P[3]={(mo+1)/2,0,0};
	FORR(b,B) {
		ll w=modpow((mo+1)/2,b);
		b=(1+mo-w)%mo;
		ll Q[3]={};
		Q[0]=P[0]*b%mo;
		Q[1]=(P[1]*w+P[0]*b)%mo;
		Q[2]=(P[2]+P[1]*b)%mo;
		swap(P,Q);
	}

	ret+=P[2];

	return C[cur];
}


