        if (val < sum) {
          val += mod;
        }
        ans += val - sum + prod - 1 - first;
        ans %= mod;
        const auto j = *yet.cbegin();
        deg[j] -= 1;
        if (deg[j] <= 1) {
          q.push(j);
        }
      }
    }
  }

  int64_t r = 1;
