void solve(ostringstream& aout, long long N, std::vector<long long> A, std::vector<long long> B){
	// 1 番を根としたとき、iを親とする部分木のノード数
	vector<int> childNum(N + 1, 0);
	Graph G(N + 1);
	rep(i, N - 1) {
		add_edge(G, A[i], B[i]);
	}

	vector<bool> visited(N + 1, false);
	// dfs1: 部分木のノード数を計算
	function<int(int)> dfs1 = [&](int nowNode) -> int {
		if (visited[nowNode]) {
			return 0;
		}

		visited[nowNode] = true;
		int ret = 1;	// 1: 自分
		for (auto e : G[nowNode]) {
			int subTreeSize = dfs1(e.dst);
			ret += subTreeSize;
		}
		return childNum[nowNode] = ret;
	};

	// 根は1
	dfs1(1);

	//dfs2: 期待値を計算
	visited = vector<bool>(N + 1, false);
	vector<mint> ans(N + 1, mint(0));

	function<void(int)> dfs2 = [&](int nowNode) {
		if (visited[nowNode]) {
			return;
		}

		visited[nowNode] = true;
		// p: 各部分木が黒点をふくまない確率
		vector<mint> p;
		for (auto e : G[nowNode]) {
			int subTreeSize = 0;
			// 親側は全体から引いて求める
			if (visited[e.dst]) {
				subTreeSize = N - childNum[nowNode];
			}
			else {
