constexpr ll MOD = 1000000007;

// a^-1 mod p
ll inv(ll a,ll p){
  return ( a == 1 ? 1 : (1 - p*inv(p%a,a)) / a + p );
}

ll pow2(ll n) {
  if (n == 0) return 1;
  else if ((n%2) == 1) return (2 * pow2(n-1)) % MOD;
  else {
    ll h = pow2(n/2);
    return h * h % MOD;
  }
}

ll calc(ll n) {
  ll p2 = pow2(n);
  ll pi2 = inv(p2, MOD);
  return (p2 + MOD - 1) * pi2 % MOD;
}

ll solve(const vector<vecint>& t, vecll& ex, int i, int p) {
  vecll cp;
  ll cntc = 0;
  for(int j:t[i]) {
    if(j==p) continue;
    ll cs = solve(t,ex,j,i);
    cp.push_back(calc(cs));
    cntc += cs;
  }
  cp.push_back(calc(t.size() - cntc - 1));
  vecll fwd;
  vecll bwd;
  ll imul = 1;
  for(auto&& e:cp) {
    fwd.push_back(imul);
    imul *= (1 + (MOD - e)) % MOD;
    imul %= MOD;
  }
  boost::reverse(cp);
  imul = 1;
  for(auto&& e:cp) {
    bwd.push_back(imul);
    imul *= (1 + (MOD - e)) % MOD;
    imul %= MOD;
  }
  boost::reverse(cp);
  boost::reverse(bwd);
  ll ans = 1 + (MOD - imul);
  ans %= MOD;
  for(auto&& j:irange(0ul,cp.size())) {
    ll tmp = fwd[j] * bwd[j];
    tmp %= MOD;
    tmp *= cp[j];
    tmp %= MOD;
    ans += (MOD - tmp) % MOD;
    ans %= MOD;
  }
  ans *= inv(2, MOD);
  ans %= MOD;
  ex[i] = ans;
  return cntc + 1;
}

