  for(auto&& i:irange(0l,n-1)) {
    int a,b;
    cin>>a>>b;
    --a;--b;
    t[a].push_back(b);
    t[b].push_back(a);
  }
  vecll ex(n, 0);
  solve(t, ex, 0, -1);
  ll ans = 0;
  for(auto&& e : ex) {
    ans += e;
    ans %= MOD;
  }
  cout<<ans<<endl;
  return 0;
}

