inline void addedge(int from, int to) {
  e[++tot] = (Edges){to, head[from]};
  head[from] = tot;
  e[++tot] = (Edges){from, head[to]};
  head[to] = tot;
}

inline LL qpow(LL a, LL k) {
  LL re = 1;
  for (; k; k >>= 1, a = a * a % mod)
    if (k & 1) re = re * a % mod;
  return re;
}

void Dfs(int now, int fa) {
  size[now] = 1;
  for (RI i = head[now]; i; i = e[i].next)
    if (e[i].to != fa) {
      Dfs(e[i].to, now);
      (ans -= Bin[size[e[i].to]] - 1) %= mod;
      size[now] += size[e[i].to];
    }
  (ans -= Bin[n - size[now]] - 1) %= mod;
  ans += Bin[n - 1] - 1;
}

