  for (RI i = 1; i <= n; ++i)
    Bin[i] = Bin[i - 1] * 2 % mod;
  for (RI i = 1, x, y; i < n; ++i)
    read(x), read(y), addedge(x, y);
  Dfs(1, 0);
  printf("%lld\n", (ans + mod) % mod * qpow(qpow(2, n), mod - 2) % mod);

  return 0;
}

