int main() {
    const mint twoinv = mint(2).inv();

    int n;
    std::cin >> n;

    Graph<> tree(n);
    for (int i = 0; i < n - 1; ++i) {
        int u, v;
        std::cin >> u >> v;
        --u, --v;
        tree[u].emplace_back(u, v);
        tree[v].emplace_back(v, u);
    }

    mint ans = 0;
    std::function<int(int, int)> dfs =
        [&](int v, int r) {
            std::vector<int> ch;
            int sz = 0;

            for (auto e : tree[v]) {
                if (e.dst == r) continue;
                ch.push_back(dfs(e.dst, v));
                sz += ch.back();
            }
            ch.push_back(n - 1 - sz);

            mint sum = twoinv.pow(n - 1);
            for (auto c : ch) {
                sum += twoinv.pow(n - c - 1) - twoinv.pow(n - 1);
            }
            ans += twoinv * (mint(1) - sum);
            return sz + 1;
        };

    dfs(0, -1);
    std::cout << ans << std::endl;
    return 0;
}

