void extGCD(ll a, ll b, ll &p, ll &q) {
    if (b == 0) {
        p = 1, q = 0;
        return;
    }
    extGCD(b, a % b, q, p);
    q -= a / b * p;
}

int modinv(ll a, ll m) {
    ll p, q;
    extGCD(a, m, p, q);
    p %= m;
    if (p < 0)
        p += m;
    return p;
}

