template <std::uint_fast64_t Modulus> class modint {
  using u64 = std::uint_fast64_t;

public:
  u64 a;

  constexpr modint(const u64 x = 0) noexcept : a(x % Modulus) {}
  constexpr u64 &value() noexcept { return a; }
  constexpr const u64 &value() const noexcept { return a; }
  constexpr modint operator+(const modint rhs) const noexcept {
    return modint(*this) += rhs;
  }
  constexpr modint operator-(const modint rhs) const noexcept {
    return modint(*this) -= rhs;
  }
  constexpr modint operator*(const modint rhs) const noexcept {
    return modint(*this) *= rhs;
  }
  constexpr modint operator/(const modint rhs) const noexcept {
    return modint(*this) /= rhs;
  }
  constexpr modint &operator+=(const modint rhs) noexcept {
    a += rhs.a;
    if (a >= Modulus) {
      a -= Modulus;
    }
    return *this;
  }
  constexpr modint &operator-=(const modint rhs) noexcept {
    if (a < rhs.a) {
      a += Modulus;
    }
    a -= rhs.a;
    return *this;
  }
  constexpr modint &operator*=(const modint rhs) noexcept {
    a = a * rhs.a % Modulus;
    return *this;
  }
  constexpr modint &operator/=(modint rhs) noexcept {
    u64 exp = Modulus - 2;
    while (exp) {
      if (exp % 2) {
        *this *= rhs;
      }
      rhs *= rhs;
      exp /= 2;
    }
    return *this;
  }
};










int N;

typedef struct {
	int next_node;
	int count;
} conn;

vector<conn> edges[200000];


// 部分木のノード数を計算
int dfs( int node, int parent_node ){
	int count = 0;
	for ( auto& it : edges[node] ){ // node -> next_node を調べる
		if ( it.next_node != parent_node ){
			if ( it.count == -1 )
				it.count = dfs( it.next_node, node );
			count += it.count;
		}
	}
	return count+1;
}


int main(){
	cin >> N;

	for ( int i = 0; i < N-1; i++ ){
		int a, b;
		cin >> a >> b;
		a--; b--;
		edges[a].push_back({b,-1});
		edges[b].push_back({a,-1});
	}

	for ( int i = 0; i < N; i++ ){
		dfs(i, -1);
	}

//	for ( int i = 0; i < N; i++ ){
//		for ( auto it : edges[i] ){
//			cout << i << "->" << it.next_node << " count=" << it.count << endl;
//		}
//	}

	using mint = modint<1000000007>;
	vector<mint> pow2(N+1);
	{
		mint a = 1;
		for ( int i = 0; i <= N; i++ ){
			pow2[i] = a;
			a *= 2;
		}
	}

	mint result = 0; // 期待値 * 2^N
	for ( int i = 0; i < N; i++ ){
		//  穴あきの頂点である == そこから出る2つの辺の先に黒が1つ以上ある
		// i->j0, i->j1, i->j2
		// j0以降が全て白の確率 : pj0
		// iが穴でない確率 = p(iが黒) + p(iが白)*( tmp ) // tmp = pj0*pj1*pj2 + !pj0*pj1*pj2 + pj0*!pj1*pj2 + pj0*pj1*!pj2
		// iが穴である確率 = p(iが白)*!( tmp )

		if ( edges[i].size() >= 2 ){
			mint t = 1; // t = tmp * 2^(N-1)
			for ( auto it : edges[i] ){
				t += pow2[it.count]-1;
			}
			result += (pow2[N-1] - t);
		}
	}

	result /= pow2[N];
	cout << result.value() << endl;

	return 0;
}

