struct mint {
    ll x;
    mint (ll x = 0) : x((mod + x % mod) % mod) {}
    mint operator -() const { return mint(-x); }
    mint& operator += (const mint a) { // コンストラクタの、modで割った余りがくる
        if ((x += a.x) >= mod) x -= mod;
        return *this;
    }
    mint& operator -= (const mint a) {
        if ((x += -a.x + mod) >= mod) x -= mod;
        return *this;
    }
    mint& operator *= (const mint a) {
        (x *= a.x) %= mod;
        return *this;
    }
    mint operator + (const mint a) const {
        mint res(*this);
        return res += a; // ?
    }
    mint operator - (const mint a) const {
        mint res(*this);
        return res -= a;
    }
    mint operator * (const mint a) const {
        mint res(*this);
        return res *= a;
    }
    mint pow(ll t) const { // mint(a).pow(t) tは余りとったりしたらあかん
        if (t == 0) return 1;
        mint a = pow(t >> 1); // 再帰
        a *= a;
        if (t & 1) a *= *this;
        return a;
    }
    // 逆元
    mint inv() const {
        return pow(mod - 2);
    }
    mint& operator /= (const mint a) { // invを利用
        return (*this) *= a.inv();
    }
    mint operator / (const mint a) const {
        mint res(*this);
        return res /= a;
    }
    friend ostream &operator << (ostream &s, mint a) { return s << a.x; }
};

void solve() {
    int n;
    cin >> n;
    vector<vector<int> > G(n);
    rep(i, n - 1) {
        int a, b;
        cin >> a >> b;
        --a; --b;
        G[a].eb(b);
        G[b].eb(a);
    }

    vector<mint> d(n, 1);
    auto dfs = [&](auto&& dfs, int v, int p) -> int {
        int sum = 0;
        for (int nv : G[v]) {
            if (nv == p) continue;
            int cnt = dfs(dfs, nv, v);
            sum += cnt;
            d[v] += modpow(2, cnt, mod) - 1; // 1つの枝だけ1つ以上黒がある
        }
        // 親方向
        int rest = (n - 1) - sum;
        d[v] += modpow(2, rest, mod) - 1;

        d[v] = (mint)modpow(2, n - 1, mod) - d[v]; // 余事象
        return sum + 1;
    };
    rep(i, n) {
        if (sz(G[i]) == 1) {
            dfs(dfs, i, -1);
            break;
        }
    }
    // cerr << d << endl;

    mint ans = 0;
    rep(i, n) ans += d[i];
    ans *= modpow(modpow(2, n, mod), mod - 2, mod);
    cout << ans << endl;
}

