int dfs( int node, int parent_node ){
	int count = 0;
	for ( auto it : edgerefs[node] ){ // node -> next_node を調べる
		conn &c  = conns[it  ];
		conn &cr = conns[it^1];
		if ( c.next_node != parent_node ){
			if ( c.count == -1 )
				c.count = dfs( c.next_node, node );
			if ( cr.count == -1 )
				cr.count = N - c.count;
			count += c.count;
		}
	}
	return count+1;
}


