struct comb_perm{
    int N;
    const ll mod = 1e9 + 7;
    vector<mint> fac;
    vector<mint> rec;

    mint modpow(mint x, int y){
        if(y == 0) return 1;
        mint e = modpow(x, y / 2);
        e = e * e;
        return e * (y % 2 == 0 ? 1 : x);
    }

    comb_perm(int N): N(N), fac(N + 1), rec(N + 1){
        fac[0] = rec[0] = 1;
        for(int i = 1; i <= N; i++){
            fac[i] = fac[i - 1] * i;
            rec[i] = modpow(fac[i], mod - 2);
        }
    }

    mint comb(int p, int r){
        return fac[p] * rec[r] * rec[p - r];
    }

    mint perm(int p, int r){
        return fac[p] * rec[p - r];
    }
};

