const int MOD = 1e9+7;
const int MAX = 2e5+10;

int pow_(ll n, ll k) {
    ll res = 1;
    while (k) {
        if (k&1) res = (res * n) % MOD;
        n = n * n % MOD;
        k >>= 1;
    }
    return res;
}

int inv(int n) {
    return pow_(n, MOD-2);
}

int N;
vi edge[MAX], adj[MAX];

int make_tree(int n, int p) {
    int count_children = 0;
    FORE (c, edge[n]) if (c != p) {
        int cnt = make_tree(c, n);
        if (cnt > 0) adj[n].push_back(cnt);
        count_children += cnt;
    }
    if (N - count_children - 1 > 0) adj[n].push_back(N - count_children - 1);
    return count_children + 1;
}

int sub(int idx) {
    vi ad = adj[idx];
    if (ad.size() == 1) return 0;
    ll ret = (MOD + pow_(2, N-1) - 1) % MOD;
    FORE (a, ad) ret = (ret + MOD - pow_(2, a) + 1) % MOD;
    return ret;
}

int solve() {
    make_tree(0, -1);
    ll ans = 0;
    REP (i, N) ans = (ans + sub(i)) % MOD;
    return ans * inv(pow_(2, N)) % MOD;
}

int main() {
