struct Binominal{
    vector<ModInt> fac,finv,inv; //fac[n]:n! finv:(n!)の逆元
    int sz;
    Binominal(int n=10) :sz(0){
        if(n==0) n=10;
        init(n);
    }
    inline void init(int n){
        fac.resize(n+1,1);
        finv.resize(n+1,1);
        inv.resize(n+1,1);
        for(int i=2;i<=n;i++){
            fac[i]=fac[i-1]*i;
            inv[i]=MOD-inv[MOD%i]*(MOD/i);
            finv[i]=finv[i-1]*inv[i];
        }
        sz=n;
    }
    //nCk(n,k<=N) をO(1)で求める
    inline ModInt com(int n,int k){
        if(n<k) return ModInt(0);
        if(n<0 || k<0) return ModInt(0);
        if(n>sz) init(n);
        return fac[n]*finv[k]*finv[n-k];
    }
    //nCk(k<=N) をO(k)　で求める 
    inline ModInt rcom(ll n,int k){
        if(n<0 || k<0 || n<k) return ModInt(0);
        if(k>sz) init(k);
        ModInt ret(1);
        for(int i=0;i<k;i++){
            ret*=(n-i);
        }
        ret*=finv[k];
        return ret;
    }

    //重複組み合わせ n種類のものから重複を許してk個を選ぶ
    //〇がn個,|がk個
    inline ModInt h(int n,int k){
        return com(n+k-1,k);
    }
};

using Graph=vector<vector<int>>;

ModInt ans(0);
vector<ModInt> t;

int dfs(int idx,int par,Graph &g,int n){
    vector<int> v;
    int cnt=0;
    for(int next:g[idx]){
        if(next==par) continue;
        int x=dfs(next,idx,g,n);
        cnt+=x;
        v.push_back(x);
    }
    if(n-cnt-1!=0) v.push_back(n-1-cnt);
    if(v.size()<=1) return 1;
    ModInt ret(0);
    ret+=t[n-1];
    for(int i=0;i<v.size();i++){
        ret+=t[v[i]]-1;
    }
    ret+=1;
    //cout<<ret<<endl;
    ret=1-ret/t[n];
    ans+=ret;
    return cnt+1;
}


