std::vector<mint> kuro;
mint res = 0;
void dfs(int i, int prev) {
	size[i] = 1;
	for (auto j : hen[i]) {
		if (j == prev) continue;
		dfs(j, i);
		size[i] += size[j];
		sizes[i].push_back(size[j]);
