const long long MOD = 1000000007;
const long long HIGHINF = (long long)1e18;
const int INF = (int)1e9;

ll n;
V< V< int > > edges;

ll modpow(ll m, ll p) {
    if (p == 0) return 1;
    ll tmp = modpow(m, p / 2);
    if (p & 1) return (tmp * tmp % MOD) * m % MOD;
    else return tmp * tmp % MOD;
}

ll ans = 0;
ll dfs(int i, int p) {
    ll sum = 0;  // 子のノード数
    ll tmpa = 1;  // 余事象、初期値は全て白の場合(= 1 通り)
    for (int e: edges[i]) {
        if (e == p) continue;
        ll cn = dfs(e, i);
        ll tmp = modpow(2, cn) - 1;  // 部分木の中で黒がある場合 = 全て白の余事象
        if (tmp < 0) tmp += MOD;
        tmpa += tmp;
        if (tmpa >= MOD) tmpa -= MOD;
        sum += cn;
    }

    if (edges[i].size() == 1) return 1;  // 部分木がない場合

    // 親側が黒の時
    tmpa += modpow(2, n - sum - 1) - 1;
    if (tmpa >= MOD) tmpa -= MOD;
    // 上で求めたのは頂点 i が含まれない頂点の色の決め方の個数
    // 頂点 i が含まれるのはその余事象なので
    ll tmp = modpow(2, n - 1) - tmpa;
    if (tmp < 0) tmp += MOD;
    ans += tmp;
    if (ans >= MOD) ans -= MOD;
    return sum + 1;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> n;
    edges.resize(n);
    for (int i = 0; i < n - 1; i++) {
        int a, b; cin >> a >> b;
        a--, b--;
        edges[a].emplace_back(b);
        edges[b].emplace_back(a);
    }

    dfs(0, -1);
    ans = ans * modpow(modpow(2, n), MOD - 2) % MOD;
    cout << ans << '\n';
    return 0;
}

