		++k;
	}

	if(sz[u] != n)
		sum = addmod(sum,powers[n-sz[u]]);

	sum = mulmod(prod,addmod(sum,MOD+1-k));

	ans = addmod(ans,mulmod(modinv(2),MOD+1-sum));
}

int main(){
	ios_base::sync_with_stdio(0); cin.tie(0);

	int u,v;
