long long calc(vector<int> &a) {
    auto all = 1ll;
    for (auto sz: a) {
        all = MOD.mul(all, invPw2[sz]);
    }
    auto bad = all;
    for (auto sz: a) {
        MOD.inc(bad, MOD.mul(MOD.mul(all, pw2[sz]), MOD.sub(1, invPw2[sz])));
    }
    auto res = MOD.div(MOD.sub(1, bad), 2);
    return res;
}

