template <int MOD>
struct Mint {
  int n;
  constexpr Mint(int n = 0): n(n) {}
  constexpr Mint operator -() const {
    return n ? MOD - n: 0;
  }
  constexpr Mint operator ++() {
    n++;
    if(n == MOD) n = 0;
    return *this;
  }
  constexpr Mint operator --() {
    n--;
    if(n < 0) n = MOD - 1;
    return *this;
  }
  constexpr Mint &operator -= (const Mint &rhs){
    if(n >= rhs.n) n -= rhs.n;
    else n = MOD - (rhs.n - n);
    return *this;
  }
  constexpr Mint &operator += (const Mint &rhs){
    n += rhs.n;
    if(n >= MOD) n -= MOD;
    return *this;
  }
  constexpr Mint &operator *= (const Mint &rhs){
    n = (long long) n * rhs.n % MOD;
    return *this;
  }
  constexpr Mint &operator /= (const Mint &rhs){
    n = (long long) n * rhs.inv().n % MOD;
    return *this;
  }
  constexpr bool operator == (const Mint &rhs) const {
    return n == rhs.n;
  }
  constexpr bool operator != (const Mint &rhs) const {
    return n != rhs.n;
  }
  friend constexpr Mint operator - (const Mint &lhs, const Mint &rhs){
    Mint r = lhs;
    r -= rhs;
    return r;
  }
  friend constexpr Mint operator + (const Mint &lhs, const Mint &rhs){
    Mint r = lhs;
    r += rhs;
    return r;
  }
  friend constexpr Mint operator * (const Mint &lhs, const Mint &rhs){
    Mint r = lhs;
    r *= rhs;
    return r;
  }
  friend constexpr Mint operator / (const Mint &lhs, const Mint &rhs){
    Mint r = lhs;
    r /= rhs;
    return r;
  }
  constexpr Mint pow(int n) const {
    Mint r = 1;
    Mint x = *this;
    for(; n; n >>= 1){
      if(n & 1) r *= x;
      x *= x;
    }
    return r;
  }
  constexpr Mint inv() const {
    return pow(MOD - 2);
  }
};

