void calc_po2()
{
	ll i,v=1;

	for(i=0;i<200002;++i)
	{
		po2[i]=v;
		v = (v*2)%mod;
	}

}

void dfsrec(vector<ll> *adj,ll nod,bool *vis)
{
	//mark this node 'nod' visited , see all of it's adjacent 
	//vertices and if they are not visited then call 'dfsrec'

	vis[nod]=true;

	ll i=0,siz = adj[nod].size();
	dow[nod]=1;

	for(i=0;i<siz;++i)
	{
		if(!vis[adj[nod][i]])
		{
			dfsrec(adj,adj[nod][i],vis);
			dow[nod] += dow[adj[nod][i]];
			par[adj[nod][i]]=nod;
		}
	}

}


void dfs(vector<ll> *adj,ll n)
{


	ll i;
	bool vis[n] = {false};
	par[0]=-1;
	dfsrec(adj,0,vis);

}

long long powt[64];
long long sumpow2(long long num,long long *arr)
{
	long long i,j;
	if(powt[0] == 0)
	{
		powt[0]=1;
		for(i=1;i<64;++i)
			powt[i]=powt[i-1]*2;
	}
	i=0;
	j=0;
	while(num>0)
	{
		if(powt[i]==num)
		{
			arr[j]=i;
			num-=powt[i];
			++j;
		}
		else if(powt[i]>num)
		{
			arr[j]=i-1;
			num-=powt[i-1];
			i=0;
			++j;
		}
		else
			++i;

	}

	return j;	
}

long long modinv(long long num,long long prime)
{
	long long var = prime-2,j,i;

	ll arr[100];

	j=sumpow2(var,arr);

	long long ans[100];

	ans[0]=num%prime;

	for(i=1;i<=arr[0];++i)
	{
		ans[i] = (ans[i-1]*ans[i-1])%prime;
	}

	for(i=1;i<j;++i)
	{
		ans[arr[0]+i] = (ans[arr[0]+i-1]*ans[arr[i]])%prime;
	}

	return ans[arr[0]+j-1];
}



void sum_it(ll &tn,ll &td,ll p,ll q)
{
	tn = ((q*tn)%mod + (p*td)%mod)%mod;
	td = (td*q)%mod;
}


int main()
{

	ll n,u,v,i,d,ans,j,tn,td,tot,var,p;

