ll N;
vector<ll> A;
vector<ll> B;

vector<Modint> expected;
ll dfs(vector<vector<ll>> &g, ll v, ll p,ll count) {
	ll sum=0;
	vector<Modint> a;
	for(ll nextv : g[v]){
		if(nextv==p) continue;
		ll t=dfs(g, nextv, v, count);
		Modint t1=Modint(1)-(Modint(1)/2).pow(t);//少なくとも１つ黒の確率
		a.push_back(t1);
		sum+=t;
	}

	ll nokori=N-1-sum;
	Modint t1=Modint(1)-(Modint(1)/2).pow(nokori);//少なくとも１つ黒の確率
	a.push_back(t1);

	Modint b=1;
	rep(i,a.size()){
		b*=Modint(1)-a[i];
	}
	Modint c=0;
	rep(i,a.size()){
		Modint t=b*a[i]/(Modint(1)-a[i]);
		c+=t;
	}
	b+=c;
	expected[v]=(Modint(1)-b)/2;
	return sum+1;
}

void solve() {
	scanf("%lld", &N);
	A.assign(N, 0);
	B.assign(N, 0);
	rep(i, N-1) { scanf("%lld%lld", &A[i], &B[i]); A[i]--;B[i]--;}
	expected.assign(N,0);
	vector<vector<ll>> g(N);
	rep(i,N-1){
		g[A[i]].push_back(B[i]);
		g[B[i]].push_back(A[i]);
	}

	dfs(g,0,-1,0);

	Modint ans=0;
	rep(i,N){
		ans+=expected[i];
	}
	printf("%lld\n", ans);
}

