[[noreturn]] void impossible() {
    PRINTLN("-1");
    EXIT();
}



void solve() {
    i64 N = RD();

    vector<vector<i64>> G(N);
    LOOP(N-1) {
        i64 a = RD1();
        i64 b = RD1();
        G[a].emplace_back(b);
        G[b].emplace_back(a);
    }

    ModInt numer = 0;
    // 戻り値: 部分木の頂点数
    auto dfs = FIX([&](auto&& self, i64 v, i64 p) -> i64 {
        ModInt cur = ModInt(2).pow(N-1);

        // 全てが白の場合
        --cur;

        // 子部分木の1つのみに黒がある場合
        i64 res = 1;
        for(i64 to : G[v]) {
            if(to == p) continue;
            i64 k = self(to, v);
            cur -= ModInt(2).pow(k) - 1;
            res += k;
        }

        // 親部分木のみに黒がある場合
        cur -= ModInt(2).pow(N-res) - 1;

        numer += cur;

        return res;
    });
    dfs(0, -1);

    ModInt denom = ModInt(2).pow(N);

    ModInt ans = numer * denom.inv();

    PRINTLN(ans);
}

signed main() {
    i64 T = 1; //RD();
    LOOP(T) {
        solve();
    }

    EXIT();
}

