#include <bits/stdc++.h>

using namespace std;
#define ll long long

const int N = 2e5 + 5, mod = 1e9 + 7;
vector<int> g[N];
int sz[N];
int n;

int fp(int a, int p) {
    if (!p) return 1;
    int t = fp(a, p >> 1);
    t = (t * 1LL * t) % mod;
    if (p & 1) t = (t * 1LL * a) % mod;
    return t;
}

int ans = 0;

void dfs(int node, int par) {
    sz[node] = 1;
    for (auto child:g[node]) {
        if (child == par)continue;
        dfs(child, node);
        sz[node] += sz[child];
    }
    int prop = fp(fp(2, n - 1), mod - 2);
    for (auto child:g[node]) {
        if (child == par)continue;
        int x = sz[child];
        //2^x - 1 / 2 ^ n
        prop = (prop + ((fp(2, x) - 1 + mod) % mod * 1LL * fp(fp(2, n - 1), mod - 2)) % mod) % mod;
    }
    int x = n - sz[node];
    prop = (prop + ((fp(2, x) - 1 + mod) % mod * 1LL * fp(fp(2, n - 1), mod - 2)) % mod) % mod;
    prop = (1 - prop + mod) % mod;
    prop = (prop * 1LL * fp(2, mod - 2)) % mod;
    ans = (ans + prop) % mod;
}

int main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cin >> n;
    for (int i = 0; i + 1 < n; i++) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    dfs(1, 1);
    cout << ans << endl;
    return 0;
}

