#include <bits/stdc++.h>
using namespace std;

using ll = long long;
static const int MAX = 2e5;
static const ll MOD = 1e9 + 7;

// 隣接リストを用いた深さ優先探索（再帰ver.） O(|V|+|E|)
vector<int> color(MAX, 0);

void dfs(const vector<vector<int>> &G, int u, int &n, vector<ll> &d, vector<vector<ll>> &branch) {
  color[u] = 1; // GRAY
  ll sz = 1, rest = n - 1;
  for (int i = 0; i < G[u].size(); i++) {
    if (color[G[u][i]] == 0) {
      dfs(G, G[u][i], n, d, branch);
      sz += d[G[u][i]];
      branch[u].emplace_back(d[G[u][i]]);
      rest -= d[G[u][i]];
    }
  }
  color[u] = 2; // BLACK
  d[u] = sz;
  if (rest > 0) branch[u].emplace_back(rest);
  return;
}

// 繰り返し自乗法(x^nをmで割った余り) O(logn)
ll power(ll x, ll n, ll m) {
  ll res = 1;
  if (n > 0) {
    res = power(x, n / 2, m);
    if (n % 2 == 0) res = (res * res) % m;
    else res = (((res * res) % m) * x) % m;
  }
  return res;
}

ll modinv(ll x) {
  return power(x, MOD - 2, MOD);
}

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  // 無向(有向)グラフの隣接リスト
  int n; // n:頂点数
  cin >> n;

  vector<vector<int>> G(n); // G:頂点数nのグラフの隣接リスト

  for (int i = 0; i < n - 1; i++) {
    int u, v;
    cin >> u >> v;
    u--;
    v--;
    G[u].emplace_back(v);
    G[v].emplace_back(u); // 有向グラフではコメントアウト
  }

  vector<ll> subtree_size(n, 1);
  vector<vector<ll>> branch(n);
  dfs(G, 0, n, subtree_size, branch);

  ll ans = 0;
  for (int i = 0; i < n; i++) {
    ll keep = power(2, n - 1, MOD);
    keep--; // all white
    for (int j = 0; j < branch[i].size(); j++) {
      keep -= power(2, branch[i][j], MOD) - 1; // only one branch is not "all white"
      keep += MOD;
    }
    keep %= MOD;
    ans += keep;
    ans %= MOD;
  }

  ans *= modinv(power(2, n, MOD)); // all pattern
  ans %= MOD;

  cout << ans << '\n';
}

