ll mod_pow(ll n, ll p, ll mod) {
    ll ret = 1;
    while (p > 0) {
        if (p & 1) ret = ret * n % mod;
        n = n * n % mod;
        p >>= 1;
    }
    return ret;
}

ll mod_inv(ll n, ll mod) {
    return mod_pow(n, mod-2, mod);
}

