        int s = 1;
        for (int c : G[v]) {
            if (c == parent[v]) continue;
            s += size[c];
            prob1 += (1 - mod_pow(two_inv, size[c], mod) + mod) * mod_pow(two_inv, N - size[c], mod) % mod;
            prob1 %= mod;
        }
        prob1 += (1 - mod_pow(two_inv, N - s, mod) + mod) * mod_pow(two_inv, s, mod) % mod;
        prob1 %= mod;
        ll prob = (two_inv - mod_pow(two_inv, N, mod) - prob1 + mod * 2) % mod;
        ans = (ans + prob) % mod;
    }
    cout << ans << endl;
}

