	int len = plist.size();
	rep(i, len) {
		ll ptmp = plist[i];
		vl powtmp;
		powtmp.push_back(ptmp);
		rep(j, 62) {
			ll nxt = powtmp[j] * powtmp[j];
			nxt %= mod;
			powtmp.push_back(nxt);
		}
		pow_.push_back(powtmp);
	}
	return;
}

ll pow1(ll i, ll b) {
	ll ans = 1;
	rep(n, 62) {
		if ((b >> n) % 2 == 1) {
			ans *= pow_[i][n];
			ans %= mod;
		}
	}
	return ans;
}

vl pow2;
void pow2_ini() {
	pow2.push_back(1);
	rep(i, nmax_def) {
		ll pow2_next = pow2[i] * 2;
		pow2_next %= mod;
		pow2.push_back(pow2_next);
	}
	return;
}

void Graph_func::solve() {
	pow2_ini();
	ll x = pow2[Vnum];
	ll y = 0;
	rep(i, Vnum) {
		int Vnum1 = DP[i];
		int Vnum2 = Vnum - DP[i];
		ll ytmp = (pow2[Vnum1] - 1) * (pow2[Vnum2] - 1);
		ytmp %= mod;
		y += ytmp;
		y %= mod;
	}
	y += pow2[Vnum]; // 基本的に(辺の数 + 1)==(頂点の数)
	y--; // 全て白のとき(辺の数)==(頂点の数)==0
	y -= pow2[Vnum - 1] * (ll)Vnum;
	y += mod * (ll)Vnum;
	y %= mod;
	plist.push_back(x);
	pow_ini();
	ll z1 = y;
	ll z2 = pow1(0, mod - 2); // Fermat
	ll z = z1 * z2;
	z %= mod;
