int dfs(int v,int r){
	vector<int> ch;
	int sz = 0;
	for(auto e : tree[v]){
		if(e.dst == r)continue;
		ch.push_back(dfs(e.dst,v));
		sz += ch.back();
	}

	ch.push_back(N - 1 - sz);
	mint co = twoinv.pow(N);
	for(auto c : ch){
		co += twoinv.pow(N - c) * (mint(1) - twoinv.pow(c));
	}
	ans += twoinv - co;
	return sz + 1;
}

