template <typename T, typename U>
T pow(T x, U n) {
    T res = 1;
    while (n > 0) {
        if (n & 1) res *= x;
        x *= x;
        n >>= 1;
    }
    return res;
}

template <typename T>
struct Graph {
    int V, E;
    struct Edge {
        int from, to;
        T cost;
    };
    vector<vector<Edge>> edge;
    vector<vector<T>> dist;
    vector<Edge> es;

    Graph(int V, int E) : V(V), E(E) {
        edge.assign(V, vector<Edge>(0));
        dist.assign(V, vector<T>(0));
    }

    void input(bool is_direct, bool index0 = false) {
        int a, b;
        T c;
        for (int i = 0; i < E; i++) {
            cin >> a >> b;
            if (!index0) a--, b--;
            edge[a].push_back((Edge){a, b, c});
            es.push_back((Edge){a, b, c});
            if (!is_direct) {
                edge[b].push_back((Edge){b, a, c});
                es.push_back((Edge){b, a, c});
            }
        }
    }

    void add_edge(int from, int to, T cost, bool is_direct) {
        edge[from].push_back({from, to, cost});
        es.push_back({from, to, cost});
        if (!is_direct) {
            edge[to].push_back({to, from, cost});
            es.push_back({to, from, cost});
            E++;
        }
        E++;
    }

    // dp[i][j] := 頂点iを覗いた部分木j(根)の頂点数
    vector<unordered_map<int, int>> dp;
    vector<int> sum;
    int calc_root(int u = 0, int from = -1) {
        if (dp.size() == 0) dp.resize(V), sum.assign(V, 0);
        for (auto e : edge[u]) {
            if (e.to == from) continue;
            dp[u][e.to] = calc_root(e.to, u);
            sum[u] += dp[u][e.to];
        }
        return sum[u] + 1;
    }
    void calc_dp(int u = 0, int from = -1) {
        if (from != -1) dp[u][from] = V - (sum[u] + 1), sum[u] += dp[u][from];
        for (auto e : edge[u]) {
            if (e.to == from) continue;
            calc_dp(e.to, u);
        }
    }
    mint solve() {
        calc_root();
        calc_dp();
        mint ans = 0;
        mint i2 = mint(2).inv();
        for (int i = 0; i < V; i++) {
            mint p = i2;
            p -= pow<mint, int>(i2, V);
            for (auto e : edge[i]) {
                p -= (mint(1) - pow<mint, int>(i2, dp[i][e.to])) *
                     pow<mint, int>(i2, V - dp[i][e.to]);
            }
            ans += p;
        }
        return ans;
    }
};

int main() {
    int N;
    cin >> N;
    Graph<int> g(N, N - 1);
    g.input(false);
    cout << g.solve() << endl;
    return 0;
}

