ll mypow(ll a, ll b) {
  if (b == 0) return 1;
  ll tmp = mypow(a, b / 2);
  if (b % 2)
    return (((tmp * tmp) % mod) * a) % mod;
  else
    return (tmp * tmp) % mod;
}

using Graph = vector<vector<int>>;
const int MAX_N = 200010;
Graph g(MAX_N);
vector<ll> ch(MAX_N), ret(MAX_N);
vector<ll> two(MAX_N, 1);  // 2^(-i)
int n;

int dfs(int cur, int pre) {
  ch[cur] = 1;
  for (auto nxt : g[cur]) {
    if (nxt == pre) continue;
    ch[cur] += dfs(nxt, cur);
  }
  if (g[cur].size() <= 1) {
    return ch[cur];
  }
  ret[cur] = two[n - 1] - 1;
  for (auto nxt : g[cur]) {
    if (nxt == pre) continue;
    ret[cur] = (ret[cur] + mod - two[ch[nxt]] + 1) % mod;
  }
  ll r = n - ch[cur];
  ret[cur] = (ret[cur] + mod - two[r] + 1) % mod;
  return ch[cur];
}

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  for (ll i = 1; i < MAX_N; i++) {
    two[i] = two[i - 1] * 2 % mod;
