  }
  dfs(0, -1);
  ll sum = 0;
  for (int i = 0; i < n; i++) sum = (sum + ret[i]) % mod;
  ll tmp = mypow(2LL, mod - 2);
  tmp = mypow(tmp, ll(n));
  sum = sum * tmp % mod;
  cout << sum << endl;
}

