ll dfs(int u, int p, int n) {
	sz[u] = 1;
	vector<int> sizes;
	ll ans = 0, prob = 0;
	for (auto& v : g[u]) {
		if (v != p) {
			ans += dfs(v, u, n);
			sz[u] += sz[v];
			prob += p2_inv[n - sz[v]] * (mod + 1 - p2_inv[sz[v]]);
			prob %= mod;
		}
	}
	if (sz[u] < n) {
		prob += p2_inv[sz[u]] * (mod + 1 - p2_inv[n - sz[u]]);
		prob %= mod;
	}
	prob += p2_inv[n] + p2_inv[1];
	prob %= mod;
	ans %= mod;
	ans += (mod + 1 - prob);
	return ans % mod;
}

ll pwr(ll x, ll e) {
	ll res = 1;
	while (e) {
		if (e & 1) {
			res = (res * x) % mod;
		}
		x = (x * x) % mod;
		e /= 2;
	}
	return res;
}

