template <int MOD>
class Fp {
 public:
  long long val;
  constexpr Fp(long long v = 0) noexcept : val(v % MOD) {
    if (val < 0) val += MOD;
  }
  constexpr int getmod() { return MOD; }
  constexpr Fp operator-() const noexcept { return val ? MOD - val : 0; }
  constexpr Fp operator+(const Fp& r) const noexcept { return Fp(*this) += r; }
  constexpr Fp operator-(const Fp& r) const noexcept { return Fp(*this) -= r; }
  constexpr Fp operator*(const Fp& r) const noexcept { return Fp(*this) *= r; }
  constexpr Fp operator/(const Fp& r) const noexcept { return Fp(*this) /= r; }
  constexpr Fp& operator+=(const Fp& r) noexcept {
    val += r.val;
    if (val >= MOD) val -= MOD;
    return *this;
  }
  constexpr Fp& operator-=(const Fp& r) noexcept {
    val -= r.val;
    if (val < 0) val += MOD;
    return *this;
  }
  constexpr Fp& operator*=(const Fp& r) noexcept {
    val = val * r.val % MOD;
    return *this;
  }
  constexpr Fp& operator/=(const Fp& r) noexcept {
    long long a = r.val, b = MOD, u = 1, v = 0;
    while (b) {
      long long t = a / b;
      a -= t * b;
      swap(a, b);
      u -= t * v;
      swap(u, v);
    }
    val = val * u % MOD;
    if (val < 0) val += MOD;
    return *this;
  }
  constexpr bool operator==(const Fp& r) const noexcept {
    return this->val == r.val;
  }
  constexpr bool operator!=(const Fp& r) const noexcept {
    return this->val != r.val;
  }
  friend constexpr ostream& operator<<(ostream& os, const Fp<MOD>& x) noexcept {
    return os << x.val;
  }
  friend constexpr Fp<MOD> modpow(const Fp<MOD>& a, long long n) noexcept {
    if (n == 0) return 1;
    auto t = modpow(a, n / 2);
    t = t * t;
    if (n & 1) t = t * a;
    return t;
  }
};

// const ll MOD = 998244353;
const ll MOD = 1000000007;
using mint = Fp<MOD>;

ll N;
VVL edge_list;
V<map<ll, ll>> ct_memo;

// u 以降の点の数, p を含まない
ll get_node_ct(ll u, ll p) {
  if (ct_memo[p].count(u) > 0) return ct_memo[p][u];
  if (ct_memo[u].count(p) > 0) return N - ct_memo[u][p];

  ll res = 1;

  for (auto v : edge_list[u]) {
    if (v == p) continue;
    res += get_node_ct(v, u);
  }

  ct_memo[p][u] = res;
  return res;
}

void solve() {
  cin >> N;

  edge_list = VVL(N, VL(0));
  ct_memo = V<map<ll, ll>>(N, map<ll, ll>());

  rep(i, N - 1) {
    ll a, b;
    cin >> a >> b;
    a--, b--;

    edge_list[a].push_back(b);
    edge_list[b].push_back(a);
  }

  // 全 S の頂点数の期待値 - 全木の黒頂点の数の期待値

  // 全 S の頂点数の期待値 = 全 S の辺の数の期待値 + 1
  // 各辺が S の頂点数に寄与する期待値 = S の頂点に入る確率 を合計すれば良い
  mint edge_ct_e = 0;

  rep(u, N) {
    for (ll v : edge_list[u]) {
      unless(u < v) continue;

      ll ct_u = get_node_ct(u, v);
      ll ct_v = N - ct_u;

      // この辺が S に含まれる確率 = u 側, v　側に一つでも黒がある確率
      mint r_for_edge = (mint(1) - mint(1) / modpow(mint(2), ct_u)) *
                        (mint(1) - mint(1) / modpow(mint(2), ct_v));
      edge_ct_e += r_for_edge;
    }
  }

  mint empty_prob = mint(1) / modpow(mint(2), N);
  mint node_ct_e = edge_ct_e + 1;
  node_ct_e -= empty_prob;  // 空グラフの場合の 1 が加算されている

  mint res = node_ct_e;

  // 全木の黒頂点の数の期待値
  res -= mint(N) / 2;

  cout << res << endl;
}

