u64 modinv(u64 a, u64 m) {
    u64 b = m, u = 1, v = 0;
    while (b) {
        u64 t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= m;
    if (u < 0) u += m;
    return u;
}

