const long long mod = 1e9 + 7;

long long inv(long long x){
  long long m = mod;
  long long u = 1;
  long long v = 0;
  while(m){
    long long t = x / m;
    x -= t * m;
    swap(x, m);
    u -= t * v;
    swap(u, v);
  }
  u %= mod;
  if(u < 0) u += mod;
  return u;
}

void half_p_init(vector<long long>& half_p){
  half_p[0] = 1;
  for(int i = 1; i < (int)half_p.size(); i++){
    long long half = inv(2);
    half_p[i] = half_p[i - 1] * half % mod;
  }
}

void find_parent(int x, vector<vector<int>>& graph, vector<int>& parent){
  for(int child : graph[x]){
    if(child != parent[x]){
      parent[child] = x;
      find_parent(child, graph, parent);
    }
  }
}

int measure_card(int x, vector<vector<int>>& graph, vector<int>& parent, vector<int>& card){
  card[x] = 1;
  for(int child : graph[x]){
    if(child == parent[x]) continue;
    card[x] += measure_card(child, graph, parent, card);
  }
  return card[x];
}

long long exp(int x, vector<vector<int>>& graph, vector<int>& parent, vector<int>& card, vector<long long>& half_p){
  int n = graph.size();

  if(graph[x].size() == 1) return 0;

  long long prob = mod + 1 - half_p[n - 1];
  prob %= mod;
  for(int child : graph[x]){
    long long p;
    if(child == parent[x]){
      p = half_p[n - 1] * inv(half_p[n - card[x]]);
      p %= mod;
      p *= (1 - half_p[n - card[x]]);
      p %= mod;
    }else{
      p = half_p[n - 1] * inv(half_p[card[child]]);
      p %= mod;
      p *= (1 - half_p[card[child]]);
      p %= mod;
    }
    prob -= p;
    while(prob < 0) prob += mod;
    prob %= mod;
  }

  return (prob * half_p[1]) % mod;
}

int main(){
  int n;
  cin >> n;

  vector<long long> half_p(n + 1);
  half_p_init(half_p);

  vector<vector<int>> graph(n);
  vector<int> parent(n, -1);
  vector<int> card(n);

  for(int i = 0; i < n - 1; i++){
    int a, b;
    cin >> a >> b;
    a--;
    b--;
    graph[a].push_back(b);
    graph[b].push_back(a);
  }

  find_parent(0, graph, parent);
  int tmp = measure_card(0, graph, parent, card);

  long long anarchy = 0;
  for(int i = 0; i < n; i++){
    anarchy += exp(i, graph, parent, card, half_p);
    anarchy %= mod;
  }

  cout << anarchy << endl;

  return 0;
}

