template <class T1, class T2> inline void divMod(T1& a, T2 b)	{   a = a * qpow(b, mod-2) % mod;    }

long long qpow(long long a, long long b)
{
    long long ret = 1;
    for (; b!=0; b>>=1)
    {
        if (b & 1)  multMod(ret, a);
        multMod(a, a);
    }
    return ret;
}

