int main() {
    int N; cin >> N;
    Tree<int> tree(N);
    vector<int> dim(N,0),scale(N,1);
    for(int i = 0; i < N-1; ++i){
        int u,v; cin >> u >> v;
        u--,v--;
        tree.makeEdge(u,v);
        tree.makeEdge(v,u);
        dim[u]++;
        dim[v]++;
    }
    tree.makeDepth(0);
    tree.makeChild();
    for(int pa:tree.order){
        for(int ch: tree.child[pa]){
            scale[pa] += scale[ch];
        }
    }
    vector<modint> inv2(N,1);
    for(int i = 1; i < N; ++i) inv2[i] = inv2[i-1]/2;
    modint one(1),ans(0);
    for(int pa:tree.order){
        if(dim[pa]==1) continue;
        vector<ll> cnt = {0};

        if(pa!=0)cnt.push_back(N - scale[pa]);
        for(int ch: tree.child[pa]) cnt.push_back(scale[ch]);
        int M = cnt.size();
        vector<modint> sum(M);
        for(int i = 0; i < M; ++i) sum[i] = inv2[cnt[i]];
        auto suml = sum,sumr = sum;
        for(int i = 1; i < M; ++i) suml[i] *= suml[i-1];
        for(int i = M-2; 0 <= i; --i) sumr[i] *= sumr[i+1];
        for(int i = 1; i+1 < M; ++i) ans += suml[i-1]*(one-sum[i])*(one-sumr[i+1])*inv2[1];
    }
    cout << ans << endl;

    return 0;
}

