ll proinverse(ll x,ll m){
    ll res=1,M=m-2;
    while(M>0){
        if(M&1) res=res*x%m;
        x=x*x%m;
        M>>=1;
    }
    return res;
}

void dfs(ll s,ll par){
    ncnt[s]=1;
    if(path[s].size()==1 && par!=-1){
        ans[s]=0; rcnt[s]=1;
        icnt[par]++;
        ncnt[par]++;
        return;
    }
    for(auto to:path[s]){
        if(to==par) continue;
        dfs(to,s);
    }
    if(par!=-1){
        icnt[par]=(icnt[par]+icnt[s])%MOD;
        ncnt[par]+=ncnt[s];
    }
    mcnt[s]=(mcnt[s]+icnt[s])%MOD;
    ll k=ncnt[s];
    rcnt[s]=(MOD+pwr[ncnt[s]]-1)%MOD;
    for(auto to:path[s]){
        if(to==par) continue;
        ans[s]=(ans[s]+mcnt[to]*(2*pwr[k-1-ncnt[to]]-1)%MOD)%MOD;
        rcnt[s]=(MOD+rcnt[s]-pwr[ncnt[to]]+1)%MOD;
    }
    ans[s]=(MOD+ans[s]+rcnt[s]-pwr[ncnt[s]-1])%MOD;
    mcnt[s]=(mcnt[s]+ans[s])%MOD;
    if(par!=-1){
        mcnt[par]=(mcnt[par]+mcnt[s])%MOD;
        icnt[par]=(icnt[par]+rcnt[s])%MOD;
    }
}

