constexpr long double EPS = 1e-12;
constexpr ll MOD = (ll)((1E+9)+7);

ll N;
map<pair<ll, ll>, ll> C;
vvll Tree;
vb flag;

ll search(ll root){
  ll ans = 1;
  flag[root] = true;
  REP(i,Tree[root].size()){
    if(flag[Tree[root][i]]) continue;
    ll tmp = search(Tree[root][i]);
    C[make_pair(root, Tree[root][i])] = tmp;
    C[make_pair(Tree[root][i], root)] = N-tmp;
    ans += tmp;
  }

  return ans;
}

ll ModPow(ll x, ll n){
  ll res = 1;
  while(n>0){
    if(n&1) res=res*x%MOD;
    x=x*x%MOD;
    n>>=1;
  }
  return res;
};

int main(){
  cin.tie(0); // cut the cin and cout (default, std::flush is performed after std::cin)
  ios::sync_with_stdio(false); // cut the iostream and stdio (DON'T endl; BUT "\n";)

  IN(N);
  Tree.resize(N);
  REP(i,N-1){
    ll A, B;
    IN(A,B);
    A--; B--;
    Tree[A].pb(B);
    Tree[B].pb(A);
  }

  ll root=0;
  while(Tree[root].size()>1) root++;

  flag.resize(N, false);

  search(root);

  for(auto itr : C){
    debug_print(itr.first.first, itr.first.second, itr.second);
  }

  ll inv2 = (MOD-(MOD/2))%MOD;

  ll ans = 0;
  ll all = ModPow(inv2, N-1);

  REP(i,N){
    if(Tree[i].size()==1) continue;
    ll tmp = all;
    REP(j,Tree[i].size()){
      ll M = C[make_pair(i, Tree[i][j])];
      ll tmp2 = ModPow(inv2, M)%MOD;
      tmp2 = (MOD+1-tmp2)%MOD;
      tmp += (tmp2*ModPow(inv2, N-1-M))%MOD;
    }
    ans += (inv2*(1+MOD-tmp))%MOD;
    ans %= MOD;
  }

  OUT(ans);
  //debug_print(ansd);

  return 0;
}

