void dfs_pre(int v, int p) {
    subt[v] = 1;
    for (int u : tree[v]) {
        if (u == p) continue;
        dfs_pre(u, v);
        subt[v] += subt[u];
    }
}

ll dfs(int v, int p) {
    ll inv2 = mpow(2, MOD - 2);

    int pt = N - 1;
    for (int u : tree[v]) {
        if (u == p) continue;
        pt -= subt[u];
    }

    ll res = 1;
    res = (res - mpow(inv2, N - 1) + MOD) % MOD;
    res = (res - mpow(inv2, N - 1 - pt) * (1 - mpow(inv2, pt) + MOD)) % MOD;
    for (int u : tree[v]) {
        if (u == p) continue;
        res = (res - mpow(inv2, N - 1 - subt[u]) * (1 - mpow(inv2, subt[u]) + MOD) % MOD + MOD) % MOD;
    }
    res = res * inv2 % MOD;

    for (int u : tree[v]) {
        if (u == p) continue;
        res = (res + dfs(u, v)) % MOD;
    }
    return res;
}

