long long int rev_mod(long long int num){
	long long int pow_num = MOD - 2;
	long long int mod_num = MOD;
	long long int pow_cur = num;
	long long int ret = 1;
	while(pow_num > 0){
		if(pow_num % 2 == 1){
			ret *= pow_cur;
			ret %= mod_num;
		}
		pow_cur *= pow_cur;
		pow_cur %= mod_num;
		pow_num /= 2;
	}
	return ret;
}

vector<int> E[210000];
map<int, int> sz[210000];
long long int p2[210000], p2m[210000];
int memo[210000];

int func(int pos, int pre){
	if(memo[pos] != 0){
		return memo[pos] - sz[pos][pre];
	}
	int ret = 1;
	bool flag = true;
	for(int i = 0; i < E[pos].size(); i++){
		int to = E[pos][i];
		if(to == pre){
			continue;
		}
		if(sz[pos].find(to) != sz[pos].end()){
			ret += sz[pos][to];
		}else{
			sz[pos][to] = func(to, pos);
			ret += sz[pos][to];
			flag = false;
		}
	}
	if(flag && E[pos].size() != 1){
		memo[pos] = 1;
		for(P p : sz[pos]){
			memo[pos] += p.second;
		}
	}
	return ret;
}

int main(){
	p2[0] = p2m[0] = 1;
	for(int i = 1; i < 210000; i++){
		p2[i] = p2[i - 1] * 2 % MOD;
		p2m[i] = p2m[i - 1] * rev_mod(2) % MOD;
	}
	long long int N;
	cin >> N;
	for(int i = 0; i < N - 1; i++){
		int A, B;
		cin >> A >> B;
		E[A].push_back(B);
		E[B].push_back(A);
	}
	long long int ans = 0;
	for(int i = 1; i <= N; i++){
		func(i, -1);
		long long int S = p2[N - 1] + (MOD - 1);
		S %= MOD;
		for(P p : sz[i]){
			S += MOD - (p2[p.second] - 1);
			S %= MOD;
			//cout << p.first << " " << p.second << endl;
		}
		ans += S;
		ans %= MOD;
	}
	ans *= p2m[N];
	ans %= MOD;
	cout << ans << endl;
	return 0;
}

