template<long long mod>
class modint{
	public:
		long long x;
		modint(long long a){x=a%mod;if(x<0)x+=mod;}
		modint(){x=0;}

		modint pow(long long a){
			modint res(1), b(x);
			while(a){
				if(a&1)res*=b;
				b*=b;
				a>>=1;
			}
			return res;
		}

		modint inv(){return pow(mod-2);}

		modint& operator+=(modint a){x=(x+a.x)%mod;return *this;}
		modint& operator-=(modint a){x=x-a.x;if(x<0)x+=mod;return *this;}
		modint& operator*=(modint a){x=x*a.x%mod;return *this;}
		modint& operator/=(modint a){x=x*a.inv().x%mod;return *this;}

		modint operator+(modint a){return modint(x)+=a;}
		modint operator-(modint a){return modint(x)-=a;}
		modint operator*(modint a){return modint(x)*=a;}
		modint operator/(modint a){return modint(x)/=a;}

		modint operator-(){return modint(x);}

		bool operator==(const modint a){return x == a.x;}
		bool operator<(const modint a){return x < a.x;}
		bool operator>(const modint a){return x > a.x;}
};

template<long long mod>
ostream& operator<<(ostream& os, const modint<mod>& a){
	os << a.x;
	return os;
}

using mint = modint<MOD>;

mint npow(int n){
    const int N = 3e6;
    static vector<mint> dp(N);
    static vector<bool> used(N,false);
    if(n==0)return 1;
    if(used[n])return dp[n];
    used[n] = true;
    return dp[n] = npow(n-1) * 2;
}

mint func(){
    int n = in();
    vvector<pii> edges(n);
    rep(i,n-1){
        int a = in()-1;
        int b = in()-1;
        edges[a].emplace_back(b,edges[b].size());
        edges[b].emplace_back(a,edges[a].size()-1);
    }

    vvector<int> depth_dp(n);
    rep(i,n){
        depth_dp[i] = vector<int>(edges[i].size(),-1);
    }

    method(depth,int,int place,int last){
        if(last==-1){
            rep(i,edges[place].size()){
                pii &edge = edges[place][i];
                depth_dp[place][i] = n - depth(edge.first,edge.second);
            }
            return 0;
        }
        int &it = depth_dp[place][last];
        if(it>=0)return it;
        it = 1;
        rep(i,edges[place].size()){
            if(i==last)continue;
            pii &edge = edges[place][i];
            it += depth(edge.first,edge.second);
        }
        return it;
    };

    method(culc_value,mint,int place){
        if(edges[place].size()<2)return mint(0);
        mint valids = npow(n-1);
        valids -= 1;
        foreach(i,edges[place]){
            valids -= npow(depth(i.first,i.second)) - 1;
        }
        return valids;
    };

    vector<pii> order;
    rep(i,n){
        order.emplace_back(edges[i].size(),i);
    }
    //sort(all(order),greater<pii>());

    mint res = 0;
    rep(i,n){
        depth(order[i].second,-1);
        res += culc_value(order[i].second);
    }
    res /= npow(n);
    return res;
}

int main(){
    cout << func() << endl;
    return 0;
}

