vector<vector<edge>> graph;
vec dp;

ll dfs(ll idx, ll par) {
    ll cnt = 0;
    for (edge e : graph[idx]) {
        if (e.to == par) continue;
        cnt += dfs(e.to, idx);
    }
    return dp[idx] = cnt + 1;
}

const int MAX = 510000;
const int MOD = 1000000007;

ll fac[MAX], finv[MAX], inv[MAX];

void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++) {
        fac[i] = fac[i-1] * i % MOD;
        inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

ll COM (int n, int k) {
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

ll modpow (ll a, ll n) {
    ll res = 1;
    while (n > 0) {
        if (n & 1) res = res * a % MOD;
        a = a * a % MOD;
        n >>= 1;
    }
    return res;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    COMinit();

    ll N;
    cin >> N;
    graph.assign(N, vector<edge>());
    dp.assign(N, -1);

    Rep (i, N-1) {
        ll a, b;
        cin >> a >> b;
        a--; b--;
        graph[a].push_back({b, i});
        graph[b].push_back({a, i});
    }

    dfs(0, -1);

    ll ans = 0;
    Rep (i, N) {   
        ll tmp = 1;
        tmp += MOD - graph[i].size();
        tmp %= MOD;
        for (auto e : graph[i]) {
            if (dp[e.to] > dp[i]) {
                tmp += modpow(2, N-dp[i]);
            } else {
                tmp += modpow(2, dp[e.to]);
            }
            tmp %= MOD;
        }
        tmp *= modpow(finv[2], N-1);
        tmp %= MOD;
        tmp = 1 - tmp + MOD;
        tmp *= finv[2];
        tmp %= MOD;
        // cout << tmp << "\n";
        ans += tmp;
        ans %= MOD;
    }

    cout << ans << endl;
}

// F - Surrounded Nodes

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
// const int INF = 2147483647;
// const ll INF = 9223372036854775807;
const ll MOD = 1e9 + 7;

struct Node {
	vector<int> neighbors;
	bool visited;
};

Node nodes[200000];
vector<int> node_cnt[200000]; // node_cnt[i][j]: nodes[i]のj番目のneighborから先のノードの数

// mod p （pは素数）の下でのべき乗を求める
ll mod_pow(ll a, ll n, ll p) {
		ll result = 1;
		while (n > 0) {
			if (n & 1) result = result * a % p;
			a = a * a % p;
			n >>= 1;
		}
		return result;
	};

// mod p （pは素数）の下での逆元を求める（フェルマーの小定理を利用）
ll mod_inverse(ll a, ll p) {
	return mod_pow(a, p-2, p);
}

// mod p （pは素数）の下での除算 (a / b)
ll mod_devide(ll a, ll b, ll p) {
	return a * mod_inverse(b, p) % p;
}

// nodes[i] から先（nodes[i]を含む）のノードの数を返す
int dfs(int i) {
	int result = 1;
	nodes[i].visited = true;

	for (int j=0; j<nodes[i].neighbors.size(); j++) {
		int k = nodes[i].neighbors[j];

		if (nodes[k].visited == true) {
			continue;
		}

		if (node_cnt[i][j] != -1) {
			result += node_cnt[i][j];
			continue;
		}

		node_cnt[i][j] = dfs(k);
		result += node_cnt[i][j];
	};

	return result;
}

void reset_node(int N) {
	for (int i=0; i<N; i++) {
		nodes[i].visited = false;
	}
}

int main() {
	int N;
	cin >> N;

	int A, B;
	for (int i=0; i<N-1; i++) {
		cin >> A >> B;
		A--;
		B--;
		nodes[A].neighbors.push_back(B);
		node_cnt[A].push_back(-1);
		nodes[B].neighbors.push_back(A);
		node_cnt[B].push_back(-1);
	}

	// node_cnt[i][j]を求める
	for (int i=0; i<N; i++) {
		reset_node(N);
		dfs(i);
	}

	/*
	// **** debug ****
	for (int i=0; i<N; i++) {
		cout << "node " << i + 1 << " :";
		for (int n : node_cnt[i]) {
			cout << " " << n;
		}
		cout << endl;
	}
	*/

	// nodeごとに穴あき度の期待値を算出し、それを合計する
	// （y/xについて、xの逆元にyを掛けたものがz）
	ll ans = 0;
	ll inv2 = mod_inverse(2, MOD); // 2の逆元

	// mod_powを予め計算
	unordered_map<ll, ll> mod_pow_inv2;
	mod_pow_inv2[N-1] = mod_pow(inv2, N-1, MOD);
	for (int i=0; i<N; i++) {
		for (int j=0; j<nodes[i].neighbors.size(); j++) {
			if (mod_pow_inv2.find(node_cnt[i][j]) == mod_pow_inv2.end()) {
				mod_pow_inv2[node_cnt[i][j]] = mod_pow(inv2, node_cnt[i][j], MOD);
			}
		}
	}

	for (int i=0; i<N; i++) {
		if (nodes[i].neighbors.size() == 1) continue; // 端点は期待値0

		// 自分以外が全て白く塗られている確率
		ll prob_all_white = mod_pow_inv2[N-1];

		// nodes[i]から出ている部分木のうち、nodes[i].neighbors[k] からの木だけが黒を含む確率
		ll prob_one_black = 0;
		for (int k=0; k<nodes[i].neighbors.size(); k++) {
			ll prob = 1;
			for (int j=0; j<nodes[i].neighbors.size(); j++) {
				if (j == k) {
					// 黒を1つでも含む確率を掛ける（全て白の余事象）
					prob = (prob * (1 - mod_pow_inv2[node_cnt[i][j]] + MOD)) % MOD;
				} else {
					// 全て白の確率を掛ける
					prob = (prob * mod_pow_inv2[node_cnt[i][j]]) % MOD;
				}
			}

			prob_one_black = (prob_one_black + prob) % MOD;
		}

		ll prob = (1 - prob_all_white + MOD) % MOD;
		prob = (prob - prob_one_black + MOD) % MOD;
		prob = (prob * inv2) % MOD; // そもそもnodes[i]が白

		// 確率がそのまま穴あき度の期待値になる
		ans = (ans + prob) % MOD;
	}

	cout << ans << endl;

	return 0;
}

