// Referring to ymatsux-san's source code: https://atcoder.jp/contests/abc138/submissions/7016619

struct Edge
{
  int src, dst;
  // ll cost;
  Edge() {}
  Edge(int src, int dst) : src{src}, dst{dst} {}
  // Edge(int src, int dst, ll cost) : src{src}, dst{dst}, cost{cost} {}

  void added_edge(vector<vector<Edge>> &V)
  {
    V[src].push_back(*this);
  }

  void added_rev(vector<vector<Edge>> &V)
  {
    V[dst].push_back(rev());
  }

  Edge rev()
  {
    Edge edge{*this};
    swap(edge.src, edge.dst);
    return edge;
  }
};

vector<vector<Edge>> ReadGraph(int N, int M, bool is_undirected = true, bool is_one_indexed = true)
{
  vector<vector<Edge>> V(N);
  for (auto i = 0; i < M; ++i)
  {
    int v, w;
    cin >> v >> w;
    if (is_one_indexed)
    {
      --v;
      --w;
    }
    Edge edge{v, w};
    edge.added_edge(V);
    if (is_undirected)
    {
      edge.added_rev(V);
    }
  }
  return V;
}

vector<vector<Edge>> ReadTree(int N)
{
  return ReadGraph(N, N - 1);
}

// ----- main() -----

mint const Two{2};

class Solve
{
  ll N;
  vector<vector<Edge>> V;
  mint ans;

public:
  Solve(ll N) : N{N}, V{ReadTree(N)}, ans{0} {}

  void flush()
  {
    dfs(0);
    cout << ans / Two.power(N) << endl;
  }

private:
  ll dfs(int src, int parent = -1)
  {
    ans += Two.power(N - 1) - 1;
    ll sum{0};
    vector<ll> W;
    for (auto e : V[src])
    {
      if (e.dst == parent)
      {
        continue;
      }
      ll t{dfs(e.dst, src)};
      W.push_back(t);
      sum += t;
    }
    W.push_back(N - 1 - sum);
    for (auto x : W)
    {
      ans -= Two.power(x) - 1;
    }
    return sum + 1;
  }
};

int main()
{
  int N;
  cin >> N;
  Solve solve(N);
  solve.flush();
}

