#define MOD 1000000007
#define HALF ((MOD + 1) / 2)

int n;
vector<int> v[100005];
int dp[100005];
long long ans;

long long po(long long b, int p) {
	long long re = 1;
	while (p) {
		if (p % 2)
			re = re * b % MOD;
		b = b * b % MOD;
		p /= 2;
	}
	return re;
}

void dfs(int a, int b) {
	dp[a] = 1;
	vector<int> tv;
	for (int i : v[a])
		if (i != b) {
			dfs(i, a);
			dp[a] += dp[i];
			tv.push_back(dp[i]);
		}
	tv.push_back(n - dp[a]);
	long long tmp = 1;
	tmp = (tmp + MOD - po(HALF, n - 1)) % MOD;
	for (int i : tv)
		tmp = (tmp + MOD - po(HALF, n - 1 - i) * (1 + MOD - po(HALF, i)) % MOD) % MOD;
	ans = (ans + HALF * tmp) % MOD;
}

int main() {
	scanf("%d", &n);
	for (int i = 1; i < n; i++) {
		int ta, tb;
		scanf("%d%d", &ta, &tb);
		v[ta].push_back(tb);
		v[tb].push_back(ta);
	}
	dfs(1, 0);
	printf("%lld\n", ans);
}

