//rootを根とした木について、各頂点の部分木/親の頂点数を返す
//vcount[v].first=v自身を含めた部分木の頂点数, second=親の頂点数
//vcount[v]first+vcount[v]second=全頂点数 が成立します
vector<pair<ll,ll>> getPartialtreeVertex(vector<vector<ll>> &g, ll root){
	auto dfs = [](auto&& dfs, vector<vector<ll>> &g, ll v, ll p, vector<pair<ll,ll>> &vcount) -> ll {
		ll vsum = 1;
		for(ll nextv : g[v]){
			if(nextv == p) continue;
			ll t = dfs(dfs, g, nextv, v, vcount);
			vsum += t;
		}
		vcount[v] = {vsum, g.size()-vsum};
		return vsum;
	};
	vector<pair<ll,ll>> vcount(g.size());
	dfs(dfs, g, root, -1, vcount);
	return vcount;
}

