typedef long long ll;
const ll MOD = 1e9 + 7;

ll modinv(ll a) {
    ll b = MOD, u = 1, v = 0;
    while (b) {
        ll t = a / b;
        a -= t * b; std::swap(a, b);
        u -= t * v; std::swap(u, v);
    }
    u %= MOD;
    if (u < 0) u += MOD;

    return u;
}
ll modpow(ll a, ll n) {
  ll ret = 1LL;
  while(n > 0) {
    if(n & 1) ret = a * ret % MOD;
    a = a * a % MOD;
    n >>= 1;
  }

  return ret;
}
ll modminus(ll a, ll b) {
  ll ret = (a - b) % MOD;
  return (ret >= 0) ? ret : ret + MOD;
}

int dfs(int pos, int prev, std::vector<std::vector<int>> from) {
  int ret = 1;
  for(auto b : from[pos]) {
    if(b == prev) {
      continue;
    }

    ret += dfs(b, pos, from);
  }

  return ret;
}

