mint npow(int n){
    const int N = 3e6;
    static vector<mint> dp(N);
    static vector<bool> used(N,false);
    if(n==0)return 1;
    if(used[n])return dp[n];
    used[n] = true;
    return dp[n] = npow(n-1) * 2;
}

mint func(){
    int n = in();
    vvector<int> edges(n);
    rep(i,n-1){
        int a = in()-1;
        int b = in()-1;
        edges[a].emplace_back(b);
        edges[b].emplace_back(a);
    }

    method(depth,int,int place,int last){
        static vector<map<int,int>> dp(n);
        if(dp[place].count(last))return dp[place][last];
        int res = 1;
        foreach(i,edges[place]){
            if(i==last)continue;
            res += depth(i,place);
        }
        return dp[place][last] = res;
    };

    method(culc_value,mint,int place){
        if(edges[place].size()<2)return mint(0);
        mint valids = npow(n-1);
        valids -= 1;
        foreach(i,edges[place]){
            valids -= npow(depth(i,place)) - 1;
        }
        return valids;
    };

    mint res = 0;
    rep(i,n){
        res += culc_value(i);
    }
    res /= npow(n);
    return res;
}

