struct node {
	int id;
	unordered_set<int> link;
	unordered_map<int, int> dp;
};
ll N;
vector<node> nod;

ll f(int ind, int par) {
	ll sum = 1;
	for (int c : nod[ind].link) {
		if (c == par)continue;
		nod[ind].dp[c] = f(c, ind);
		sum += nod[ind].dp[c];
	}
	if (par != -1) {
		nod[ind].dp[par] = N - sum;
	}
	return sum;
}



//拡張ユークリッドの互除法。戻り値は最大公約数、x,yはax+by=gcd(a,b)を満たす組の一つ
long long gcdext(long long a, long long b, long long& x, long long& y) {
	if (b == 0) {
		x = 1;
		y = 0;
		return a;
	}
	long long g = gcdext(b, a % b, y, x);
	y -= a / b * x;
	return g;
}

//モジュラ逆数
long long modinv(long long a, long long mod) {
	long long x, y;
	gcdext(a, mod, x, y);
	x = ((x % mod) + mod) % mod;
	return x;
}
ll modpow(ll r, ll n, ll mod) {
	ll ans = 1;
	ll tmp = r;
	while (n > 0) {
		if ((n & 1) > 0) {
			ans = ans * tmp % mod;
		}
		tmp = tmp * tmp % mod;
		n >>= 1;
	}
	return ans;
}

