    for (int i = 0; i < n - 1; ++i) {
        int a, b;
        cin >> a >> b;
        a--, b--;
        edges[a].push_back(b);
        edges[b].push_back(a);
    }
    vi size(n, -1);
    vvi part(n);
    function<int(int, int)> dfs = [&](int c, int p) {
        if (size[c] != -1)
            return size[c];
        int ret = 0;
        for (auto &v : edges[c]) {
            if (v == p)
                continue;
            int ch = dfs(v, c) + 1;
            ret += ch;
            part[c].emplace_back(ch);
        }
        return size[c] = ret;
    };
    dfs(0, -1);
    mint ret = 0;
    for (int i = 0; i < n; ++i) {
        if (part[i].size() == 0) // leaf
            continue;
        mint temp = mint(2).pow(n - 1) - 1;
        if (i != 0)
            part[i].push_back(n - 1 - size[i]);
        for (auto &ch : part[i]) {
            temp -= mint(2).pow(ch) - 1;
        }
        ret += temp;
    }
    ret /= mint(2).pow(n);
    cout << ret << "\n";
    return 0;
}

