        E[A-1].push_back(B-1);
        E[B-1].push_back(A-1);
    }

    long long M = 1000000007;

    vector<long long> P2(N+1);
    P2[0] = 1;
    for (int i=1; i<=N; i++)
        P2[i] = P2[i-1]*2%M;

    long long ans = 0;
    function<int(int, int)> f = [&](int c, int p)
    {
