        {
            ph -= (P2[N-s-1]-1+M)%M;
            lc++;
        }
        ph -= 1;
        ans += (ph%M+M)%M * powmod(P2[N], M-2, M) % M;
        ans %= M;
        return s+1;
    };
    f(0, -1);
