ll modpow(ll a, ll n, ll mod) {
    ll res = 1;
    while (n) {
        if (n & 1) res = res * a % mod;
        a = a * a % mod;
        n >>= 1;
    }
    return res;
}

ll modinv(ll a, ll mod) {
    ll b = mod, u = 1, v = 0;
    while (b) {
        ll t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= mod;
    if (u < 0) u += mod;
    return u;
}

int dfs(int v, int pv) {
    int num_chi = 1; // 自分自身も含む
    REP(i, T[v].size()) {
        int nv = T[v][i].first;
        if (nv == pv) continue;
        T[v][i].second = dfs(nv, v);
        num_chi += T[v][i].second;
    }
    REP(i, T[v].size()) {
        if (T[v][i].first == pv) T[v][i].second = N - num_chi;
    } 
    return num_chi;
}

ll calc_z() {
    ll x = modpow(2, N, MOD);
    ll x_inv = modinv(x, MOD);
    ll y = 0;

    REP(i, N) {
        y = (y + modpow(2, N-1, MOD)) % MOD;
        y = (y-1) % MOD;
        REP(j, T[i].size()) {
            y = (y - modpow(2, T[i][j].second, MOD) + 1) % MOD;
        }
    }

    ll z = (x_inv * y) % MOD;
    if (z < 0) z += MOD;
    return z;
}

