      mint prob = mint(1) - (inv2 ^ (N - 1));
      for (int x : ch) {
        prob -= (mint(1) - (inv2 ^ x)) * (inv2 ^ (N - 1 - x));
      }
      prob /= 2;
      res += prob;
      return csum + 1;
    };
    dfs(dfs, 0);
    cout << res.value() << endl;
  }
  return 0;
}

