    {
        if (child.size() <= 1)
        {
            continue;
        }
        Mod<MOD> tmp = Mod<MOD>(1) - Mod<MOD>(1) / (1ll << (N - 1));
        for (auto c : child)
        {
            tmp -= Mod<MOD>(1) / (1ll << (N - (c + 1))) * (Mod<MOD>(1) - Mod<MOD>(1) / (1ll << c));
        }
        ans += tmp / 2;
    }
    cout << ans << endl;
}

