int dfs(int cur, int prev = -1) {
    int sz = 1;
    mint score = mint(2).pow(n - 1) - 1;
    for (int to : adj[cur]) {
        if (to == prev) continue;
        int t = dfs(to, cur);
        sz += t;
        score -= mint(2).pow(t) - 1;
    }
    if (prev != -1) {
        score -= mint(2).pow(n - sz) - 1;
    }
    ans += score;
    return sz;
}

