  }

  //for prime mod
  mint inv() const {
    return pow(mod-2);
  }
  mint& operator/=(const mint a) {
    return (*this) *= a.inv();
  }
  mint operator/(const mint a) const {
    mint ret(*this);
    return ret /= a;
  }
};
ostream &operator<<(ostream& os, const mint& x) {
  os << x.x;
  return os;
}

vector<int> G[200005];
int parent[200005];
int cnt[200005];

int dfs(int now, int prev){
  int ret = 0;
  parent[now] = prev;

  rep(i,G[now].size()){
    if(G[now][i] == prev) continue;
    ret += dfs(G[now][i], now);
  }

  ret++;
  return cnt[now] = ret;
}


int main(){
  int N;
  cin >> N;
  rep(i,N-1){
    int a, b;
    cin >> a >> b;
    G[a].push_back(b);
    G[b].push_back(a);
  }

  dfs(1, -1);

  mint ans(0);
  REP(i,1,N+1){
    vector<int> w;
    rep(j,G[i].size()){
      int c = 0;
      if(G[i][j] == parent[i]){
        c = N - cnt[i];
      }else{
        c = cnt[G[i][j]];
      }
      w.push_back(c);
    }
    mint sum(1);
    rep(i,w.size()){
      sum += mint(2).pow(w[i]) - 1;
    }
    ans += mint(2).pow(N-1) - sum;
  }

  ans /= mint(2).pow(N);

  cout << ans << endl;

  return 0;
}

