        g.add_edge(A, B);
        g.add_edge(B, A);
    }

    vector<vector<long long>> children(g.node);
    dfs(g, children, 0, 1);

    Mod<MOD> ans = 0;
    for (auto child : children)
    {
        if (child.size() <= 1)
        {
            continue;
        }
        Mod<MOD> tmp = Mod<MOD>(1);
        tmp -= power(Mod<MOD>(1) / 2, (N - 1));
        for (auto c : child)
        {
            tmp -= power(Mod<MOD>(1) / 2, N - (c + 1)) * (Mod<MOD>(1) - power(Mod<MOD>(1) / 2, c));
        }
        ans += tmp / 2;
    }
    cout << ans << endl;
}

