constexpr auto pow(long long x, long long n, const long long mod) {
    long long ret = 1;
    while(n > 0) {
        if ((n & 1) == 1) ret = (ret * x) % mod;
        x = (x * x) % mod;
        n >>= 1;
    }
    return ret;
}

constexpr auto inverse(const long long x, const long long p) {
    return pow(x, p - 2, p);
}

std::vector<std::vector<int>> g;
constexpr i64 mod = 1000000007;
std::vector<i64> cs, dp, p2;
int n;

int szdfs(int v, int p) {
    for (int to : g[v]) {
        if (to == p) continue;
        cs[v] += szdfs(to, v);
    }
    return cs[v];
}

void dfs(int v, int p) {
    i64 s = p2[n - cs[v]] - 1;
    for (int to : g[v]) {
        if (to == p) continue;
        dfs(to, v);
        s = (s + p2[cs[to]] + mod - 1) % mod;
    }
    dp[v] = s + 1;
}

int main() {
    std::cin >> n;
    g.resize(n); cs.resize(n, 1); dp.resize(n);
    p2.push_back(1);
    for (int i = 0; i < n; i++) p2.push_back(p2.back() * 2 % mod);
    for (int i = 1; i < n; i++) {
        int u, v;
        std::cin >> u >> v;
        --u; --v;
        g[u].push_back(v);
        g[v].push_back(u);
    }

    szdfs(0, -1);
    dfs(0, -1);

    i64 ret = 0;
    for (int i = 0; i < n; i++) {
        ret = (ret + p2[n - 1] + mod - dp[i]) % mod;
    }

    std::cout << ret * inverse(p2[n], mod) % mod << std::endl;

    return 0;
}

