}
using mint = ModInt<long long>;

void solve() {
    int n;
    cin >> n;
    auto g = vecs(n, 0, int());
    rep(i, n - 1) {
        int a, b;
        cin >> a >> b;
        --a, --b;
        g[a].emplace_back(b);
        g[b].emplace_back(a);
    }

    auto cnt = vecs(n, int());
    funcs([&](auto dfs, int v, int p) -> void {
        int res = 1;
        each(nv, g[v]) {
            if (nv == p) continue;
            dfs(nv, v);
            res += cnt[nv];
        }
        cnt[v] = res;
    })(0, -1);

    mint ans = 0;
    funcs([&](auto dfs, int v, int p) -> void {
        mint res = 0;
        mint sum = 1;
        if (p != -1) {
            auto tmp = mint(2).pow(cnt[0] - cnt[v]);
            res += tmp - 1;
            sum *= tmp;
        }

        each(nv, g[v]) {
            if (nv == p) continue;
            auto tmp = mint(2).pow(cnt[nv]);
            res += tmp - 1;
            sum *= tmp;
            dfs(nv, v);
        }

        res += 1;
        if (sz(g[v]) != 1)
            ans += sum - res;
        })(0, -1);

    ans /= mint(2).pow(n);
    cout << ans << endl;
}

signed main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(15);
    solve();
    cout.flush();
    return 0;
}

