vvll g;
vll found; //発見されたフラグ
vvll childCount;

ll dfs(ll parent) { //引数で渡されたノードを親とした部分木に含まれるノード数(親含む)を返す
	//このノードを発見済みに
	found[parent] = 1;

	//このノードの子を探索
	ll count = 1; //自分自身
	for (auto next : g[parent]) {
		if (found[next] > 0) {
			continue; //発見済み＝親
		}

		ll temp = dfs(next);
		childCount[parent].push_back(temp);
		count += temp;
	}

	return count;
}

ll mod_pow(ll x, ll n, ll mod) {
	ll ret = 1;
	while (n > 0) {
		if (n & 1) {
			(ret *= x) %= mod;
		}
		(x *= x) %= mod;
		n >>= 1;
	}
	return ret;
}

int main() {
	ll N;
	cin >> N;
	g.resize(N);
	rep(i, N - 1) {
		ll A;
		cin >> A;
		ll B;
		cin >> B;
		A--;
		B--;
		g[A].push_back(B);
		g[B].push_back(A);
	}
	found.resize(N, 0);
	childCount.resize(N);
	dfs(0); //ノード0を根とする

	//2^iを求めておく
	vmll twoPow(N + 1);
	twoPow[0] = 1;
	reps(i, 1, N) {
		twoPow[i] = twoPow[i - 1] * 2;
	}

	//すべての頂点を走査して、その頂点が穴となるパタン数を計上
	mll sum = 0;
	rep(i, N) {
		mll temp = twoPow[N - 1] - 1;
		ll countNotChild = N - 1;

		for (auto item : childCount[i]) {
			countNotChild -= item;
			temp -= (twoPow[item] - 1);
		}

		temp -= (twoPow[countNotChild] - 1);
		sum += temp;
	}

	mll result = sum / twoPow[N];

	cout << result << endl;

	return 0;
}

