mint ans;
vector<mint> pow2;
int N;
vl size;
vvl edges;

void dfs(int v, int pre) {
    size[v] = 1;
    mint cnt = pow2[N - 1] - 1;
    for (auto to : edges[v]) {
        if (to == pre) continue;
        dfs(to, v);
        size[v] += size[to];
        cnt -= pow2[size[to]] - 1;
    }
    cnt -= pow2[N - size[v]] - 1;
    ans += cnt;
}

int main() {
    cin >> N;
    edges.resize(N);
    size.resize(N);
    pow2.assign(N+1, 1);
    rep(i,N-1) {
        int a, b; cin >> a >> b;
        a--; b--;
        edges[a].push_back(b);
        edges[b].push_back(a);
    }
    rep(i,N) pow2[i+1] = pow2[i] * 2;

    int root = 0;
    dfs(root, -1);
    ans /= pow2[N];
    cout << ans << endl;
    return 0;
}

