const int M = 1e9 + 7, N = 2e5 + 7;
int ans;

int qpow(int a, int b) {
	if(b == 0) return 1;
	int t = qpow(a, b/2);
	if(b & 1) return t * t % M * a % M;
	else return t * t % M;
}

int inv(int a) {
	return qpow(a, M-2);
}

vi G[N];
int sum[N], cnt[N];

void dfs(int u, int p = -1) {
	if(G[u].size() == 1 && p != -1) {
		sum[u] = 0;
		cnt[u] = 2;
		return;
	}
	cnt[u] = 1;
	for(int v:G[u])if(v != p) {
		dfs(v, u);
		cnt[u] = cnt[u] * cnt[v] % M;
	}
	for(int v:G[u]) if(v != p) {
		sum[u] += cnt[u] * inv(cnt[v]) % M * (sum[v] + sum[v]) % M;
		ans -= sum[v] + (cnt[v] - 1);
	}
	sum[u] += (cnt[u] - 1);
	ans += sum[u] ;
	cnt[u] = cnt[u] * 2 % M;
}

