void dp(int idx, int par){
    int ans = 1;
    int ans2 = zi[n-1];

    for(int i = 0;i < graph[idx].size();i++){
        int child = graph[idx][i];
        if(child == par) continue;

        dp(child, idx);

        ans += dp1[child];
        ans2 -= (MOD+zi[dp1[child]]-1)%MOD;
        if(ans2 < 0) ans2 = MOD+ans2;
    }

    dp1[idx] = ans;
    ans2 -= zi[n-ans];
    if(ans2 < 0) ans2 = MOD+ans2;

    dp2[idx] = ans2;
    return;
}

