ll mod_pow(ll x, ll p, ll M = MOD) {
  ll a = 1;
  while (p) {
    if (p % 2)
      a = a*x%M;
    x = x*x%M;
    p /= 2;
  }
  return a;
}

ll mod_inverse(ll a, ll M = MOD) {
  return mod_pow(a, M - 2, M);
}


vii G;
vl dp;
ll inv2 = mod_inverse(2);

ll dfs1(int now, int par) {
  ll mul = 1;
  for (int ch: G[now]) {
    if (ch == par) continue;
    mul = mul * (1 - dfs1(ch, now)) % MOD;
  }
  dp[now] = (1 - mul * inv2 % MOD + MOD) % MOD;
  return dp[now];
}

ll ans = 0;

void dfs2(int now, int par) {
  //DEBUG(now);
  vl white;
  for (int ch: G[now]) {
    white.push_back((1 - dp[ch] + MOD) % MOD);
  }
  int n = white.size();
  vl left(n + 1), right(n + 1);
  left[0] = 1;
  rep (i, n) {
    left[i + 1] = left[i] * white[i] % MOD;
  }
  right[0] = 1;
  rep (i, n) {
    right[i + 1] = right[i] * white[n - 1 - i] % MOD;
  }

  /*
  DEBUG_VEC(dp);
  DEBUG_VEC(white);
  DEBUG_VEC(left);
  DEBUG_VEC(right);
  //*/

  ll ng = 0;
  ng += left[n];
  rep (i, n) {
    ll add = left[i] * right[n - 1 - i] % MOD;
    (add *= (1 - white[i])) %= MOD;
    (ng += add) %= MOD;
  }
  //DEBUG(ng);
  (ans += (1 - ng) % MOD * inv2 % MOD) %= MOD;

  ll ori = dp[now];
  int cnt = 0;
  for (int ch: G[now]) {
    if (ch == par) {
      cnt++;
      continue;
    }
    ll ori_ch = dp[ch];
    ll add = left[cnt] * right[n - 1 - cnt] % MOD;
    dp[now] = (1 - add * inv2 % MOD + MOD) % MOD;
    dp[ch] = (1 - ((1 - ori_ch) * dp[now] % MOD) + MOD) % MOD;
    dfs2(ch, now);
    dp[now] = ori;
    dp[ch] = ori_ch;
    cnt++;
  }
}

