}
const ll N = 2e5;
ll n, not_count = 0;
vector <ll> edge[N+1];
ll dp[N+1] = {};
ll inv2 = fast_exp(2,mod-2);
ll cnt_subtree(ll v, ll par)
{
	ll cnt = 1;
	for(auto e: edge[v])
	{
		if(e != par)
		{
			cnt = (cnt + cnt_subtree(e,v));
		}
	}
	dp[v] = cnt;
	return cnt;
}
void printer()
{
	for(int i = 1; i<=n ; i++)
		cout<<i<<"   :    "<<dp[i]<<endl;

	cout<<"\n\n";
}

void re_root(ll root, ll new_root)
{
	dp[root] -= dp[new_root];
	dp[new_root] += dp[root];
	return;
}

void dfs_notcount(ll v, ll par)
{
	cout<<"root = "<<v<<endl;
	printer();
	for(auto e : edge[v])
	{

		not_count = ( not_count +  fast_exp(inv2 , n-dp[e]-1)  )%mod;
		if(e == par)
			continue;
		re_root(v,e);

		dfs_notcount(e,v);

		re_root(e,v);
		cout<<"root = "<<v<<endl;
		printer(); 
	}
	return;
}


