struct Edge {
	int next,to;
}edge[N<<1];
inline void add(int u,int v) {
	edge[++cnt] = (Edge)<%head[u],v%>;
	head[u] = cnt;
}
int Pow(int x,int y) {
	int res = 1, base = x;
	while(y) {
		if(y&1) res = (res*base)%MOD; base = (base*base)%MOD; y >>= 1;
	}
	return res;
}
void Dfs(int u,int fath) {
	sz[u] = 1, fa[u] = fath;
	for(int i=head[u];i;i=edge[i].next) {
		int v = edge[i].to;
		if(v != fath) {
			Dfs(v,u); sz[u] += sz[v];
		}
	}
}
signed main()
{
	n = read();
	for(int i=1,u,v;i<=n-1;++i) {
		u = read(), v = read();
		add(u,v), add(v,u);
	}
	p[0] = 1;
	for(int i=1;i<=n;++i) p[i] = (p[i-1]<<1)%MOD;
	int inv = Pow(p[n],MOD-2);
	Dfs(1,0);
	for(int u=1;u<=n;++u) {
		int tot = (p[n-1]-1+MOD)%MOD;
		for(int i=head[u];i;i=edge[i].next) {
			int v = edge[i].to;
			if(v == fa[u]) tot = (tot - (p[n-sz[u]]-1+MOD)%MOD+MOD)%MOD;
			else tot = (tot - (p[sz[v]]-1+MOD)%MOD+MOD)%MOD;
		}
		ans = (ans+(tot*inv)%MOD)%MOD;
	}
	printf("%lld\n",ans);
	return 0;
}

