const ll mod = 1000000007;
struct mint {
    ll x;  // typedef long long ll;
    mint(ll x = 0) : x((x % mod + mod) % mod) {}
    mint& operator+=(const mint a) {
        if ((x += a.x) >= mod) x -= mod;
        return *this;
    }
    mint& operator-=(const mint a) {
        if ((x += mod - a.x) >= mod) x -= mod;
        return *this;
    }
    mint& operator*=(const mint a) {
        (x *= a.x) %= mod;
        return *this;
    }
    mint operator+(const mint a) const {
        mint res(*this);
        return res += a;
    }
    mint operator-(const mint a) const {
        mint res(*this);
        return res -= a;
    }
    mint operator*(const mint a) const {
        mint res(*this);
        return res *= a;
    }
    mint pow(ll t) const {
        if (!t) return 1;
        mint a = pow(t >> 1);
        a *= a;
        if (t & 1) a *= *this;
        return a;
    }

    mint inv() const {
        return pow(mod - 2);
    }
    mint& operator/=(const mint a) {
        return (*this) *= a.inv();
    }
    mint operator/(const mint a) const {
        mint res(*this);
        return res /= a;
    }
};

int n;
mint ans;
vector<int> adj[200200];

int dfs(int cur, int prev = -1) {
    int sz = 1;
    mint score = mint(2).pow(n - 1) - 1;
    vector<int> parts;
    for (int to : adj[cur]) {
        if (to == prev) continue;
        int t = dfs(to, cur);
        sz += t;
        parts.push_back(t);
    }
    if (prev != -1) {
        parts.push_back(n - sz);
    }
    for (int t : parts) {
        score -= mint(2).pow(t) - 1;
    }
    ans += score;
    return sz;
}

