void solve(int N, vi A, vi B) {
  vvi adj(N);
  rep(i, N - 1) {
    adj[A[i]].push_back(B[i]);
    adj[B[i]].push_back(A[i]);
  }
  mint ans = mint(2).pow(N - 1) * N - N;
  function<int(int, int)> dfs = [&](int x, int p) {
    int cnt = 1;
    each(nx, adj[x]) {
      if(nx == p) continue;
      int ncnt = dfs(nx, x);
      cnt += ncnt;
      ans -= mint(2).pow(ncnt) - 1;
    }
    ans -= mint(2).pow(N - cnt) - 1;
    return cnt;
  };
  dfs(0, -1);
  COUT(ans / mint(2).pow(N));
}


