using namespace std;

#define MAXN 200000

// x^n in mod
ll modpow(ll x, ll n, ll mod){
  if(n==0) return 1;

  if(n%2==0){
    return modpow(x*x%mod, n/2, mod) % mod;
  }else{
    return x * modpow(x, (n-1), mod) % mod;
  }
}

int n;
vector<int> to[MAXN];

ll result=0;

int dfs(int v, int p=-1){
  int res=1;
  vector<int> ts;
  for(int u: to[v]){
    if(u==p)continue;
    int t = dfs(u, v);
    res += t;
    ts.push_back(t);
  }
  if(p!=-1)ts.push_back(n-res);

  ll now = modpow(2, n-1, MOD)-1;
  for(int t: ts)now -= modpow(2, t, MOD)-1;
  result += now;
  result%=MOD;

  return res;
}

