  }

  dfs(0);
//cout<<result<<' '<<modpow(2, n, MOD)<<endl;
  ll all = modpow(2, n, MOD);
  result *= modpow(all, MOD-2, MOD);

  cout<<result%MOD<<endl;

  return 0;
}

