    ll a, b;
    cin >> a >> b;
    --a; --b; // 0-indexed
    tree[a].push_back(b);
    tree[b].push_back(a);
  }

  dfs(0); // start dfs from 0
  ans /= mint(2).pow(n);
  cout << ans.x << endl;
}

