const ll MOD = 1000000007;

ll modpow(ll x, ll n){
    ll res = 1;
    ll mul = x;
    while(n){
        if(n % 2) res = res * mul % MOD;
        mul = mul * mul % MOD;
        n /= 2;
    }
    return res;
}

const ll h = modpow(2, MOD - 2);

struct Graph
{
    int n;
    vector<vector<int>> g;

    Graph(int n) : n(n){
        g.resize(n);
    }

    void init(int n_){
        n = n_;
        g.resize(n_);
    }

    void add_edge(int from, int to){
        g[from].push_back(to);
    }
};

struct Tree	//create tree(directed) from graph(undirected)
{
    int n;
    int root;
    vector<vector<int>> t;
    vector<int> par;
    vector<int> dpt;
    vector<ll> sz;

    void init(Graph &g, int root_){
        n = g.n;
        root = root_;
        t.resize(n);
        par.resize(n);
        dpt.resize(n);
        sz.resize(n);
        fill(dpt.begin(), dpt.end(), -1);
        queue<int> que;
        par[root] = -1;
        dpt[root] = 0;
        que.push(root);
        while(que.size()){
            int pa = que.front();
            que.pop();
            for(int ch : g.g[pa]){
                if(dpt[ch] == -1){
                    t[pa].push_back(ch);
                    par[ch] = pa;
                    dpt[ch] = dpt[pa] + 1;
                    que.push(ch);
                }
            }
        }
    }

    Tree(){}

    Tree(Graph &g, int root_){
        init(g, root_);
    }

    ll size(int k){
        if(sz[k]) return sz[k];
        ll res = 1;
        for(int ch : t[k]) res += size(ch);
        return sz[k] = res;
    }
};

int main()
{
    int n;
    cin >> n;
    Graph g(n);
    for(int i = 0; i < n - 1; i++){
        int a, b;
        cin >> a >> b;
        a--; b--;
        g.add_edge(a, b);
        g.add_edge(b, a);
    }
    Tree t(g, 0);
    ll ans = 0;
    if((int)t.t[0].size() != 1){
        ll s = 1;
        for(int ch : t.t[0]){
            s = (s + MOD - modpow(h, n - t.size(ch) - 1)) % MOD;
        }
        s = (s + modpow(h, n - 1) * ((ll)t.t[0].size() - 1) % MOD) % MOD;
        ans = s * h % MOD;
    }
    for(int i = 1; i < n; i++){
        if((int)t.t[i].size() == 0) continue;
        ll s = 1;
        for(int ch : t.t[i]){
            s = (s + MOD - modpow(h, n - t.size(ch) - 1)) % MOD;
        }
        s = (s + modpow(h, n - 1) * (ll)t.t[i].size() % MOD) % MOD;
        s = (s + MOD - modpow(h, t.size(i) - 1)) % MOD;
        ans = (ans + s * h % MOD) % MOD;
    }
    cout << ans << endl;
}

