const ll mod = 1e9 + 7;

ll mod_pow(ll x, ll n) {
    ll ret = 1;
    while (n) {
        if (n&1) {
            ret = ret * x % mod;
            x = x * x % mod;
            n >>= 1;
        }
        else {
            x = x * x % mod;
            n >>= 1;
        }
    }
    return ret;
}

int n;
vector<int> g[101010];
ll ans = 0;

ll dfs(int v, int p) {
    vector<int> child;
    int sz = 0;

    for (auto & u : g[v]) {
        if (u == p) continue;
        child.push_back(dfs(u, v));
        sz += child[child.size()-1];
    }

    child.push_back(n - 1 - sz);

    ll prob = mod_pow(mod_pow(2, n), mod-2);
    for (auto & c : child) {
        prob += mod_pow(mod_pow(2, n-c), mod-2) * (1 - mod_pow(mod_pow(2, c), mod-2)) % mod;
    }
    ans += (mod_pow(2, mod-2) - prob) % mod;
    ans %= mod;

    return sz + 1;
}

