void solve() {
    int n;
    cin >> n;
    vector<vector<int> > G(n);
    rep(i, n - 1) {
        int a, b;
        cin >> a >> b;
        --a; --b;
        G[a].eb(b);
        G[b].eb(a);
    }

    vector<ll> d(n, 1);
    auto dfs = [&](auto&& dfs, int v, int p) -> int {
        int sum = 0;
        for (int nv : G[v]) {
            if (nv == p) continue;
            int cnt = dfs(dfs, nv, v);
            sum += cnt;
            add(d[v], modpow(2, cnt, mod) - 1); // 1つの枝だけ1つ以上黒がある
        }
        // 親方向
        int rest = (n - 1) - sum;
        add(d[v], modpow(2, rest, mod) - 1);

        d[v] = (modpow(2, n - 1, mod) - d[v] + mod) % mod; // 余事象
        return sum + 1;
    };
    rep(i, n) {
        if (sz(G[i]) == 1) {
            dfs(dfs, i, -1);
            break;
        }
    }
    // cerr << d << endl;

    ll ans = accumulate(all(d), 0LL) % mod; // debuged
    (ans *= modpow(modpow(2, n, mod), mod - 2, mod)) %= mod;
    cout << ans << endl;
}

