int dfs(int from, int now) {
    int res = 1;
    for(auto to: adj[now]) if (to!=from) { par[to] = now; res += dfs(now, to); }
    return child[now] = res;
}

void solve() {
    dfs(-1, 0);
    ll ans = 0;
    rep(now, N) {
        ll num = modpow(2, N-1) + 1;
        ll ue = N-1;
        for(auto to: adj[now]) if (par[to] == now) ue -= child[to];
        //cout << ue << endl;
        for(auto to: adj[now]) {
            if (par[to] == now) num += modpow(2, child[to]) + mod - 1;
            else num += modpow(2, ue) + mod - 1;
            chmod(num);

        }
        num = modpow(2, N) - num;
        chmod(num);
        num *= modpow(modpow(2, N), mod-2);
        chmod(num);
        ans += num;
        chmod(ans);
    }

    // ans *= modpow(modpow(2, N), mod-2);
