class LCA{
public:
  typedef pair<int,int> P;
  int LOG_V;                          //log V (自分で決めて)
  int V;                              //頂点数
  vector<vector<P> > G;               //グラフの隣接リストの表現
  int root;                           //根のノード番号
  vector<vector<int> > parent;        //親を2^k回辿って到達する頂点(根を通りすぎる場合は-1とする)
  vector<int> depth;                  //根からの深さ
  vector<int> D;                      //根からの距離
  int ok;

  LCA():V(-1){}
  LCA(int V,int root = 0):V(V),G(V),root(root),depth(V), D(V, 0),ok(0){
    LOG_V = 1;
    int tmp = V;
    while(tmp) LOG_V++, tmp /= 2;
    parent.resize(LOG_V, vector<int>(V));
  }

  void add_edge(int a, int b,int c = 1){
    assert(a >= 0 && b >= 0);
    assert(a < V && b < V);
    G[a].push_back(P(b,c));
    G[b].push_back(P(a,c));
  }

  void dfs(int v,int p,int d,int c){
    assert(v < V);
    parent[0][v] = p;
    depth[v] = d;
    D[v] = c;
    for(auto to:G[v])
      if(to.first != p) dfs(to.first, v, d+1, c + to.second);
  }

  //vからn個上の祖先
  int getAnc(int v,int n){
    for(int k=0; k<LOG_V ;k++) if((v != -1) && (n>>k&1)) v=parent[k][v];
    return v;
  }

  //初期化
  void build(){
    ok = 1;
    //parent[0]とdepthを初期化する。
    dfs(root, -1, 0, 0);
    //parentを初期化する
    for(int k=0; k+1<LOG_V ;k++)
      for(int v=0; v<V ;v++)
        if(parent[k][v] < 0)parent[k+1][v] = -1;
        else parent[k+1][v] = parent[k][parent[k][v]];
  }

  //uとvのLCAを求める
  int get(int u,int v){
    assert(ok);
    assert(u >= 0 && v >= 0);
    assert(u < V && v < V);
    if(depth[u]>depth[v]) swap(u,v);
    v = getAnc(v, depth[v] - depth[u]);

    if(u==v) return u;
    //二分探索でLCAを求める
    for(int k=LOG_V-1; k>=0 ;k--)
      if(parent[k][u] != parent[k][v]){
        u = parent[k][u];
        v = parent[k][v];
      }
    return parent[0][u];
  }

  int getDis(int u,int v){
    assert(u >= 0 && v >= 0);
    assert(u < V && v < V);
    return D[u] + D[v] - 2 * D[get(u, v)];
  }

  //rootを根としたときの頂点uの親: O(logV)
  int getParent(int u, int root = -1){
    if(root == -1) root = this->root;
    assert(ok);
    assert(0 <= u && u < V);
    assert(0 <= root && root < V);
    if(u == root) return -1;
    int num = depth[root] - depth[u];
    if(num > 0){
      int v = getAnc(root, num - 1);
      int p = parent[0][v];
      if(p == u) return v;
    }
    return parent[0][u];
  }
};


class TreeSize{
public:
  int V;                        //ノード数
  int root;                     //根
  vector<vector<int> > G;       //Graph
  vector<int> w;                //ノードのに重みが有る場合デフォルトでは1
  vector<int> sz;               //部分木のサイズ
  LCA lca;
  int ok;
  TreeSize():V(-1){};
  TreeSize(int V,int root = 0):V(V),root(root),G(V),w(V,1),sz(V,0), lca(V, root),ok(0){}
  void resize(int n){*this = TreeSize(n);}
  int& operator [](int i){return w[i];}

  void add_edge(int a,int b){
    ok = false;
    assert(a < V && b < V);
    assert(a >= 0 && b >= 0);
    lca.add_edge(a, b);
    G[a].push_back(b);
    G[b].push_back(a);

  }

  void build(int root=-1){
    ok = 1;
    if(root != -1) this->root = root;
    dfs(this->root,-1);
    lca.build();
  }

  int dfs(int pos,int pre = -1){
    sz[pos] = w[pos];
    for(int to:G[pos]) if(to != pre) sz[pos] += dfs(to, pos);
    return sz[pos];
  }
  int size(int i){assert(ok), assert(0 <= i && i < V);return sz[i];}
  int size(int i, int root){
    assert(ok);
    assert(0 <= i && i < V);
    assert(0 <= root && root < V);
    int p = lca.getParent(i, root);
    if(p == -1) return V;
    return (lca.parent[0][p] == i)? V - sz[p]:sz[i];
  }
};

