int solve2(int sz) {
	if (sz == 0)
		return 0;
	int &ans = dp[sz];
	if (ans != -1)
		return ans;
	return ans = add(half, mul(half, solve2(sz - 1)));
}

int solve(int node, int idx, int cnt) {
	if (idx == szs[node].size())
		return cnt == 2;
	int &ans = dp2[idx][cnt];
	if (mark[idx][cnt] == node)
		return ans;
	mark[idx][cnt] = 1;
	return ans = add(mul(solve(node, idx + 1, cnt), val[szs[node][idx]])
			, mul(solve(node, idx + 1, min(cnt + 1, 2)), solve2(szs[node][idx])));
