        vis[id]+=i;
        continue;
      }
      solvelist.eb(g[id][i]);
      v[id][i]=dfs(g[id][i],i);
      res=merge(res,v[id][i]);
    }
    return res+1;
  }
  ll call(int i,int j){
    ll res=E;
    if(j)res=merge(l[i][j-1],res);
    if(j+1!=(int)g[i].size())res=merge(res,r[i][j+1]);
    return res+1;
  }
