using mint = modint<MOD>;

mint npow(int n){
    const int N = 3e6;
    static vector<mint> dp(N);
    static vector<bool> used(N,false);
    if(n==0)return 1;
    if(used[n])return dp[n];
    used[n] = true;
    return dp[n] = npow(n-1) * 2;
}

mint func(){
    int n = in();
    vvector<pii> edges(n);
    rep(i,n-1){
        int a = in()-1;
        int b = in()-1;
        edges[a].emplace_back(b,edges[b].size());
        edges[b].emplace_back(a,edges[a].size()-1);
    }

    vvector<int> depth_dp(n);
    rep(i,n){
        depth_dp[i] = vector<int>(edges[i].size(),-1);
    }

    method(depth,int,int place,int last){
        int &it = depth_dp[place][last];
        if(it>=0)return it;
        it = 1;
        rep(i,edges[place].size()){
            if(i==last)continue;
            pii &edge = edges[place][i];
            it += depth(edge.first,edge.second);
        }
        return it;
    };

    method(culc_value,mint,int place){
        if(edges[place].size()<2)return mint(0);
        mint valids = npow(n-1);
        valids -= 1;
        foreach(i,edges[place]){
            valids -= npow(depth(i.first,i.second)) - 1;
        }
        return valids;
    };

    vector<pii> order;
    rep(i,n){
        order.emplace_back(edges[i].size(),i);
    }
    sort(all(order),greater<pii>());

    mint res = 0;
    rep(i,n){
        res += culc_value(order[i].second);
    }
    res /= npow(n);
    return res;
}

int main(){
    cout << func() << endl;
    return 0;
}

