const ll MOD =  1e9+7;
ll powmod(ll x, ll n){
    ll ret=1;
    while(n>0){
        if(n&1){
            ret*=x;
            ret%=MOD;
            n-=1;
        }
        else{
            x*=x;
            x%=MOD;
            n>>=1;
        }
    }
    return ret;
}
struct Rerooting{
    /*  begin here  */
    struct DP{
        long long dp;
        DP(long long dp_):dp(dp_){}
    };
    const DP identity=DP(0);
    function<DP(DP,DP)> merge = [](DP dp_cum,DP d) -> DP{ return DP((dp_cum.dp+d.dp)%MOD); };
    function<DP(DP)> add_root = [](DP d) -> DP{ return DP(d.dp+1); };
    /*  end here   */
    struct Edge{
        int to;
    };
    using Graph=vector<vector<Edge>>;
    vector<vector<DP>> dp; //dp[i][j]:=from i number j path
    vector<DP> ans;
    Graph G;
    Rerooting(int N):G(N){
        dp.resize(N);
        ans.assign(N,identity);
    }
    void add_edge(int a,int b){
        G[a].push_back({b});
    }
    void build(){
        dfs(0);
        dfs2(0,identity);
    }
    DP dfs(int _v,int _par=-1){
        DP dp_cum=identity; //累積をとる
        int _sz=(int)G[_v].size();
        dp[_v]=vector<DP>(_sz,identity);
        for(int _i=0;_i<_sz;_i++){
            int _u=G[_v][_i].to;
            if(_u==_par) continue;
            dp[_v][_i]=dfs(_u,_v);
            dp_cum=merge(dp_cum,dp[_v][_i]);
        }
        return add_root(dp_cum);
    }
    void dfs2(int _v,const DP& dp_p,int _par=-1){
        int _sz=(int)G[_v].size();
        for(int _i=0;_i<_sz;_i++){
            if(G[_v][_i].to==_par) dp[_v][_i]=dp_p;
        }
        vector<DP> dp_l(_sz+1,identity),dp_r(_sz+1,identity);
        for(int _i=0;_i<_sz;_i++){
            dp_l[_i+1]=merge(dp_l[_i],dp[_v][_i]);
        }
        for(int _i=_sz-1;_i>=0;_i--){
            dp_r[_i]=merge(dp_r[_i+1],dp[_v][_i]);
        }
        ans[_v]=add_root(dp_l[_sz]);
        for(int _i=0;_i<_sz;_i++){
            int _u=G[_v][_i].to;
            if(_u==_par) continue;
            dfs2(_u,add_root(merge(dp_l[_i],dp_r[_i+1])),_v);
        }
    }
    ll solve(int v){
        ll res=0;
        rep(j,dp[v].size()){
            res+=powmod(2,dp[v][j].dp);
            res%=MOD;
        }
        return res;
    }
};

signed main(){
    std::cin.tie(nullptr);
    std::ios_base::sync_with_stdio(false);
    int n; cin >> n;
    Rerooting tree(n);
    vector<ll> deg(n,0);
    rep(i,n-1){
        int x,y; cin >> x >> y;
        x--; y--;
        tree.add_edge(x, y);
        tree.add_edge(y, x);
        deg[x]++; deg[y]++;
    }
    tree.build();
    ll ans=(n*powmod(2,n-1))%MOD;
    ans-=n;
    ans=(ans+MOD)%MOD;
    rep(i,n){
        ll res=tree.solve(i);
        //cout << res << endl;
        ans+=deg[i];
        ans-=res;
        ans=(ans+MOD)%MOD;
    }
    ll x=MOD-1-n;
    ans*=powmod(2,x);
    ans%=MOD;
    cout << ans << endl;
}

