int rec(int v, int p = -1) {
    int res = 0;
    int tmp = modpow[N - 1] - 1;
    dp[v] = 1;
    for (auto nv : G[v]) {
        if (nv == p)
            continue;
        (res += rec(nv, v)) %= MOD;
        (tmp -= modpow[dp[nv]] - 1) %= MOD;
        dp[v] += dp[nv];
    }
    (tmp -= modpow[N - dp[v]] - 1) %= MOD;
    (res += tmp) %= MOD;
    return res;
}

void extGCD(ll a, ll b, ll &p, ll &q) {
    if (b == 0) {
        p = 1, q = 0;
        return;
    }
    extGCD(b, a % b, q, p);
    q -= a / b * p;
}

int modinv(ll a, ll m) {
    ll p, q;
    extGCD(a, m, p, q);
    p %= m;
    if (p < 0)
        p += m;
    return p;
}

