void solve(const Graph &tree, int parent, int child, vector<int> *subs, vector<mint> *dp){
  static const int N= (int)tree.size();

  mint Nwhite_not_holed= 1; // 黒い頂点が0個の木
  // 黒い頂点が1つの枝だけの木を足し上げる
  for(auto ngh:tree.at(child)){
    if(ngh != parent){
      solve(tree, child, ngh, subs, dp);

      subs->at(child)+= subs->at(ngh);
      Nwhite_not_holed+= ((mint)2).pow(subs->at(ngh))- 1;
    }
  }
  subs->at(child)++;
  Nwhite_not_holed+= ((mint)2).pow(N- subs->at(child))- 1;

  dp->at(child)= ((mint)2).pow(N-1)- Nwhite_not_holed;
}

int main(){
  int N;
  cin >> N;
  const int M= N-1;

  Graph tree(N);

  int v1,v2;
  for(int j=0; j<M; j++){
    cin >> v1 >> v2;
    v1--; v2--; // 1-indexed -> 0-indexed
    tree.at(v1).emplace_back(v2);
    tree.at(v2).emplace_back(v1);
  }

  vector<int> subs(N);
  vector<mint> dp(N);

  solve(tree, -1, 0, &subs, &dp);

  mint Nholed= 0;
  for(auto holed_v:dp){
    Nholed+= holed_v;
  }
  mint ans= Nholed/ ((mint)2).pow(N);

  cout << ans << endl;
}

