        p2[i] = p2[i - 1] * 2 % MOD;
    }
    int n;
    scanf("%d", &n);
    for (int i = 1, u, v; i < n; i++) {
        scanf("%d%d", &u, &v);
        --u, --v;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    dfs(0);
    i64 ans = 0;
    for (int i = 0; i < n; i++) {
        ans += (p2[sz[i]] - 1) * (p2[n - sz[i]] - 1) % MOD;
        ans %= MOD;
    }
    ans = (ans - n * p2[n - 1] % MOD + p2[n] - 1 + MOD) % MOD;
    ans = ans * pow(p2[n], MOD - 2, MOD) % MOD;
    printf("%lld\n", ans);
}

