vector<vector<ll>> net;
vector<map<ll, ll>> num;

void count(ll cur, ll par){
    for(ll nxt : net.at(cur)){
        if(nxt == par){ continue; }
        count(nxt, cur);
        ll tmp = 1;
        for(ll x : net.at(nxt)){
            if(x == cur){ continue; }
            tmp += num.at(nxt).at(x);
        }
        num.at(cur)[nxt] = tmp;
    }
    if(par != -1){
        ll tmp = 0;
        for(ll nxt : net.at(cur)){
            if(nxt != par){
                tmp += num.at(cur).at(nxt);
            }
        }
        num.at(cur)[par] = (ll)net.size() - 1 - tmp;
    }
}

void solve(long long N, std::vector<long long> A, std::vector<long long> B){
    net.resize(N);
    REP(i, N - 1){
        ll a = A.at(i) - 1;
        ll b = B.at(i) - 1;
        net.at(a).push_back(b);
        net.at(b).push_back(a);
    }

    num.resize(N);
    count(0, -1);

    vector<mint> pow2(N), pow2inv(N);
    pow2.at(0) = 1;
    pow2inv.at(0) = 1;
    for(ll i = 1; i < N; ++i){
        pow2.at(i) = pow2.at(i - 1) * 2;
        pow2inv.at(i) = pow2.at(i).inv();
    }

    mint ans = 0;
    REP(i, N){
        mint tmp = 0;
        for(auto p : num.at(i)){
            assert(p.second < N);
            tmp += pow2.at(p.second);
        }
        tmp -= net.at(i).size();
        tmp += 1;
        for(auto p : num.at(i)){
            tmp *= pow2inv.at(p.second);
        }
        ans += (mint(1) - tmp) / 2;
    }
    cout << ans << endl;
}

