    ans[v] = dpLeft[deg].addRoot();

    rep(i,deg) {
        int u = to[v][i];
        if (u == p) continue;
        DP d = dpLeft[i] + dpRight[i+1];
        rerootbfs(u, d.addRoot(), v);
    }
}

void reroot(){
    rerootdfs(0);
    rerootbfs(0);
}

