int N;
int sz[212345];
ModInt ret = 0;
Graph<> g;

void dfs(int v, Tree<> &t) {
    sz[v]      = 1;
    ModInt out = 0;
    for (int u : t.Ns(v)) {
        dfs(u, t);
        sz[v] += sz[u];
        out += inv(ModInt(2) ^ (N - sz[u] - 1));
    }
    if (v != 0) {
        int b = N - sz[v];
        out += inv(ModInt(2) ^ (N - b - 1));
    }
    out -= (g.degree(v) - 1) * inv(ModInt(2) ^ (N - 1));
    // cerr << v + 1 << " " << *out << endl;
    ret += inv(2) * (1 - out);
}
