const int mod = 1e9 + 7;
const int maxn = 2e5 + 5;

int two[maxn];
int inv2 = (mod + 1) / 2;
int n;
int h[maxn], mem;
int siz[maxn];
struct {
    int v;
    int next;
} e[maxn << 1];

void add(int u, int v) {
    e[mem].v = v;
    e[mem].next = h[u];
    h[u] = mem++;
}

void dfs_size(int u, int fa) {
    siz[u] = 1;
    for (int i = h[u]; i + 1; i = e[i].next) {
        int v = e[i].v;
        if (v == fa) continue;
        dfs_size(v, u);
        siz[u] += siz[v];
    }
}

void dfs_ans(int u, int fa, long long &ans) {
    long long tans = two[n - 1] - 1;
    for (int i = h[u]; i + 1; i = e[i].next) {
        int v = e[i].v;
        tans ++;
        if (v == fa) {
            tans -= two[n - siz[u]];
        } else {
            tans -= two[siz[v] ];
            dfs_ans(v, u, ans);
        }
    }
    ans = (ans + tans) % mod;
}

long long fast(long long num, int ci) {
    long long ans = 1;
    while (ci) {
        if (ci & 1) ans = ans * num % mod;
        num = num * num % mod;
        ci = ci >> 1;
    }
    return ans;
}

