template< int mod >
struct ModInt {
  int x;

  ModInt() : x(0) {}

  ModInt(int64_t y) : x(y >= 0 ? y % mod : (mod - (-y) % mod) % mod) {}

  ModInt &operator+=(const ModInt &p) {
    if((x += p.x) >= mod) x -= mod;
    return *this;
  }

  ModInt &operator-=(const ModInt &p) {
    if((x += mod - p.x) >= mod) x -= mod;
    return *this;
  }

  ModInt &operator*=(const ModInt &p) {
    x = (int) (1LL * x * p.x % mod);
    return *this;
  }

  ModInt &operator/=(const ModInt &p) {
    *this *= p.inverse();
    return *this;
  }

  ModInt operator-() const { return ModInt(-x); }

  ModInt operator+(const ModInt &p) const { return ModInt(*this) += p; }

  ModInt operator-(const ModInt &p) const { return ModInt(*this) -= p; }

  ModInt operator*(const ModInt &p) const { return ModInt(*this) *= p; }

  ModInt operator/(const ModInt &p) const { return ModInt(*this) /= p; }

  bool operator==(const ModInt &p) const { return x == p.x; }

  bool operator!=(const ModInt &p) const { return x != p.x; }

  ModInt inverse() const {
    int a = x, b = mod, u = 1, v = 0, t;
    while(b > 0) {
      t = a / b;
      swap(a -= t * b, b);
      swap(u -= t * v, v);
    }
    return ModInt(u);
  }

  ModInt pow(int64_t n) const {
    ModInt ret(1), mul(x);
    while(n > 0) {
      if(n & 1) ret *= mul;
      mul *= mul;
      n >>= 1;
    }
    return ret;
  }

  friend ostream &operator<<(ostream &os, const ModInt &p) {
    return os << p.x;
  }

  friend istream &operator>>(istream &is, ModInt &a) {
    int64_t t;
    is >> t;
    a = ModInt< mod >(t);
    return (is);
  }

  static int get_mod() { return mod; }
};

using modint = ModInt< MOD >;
using vm = vector<modint>;

void solve(){
  ini(N);
  vvi g(N);
  rep(i , N - 1){
    ini(x , y); x--; y--;
    g[x].pb(y); g[y].pb(x);
  }

  modint ans = 0;

  auto f = [&](vi v) -> modint{
    modint ret = 1;
    // 全部白
    ret -= modint(1) / modint(2).pow(N - 1);
    // 一個の子だけ黒
    each(x , v){
      modint cur = 1;
      // N - 1 - x個は白
      cur /= modint(2).pow(N - 1 - x);
      // x個は全部白以外
      modint nya = 1;
      nya -= modint(1) / modint(2).pow(x);
      cur *= nya;
      ret -= cur;
    }
    return ret;
  };

  auto dfs = [&](auto rec,int cur,int par) -> int{
    vi chd; int cnt = 1;
    each(x , g[cur]){
      if(x == par) continue;
      int dst = rec(rec , x , cur);
      chd.pb(dst);
      cnt += dst;
    }
    chd.pb(N - cnt);
    ans += f(chd);
    return cnt;
  };

  dfs(dfs , 0 , -1);
  out(ans / 2);

}

