ll mpow(ll x, ll n){ //x^n(mod M)
    ll ans = 1;
    while(n != 0){
        if(n&1) ans = ans*x % MOD;
        x = x*x % MOD;
        n = n >> 1;
    }
    return ans;
}

ll minv(ll x){
    return mpow( x, MOD-2 );
}

int n;
vector<vector<int> > g;
ll ans;

int dfs(int par, int curr)
{
    int siz=(int)g[curr].size();
    int sum=0;
    vector<int> v;
    int i;
    for(i=0; i<siz; i++) {
        int next=g[curr][i];
        if(next==par) continue;
        int ret=dfs(curr, next);
        sum+=ret;
        v.push_back(ret);
    }
    v.push_back(n-sum-1);
    ll ans0=0;
    int siz0=(int)v.size();
    for(i=0; i<siz0; i++) {
        ll tmp=(1-minv(mpow(2, v[i]))+MOD)%MOD;
        tmp=tmp*minv(mpow(2,n-v[i]))%MOD;
        ans0=(ans0+tmp)%MOD;
    }
    ans0=(ans0+minv(mpow(2,n)))%MOD;
    ans0=(minv(2)-ans0+MOD)%MOD;
    ans=(ans+ans0)%MOD;

    sum++;
    return sum;
}

int main(int argc, char* argv[])
{
    scanf("%d", &n);
