        int a,b;
        scanf("%d%d", &a, &b); a--; b--;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    ans=0;
    int ret=dfs(-1, 0);
    assert(ret==n);
    printf("%lld\n", ans);

    return 0;
}

