            sm+=node[i].cl.bsm+node[i].cl.wsm;
            nm+=node[i].cl.bnm+node[i].cl.wnm;
        }
        sm%=MOD;
        nm+=1;
        nm%=MOD;
        int res=sm*modinv(nm,MOD);
        res%=MOD;
        //printf("nm=%lld sm=%lld\n",nm,sm);
        cout<<res<<"\n";
    }
};
