    for (int i = 0; i < N - 1; i++) {
      int a, b;
      cin >> a >> b;
      --a;
      --b;
      G[a].push_back(b);
      G[b].push_back(a);
    }
    mint res = 0;
    mint inv2 = mint(1) / 2;
    auto dfs = [&](auto &dfs, int v, int p = -1) -> int {
      vector<int> ch;
      int csum = 0;
      for (int u : G[v]) {
        if (u == p) continue;
        int c = dfs(dfs, u, v);
        ch.push_back(c);
        csum += c;
      }
      ch.push_back(N - 1 - csum);
      mint prob = mint(1) - inv2.power(N - 1);
      for (int x : ch) {
        prob -= (mint(1) - inv2.power(x)) * inv2.power(N - 1 - x);
      }
      prob /= 2;
      res += prob;
      return csum + 1;
    };
    dfs(dfs, 0);
    cout << res.value() << endl;
  }
  return 0;
}

