    for(LL i = 0; i < n; ++i){
        LL left = num_children[i] - 1;
        LL right = n - num_children[i];
        exp += ModInt(1) / ModInt(2) * (ModInt(1) - ModInt(1) / ModInt(2).pow(left))
            * (ModInt(1) - ModInt(1) / ModInt(2).pow(right));

    }
