	REP(i, N - 1) {
		int a, b;
		scanf("%d %d", &a, &b);
		--a; --b;
		g[a].push_back(b);
		g[b].push_back(a);
	}

	if (N == 2) {
		cout << 0 << endl;
		return 0;
	}

	dfs(0, -1);

	ll ans = 0;
	REP(i, N) {
		ll cur = mod_pow(mod_pow(2, N, MOD), MOD - 2, MOD);
		vector<int> childs;
		if (N - cnt[i] > 0) childs.push_back(N - cnt[i]);
		for (int v : g[i]) if (v != oya[i]) {
			childs.push_back(cnt[v]);
		}
		if (childs.size() < 2) continue;
		vector<vector<ll> > dp(childs.size() + 1, vector<ll>(3, 0));
		dp[0][0] = 1;
		REP(i, childs.size()) REP(j, 3) {
			ll pat = (mod_pow(2, childs[i], MOD) - 1 + MOD) % MOD;
			if (j < 2) {
				(dp[i + 1][j + 1] += dp[i][j] * pat % MOD) %= MOD;
				(dp[i + 1][j] += dp[i][j]) %= MOD;
			}
			else (dp[i + 1][j] += dp[i][j] * (pat + 1)) %= MOD;
		}
		cur = cur * dp[childs.size()][2] % MOD;
		ans = (ans + cur) % MOD;
	}
