    long long fval = 0, gval = 0;
    fval = gval = modexp(2, ssum, M) - 1;
    for (int j : adj[i]) {
        fval += f[j] - modexp(2, s[j], M) + 1
            + g[j] * (modexp(2, ssum - s[j] + 1, M) - 1);
        gval += g[j] * modexp(2, ssum - s[j] + 1, M);
        fval %= M; gval %= M;
