namespace ModInt{
    constexpr long long MOD = (long long)1e9 + 7;
    struct mint {
        long long x;

        mint(long long x=0):x((x%MOD+MOD)%MOD){}

        mint& operator+=(const mint a) {
            if ((x += a.x) >= MOD) x -= MOD;
            return *this;
        }
        mint& operator-=(const mint a) {
            if ((x += MOD-a.x) >= MOD) x -= MOD;
            return *this;
        }
        mint& operator*=(const mint a) {
            (x *= a.x) %= MOD;
            return *this;
        }
        mint operator+(const mint a) const {
            mint res(*this);
            return res+=a;
        }
        mint operator-(const mint a) const {
            mint res(*this);
            return res-=a;
        }
        mint operator*(const mint a) const {
            mint res(*this);
            return res*=a;
        }
        mint pow(long long t) const {
            mint res = 1, a(*this);
            while(t){
                if(t&1) res *= a;
                t >>= 1, a *= a;
            }
            return res;
        }
        mint invPow(long long t) const {
            return pow(MOD-1-t);
        }
        mint inv() const {
            return pow(MOD-2);
        }
        mint& operator/=(const mint a) {
            return (*this) *= a.inv();
        }
        mint operator/(const mint a) const {
            mint res(*this);
            return res/=a;
        }
        friend istream& operator>>(istream& in, mint& a){
            long long _v; in>>_v;
            a = mint(_v);
            return in;
        }
        friend ostream& operator<<(ostream& out, const mint& a){
            return out<<a.x;
        }
        friend bool operator==(const mint& a, const mint& b){
            return a.x == b.x;
        }
        friend bool operator!=(const mint& a, const mint& b){
            return a.x != b.x;
        }
    };
    template <typename T, typename U>
    mint pow(T a, U x){
        // return a^x mod MOD
        return mint(a).pow(x);
    }
    template <typename T, typename U>
    mint invPow(T a, U x){
        // return 1 / (a^x) mod MOD
        return mint(a).pow(MOD-1-x);
    }
    mint operator+(const int a, const mint b){
        return b + a;
    }
    mint operator+(const long long a, const mint b){
        return b + a;
    }
    mint operator-(const int a, const mint b){
        return mint(MOD-b.x) + a;
    }
    mint operator-(const long long a, const mint b){
        return mint(MOD-b.x) + a;
    }
    mint operator*(const int a, const mint b){
        return b * a;
    }
    mint operator*(const long long a, const mint b){
        return b * a;
    }
    mint operator/(const int a, const mint b){
        return b.inv() * a;
    }
    mint operator/(const long long a, const mint b){
        return b.inv() * a;
    }
}

using namespace ModInt;

class Task{
public:
    void solve(istream& in, ostream& out){
        int N;
        in>>N;
        mint ans = 1 - mint(N) / 2 - invPow(2, N);
        vc<int> sz(N, 0);
        vvc<int> G(N);
        REP(i, N-1){
            int a, b;
            in>>a>>b;
            a--, b--;
            G[a].pb(b);
            G[b].pb(a);
        }
        function<void(int, int)> dfs = [&](int s, int p){
            sz[s] = 1;
            for(auto& u : G[s]){
                if(u==p) continue;
                dfs(u, s);
                sz[s] += sz[u];
            }
            if(p!=-1){
                ans += (1-invPow(2, sz[s])) * (1-invPow(2, N-sz[s]));
            }
        };
        dfs(0, -1);
        out<<ans<<'\n';
    }
};

int main(){
    istream& in(cin);
    ostream& out(cout);
    ios_base::sync_with_stdio(false);
    in.tie(nullptr), out.tie(nullptr);
    Task solver;
    solver.solve(in, out);
    return 0;
}

