constexpr int mod = 1e9 + 7;

using LLi = long long int;
// 累乗の余りを求める関数
    inline LLi power_mod(LLi a, LLi n, LLi mod_number___ = mod){
        LLi res = 1LL, waiting = a;
        while(n != 0LL){ if((n & 1LL) != 0LL){ res *= waiting; res %= mod_number___;}
            waiting *= waiting; waiting %= mod_number___; n >>= 1; }
        return res;
    }
    // Z/pZ上の逆元を求める関数 (フェルマーの小定理)
    inline LLi inverse_mod(LLi a, LLi mod_number___ = mod){
        return power_mod(a, mod_number___-2);
    }


std::vector<int> In;
std::vector<std::vector<int>> Edge;
std::vector<std::vector<int>> A;
std::vector<int> Depth;

int main(void){
    int n; scanf("%d", &n);
    Edge.resize(n);
    REP(i, n-1){
        int a, b; scanf("%d%d", &a, &b); a--; b--;
        Edge[a].push_back(b);
        Edge[b].push_back(a);
    }
    In.resize(n); REP(i, n) In[i] = Edge[i].size();
    std::queue<int> Q;
    Depth.assign(n, -1);
    Depth[0] = 0; Q.push(0);
    while(not Q.empty()){
        int v = Q.front(); Q.pop();
        for(int nv : Edge[v]) if(Depth[nv] == -1){
            Depth[nv] = Depth[v] + 1; Q.push(nv);
        }
    }

    A.resize(n);
    REP(i, n){
        bool flag = true;
        for(int v : Edge[i]) if(Depth[v] > Depth[i]){flag = false; break;}
        if(flag) Q.push(i); 
    }
    while(not Q.empty()){
        int v = Q.front(); Q.pop();
        if(v == 0) continue;
        int sum = 1; for(int x : A[v]) sum += x;
        for(int nv : Edge[v]) if(Depth[nv] < Depth[v]){
            In[nv]--; A[nv].push_back(sum);
            if(In[nv] == 1) Q.push(nv);
        }
    }

    lli inv_twon = inverse_mod(power_mod(2, n));
    lli inv_two = inverse_mod(2);

    lli res = (n * inv_two) % mod;

    REP(i, n){
        lli val = 1;
        int k = n - 1;
        for(int x : A[i]){
            (val += power_mod(2, x) + mod - 1) %= mod;
            k -= x;
        }
        (val += power_mod(2, k) + mod - 1) %= mod;
        (val *= inv_twon) %= mod;
        (res += mod - val) %= mod;
    }
    printf("%lld\n", res);

    return 0;
}

