using namespace std;
lint p=1e9+7;
lint pow2[200001];

lint pow_mod(lint a,lint b,lint p){
  if(b==0)return 1;
  if(b%2==0){
    lint d=pow_mod(a,b/2,p);
    return (d*d)%p;
  }else{
    return (a*pow_mod(a,b-1,p))%p;
  }
}

//x / a mod p=x * inv_mod(a,p) 
lint inv_mod(lint a,lint p){
  return pow_mod(a,p-2,p);//(a^(p-2))mod p
}

int main(){
  pow2[0]=1;
  FOR(i,1,2e5+1)pow2[i]=(pow2[i-1]*2)%p;
  int N;
  cin>>N;
  vector<int> c[N];
  REP(i,N-1){
    int A,B;
    cin>>A>>B;
    A--;B--;
    c[A].push_back(B);
    c[B].push_back(A);
  }
  stack<int> s;
  vector<int> k[N];
  bool d[N];
  REP(i,N)d[i]=false;
  s.push(0);
  while(!s.empty()){
    int now=s.top();
    d[now]=true;
    // cerr<<now<<endl;
    if(c[now].empty()){
      s.pop();
      int sum=1;
      for(auto e:k[now])sum+=e;
      if(!s.empty())k[s.top()].push_back(sum);
    }else{
      int next=c[now].back();
      if(d[next]){
          c[now].pop_back();
          continue;
      }
      s.push(next);
      c[now].pop_back();
    }
  }
  FOR(i,1,N){
    int sum=N-1;
    for(auto e:k[i])sum-=e;
    k[i].push_back(sum);
  }
  // REP(i,N){
  //   for(auto e:k[i])cerr<<e<<" ";
  //   cerr<<endl;
  // }
  lint ans=0;
  REP(i,N)if(k[i].size()>1){
    lint temp=pow2[N-1];
    temp-=1;
    for(auto e:k[i]){
      temp+=p;
      temp-=pow2[e]-1;
      temp%=p;
    }
    // cerr<<temp<<endl;
    ans+=temp;
    ans%=p;
  }
  cout<<(ans*inv_mod(pow2[N],p))%p<<endl;
  return 0;
}

