}

long long r, q;
long long extGCD(long long a, long long b, long long &r, long long &q) {
    if (b == 0) {
        r = 1;
        q = 0;
        return a;
    }
    long long d = extGCD(b, a%b, q, r); // 再帰的に解く
    q -= a / b * r;
    return d;
}

// 負の数にも対応した mod (a = -11 とかでも OK) 
inline long long mod(long long a, long long m) {
    return (a % m + m) % m;
}

// 逆元計算 (ここでは a と m が互いに素であることが必要)
long long modinv(long long a, long long m) {
    long long x, y;
    extGCD(a, m, x, y);
    return mod(x, m); // 気持ち的には x % m だが、x が負かもしれないので
}

