ll dp(ll n) {
	if (DP[n] != -1)return DP[n];
	if (childs[n].size() == 0) {
		DP[n] = 1;
		return 1;
	}
	DP[n] = 1;
	for (ll c : childs[n]) {
		DP[n] += dp(c);
	}
	return DP[n];
}

ll modpow(ll base, ll p) {
	if (p == 0)return 1;
	if (p == 1)return base;
	ll ans = modpow(base, p / 2);
	ans = (ans * ans) % MOD;
	if (p & 1)ans = (ans * base) % MOD;
	return ans;
}

int main() {
