	while (!q.empty()) {
		ll cur = q.front().first;
		ll p = q.front().second;
		q.pop();
		parents[cur] = p;
		for (ll c : edges[cur]) {
			if (c == p)continue;
			childs[cur].push_back(c);
			q.push(pll(c, cur));
		}
	}
	DP.resize(N, -1);
	dp(0);
	ll ans = (modpow(2,N-1)+MOD-1)%MOD;
	ans = (ans * N) % MOD;
	for (ll n = 0; n < N; n++) {
		for (ll c : childs[n]) {
			ans = (ans+MOD-modpow(2, DP[c])+1)%MOD;
		}
		ans = (ans + MOD - modpow(2, N - DP[n]) + 1) % MOD;
	}
	ll inv = modpow(2, N * (MOD - 2));
	ans = (ans * inv) % MOD;
	cout << ans << "\n";
	return 0;
}

