    ll now=power(2,n-1)-1;
    for (int i=0;i<graph[s].size();i++)
    {
        int u=graph[s][i];
        if (u==w) continue;
        sz=dfs(u,s,graph);
        acu+=sz;
        now-=power(2,sz)-1;
    }
    now-=power(2,n-1-acu)-1;
    ans+=now;
    return sz;
}

