	if (x < 0) return x + MOD;
	return x;
}
ll mult(ll x, ll y) {
	return (x * y) % MOD;
}
ll bin_pow(ll x, ll p) {
	if (p == 0) return 1;
	if (p & 1) return mult(x, bin_pow(x, p - 1));
	return bin_pow(mult(x, x), p / 2);
}

int deg[200020];
void solve() {
	int N; cin >> N;
	REP(i, N-1) {
		int u, v; cin >> u >> v;
		u--, v--;
		G[u].push_back(v);
		G[v].push_back(u);
		deg[u]++;
		deg[v]++;
	}

	dfs(0, 0);
	int inv2 = bin_pow(2, MOD - 2);
	ll ans = 0;

	REP(i, N) {
		if (deg[i] == 1)continue;
		int sb1 = bin_pow(inv2, N - 1);
		int sb2 = 0;
		for (auto nxt : G[i]) {
			int S = 0;
			if (nxt == par[i])S = N - siz[i];
			else S = siz[nxt];

			sb2 = add(sb2, mult(bin_pow(inv2, N - 1 - S), sub(1, bin_pow(inv2, S))));
		}
		int tmp = sub(1, sb1);
		tmp = sub(tmp, sb2);
		ans = add(ans, mult(inv2, tmp));
	}
	print(ans);
}

