#include <bits/stdc++.h>
using namespace std;

const long mod = 1000000007;
long n;
vector<int> g[200000];
vector<int> degs[200000];

long mpow(long b, long e) {
  if (e == 0) return 1;
  if (e % 2 == 1) return b * mpow(b, e - 1) % mod;
  long t = mpow(b, e / 2);
  return t * t % mod;
}

long inv(long n) {
  return mpow(n, mod - 2);
}

int rec(int from, int prev) {
  int sum = 1;
  for (int to : g[from]) {
    if (to == prev) continue;
    int deg = rec(to, from);
    if (deg > 0) degs[from].push_back(deg);
    sum += deg;
  }

  int rem = n - sum;
  if (rem > 0) {
    degs[from].push_back(rem);
  }
  return sum;
}

int main() {
  cin >> n;
  for (int j = 1; j < n; ++j) {
    int a, b;
    cin >> a >> b;
    --a; --b;
    g[a].push_back(b);
    g[b].push_back(a);
  }

  rec(0, -1);

  long sum = 0;
  for (int i = 0; i < n; ++i) {
    long prob = 1;
    prob = (prob + mod - inv(mpow(2, n - 1))) % mod;
    for (int deg : degs[i]) {
      prob = (
        prob + mod -
        (1 + mod - inv(mpow(2, deg))) % mod
        * inv(mpow(2, n - 1 - deg)) % mod
      ) % mod;
    }
    sum = (sum + prob * 500000004) % mod;
  }
  cout << sum << endl;
}

