long long n;
std::vector<int> G[200'010];
long long cnt[200'010];//iを頂点とする部分木内の頂点の個数(i自身は含まない)
long long dp[200'010];//iが白かつ黒で作られる部分木に含まれない塗り方の数
void dfs(int v, int p = -1){
  for(int nv:G[v]){
    if(nv == p)continue;
    dfs(nv, v);
    cnt[v] += 1 + cnt[nv];
    dp[v] += po(2LL, 1+cnt[nv]);
    dp[v] = mod(dp[v]);
  }
  dp[v] += po(2LL, n-(1+cnt[v]));
  dp[v] = mod(dp[v]);
  dp[v] -= G[v].size();
  dp[v]++;
  dp[v] = mod(dp[v]);
  return;
}
int main(){
  using namespace std;
