  int a[n], b[n];
  REP(i,n){
    cin>>a[i]>>b[i];
    a[i]--;b[i]--;
    G[a[i]].push_back(b[i]);
    G[b[i]].push_back(a[i]);
  }
  long long all_ = po(2LL, n);
  long long ans = 0;
  REP(i,n){
    ans += (all_ - dp[i]);
    ans = mod(ans);
  }
  cout<<ans<<endl;
  return 0;
}

