int n;
vll po2;
ll ans = 0;

int dfs(int now, int prev, const vvi &tr) {
  vi sizes;
  ll su = 0;
  for(int i=0;i<SZ(tr[now]);++i) {
    int nxt = tr[now][i];
    if(nxt == prev) continue;
    sizes.push_back(dfs(nxt, now, tr));
    su += sizes.back();
  }
  if(n > su + 1) sizes.push_back(n - su - 1);
  //cout << now << ":";
  //printv(sizes);
  //cout << endl;
  ll tmp = po2[n-1];
  for(int i=0;i<SZ(sizes);++i) {
    tmp += po2[sizes[i]];
    tmp %= MOD;
  }
  tmp += MOD - SZ(sizes) + 1;
  tmp %= MOD;
  ans += po2[n] - tmp;
  ans %= MOD;
  //cout << now << ":" << po2[n] - tmp + n - 2 << endl;
  return su + 1;
}

