	vector<pair<int, int>> vp;
	unordered_map<int, unordered_set<int>> um;
	unordered_map<int, int> weight;
	unordered_map<int, unordered_map<int, int>> pw;
	for (int i = 1; i < n; i++) {
		int a, b;
		cin >> a >> b;
		vp.push_back(make_pair(a, b));
		um[a].insert(b);
		um[b].insert(a);
	}
	for (int i = 1; i <= n; i++)
		weight[i] = 1;

	vector<int> v1, v2;
	for (int i = 1; i <= n; i++) {
		if (um[i].size() == 1)
			v1.push_back(i);
	}

	while (v1.size() > 0) {
		v2.clear();
		for (auto node : v1) {
			if (um[node].size() == 0) continue;
			int next = *(um[node].begin());
			pw[node][next] = weight[node];
			pw[next][node] = n - weight[node];
			weight[next] += weight[node];
			um[next].erase(node);
			if (um[next].size() == 1) v2.push_back(next);
		}
		v1 = v2;
	}

	for (int i = 0; i < n - 1; i++) {
		um[vp[i].first].insert(vp[i].second);
		um[vp[i].second].insert(vp[i].first);
	}

	long long int a = 0, b = mypow(2, n - 1);
	for (int i = 1; i <= n; i++) {
		if (um[i].size() < 2) continue;

		// i -> 
		a += um[i].size();
		a += b;
		a %= mod;
		for (auto next : um[i]) {
			int right = pw[next][i];
			a -= mypow(2, right);
			while (a < 0)
				a += mod;
		}
		a -= 1;
		if (a < 0) a += mod;
	}
	b = mypow(2, n);
	long long int step = 1;
	while (a % b != 0) {
		long long int next_b = (mod / b * b + b) % mod;
		step = step * (mod / b + 1) % mod;
		b = next_b;
	}
	cout << a / b * step % mod << endl;
}

