long long extGCD(long long a, long long b, long long *px, long long *py){
    if(b == 0){
        *px = 1;
        *py = 0;
        return a;
    }
    long long d = extGCD(b, a%b, py, px);
    *py -= a/b * (*px);
    return d;
}

long long modinv(long long a, long long mod){
    long long x, y;
    extGCD(a, mod, &x, &y);
    x %= mod;
    if(x < 0) x += mod;
    return x;
}

long long modpow(long long a, long long n, long long mod) {
    long long res = 1;
    while (n > 0) {
