#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
// const int INF = 2147483647;
// const ll INF = 9223372036854775807;
const ll MOD = 1e9 + 7;

// mod p （pは素数）の下でのべき乗を求める
ll mod_pow(ll a, ll n, ll p) {
		ll result = 1;
		while (n > 0) {
			if (n & 1) result = result * a % p;
			a = a * a % p;
			n >>= 1;
		}
		return result;
	};

// mod p （pは素数）の下での逆元を求める（フェルマーの小定理を利用）
ll mod_inverse(ll a, ll p) {
	return mod_pow(a, p-2, p);
}

// mod p （pは素数）の下での除算 (a / b)
ll mod_devide(ll a, ll b, ll p) {
	return a * mod_inverse(b, p) % p;
}

struct Node {
	vector<int> neighbors;
	bool visited;
};

Node nodes[200000];

vector<int> node_cnt[200000]; // node_cnt[i][j]: nodes[i]のj番目のneighborから先のノードの数

// nodes[i] から先（nodes[i]を含む）のノードの数を返す
int dfs(int i) {
	int result = 1;
	nodes[i].visited = true;

	for (int j=0; j<nodes[i].neighbors.size(); j++) {
		int k = nodes[i].neighbors[j];

		if (nodes[k].visited == true) {
			continue;
		}

		if (node_cnt[i][j] != -1) {
			result += node_cnt[i][j];
			continue;
		}

		node_cnt[i][j] = dfs(k);
		result += node_cnt[i][j];
	};

	return result;
}

void reset_node(int N) {
	for (int i=0; i<N; i++) {
		nodes[i].visited = false;
	}
}

int main() {
	int N;
	cin >> N;

	int A, B;
	for (int i=0; i<N-1; i++) {
		cin >> A >> B;
		A--;
		B--;
		nodes[A].neighbors.push_back(B);
		node_cnt[A].push_back(-1);
		nodes[B].neighbors.push_back(A);
		node_cnt[B].push_back(-1);
	}

	// node_cnt[i][j]を求める
	for (int i=0; i<N; i++) {
		reset_node(N);
		dfs(i);
	}

	/*
	// **** debug ****
	for (int i=0; i<N; i++) {
		cout << "node " << i + 1 << " :";
		for (int n : node_cnt[i]) {
			cout << " " << n;
		}
		cout << endl;
	}
	*/

	// nodeごとに穴あき度の期待値を算出し、それを合計する
	// （y/xについて、xの逆元にyを掛けたものがz）
	ll ans = 0;
	ll inv2 = mod_inverse(2, MOD); // 2の逆元
	for (int i=0; i<N; i++) {
		if (nodes[i].neighbors.size() == 1) continue; // 端点は期待値0

		// 自分以外が全て白く塗られている確率
		ll prob_all_white = mod_pow(inv2, N-1, MOD);

		// nodes[i]から出ている部分木のうち、nodes[i].neighbors[k] からの木だけが黒を含む確率
		ll prob_one_black = 0;
		for (int k=0; k<nodes[i].neighbors.size(); k++) {
			ll prob = 1;
			for (int j=0; j<nodes[i].neighbors.size(); j++) {
				if (j == k) {
					// 黒を1つでも含む確率を掛ける（全て白の余事象）
					prob = (prob * (1 - mod_pow(inv2, node_cnt[i][j], MOD) + MOD)) % MOD;
				} else {
					// 全て白の確率を掛ける
					prob = (prob * mod_pow(inv2, node_cnt[i][j], MOD)) % MOD;
				}
			}

			prob_one_black = (prob_one_black + prob) % MOD;
		}

		ll prob = (1 - prob_all_white + MOD) % MOD;
		prob = (prob - prob_one_black + MOD) % MOD;
		prob = (prob * inv2) % MOD; // そもそもnodes[i]が白

		// 確率がそのまま穴あき度の期待値になる
		ans = (ans + prob) % MOD;
	}

