template<typename T>
T extgcd(T a,T b,T& x, T& y){
	T d=a;
	if(b!=0){
		d = extgcd(b, a%b, y, x);
		y -= (a/b) * x;
	}
	else{
		x = 1; y = 0;
	}
	return d;
}
template<typename T>
T mod_inv(T a,T m){
	T x,y;
	extgcd(a,m,x,y);
	return (m+x%m)%m;
}

ll pow2(int d){
	if(d == 0) return 1;
	if(d == 1) return 2;
	if(d % 2 == 0){
		ll tmp = pow2(d / 2);
		return (tmp*tmp)%MOD;
	}
	ll tmp = pow2(d / 2);
	return (2 * (tmp * tmp))%MOD;
}

