void solve(){
	dfs(0, -1);
	rep1(i, N-1){
		int s = 0;
		rep(j ,sz(con[i])){
			s += con[i][j];
		}
		con[i].pb(N-1-s);
	}
}

void output(){
  ll ans = mod_inv(pow2(N), MOD);
  ll tmp = 0;
  rep(i, N){
  	ll x = 1;
  	rep(j, sz(con[i])){
  		x += (pow2(con[i][j]) - 1);
  	}
  	x %= MOD;
  	tmp += (pow2(N-1) - x +MOD)%MOD;
  }
  ans = (ans * tmp)%MOD;
  cout<<ans<<endl;
}

