	}
	dfs(0,-1,n);
	inverse();
	for(i=0;i<n;i++){
		ll x = inv[2];
		ll y = (1 - pw(inv[2],n - 1) + mod)%mod;
		for(j=0;j<H[i].size();j++){
			ll z = (1 - pw(inv[2],H[i][j]) + mod)%mod;
			(z *= pw(inv[2],n - H[i][j] - 1)) %= mod;
			y -= z;
			y = (y + mod)%mod;
		}
		(ans += x*y%mod) %= mod;
	}
	cout << ans << endl;
}

#include <bits/stdc++.h>
using namespace std;
const int N = 2e5 + 10;
const int mod = 1e9 + 7;
vector <int> e[N];
int fa[N];
int p[N];
int sz[N];
int M(int u, int v)
{
	return 1ll * u * v % mod;
}
int P(int u, int v)
{
	if (v % 2)
		return M(u, P(u, v - 1));
	if (v)
		return P(M(u, u), v / 2);
	return 1;
}
int I(int u)
{
	return P(u, mod - 2);
}
int R(int u)
{
	return (mod + 1 - u) % mod;
}
int A(int u, int v)
{
	return (u + v) % mod;
}
void dfs(int u)
{
	sz[u] = 1;
	for (auto v : e[u])
	{
		if (v == fa[u])
			continue;
		fa[v] = u;
		dfs(v);
		sz[u] += sz[v];
	}
}
int main()
{
	ios::sync_with_stdio(0);
	cin.tie(0);
	cout.tie(0);
	int n;
	cin >> n;
	for (int i = 1; i < n; ++i)
	{
		int u, v;
		cin >> u >> v;
		e[u].emplace_back(v);
		e[v].emplace_back(u);
	}
	dfs(1);
	int ans = 0;
	for (int i = 1; i <= n; ++i)
	{
		if (e[i].size() < 2)
			continue;
		int p1 = 1;
		for (int j : e[i])
		{
			p[j] = I(P(2, j == fa[i] ? n - sz[i] : sz[j]));
			p1 = M(p1, p[j]);
		}
		int p2 = 0;
		for (int j : e[i])
		{
			p2 = A(p2, M(M(p1, I(p[j])), R(p[j])));
		}
		ans = A(ans, M(I(2), R(A(p1, p2))));
	}
	cout << ans;
