        }
        cnt_out+=1;

        for(i64 v:tree[u]){
            if(v==p) continue;
            rec(v,u,N-size[v]);
        }
    };
    rec(0,-1,0);

    fp<mod> all;
    rep(u,0,N) all+=rep_pow(fp<mod>(2),N-1);

    fp<mod> sum=all-cnt_out;
    fp<mod> ans=sum/rep_pow(fp<mod>(2),N);

    cout << ans << endl;

    print(cnt_out);
    print(all);
    print(sum);
}

