ll powerm(ll a,ll b,ll m=mod)
{
	a%=m;
	ll res=1%m;
	while(b>0)
	{
		if(b & 1)
		{
			res=(res*a)%m;
		}
		b>>=1;
		a=(a*a)%m;
	}
	return res;
}

void dfs(ll u,ll p)  // Find number of vertices in the subtree of u including it.
{
    sub[u]=1;
    for(auto v:adj[u])
    {
        if(v==p)
        {
            continue;
        }
        dfs(v,u);
        sub[u]+=sub[v];
    }
}

// How many subsets will include u as white colored in the optimal strategy.
//
// For this first of all we need to make u as a root of tree.
//
// This can be easily done by some + , - in the size of its parent.
//
// Now to have u as a white and included in subset we must have at least two vertices
// from the subtree of different children of u colored black.
//
// Which means you will have to take at least one vertex from them.
//
// Say if there are sub[v] vertices in the subtree of v (v is a child of u), then you can
// choose (2^(sub[v])-1), subsets in which you will have at least one vertex will be
// present from subtree of v and colored black.
//
// Now you just need to take subsets of children of u (with size > 1) and take at least one
// element from it, think in how many ways it can be done.
//
// So, basically find product over all the subsets and subtract case of size 1.


void solve(ll u,ll p)
{
    ll add=1,sum=0;
    for(auto v:adj[u])
    {
        add=(add * pw[sub[v]])%mod;
        sum=(sum + pw[sub[v]] - 1 + mod)%mod;
    }
    add=(add-1+mod)%mod;
    add=(add-sum+mod)%mod;
    ans=(ans + add)%mod;
    for(auto v:adj[u])
    {
        if(v==p)
        {
            continue;
        }
        // Go from u ---> v
        sub[u]-=sub[v];  // Making v as a root of tree
        sub[v]+=sub[u];
        solve(v,u);
        sub[v]-=sub[u];  // Making u again as a root of tree
        sub[u]+=sub[v];
    }
}

