    add(ans, pow2[N-1]);
    add(ans, G[cur].size()-1);
    for(int nxt : G[cur])
        sub(ans, pow2[nodes[nxt]]);

    for(int nxt : G[cur]){
        if(nxt == prv) continue;
        nodes[cur] -= nodes[nxt];
        nodes[nxt] = N;
        efs(nxt, cur);
        nodes[cur] = N;
    }
}

