}

int fastpow(int b, int p) {
	if (!p)
		return 1;
	int ret = fastpow(b, p / 2);
	ret = mul(ret, ret);
	if (p & 1)
		ret = mul(ret, b);
	return ret;
}

const int N = 2e5 + 5;
