void dfs(int node, int parent = -1) {
	sz[node] = 1;
	for (auto &neg : g[node])
		if (neg != parent)
			dfs(neg, node), sz[node] += sz[neg], szs[node].push_back(sz[neg]);
	if (n - sz[node] >= 1)
		szs[node].push_back(n - sz[node]);
