const int MOD = 1000000007;

void Dfs(int node, int par, VEC(VEC(int))& Edges,
         VEC(int)& parents,
         VEC(int)& Sizes, int& count)
{
    int curc = count++;
    parents[node] = par;
    for (int child : Edges[node])
        if (child != par) {
            Dfs(child, node, Edges, parents, Sizes, count);
        }

    Sizes[node] = count - curc;
};

int modpow(int a, int x)
{
    if (x == 0)
        return 1;

    if (x % 2 == 1)
        return (int)(a * 1LL * modpow(a, x - 1) % MOD);

    int ret = modpow(a, x / 2);
    return (int)(ret * 1LL * ret % MOD);
};

int modinv(int a)
{
    return modpow(a, MOD - 2);
};

int F(int x)
{
    int a = modpow(2, x);
    int numer = (MOD + a - 1) % MOD;
    int denom = a;
    return (int)(numer * 1LL * modinv(denom) % MOD);
};

int G(int x)
{
    return modinv(modpow(2, x));
};

