        for (int b : B)
            none = (int)(none * 1LL * b % MOD);

        // 1 - none - one.
        int one = 0;
        FOR(j, 0, A.size()) {
            int rest = (int)(none * 1LL * modinv(B[j]) % MOD);
            one += (int)(rest * 1LL * A[j] % MOD);
            one %= MOD;
        }

        ret += (MOD + 1 - none + MOD - one) % MOD;
        ret %= MOD;
    }

    ret = (int)(ret * 1LL * modinv(2) % MOD);
    cout << ret << endl;
    return 0;
};

