    }

    ModInt(int v)
    {
        m_value = (long long int) v;
    }

    ModInt(const ModInt &t)
    {
        m_value = t.getint();
    }

    int operator + (const ModInt &t) 
    {
		return ModInt::modadd(getint(), t.getint());
	}    

    int operator + (int t) 
    {
		return ModInt::modadd(getint(), t);
	}      

    int operator -  (const ModInt &t) 
    {
		return ModInt::modminus(getint(), t.getint());
	}    
    int operator - (int t) 
    {
		return ModInt::modminus(getint(), t);
	}  

    int operator * (const ModInt &t) 
    {
		return ModInt::modmul(getint(), t.getint());
	}  
    int operator * (int t) 
    {
		return ModInt::modmul(getint(), t);
	} 

    ModInt& operator += ( const ModInt &t )
    {
        (*this) += t.getint();
        return (*this);
    }


    ModInt& operator *= ( const ModInt &t )
    {
        (*this) *= t.getint();
        return (*this);
    }

    ModInt& operator -= ( const ModInt &t )
    {
        (*this) -= t.getint();
        return (*this);
    }

    ModInt& operator += ( int v )
    {
        m_value += v;
        if(m_value >= _BM) m_value -= _BM;
        return *this;
    }

    ModInt& operator -= ( int v )
    {
        m_value -= v;
        if( m_value < 0 ) m_value += _BM;
        return *this;
    }

    ModInt& operator *= ( int v )
    {
        m_value *= v;
        m_value %= _BM;
        return *this;
    }

    static int modadd( int a, int b )
    {
        ModInt t(a);
        t += b;
        return t.getint();
    }

    static int modminus( int a, int b )
    {
        ModInt t(a);
        t -= b;
        return t.getint();
    }    

    static int modmul( int a, int b )
    {
        ModInt t(a);
        t *= b;
        return t.getint();
    }

    // a^b;
    static int modpow(int a, int b)
    {
        ModInt ans(1);
        int heap[32];
        heap[0] = a;
        for( int bit = 0; b >= (1 << bit); bit++ )
        {
            if( bit > 0 ) heap[bit] = modmul( heap[bit - 1], heap[bit - 1] );
            if( b & (1 << bit) )
            {
                ans *= heap[bit];
            }
        }
        return ans.getint();
    }

    static int reciprocal(int a)
    {
        return modpow(a, _BM - 2);
    }

    static int combination(int n, int r)
    {
        int *fac = (int *)malloc(sizeof(int) * (n + 1));
        int *facinv = (int *)malloc(sizeof(int) * (n + 1));
        fac[0] = 1;
        for( int k = 1; k <= n; k++) fac[k] = modmul(k, fac[k - 1]);
        facinv[n] = reciprocal( fac[n] );
        for( int k = n ; k > 0; k--) facinv[k - 1] = modmul(k, facinv[k]);

        ModInt ans(fac[n]);
        ans *= facinv[r];
        ans *= facinv[n - r];

        free(fac);
        free(facinv);
        return ans.getint();
    }

    int getint() const
    {
        return (int) m_value;
    }


private:
    void _mod()
    {
        if( m_value < 0 ) 
        m_value %= _BM;
    }
};

