void dfs(int v, int p) {
    sz[v] = 1;
    for (auto u : g[v]) {
        if (u == p) continue;
        dfs(u, v);
        sz[v] += sz[u];
    }
}

int powmod(int a, int p) {
    if (p == 0) return 1;
    if (p == 1) return a % mod;
    int k = powmod(a, p / 2);
    if (p & 1) return (k * k % mod) * a % mod;
    return k * k % mod;
}

int rev(int x) {
    return powmod(x, mod - 2);
}

void add(int& a, int b) {
    a += b;
    a %= mod;
}

void sub(int& a, int b) {
    a -= b;
    if (a < 0) a += mod;
}

