                s.pb(sz[u]);
                sum += sz[u];
            }
        }
        if (n - sum - 1 > 0) s.pb(n - sum - 1);
        if (s.size() < 2) continue;
        add(ans, powmod(2, n - 1));
        sub(ans, 1);
        for (auto k : s) {
            sub(ans, powmod(2, k) - 1);
        }
    }
    int val = rev(powmod(2, n));
    val = (val * ans) % mod;
    cout << val;
}
