ll dfs(ll index, ll par)
{
  ll res = 1;
  for (ll i = 0; i < E.at(index).size(); ++i)
  {
    ll check = E.at(index).at(i);
    if (check == par)
    {
      continue;
    }
    ll temp = dfs(check, index);
    dp.at(index).push_back(temp);
    res += temp;
  }
  if (N != res)
  {
    dp.at(index).push_back(N - res);
  }
  return res;
}

ll calc(vector<vector<ll>> dp)
{
  ll res = 0;
  for (ll i = 0; i < N; ++i)
  {
    if (dp.at(i).size() == 1)
    {
      continue;
    }
    ll temp = modpow(2, N - 1, mod) - 1;
    for (ll j = 0; j < dp.at(i).size(); ++j)
    {
      temp -= modpow(2, dp.at(i).at(j), mod) - 1;
      if (temp < 0)
      {
        temp += mod;
      }
    }
    res = (res + temp) % mod;
  }
  return res;
}

