            sum %= MOD;
        }
        int64_t p0 = inv(dpow(2, n - 1));
        int64_t p1 = sum * prod % MOD;

        result += ((1 - p0 + MOD) % MOD - p1 + MOD) % MOD;
        result %= MOD;
    }
    result = result * inv(2) % MOD;
    cout << result << endl;

    return 0;
}

