ll power(ll n,ll m)
{
    ll ans=1;
    for (int r=0;m>>r>0;r++)
    {
        if ((m>>r)&1) ans=ans*n%mod;
        n=n*n%mod;
    }
    return ans;
}

ll inv(ll n)
{
    return power(n,mod-2);
}

ll dfs(int s,int w,vector<vector<int>> graph)
{
    int n=graph.size();
    ll sz=1;
    for (int i=0;i<graph[s].size();i++)
    {
        int u=graph[s][i];
        if (u==w) continue;
        sz+=dfs(u,s,graph);
    }
    return sz;
}

ll dfs2(int s,int w,vector<vector<int>> graph)
{
    int n=graph.size();
    ll ans=0;
    ll upsize=n-dfs(s,w,graph);
    ll now=power(2,n-1)-1;
    now-=power(2,upsize)-1;
    for (int i=0;i<graph[s].size();i++)
    {
        int u=graph[s][i];
        if (u==w) continue;
        ll sz=dfs(u,s,graph);
        ans+=dfs2(u,s,graph);
        now-=power(2,sz)-1;
    }
    ans+=now;
    return ans;
}

