void dfs(ll now, ll par) {
    sz[now] = 1;
    FOREACH(to, G[now]) {
        if(to == par) continue;
        dfs(to, now);
        sz[now] += sz[to];
    }
}

void dfsall(ll now, ll par) {
    VL cs;
    FOREACH(to, G[now]) {
        if(to != par) dfsall(to, now);
        if(to == par)
            cs.emplace_back(N - sz[now]);
        else
            cs.emplace_back(sz[to]);
    }
    if(cs.size() >= 2) {
        mint re = modpow((mint)1 / 2, N - 1);
        FOREACH(c, cs) {
            re += ((mint)1 - modpow((mint)1 / 2, c)) *
                  modpow((mint)1 / 2, N - 1 - c);
        }
        ans += ((mint)1 - re) / 2;
    }
}

