typedef long long ll;

ll MOD = 1000000007; ll HALF = 500000004;
ll n;
ll ans = 0;
vector<ll> pows(200000);
vector<vector<ll> > adj(200000);

ll dfs(ll x, ll p, ll &ans) {
	ll cnt = 1LL;
	ll tmp = 1LL - pows[n-1] + MOD*2;
	for (auto v : adj[x])
	{
		if (v == p) continue;
		ll w = dfs(v, x, ans);
		tmp -= pows[n-1-w] - pows[n-1] - MOD*2;
		cnt += w;
	}
	if (n > cnt) tmp -= pows[cnt-1] - pows[n-1] - MOD*2;
	tmp = (tmp * HALF) % MOD;
	ans = (ans + tmp) % MOD;

	return cnt;
}


int main() {
	cin >> n;
	pows[0] = 1;
	for (int i = 0; i < 199999; ++i) pows[i+1] = (pows[i] * HALF) % MOD;
	for (int i = 0; i < n-1; ++i)
	{
		ll a, b; cin >> a >> b;
		adj[a-1].push_back(b-1);
		adj[b-1].push_back(a-1);
	}

	dfs(0, -1, ans);

	cout << ans << endl;
	return 0;
}

