const int mod = 1000000007;
struct mint {
  ll x; // typedef long long ll;
  mint(ll x=0):x((x%mod+mod)%mod){}
  mint operator-() const { return mint(-x);}
  mint& operator+=(const mint a) {
    if ((x += a.x) >= mod) x -= mod;
    return *this;
  }
  mint& operator-=(const mint a) {
    if ((x += mod-a.x) >= mod) x -= mod;
    return *this;
  }
  mint& operator*=(const mint a) {
    (x *= a.x) %= mod;
    return *this;
  }
  mint operator+(const mint a) const {
    mint res(*this);
    return res+=a;
  }
  mint operator-(const mint a) const {
    mint res(*this);
    return res-=a;
  }
  mint operator*(const mint a) const {
    mint res(*this);
    return res*=a;
  }
  mint pow(ll t) const {
    if (!t) return 1;
    mint a = pow(t>>1);
    a *= a;
    if (t&1) a *= *this;
    return a;
  }

  // for prime mod
  mint inv() const {
    return pow(mod-2);
  }
  mint& operator/=(const mint a) {
    return (*this) *= a.inv();
  }
  mint operator/(const mint a) const {
    mint res(*this);
    return res/=a;
  }
};

int n;
vector<int> to[200005]; // 隣接リスト

mint ans;
// 戻り値は頂点v以下の部分きのサイズ（頂点数）
int dfs (int v, int p = -1) {
  int res = 1;
  vector<int> ts;
  for (int u : to[v]) {
    if (u == p) continue;  // 隣接相手が親ならスルー
    int t = dfs(u, v);
    res += t;
    ts.push_back(t);
  }

  if (p != -1) {
    ts.push_back(n - res);  // 部分木じゃない、親方向の木のサイズ
  }

  // 頂点vが白の時、vを内部に含むような部分きの数をnowとする
  mint now = mint(2).pow(n - 1) - 1;
  for (int t : ts) {
    now -= mint(2).pow(t) - 1;
  }
  ans += now;
  return res;
}

