vector<vector<ll>> g(200100);
vector<ll> inv(200100), sbs(200100, -1);

ll modpow(ll x, ll n, ll mod) {
    ll r = 1;
    while (n > 0) {
        if (n & 1)
            r = r * x % mod;
        x = x * x % mod;
        n >>= 1;
    }
    return r;
}

ll dfs(ll v, ll p) {
    if (sbs[v] != -1)
        return sbs[v];
    sbs[v] = 1;
    for (auto u : g[v])
        if (u != p) {
            sbs[v] += dfs(u, v);
            ans += (mod + 1 - modpow(inv[2], sbs[u], mod)) *
                   (mod + 1 - modpow(inv[2], n - sbs[u], mod)) % mod;
        }
    return sbs[v];
}

