        a--, b--;
        g[a].emplace_back(b);
        g[b].emplace_back(a);
    }
    dfs(0, -1);

    ans = (ans + mod - modpow(inv[2], n, mod)) % mod;
    ans = (ans + mod - n * inv[2] % mod) % mod;
    cout << ans << endl;
    return 0;
}

