vector<int>to[200005];
mint ans; 
int N;
int dfs(int v, int p = -1) {
	int res = 1;
	vector<int>ts;
	for (int e : to[v]) {
		if (p == e) {
			continue;
		}
		int t = dfs(e, v);
		res += t;
		ts.push_back(t);
	}
	if (-1 != p) {
		ts.push_back(N - res);
	}
	mint now = mint(2).pow(N - 1) - 1;
	for (int t:ts) {
		now -= mint(2).pow(t) - 1;
	}
	ans += now;
	return res;
}

