    in = out = vl(n);

    auto dfs = [&](auto dfs, ll source) -> void{
        visited[source] = true;
        in[source] = euler_tour.size();
        euler_tour.pb(source);

        bool is_leaf = true;
        for (auto& e: tree[source]){
            ll target = e.to;
            if (visited[target]) continue;
            else is_leaf = false;
            dfs(dfs, target);
            euler_tour.pb(source);
        }

        out[source] = euler_tour.size() - 1;
    };

    dfs(dfs, anc);
}

void read_graph(ll n_vertex, ll n_edges, Graph& graph,
                ll cost = -1, bool directed = false, ll offset = -1){

    graph.resize(n_vertex);
    rep(i, n_edges){
        ll from, to, c = cost;
        if (cost == -1) in3(from, to, c);
        else in2(from, to);
        from += offset, to += offset;

        graph[from].pb({to, cost});
        if (!directed) graph[to].pb({from, cost});
    }
}

void read_vector(ll n, vl& v, ll offset = 0){
    v.resize(n);
    rep(i, n){
        in1(v[i]);
        v[i] += offset;
    }
}

void read_pair_vector(ll n, vpl& v, ll offset1 = 0, ll offset2 = 0, bool rev = false){
    v.resize(n);
    rep(i, n){
        ll a, b; in2(a, b);
        a += offset1, b += offset2;
        if (!rev) v[i] = {a, b};
        else v[i] = {b, a};
    }
}

