    cost: if link cost is fixed, put positive integer
          otherwise -1
    directed: if directed true, olse false
    offset: if the given vertex is 1-indexed, -1.
*/

void solve(){
    in1(n);

    PowerMemo p2(n + 5, 2, MOD);
    RerootingTreeDP<Merger> dp(n);
    rep(i, n - 1){
        in2(a, b); a--, b--;
        dp.add_edge(a, b, 1);
    }
    dp.dp();

    mint answer = n * p2[n - 1];
    rep(i, n){
        rep(j, dp.tree[i].size()){
            ll n_children = dp.tree[i][j].value;
            answer -= p2[n_children] - 1;
