const int MAXV = 10000;

u64 modPow(u64 n, u64 k){
    if (k == 0) return 1LL % mod;
    u64 r = modPow(n, k >> 1);
    r = r * r % mod;
    if (k & 1) r = r * n % mod;
    return r;
}

u64 modinv(u64 a, u64 m) {
    u64 b = m, u = 1, v = 0;
    while (b) {
        u64 t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= m;
    if (u < 0) u += m;
    return u;
}

const int ONE = 1, NONE = 0, OTHER = 2;
list<edge> edges[MAXV];
vector<u64> sz(MAXV, 0);
u64 dp[MAXV][MAXV][3];

int main(int argc, char *argv[])
{

    cin.tie(0);
    ios::sync_with_stdio(false);


    memset(dp, 0, sizeof(dp));
    int N;

    cin >> N;
    vector<int> cnt(N, 0);
    for (int i = 0; i < N - 1; i++) {
        int A, B;
        cin >> A >> B;
        A--, B--;
        edges[A].push_back(edge{B, 0});
        edges[B].push_back(edge{A, 0});
    }

    function<void (int)> print = [&](int v) {
        cout << "dp[" << v << "];" << 0 << " " << 1 << " " << 2 << " " << endl;
        for (int i = 0; i < sz[v] + 1; i++) {
            cout << "i = " << i << ";" << dp[v][i][NONE] << " " << dp[v][i][ONE] << " " << dp[v][i][OTHER] << endl;
        }
    };
    function<void (int, int)> dfs = [&](int v, int parent) {
        sz[v] = 1;
        dp[v][1][NONE] = 1;
        //print(v);
        for (auto u : edges[v]) {
            if (u.to == parent) continue;
            dfs(u.to, v);
            vector<vector<u64>> merged(sz[v] + sz[u.to] + 1, vector<u64>(3,0));
            for (int i = 0; i < sz[v] + 1; i++) {
                for (int j = 0; j < sz[u.to] + 1; j++) {
                    for (int d = 0; d <= 2; d++) {
                        if (j == 1 && d == 0) {
                            merged[i][min(NONE + 1, OTHER)] += dp[u.to][j][d] * dp[v][i][NONE];
                            merged[i][min(ONE + 1, OTHER)] += dp[u.to][j][d] * dp[v][i][ONE];
                            merged[i][min(OTHER + 1, OTHER)] += dp[u.to][j][d] * dp[v][i][OTHER];
                        } else if (j == 0 && d == 0) {
                            merged[i][min(NONE, OTHER)] += dp[u.to][j][d] * dp[v][i][NONE];
                            merged[i][min(ONE, OTHER)] += dp[u.to][j][d] * dp[v][i][ONE];
                            merged[i][min(OTHER, OTHER)] += dp[u.to][j][d] * dp[v][i][OTHER];
                        }
                        else {
                            merged[i + j][min(NONE + 1, OTHER)] += dp[u.to][j][d] * dp[v][i][NONE];
                            merged[i + j][min(ONE + 1, OTHER)] += dp[u.to][j][d] * dp[v][i][ONE];
                            merged[i + j][min(OTHER + 1, OTHER)] += dp[u.to][j][d] * dp[v][i][OTHER];
                        }
                    }
                }
            }
            sz[v] += sz[u.to];
            for (int i = 0; i < merged.size(); i++) {
                dp[v][i][NONE] = merged[i][NONE];
                dp[v][i][ONE] = merged[i][ONE];
                dp[v][i][OTHER] = merged[i][OTHER];
                if (dp[v][i][NONE] || dp[v][i][ONE] || dp[v][i][OTHER]) {
                    cnt[v] = max(cnt[v], i);
                }
            }
            //print(v);
        }
        dp[v][0][NONE] = 1;
        //print(v);
    };
    dfs(0, -1);

    //for (int i = 0; i < N; i++) {
    //    print(i);
    //}

    u64 partial_sum = 0;
    for (int i = 0; i < N; i++) {
        for (int j = 1; j <= cnt[i]; j++) {
            if (dp[i][j][ONE] && j > 1) {
                partial_sum += dp[i][j][ONE] * (j - 1) * modPow(2LL, (u64)j - 2);
                partial_sum %= mod;
            }
            if (dp[i][j][OTHER]) {
                partial_sum += dp[i][j][OTHER] * j * modPow(2LL, (u64)j - 1);
                partial_sum %= mod;
            }
        }
    }
    u64 denom = 1;
    for (int i = 0; i < N; i++) {
        denom *= modinv(2LL, mod);
        denom %= mod;
    }

    cout << (partial_sum * denom) % mod << endl;


    return 0;

}

