	return ((a%mod) * (b%mod)) % mod;
}


ll fp(ll b, ll e) {
	if (!e)
		return 1;
	ll ans = fp(b, e / 2);
	ans = mul(ans, ans);
	if (e & 1) {
		ans = mul(b, ans);
	}
	return ans;
}

ll divide(ll a, ll b) {
	return ((a%mod) * fp(b, mod - 2)) % mod;
}



