	}
	//istream ostream での入出力サポート
	std::ostream& operator<<(std::ostream& stream, const Modint<MOD>& p) {
		stream << p.val;
		return stream;
	}
	std::istream& operator >> (std::istream& stream, Modint<MOD>& p) {
		stream >> p.val;
