typedef long long ll;
using namespace std;

ll toPower(ll a, ll power) {
  if(power == 0) {
    return  1;
  }
  if(a == 0) {return 0;}
  ll foo = toPower(a, power/2);
  if(power%2 == 0) {
    return (foo*foo) % P;
  } 
  return (((foo*foo)%P)*a)%P;
}

ll inv(ll a) {
  return toPower(a, P-2);
}
struct Node {
  int parent;
  vector<int> children;
  int numDesc;
};

int main() {
  cin >> N;
  vector<set<int>> edges(N);
  for(int i = 0; i< N-1; i++) {
    //cout << i << endl;
    int a,b;
    cin >> a >> b;
    a--; b--;
    edges[a].insert(b);
    edges[b].insert(a);
  }

  vector<Node> nodes(N);
  stack<pair<int,int>> st;
  st.emplace(0,-1);
  while(!st.empty()) {
    auto node_parent = st.top(); st.pop();
    auto node = node_parent.first; auto parent = node_parent.second;
    nodes[node].parent = parent;

    for(const auto neighbor: edges[node]) {
      if(neighbor != parent) {
        st.emplace(neighbor,node);
        nodes[node].children.push_back(neighbor);
      }
    }
  }

  vector<ll> numDesc(N,0);
  function<ll(int)> fillNumDesc =  [&](int node) {
    if(numDesc[node] != 0) {return numDesc[node];}
    ll ans = 1;
    for(const auto ch : nodes[node].children) {
      ans += fillNumDesc(ch);
    }
    numDesc[node] = ans;
    return ans;
  };

  fillNumDesc(0);

 // std::copy(numDesc.begin(), numDesc.end(), std::ostream_iterator<ll>(std:://cout << "numDesc ", " "));
  //cout << endl;

  ll half = inv(2);
  function<ll(vector<ll>)> chanceThrough = [&](vector<ll> nSizes) {
    vector<ll> chanceBlack(nSizes.size());
    ll ans = 1;
    ll chanceAllWhite = toPower(half,N-1);
    for(int i = 0; i < nSizes.size() ; i++) {
      chanceBlack[i] = ((1-toPower(half, nSizes[i]))+P)%P;
    }
    ans -= chanceAllWhite; 
    for(int i = 0; i < nSizes.size(); i++) {
      ans -= (chanceBlack[i]*toPower(half,(N-nSizes[i]-1))+P)%P;
      ans += P; ans %= P;
    }  
    ans += P; ans %= P;
    //cout << "chance go through " << ans << endl;
    return ans;
  };

  ll ans = 0.0;
  for(int i = 0; i < N; i++) {
//    //cout << "Node " << i << " has parent " << nodes[i].parent << " with children # " << nodes[i].children.size() << " and desc # " << numDesc[i] << endl;
    vector<ll> nSizes;
    for(const auto child: nodes[i].children) {
      nSizes.push_back(numDesc[child]);
    } nSizes.push_back(N-numDesc[i]);
    ans += half*chanceThrough(nSizes);
    ans += P; ans %=P;
  }

  cout << ans << endl;




}

