pair<mint, ll> f(ll i)
{
    mint res = 0;
    mint e = 1 - 1 / mint(2).pow(N - 1);
    ll k = 1;
    for (auto [j, _] : T[i])
    {
        auto [r, c] = f(j);
        res += r;
        k += c;
        e -= (1 - 1 / mint(2).pow(c)) / mint(2).pow(N - 1 - c);
    }
    e -= (1 - 1 / mint(2).pow(N - k)) / mint(2).pow(k - 1);
    res += e / 2;
    return {res, k};
}

