constexpr int N = 200'225, P = 1000'000'007;
vector<int> g[N];
int sz[N], p2[N],  n, ans, inv2 = (P + 1) / 2;
int dfs(int u, int p) {
  sz[u] = 1;
  for (int v : g[u])
    if (v != p)
      sz[u] += dfs(v, u);
  if (p != 0)
    ans = (ans + (int64_t) (1 + P - p2[sz[u]]) * (1 + P - p2[n - sz[u]]) % P) % P;
  return sz[u];
}
int main() {
  p2[0] = 1;
  for (int i = 1; i < N; ++i)
    p2[i] = (int64_t) p2[i - 1] * inv2 % P;
  in >> n;
  ans = (P - (int64_t)n * inv2 % P) % P;
  for (int i = 1, v, u; i < n; ++i) {
    in >> v >> u;
    g[v].push_back(u);
    g[u].push_back(v);
  }
  dfs(1, 0);
  cout << (int64_t)(ans + (int64_t)(1 + P - p2[n]) % P) % P << '\n';
}

