int powmod(int a, int n, int mod) {
	if (n == 0) return 1;
	if (n % 2 == 0) return powmod((a * a) % mod, n / 2, mod);
	return (a * powmod(a, n - 1, mod)) % mod;
}

int mod = 1000000007;
int n;
vector<int> et[200000];
int ans = 0;
int p2[200001];

int dfs(int p, int v) {
	int i;

	int sz = 1;
	int cnt = 1;
	rep(i, et[v].size()) {
		int nv = et[v][i];
		if (nv == p) continue;
		int res = dfs(v, nv);
		sz += res;
		cnt += (p2[res] - 1);
		cnt %= mod;
	}
	cnt += (p2[n - sz] - 1);
	cnt %= mod;
	ans += p2[n - 1] + mod - cnt;
	ans %= mod;

