int dfs(int v, int p=-1) {
  int res = 1;
  vi ts; // vに隣接する頂点以下の部分木のサイズのリスト(親も含む)
  for (int u : to[v]) {
    if (u == p) continue;
    int t = dfs(u,v); // u以下の部分木のサイズ
    res += t;
    ts.pb(t);
  }
  if (p != -1) {
    ts.pb(n-res); // vが根じゃなければ、親以下の部分木のサイズも追加
  }
  // now: vを白として内部に含むものが何通りあるか
  mint now = mint(2).pow(n-1) - 1; // v以外のn-1頂点について、(全通り)-(全部白)
  for (int t : ts) {
    //   -(ちょうど一個の部分木のみに1個以上の黒がある)
    // = -{(ある部分木tについて全通り) - (tについて全部白)}
    now -= mint(2).pow(t) - 1;
  }
  ans += now;
  return res; // v以下の部分木のサイズを返す
}

