void ddfs(int v, int pval = 0, int p = -1) {
    int s = (int)g[v].size();
    rep(i, s) {
        int to = g[v][i];
        if(to == p) {
            dp[v][i] += pval;
            continue;
        }
    }
    vector<int> left(s + 1, 0), right(s + 1, 0);
    rep(i, s) {
        left[i + 1] = left[i] + dp[v][i];
        right[i + 1] = right[i] + dp[v][s - 1 - i];
    }
    rep(i, s) {
        int to = g[v][i];
        if(to == p) continue;
        ddfs(to, left[i] + right[s - 1 - i], v);
    }
}

