ll rui(ll a,ll b){
    ll res=1;
    ll x=a;
    while(b){
        if(b&1)res=res*x%mod;
        x=x*x%mod;
        b/=2;
    }
    return res;
}

vector<vector<ll> >G(MAX);
vector<ll>siz(MAX);

void dfs(ll i,ll p){
    for(auto e:G[i]){
        if(e==p)continue;
        dfs(e,i);
        siz[i]+=siz[e];
    }
    siz[i]++;
}
ll n;
ll ans;
void dfs2(ll i,ll p){
    ll sum=0;
    if(i)sum=rui(2LL,n-siz[i])-1;
    else sum=0;
    for(auto e:G[i]){
        if(e==p)continue;
        sum=(sum+(rui(2LL,siz[e])-1))%mod;
        dfs2(e,i);
    }
    sum=(rui(2LL,n-1)-(1+sum)%mod)%mod;
    if(G[i].size()==1)sum=0;
    ans+=sum;
}
signed main(){
    cin>>n;
    rep(i,n-1){
        ll a,b;cin>>a>>b;
