        G[b].pb(a);
    }
    ans=0;
    dfs(0,-1);
    dfs2(0,-1);
    ll inv=rui(2LL,n);
    inv=rui(inv,mod-2LL);
    ans=ans*inv%mod;
    if(ans<0)ans+=mod;
    cout<<ans<<endl;
}

