template <typename T, typename U> T pow_fast(T x, U n) {
    T ret = (T)1;
    while(n) {
        if(n & (U)1) ret *= x;
        x *= x;
        n >>= 1;
    }
    return ret;
}

template <typename ModType, ModType MOD> struct ModInt {
    ModType val;
    ModInt() : val(0) {}
    ModInt(ModType x) : val(x % MOD) {
        if(val < 0) val += MOD;
    };
    operator ModType() const { return val; }
    ModInt &operator+=(const ModInt &m) {
        val += m.val;
        if(val >= MOD) val -= MOD;
        return *this;
    }
    ModInt &operator-=(const ModInt &m) {
        val -= m.val;
        if(val < 0) val += MOD;
        return *this;
    }
    ModInt &operator*=(const ModInt &m) {
        (val *= m.val) %= MOD;
        return *this;
    }
    ModInt &operator/=(const ModInt &m) {
        *this *= m.inverse();
        return *this;
    }
    ModInt operator+(const ModInt &m) const { return ModInt(*this) += m; }
    ModInt operator-(const ModInt &m) const { return ModInt(*this) -= m; }
    ModInt operator*(const ModInt &m) const { return ModInt(*this) *= m; }
    ModInt operator/(const ModInt &m) const { return ModInt(*this) /= m; }
    ModInt inverse() const { return pow_fast(*this, MOD - 2); }
    ModInt pow(ModType n) const {return pow_fast(*this, n); }

    friend std::ostream &operator<<(std::ostream &os, const ModInt &rhs) {
        os << rhs.val;
        return os;
    }
    friend std::istream &operator>>(std::istream &is, ModInt &rhs) {
        ModType value;
        is >> value;
        rhs = ModInt(value);
        return is;
    }
};

using mint = ModInt<ll, MOD>;
int n;
vector<vi> es;

vi size_sub_graph;

int dfs1(int cur, int par) {
    size_sub_graph[cur] = 1;
    for(auto&& to: es[cur]) if(to != par) size_sub_graph[cur] += dfs1(to, cur);
    return size_sub_graph[cur];
}
mint calc(int cur, int par) {
    mint p = mint(1)/mint(2);
    mint ret = 0;
    // 全部白
    mint all_white = 1;
    if(par != -1) {
        all_white *= p.pow(n - size_sub_graph[cur]);
    }
    for(auto&& to: es[cur]) if(to != par) {
        all_white *= p.pow(size_sub_graph[to]);
    }
    //
    mint a_black = 0;
    if(par != -1) {
        a_black += all_white * mint(2).pow(n-size_sub_graph[cur]) * (mint(1) - p.pow(n-size_sub_graph[cur]));
    }
    for(auto&& to: es[cur]) if(to != par) {
        a_black += all_white * mint(2).pow(size_sub_graph[to]) * (mint(1) - p.pow(size_sub_graph[to]));
    }
    if(es[cur].size() == 1) {
        ret = mint(0);
    }
    else {
        ret = p * (mint(1) - (all_white+a_black));
    }
    for(auto&& to: es[cur]) if(to != par) ret += calc(to, cur);
    return ret;
}


