long long modpow(long long a, long long b, long long m) {
	long long p = 1, q = a;
	for (int i = 0; i < 32; i++) {
		if ((b / (1LL << i)) % 2 == 1) { p *= q; p %= m; }
		q *= q; q %= m;
	}
	return p;
}

long long Div(long long a, long long b, long long m) {
	return (a * modpow(b, m - 2, m)) % m;
}

const long long mod = 1000000007;
long long power[1 << 18];

void init() {
	power[0] = 1;
	for (int i = 1; i < 250000; i++) power[i] = (2LL * power[i - 1]) % mod;
}

int N, A[1 << 18], B[1 << 18], dp[1 << 18];
vector<int> X[1 << 18];

void dfs(int pos) {
	dp[pos] = 1;
	for (int i = 0; i < X[pos].size(); i++) {
		if (dp[X[pos][i]] >= 1) continue;
		dfs(X[pos][i]);
		dp[pos] += dp[X[pos][i]];
	}
}

int main() {
	cin >> N; init();
	for (int i = 1; i <= N - 1; i++) {
		cin >> A[i] >> B[i];
		X[A[i]].push_back(B[i]);
		X[B[i]].push_back(A[i]);
	}
	dfs(1);

	long long sum = 0;
	for (int i = 1; i <= N; i++) {
		vector<int> V; int rem = N - 1;
		for (int j = 0; j < X[i].size(); j++) {
			if (dp[X[i][j]] >= dp[i]) continue;
			V.push_back(dp[X[i][j]]);
			rem -= dp[X[i][j]];
		}
		if (rem >= 1) V.push_back(rem);

		long long prob = 1;
		for (int j = 0; j < V.size(); j++) {
			long long prob1 = Div(1, power[N - 1 - V[j]], mod);
			long long prob2 = (mod + 1LL - Div(1, power[V[j]], mod)) % mod;
			prob -= (prob1 * prob2 % mod);
			prob = (prob + mod) % mod;
		}
		prob -= Div(1, power[N - 1], mod);
		prob = (prob + mod) % mod;

		prob = Div(prob, 2, mod);
		sum += prob; sum %= mod;
	}
	cout << sum << endl;
	return 0;
}

