	Pow[0]=1;
	for(int i=1;i<n;i++)scanf("%d%d",&u,&v),add(u,v),Pow[i]=2ll*Pow[i-1]%mo;
	inv=power(Pow[n-1],mo-2);
	dfs(1,0);
	printf("%d",ans%mo);
