vector<vector<ll> > v(N);
vector<ll> dpin(N,1),pa(N),dpout(N);

void dfs1(ll n,ll p){
	pa[n]=p;
	for(auto& to:v[n]){
		if(to==p)continue;
		dfs1(to,n);
		dpin[n]+=dpin[to];
	}
	return;
}

void dfs2(ll n,ll p){
	vector<ll> v1,v2;
	for(auto& to:v[n]){
		if(to==p)v1.pb(0),v2.pb(0);
		else v1.pb(dpin[to]),v2.pb(dpin[to]);
	}
	int niko=v1.size();
	for(int i=1;i<niko;i++)v1[i]+=v1[i-1];
	for(int i=niko-2;i>=0;i--)v2[i]+=v2[i+1];
    for(int i=0;i<niko;i++){
    	int to=v[n][i];
    	if(to==p)continue;
    	ll line=1LL;
    	if(i>0)line+=v1[i-1];
		if(i<niko-1)line+=v2[i+1];
		line+=dpout[n];
		dpout[to]=line;
		dfs2(to,n);
    }
    return;
}
