			f[u] = (f[u] + (1ll - f[u]) * sf[v]) % mod;
			h[u] = ((1ll - h[u]) * sf[v] + (1ll - sf[v]) * h[u]) % mod;
		}
	sf[u] = ((mod+1)/2+(mod+1ll)/2*f[u])%mod; 	
}

void dfs2(int u,int ff){
