// a^n mod を計算する
long long modpow(long long a, long long n, long long mod) {
    long long res = 1;
    while (n > 0) {
        if (n & 1) res = res * a % mod;
        a = a * a % mod;
        n >>= 1;
    }
    return res;
}

// a^{-1} mod を計算する
long long modinv(long long a, long long mod) {
    return modpow(a, mod - 2, mod);
}
int dp(int i){
    if (Childnum[i]!=-1){
        return Childnum[i];
    }
    if (Child[i].size()==0){
        Childnum[i]=0;
        return 0;
    }
    int res=0;
    for (auto&& j:Child[i]){
        res+=dp(j)+1;
    }
    Childnum[i]=res;
    return res;
}
int main(void){
