    vector<int> reached(N,0);
    while(!q.empty()){
        int r=q.front();q.pop();
        reached[r]=1;
        for(auto&& p:G[r]){
            if (reached[p]==1){
                continue;
            }
            Child[r].push_back(p);
            q.push(p);
        }
    }
    dp(0);
    long long int ans=(N*(1-modinv(modpow(2,N-1,mod),mod)))%mod;
    for (int r=0;r<N;r++){
