    for (int i = 0; i < N; i++) {
        for (int j = 1; j <= cnt[i]; j++) {
            if (dp[i][j][ONE] && j > 1) {
                partial_sum += dp[i][j][ONE] * (j - 1) * modPow(2, j - 2);
                partial_sum %= mod;
            }
            if (dp[i][j][OTHER]) {
                partial_sum += dp[i][j][OTHER] * j * modPow(2, j - 1);
                partial_sum %= mod;
            }
        }
    }
    u64 denom = 1;
    for (int i = 0; i < N; i++) {
        denom *= modinv(2, mod);
        denom %= mod;
    }

    cout << (partial_sum * denom) % mod << endl;


    return 0;

}

