mint ans;
vector<mint> pow2;
int N;
vl size;
vvl edges;

void calcSize(int root, int pre) {
    for (auto to : edges[root]) {
        if (to == pre) continue;
        calcSize(to, root);
        size[root] += size[to];
    }
}

void dfs(int root, int pre) {
    // 祖先と子孫に黒が少なくとも１つずつ存在する組み合わせ
    int up   = N - size[root];
    int down = size[root] - 1;
    ans += (pow2[up] - mint(1)) * (pow2[down] - mint(1));
    // root++;DEBUG(root);root--; DEBUG(ans);

    // （黒が1つ以上存在する子孫）が２つ以上存在する組み合わせ
    vector<mint> cnts;
    mint sum(0), product(1);
    for (auto to : edges[root]) {
        if (to == pre) continue;
        dfs(to, root);
        mint cnt = pow2[size[to]] - mint(1);
        cnts.push_back(cnt);
        sum += cnt;
        product *= cnt;
    }
    int n = cnts.size();
    if (n > 2) ans += product;
    ans += mint(n) * mint(n-1) * product / mint(2);
    // root++;DEBUG(root);root--; DEBUG(ans);
}

int main() {
    cin >> N;
    edges.resize(N);
    size.assign(N, 1);
    pow2.assign(N+1, 1);
    rep(i,N-1) {
        int a, b; cin >> a >> b;
        a--; b--;
        edges[a].push_back(b);
        edges[b].push_back(a);
    }
    rep(i,N) pow2[i+1] = pow2[i] * mint(2);

    int root = 0;
    calcSize(root, -1);
    dfs(root, -1);
    ans /= pow2[N];
    cout << ans << endl;
    return 0;
}

