ll modpow(ll b, ll e, ll m){  // bのe乗のmod m を返す
  if (e == 0) return 1;
  cme = modpow(b, e / 2, m);
  cme = (cme * cme) % m;
  if (e % 2 == 1) cme = (cme * b) % m;
  return cme;
}

pair<ll,ll> gcd_ext(ll a_,ll b_){
    // """
    // # 拡張ユークリッドの互除法
    // # a*x + b*y = gcd(a,b) となる (x,y) を求める.
    // """
    ll x_=0, y_=1, lastx=1, lasty=0;
    while (b_ != 0){
        ll q_ = a_ / b_;
        ll c_ = a_;
        a_ = b_;
        b_ = c_ % b_;
        ll s_ = x_, t_= y_;
        x_ = lastx - q_ * s_;
        y_ = lasty - q_ * t_;
        lastx = s_;
        lasty = t_;
    }
    return (mp(lastx,lasty));
}

