using T = pair<ll,pair<ll,ll>>;
T identity=mp(0,mp(1,0));    // 単位元 
bool Commutative_group=0;  //可換群か否か(未整備)
T Inverce;  //逆元

T merge(T left,T right){
  ll LA=left.fr,LB=left.sc.fr,LC=left.sc.sc;
  ll RA=right.fr,RB=right.sc.fr,RC=right.sc.sc;
  ll K=0;
  if(LB==0){
    K+=LC;
    K%=MOD;
  }
  else{
    K+=modpow(2,LA,MOD);
  }
  if(RB==0){
    K+=RC;K%=MOD;
  }
  else{
    K+=modpow(2,RA,MOD);
  }
  return mp(LA+RA,mp(0,(K-1+MOD)%MOD));
}

T addNode(T value,ll nodeID){
  return mp(value.fr+1,mp(1,value.sc.sc));
}
