const int BUF = 200005;
const int MOD = 1000000007;


int add(int a, int b) {
    return (a + b) % MOD;
}

int sub(int a, int b) {
    return (a + MOD - b) % MOD;
}

int modpow(int p, long long n) {
    if (n == 0) return 1;
    int t = modpow(p, n / 2);
    return n % 2 == 0 ? 1LL * t * t % MOD : 1LL * t * t % MOD * p % MOD;
}


int nNode;
vector<int> adj[BUF];

void read() {
    for (int i = 0; i < BUF; ++i) adj[i].clear();

    cin >> nNode;
    for (int i = 0; i < nNode - 1; ++i) {
        int s, t;
        cin >> s >> t;
        --s, --t;
        adj[s].push_back(t);
        adj[t].push_back(s);
    }
}


int getNumSubtreeNode(int node, int node2nSubtreeNode[BUF], map<pair<int, int>, int> &edge2nSubtreeNode) {
    int &ret = node2nSubtreeNode[node];
    ret = 1;

    for (int i = 0; i < adj[node].size(); ++i) {
        int nex = adj[node][i];
        if (node2nSubtreeNode[nex] != -1) continue;

        int nexNumSubtreeNode = getNumSubtreeNode(nex, node2nSubtreeNode, edge2nSubtreeNode);
        edge2nSubtreeNode[make_pair(node, nex)] = nexNumSubtreeNode;
        edge2nSubtreeNode[make_pair(nex, node)] = nNode - nexNumSubtreeNode;

        ret += nexNumSubtreeNode;
    }

    return ret;
}


int rec(int node, int childIdx, int nChose, vector< vector<int> > &dp, map<pair<int, int>, int> &edge2nSubtreeNode) {
    if (childIdx == adj[node].size()) {
        return nChose == 2 ? 1 : 0;
    }

    int &ret = dp[childIdx][nChose];
    if (ret != -1) return ret;
    ret = 0;

    // Choose at least one node from node's childIdx-th subtree
    ret = add(ret, 1LL * rec(node, childIdx + 1, min(nChose + 1, 2), dp, edge2nSubtreeNode) *
              sub(modpow(2, edge2nSubtreeNode[make_pair(node, adj[node][childIdx])]), 1));

    // Choose noting
    ret = add(ret, rec(node, childIdx + 1, nChose, dp, edge2nSubtreeNode));

    return ret;
}


void work() {
    map<pair<int, int>, int> edge2nSubtreeNode;

    int node2nSubtreeNode[BUF];
    memset(node2nSubtreeNode, -1, sizeof(node2nSubtreeNode));
    getNumSubtreeNode(0, node2nSubtreeNode, edge2nSubtreeNode);

    int sum = 0;
    for (int i = 0; i < nNode; ++i) {
        vector<vector<int> > dp(adj[i].size(), vector<int>(3, -1));
        sum = add(sum, rec(i, 0, 0, dp, edge2nSubtreeNode));
    }

    cout << (1LL * sum * modpow(2, 1LL * nNode * (MOD - 2))) % MOD << endl;
}


int main() {
    read();
    work();
    return 0;
}

