}

ll son[MAX] = {};//子ノードの個数

void son_calc(ll v) {
	son[v] = 0;
	rep(i, tree[v].size()) {
		ll w = tree[v][i];
		son_calc(w);
		son[v] += son[w] + 1;
	}
	//cout << v << son[v] << endl;
	return;
}

ll p(ll n) {
	if (n == 0) { return 1; }
	if (n == 1) { return 2; }
	ll x = p(n / 2);
	return x * x%MOD*p(n % 2) % MOD;
}

ll iv(ll i) {
	if (i == 1) { return 1; }
	return MOD - iv(MOD%i)*(MOD / i) % MOD;
}

