			ll v = tree[u][i];
			branch.push_back(son[v] + 1);
			sum += son[v] + 1;
		}

		if (u != 1) { branch.push_back(N - 1 - sum); }

		ll x = p(N-1)+branch.size()-1;
		rep(i, branch.size()) {
				x -= p(branch[i]);
				x %= MOD;
				if (x < 0) { x += MOD; }
