long long power(long long m, long long n){
    long long res = 1;
    while(n > 0){
        if(n & 1) {
            res = (res * m) % MOD;
        }
        m = (m * m) % MOD;
        n >>= 1;
    }
    return res;
}
long long inverse(long long a){
    return power(a, MOD - 2);
}

int dfs(int cur, int N){
    done[cur] = true;
    long long ret = 0;
    vector <int> child_node_nums;
    for(int i = 0; i < edges[cur].size(); i++){
        if(done[edges[cur][i]]){
            continue;
        }
        int tmp = dfs(edges[cur][i], N);
        ret += tmp;
        child_node_nums.push_back(tmp);
    }
    child_node_nums.push_back(N - ret - 1);

    long long not_hole = two_inverse_power[1];
    for(int i = 0; i < child_node_nums.size(); i++){
        long long tmp_not_hole = (two_inverse_power[N - child_node_nums[i]] - two_inverse_power[N] + MOD) % MOD;
        not_hole = (not_hole + tmp_not_hole) % MOD;
    }
    not_hole = (not_hole + two_inverse_power[N]) % MOD;
    ans = (ans + (1 - not_hole + MOD) % MOD) % MOD;
    return ret + 1;
}

