ModInt<MOD> solve() {
  ModInt<MOD> res, two = 2;
  cnt.assign(n, 0);
  ch.assign(n, 0);
  par.assign(n, -1);
  ch[0] = 1;
  rec(0);
  for(int i = 0; i < n; ++i) {
    ModInt<MOD> now = 0;
    for(auto nowp : edges[i])
      if(par[i] != nowp) now += two.pow(cnt[nowp]) - 1;
    if(par[i] != -1) now += two.pow(n - cnt[i]) - 1;
    res += two.pow(n - 1) - 1 - now;
  }
  return res / two.pow(n);
}

long long rec(long long now) {
  long long res = 0;
  for(auto nextp : edges[now]) {
    if(!ch[nextp]) {
      ch[nextp] = 1;
      par[nextp] = now;
      res += rec(nextp);
    }
  }
  return cnt[now] = res + 1;
}

