template<typename T>
struct ReRooting{
    using Func = function<T(T, T)>;
    struct edge{
        ll to;
        T val;
        edge(){}
        edge(ll t_, T v_): to(t_), val(v_){}
    };
    vector<vector<edge>> G;     // グラフ
    vector<T> V;                // 各頂点を根としたときの値
    vector<map<ll, T>> dp;
    T id;

    ReRooting(ll N_, T id_)
        : G(N_), V(N_), dp(N_), id(id_){}

    void addedge(ll a, ll b, T c){
        G[a].emplace_back(b, c);
    }

    T merge(T a, T b) {
        return a + b;
    }
    T rooting(T a, T b) {
        return a + b;
    }

    void build(){
        ll N = G.size();
        auto dfs = [&](auto&& dfs, ll now, ll par, bool flag) {
            if (dp[now].count(par)) return dp[now][par];

            if(par == -1 or flag){
                vector<T> A;
                for (ll i = 0; i < G[now].size(); i++){
                    ll to = G[now][i].to;
                    if (to == par) continue;

                    T v = rooting(dfs(dfs, to, now, flag), G[now][i].val);
                    A.emplace_back(v);
                }

                vector<T> R(A.size() + 1, id);  //右からの累積和
                for (ll i = A.size(); i > 0; i--) R[i - 1] = merge(R[i], A[i - 1]);

                if(par == -1){
                    rep(i, A.size()) C[now].eb(A[i]);
                    T L = id;
                    for (ll i = 0; i < G[now].size(); i++){
                        ll to = G[now][i].to;

                        dp[now][to] = merge(L, R[i + 1]);  //now->toを除いた値
                        L = merge(L, A[i]);  //左から累積していく
                    }
                }

                return dp[now][par] = R[0];

            }
            else{
                dfs(dfs, now, -1, flag);
                return dfs(dfs, now, par, flag);
            }
        };

        dfs(dfs, 0, -1, true);

        for (ll i = 0; i < N; i++) dfs(dfs, i, -1, false), V[i] = dp[i][-1];
    }
};

