ll rui(ll a,ll b){
    ll ans=1;
    while(b>0){
        if(b&1) ans=ans*a%mod;
        a=a*a%mod;
        b/=2;
    }
    return ans;
}
ll sum=0;

void preDFS(int u,int p){
    size[u]=1;
    for(int to:G[u]){
        if(to==p) continue;
        preDFS(to,u);
        size[u]+=size[to];
    }
}

void solve(int u,int p){

    ll prob=mod+1;
    prob-=rui(rui(2,mod-2),N-1);
    for(int to:G[u]){
        prob+=mod;
        prob-=(rui(2,size[to])-1)*rui(rui(2,size[to]),mod-2)%mod*rui(rui(2,mod-2),N-1-size[to])%mod;
        prob%=mod;

        if(to==p) continue;

        size[u]-=size[to];
        size[to]=N;

        solve(to,u);

        size[to]-=size[u];
        size[u]=N;
    }
    if(G[u].size()==1) prob=0;
    sum+=prob*rui(2,mod-2);
    sum%=mod;

