struct subtree_size{//木で、ある頂点を除いた時にできる森の各木のサイズを求める
	vector<int> u,v; //辺集合
	vector<int> us,vs;
	vector<vector<int>> forest;
	int N;
	subtree_size(vector<int> u_,vector<int> v_){
		u = u_; v = v_;
		N = u.size() + 1;
		us.resize(N-1,0);
		vs.resize(N-1,0);
		set<int> connect[N];
		vector<int> num(N,0);
		vector<int> did(N-1,0);//1->uでやった 2->vでやった
		for(int i=0;i<N-1;i++){
			connect[u[i]].insert(i);
			connect[v[i]].insert(i);
		}
		queue<int> Q;//辺の番号が入る
		for(int i=0;i<N;++i){
			if(connect[i].size() == 1){
				Q.push( *connect[i].begin() );
			}
		}
		while( Q.size() ){
			int ie = Q.front();
			Q.pop();
			if(connect[u[ie]].size() == 1){
				us[ie] = num[u[ie]] + 1;
				num[v[ie]] += us[ie];
				connect[u[ie]].clear();
				connect[v[ie]].erase(ie);
				if(connect[v[ie]].size()==1){
					Q.push( *connect[v[ie]].begin() );
				}
				if(not did[ie]) did[ie] = 1;
			}else{
				vs[ie] = num[v[ie]] + 1;
				num[u[ie]] += vs[ie];
				connect[v[ie]].clear();
				connect[u[ie]].erase(ie);
				if(connect[u[ie]].size()==1){
					Q.push( *connect[u[ie]].begin() );
				}
				if(not did[ie]) did[ie] = 2;
			}
		}
		forest.resize(N);
		for(int i=0;i<N-1;i++){
			if(did[i]==1){
				vs[i] = N - us[i];
			}else{
				us[i] = N - vs[i];
			}
			forest[u[i]].push_back(vs[i]);
			forest[v[i]].push_back(us[i]);
		}
	}
};



