	subtree_size ss(u,v);
	ll ans = 0;
	FOR(i,0,N){
		ll sum = 0;
		for(auto s:ss.forest[i]){
			sum += s;
			(ans += MOD - calc(2,s,MOD) + 1 ) %= MOD;
		}
		(ans += calc(2,sum,MOD)) %= MOD;
		(ans += MOD - 1) %= MOD;
	}
	(ans *= calc(calc(2,N,MOD),MOD-2,MOD)) %= MOD;
	cout << ans << endl;
}

