void dp(int u,int n){
    count[u] = 1;
    long long p = ((1ll - power[n-1])%mod + mod)%mod;
    for(unsigned int i = 0; i < g[u].size(); i++){
        int v = g[u][i];
        if(count[v]!=0) continue;
        dp(v,n);
        long long minus = ((1ll-power[count[v]])%mod+mod)%mod*(power[n-count[v]-1])%mod;
        p = ((p - minus)%mod+mod)%mod;
        count[u] += count[v];
    }
    long long minus = ((1ll-power[n-count[u]])%mod+mod)%mod*(power[n-(n-count[u])-1])%mod;
    p = ((p - minus)%mod+mod)%mod;
    //printf("p = %lld\n",p);
    f[u] = p*inv2%mod;
}

