ll modpower(ll a, ll r){ //a^r
    ll x = 1;
    while (r > 0) {
        if (r & 1) x = x * a % mod;
        r >>= 1;
        a = a * a % mod;
    }
    return x;
}

ll modinv(ll a){
    return modpower(a, mod-2);
}

int main(){
    int N;
    cin >> N;
    vector<vector<int>> edge(N+1, vector<int>());
    for (int i = 0; i < N-1; i++) {
        int A, B;
        cin >> A >> B;
        edge[A].push_back(B);
        edge[B].push_back(A);
    }
    vector<int> parent(N+1, 0);
    vector<vector<int>> child(N+1, vector<int>());
    queue<int> q;
    vector<int> ts;
    ts.push_back(1);
    q.push(1);
    while (!q.empty()) {
        int now = q.front();
        q.pop();
        for (int nxt : edge[now]) {
            if (nxt == parent[now]) continue;
            parent[nxt] = now;
            child[now].push_back(nxt);
            q.push(nxt);
            ts.push_back(nxt);
        }
    }
    vector<ll> rs(N+1, 0);
    for (int i = N-1; i >= 0; i--) {
        rs[ts[i]] = 1;
        for (int t : child[ts[i]]) {
            rs[ts[i]] += rs[t];
        }
