struct mint {
    ll x; // typedef long long ll;
    mint(ll x = 0) : x((x % mod + mod) % mod) {}

    mint &operator+=(const mint a) {
        if ((x += a.x) >= mod) x -= mod;
        return *this;
    }

    mint &operator-=(const mint a) {
        if ((x += mod - a.x) >= mod) x -= mod;
        return *this;
    }

    mint &operator*=(const mint a) {
        (x *= a.x) %= mod;
        return *this;
    }

    mint operator+(const mint a) const {
        mint res(*this);
        return res += a;
    }

    mint operator-(const mint a) const {
        mint res(*this);
        return res -= a;
    }

    mint operator*(const mint a) const {
        mint res(*this);
        return res *= a;
    }

    mint pow(ll t) const {
        if (!t) return 1;
        mint a = pow(t >> 1);
        a *= a;
        if (t & 1) a *= *this;
        return a;
    }

    // for prime mod
    mint inv() const {
        return pow(mod - 2);
    }

    mint &operator/=(const mint a) {
        return (*this) *= a.inv();
    }

    mint operator/(const mint a) const {
        mint res(*this);
        return res /= a;
    }

    friend std::istream &operator>>(std::istream &in, mint &o) {
        ll a;
        in >> a;
        o = a;
        return in;
    }

    friend std::ostream &operator<<(std::ostream &out, const mint &o) {
        out << o.x;
        return out;
    }

};

ll rec(int now,
       vector<vector<int>> &edges,
       vector<ll> &cnt,
       vector<bool> &ch,
       vector<ll> &par) {
    ll res = 0;
    for (auto nextp : edges[now]) {
        if (!ch[nextp]) {
            ch[nextp] = 1;
            par[nextp] = now;
            res += rec(nextp, edges, cnt, ch, par);
        }
    }
    return cnt[now] = res + 1;
}


mint solve(int n, vector<vector<int>> &edges) {
    mint res, two = 2;

    vector<ll> cnt(n, 0);
    vector<bool> ch(n, false);
    vector<ll> par(n, -1);

    ch[0] = 1;
    rec(0, edges, cnt, ch, par);
    for (int i = 0; i < n; ++i) {
        mint now = 0;
        long long sum = 0;
        for (auto nowp : edges[i])
            if (par[i] != nowp) {
                sum += cnt[nowp];
                now += two.pow(cnt[nowp]) - 1;
            }
        if (par[i] != -1) now += two.pow(n - sum - 1) - 1;
        res += two.pow(n - 1) - 1 - now;
    }
    return res / two.pow(n);
}

