void solve(){
  using namespace qweqwe::stdplus::iosplus;
  using namespace qweqwe::stdplus::math;
  using namespace qweqwe::math;
  using mint = modint<mod>;
  using Edge = pair<int,int>;
  using Edges = vector<Edge>;
  iosFast();
  int n;
  cin >> n;
  vector<Edges> graph(n);
  FOR(i,0,n-1){
    int a, b;
    cin >> a >> b;
    --a; --b;
    graph[a].push_back(Edge(b,0));
    graph[b].push_back(Edge(a,0));
  }
  vector<int> checked(n,0);
  while(true){
    bool cont = true;
    FOR(i,0,n){
      if(checked[i]==1) continue;
      cont = false;
      ll s = 0; int snum = 0;
      for(auto x: graph[i]){
        if(checked[x.first]==1){
          s += x.second;
        }else{
          snum++;
        }
      }
      if(snum <= 1){
        checked[i] = 1;
        for(int j=0; j<graph[i].size(); ++j){
          if(checked[graph[i][j].first]==0){
            graph[i][j].second = n - s - 1;
            for(int k = 0; k<graph[graph[i][j].first].size(); ++k){
              if(graph[graph[i][j].first][k].first==i){
                graph[graph[i][j].first][k].second = s + 1;
              }
            }
          }
        }
      }
    }
    if(cont) break;
  }
  vector<mint> pow2s(n+10,1); mint inv2n, two(2), one(1);
  FOR(i,0,n+5){
    pow2s[i+1] = two * pow2s[i];
  }
  inv2n = pow2s[n].inv();
  mint ans(0);
  FOR(i,0,n){
    mint mini(0);
    for(auto x: graph[i]){
      mini += pow2s[x.second];
      mini -= one;
    }
    mini += one;
    mini = pow2s[n-1] - mini;
    ans += mini;
  }
  ans *= inv2n;
  cout << ans << endl;
}


