ll modpow(ll n, ll k)
{
    if (k == 0)
    {
        return 1;
    }
    else if (k % 2 == 0)
    {
        ll res = modpow(n, k / 2);
        return res * res % mod;
    }
    else
    {
        ll res = modpow(n, k - 1);
        return res * n % mod;
    }
}

ll modinv(ll n)
{
    return modpow(n, mod - 2);
}

void dfs1(int v, int par = -1) {
