  mint sum = 0;
  rep(i, N) {
    for (auto s : cc_size[i]) {
      sum += modpow(mint(2), s);
    }
  }
  mint p = modpow(mint(2), N);
  mint ans = mint(N) / mint(2);
  ans += (mint(N-2) - sum) / p;
  cout << ans << endl;
  return 0;
}

