struct subtree_size{//木
	vector<vector<int>> Ge;
	vector<int> u,v; //辺集合
	vector<int> us,vs;
	int N;
	subtree_size(vector<int> u_,vector<int> v_){
		u = u_;
		v = v_;
		N = u.size() + 1;
		Ge.resize(N);
		for(int i=0;i<N-1;i++){
			// 頂点iに属する辺eのindexをGe[i]に追加
			Ge[u[i]].push_back(i);
			Ge[v[i]].push_back(i);
		}
		us.resize(N-1,-1);
		vs.resize(N-1,-1);
	}
	int usize(int i){//us[i]を構築
		if(us[i]!=-1)return us[i];
		int res = 0;
		for(auto ie:Ge[u[i]]){
			if(ie == i)continue;
			if(u[i] == u[ie]){
				res += vsize(ie);
			}else{
				res += usize(ie);
			}
		}
		return us[i] = res+1;
	}
	int vsize(int i){//vs[i]を構築
		if(vs[i]!=-1)return vs[i];
		int res = 0;
		for(auto ie:Ge[v[i]]){
			if(ie == i)continue;
			if(v[i] == u[ie]){
				res += vsize(ie);
			}else{
				res += usize(ie);
			}
		}
		return vs[i] = res+1;
	}
	vector<int> size_set(int i){
		vector<int> res;
		for(auto ie:Ge[i]){
			if(i != u[ie]){
				res.push_back(usize(ie));
			}else{
				res.push_back(vsize(ie));
			}
		}
		return res;
	}
};


ll calc(ll a,ll b,ll p){//a^(b) mod p   
	if(b==0)return 1;
	ll y = calc(a,b/2,p);y=(y*y)%p;
	if(b & 1) y = (y * a) % p;
	return y;
}

int main(){
	ll N;
	cin >> N;
	vector<int> u(N-1),v(N-1);
	FOR(i,0,N-1){
		cin >> u[i] >> v[i];
		u[i]--;
		v[i]--;
	}
	subtree_size ss(u,v);
	ll ans = 0;
	FOR(i,0,N){
		ll sum = 0;
		for(auto s:ss.size_set(i)){
			sum += s;
			(ans += MOD - calc(2,s,MOD) + 1 ) %= MOD;
		}
		(ans += calc(2,sum,MOD)) %= MOD;
		(ans += MOD - 1) %= MOD;
	}
	(ans *= calc(calc(2,N,MOD),MOD-2,MOD)) %= MOD;
	cout << ans << endl;
}

