P diameter_p(tree<> &E) {    auto d = diameters_p(E);    int dis = -1;    int l = -1, r = -1;    rep(i, sz(d)) {        if (chma(dis, d[i].se)) {            l = i;            r = d[i].fi;        }    }    return mp(l, r);}
