unordered_map<int, unordered_map<int, int>> memo;

int count(int p, int u) {
  if (memo[p][u] != 0) return memo[p][u];
  if (memo[u][p] != 0) return N - memo[u][p];

  int res = 1;
  for (int v : G[u]) {
    if (v == p) continue;
    res += count(u, v);
  }
  return memo[p][u] = res;
}

