long long fastpower(long long b, long long p) {
    long long res = 1;
    long long v = b;
    while (p) {
        if (p & 1) res = (res * v) % mod;
        p >>= 1;
        v = (v * v) % mod;
    }
    return res;
}

long long hlf = fastpower(2, mod - 2);

int sz[N];

void getsz(int u, int p) {
    sz[u] = 1;
    for (auto v:adj[u]) {
        if (v == p) continue;
        getsz(v, u);
        sz[u] += sz[v];
    }
}

int n;
long long memo[N][2];

long long solve(int l, bool o) {
    if (l == 0) return o;
    long long &res = memo[l][o];
    if (~res) return res;
    res = (hlf * solve(l - 1, o)) % mod;
    res = (res + hlf * solve(l - 1, 1)) % mod;
    return res;
}

long long ans = 0;

long long memo2[N][4];
int vis[N][4], vid = 0;
int l;
vector<long long> arr;

long long solve2(int idx, int c) {
    c = min(c, 2);
    if (idx == l) {
        return c == 2;
    }
    long long &res = memo2[idx][c];
    if (vis[idx][c] == vid) return res;
    vis[idx][c] = vid;
    res = ((1-arr[idx]+mod)*solve2(idx + 1, c)) % mod;
    res = (res + solve2(idx + 1, c + 1) * arr[idx]) % mod;
    return res;
}


void dfs(int u, int p) {
    long long val = hlf;
    int c = 0;
    vector<long long> vec;
    for (auto v:adj[u]) {
        if (v == p) continue;
        vec.push_back(solve(sz[v], 0));
        ++c;
        dfs(v, u);
    }
    if (n - sz[u]) {
        ++c;
        vec.push_back(solve(n - sz[u], 0));
    }
    if (c > 1) {
        arr = vec;
        l = vec.size();
        ++vid;
        val = (solve2(0, 0)) % mod;
        val = (val * hlf) % mod;
        ans = (ans + val) % mod;
    }
}


