  }
  vector<int> size(N);
  mint ans = 0;
  auto dfs = [&](auto dfs, int u, int p) -> void {
    size[u] = 1;
    mint q = modinv(2);
    q -= modinv(modpow(2, N));
    for (int v : G[u]) if (v != p) {
      dfs(dfs, v, u);
      size[u] += size[v];
      q -= (modpow(2, size[v]) - 1) * modinv(modpow(2, N));
    }
    q -= (modpow(2, N - size[u]) - 1) * modinv(modpow(2, N));
    ans += q;
  };
  dfs(dfs, 0, -1);
  cout << ans << endl;
}

