long long int P[200005];

long long int POW(long long int a, long long int k) {
	if (k == 0) { return 1; }
	if (k == 1) { return a; }

	if (k % 2 == 1) { return (a*POW(a, k - 1)) % MOD; }

	long long int ret = POW(a, k / 2);

	return (ret*ret) % MOD;
}

long long int INV(long long int val) {
	return POW(val, MOD - 2);
}

