constexpr int P = 1000000007;

ll powmod(ll n, ll k) {
    ll r = 1, t = n % P;
    for (; k != 0; k /= 2) {
        if (k & 1) r = r * t % P;
        t = t * t % P;
    }
    return r;
}
ll inv(ll n) {
    return powmod(n, P - 2);
}

ll r;
vector<int> a;

struct Graph {
    struct Vertex { int n; };
    struct Edge { int i, n; };
    Graph(int n, int m) : v(n, { -1 }), e(m), n(n), m(0) {}
    void add_edge(int i, int j) {
        e[m] = { j, v[i].n };
        v[i].n = m;
        m++;
    }
    int dfs(int i, int p) {
        int c = 1;
        for (int j = v[i].n; j >= 0; j = e[j].n) {
            Edge& o = e[j];
            if (o.i == p) continue;
            int t = dfs(o.i, i);
            c += t;
            r += a[n] - a[t] - a[n - t] + 1;
        }
        return c;
    }
    void solve() {
        r = 0;
        a = vector<int>(n + 1);
        a[0] = 1;
        for (int i = 0; i < n; i++) {
            a[i + 1] = a[i] * 2 % P;
        }
        dfs(0, -1);
        r += a[n] - 1;
        r -= a[n - 1] * n;
        r %= P;
        if (r < 0) r += P;
        r = r * inv(a[n]) % P;
        cout << r << endl;
    }
    vector<Vertex> v;
    vector<Edge> e;
    int n, m;
};

