#include <bits/stdc++.h>
using namespace std;
using ll = long long;

struct Edge {
    int to;
    ll ch;
};

ll solve() {
    ll N, a, b;
    cin >> N;
    vector<vector<Edge>> G(N);
    for ( int i = 0; i < N-1; i++ ) {
        cin >> a >> b;
        a--, b--;
        G[a].push_back(Edge{b,0LL});
        G[b].push_back(Edge{a,0LL});
    }

    function<ll(int, int)> dfs = [&](int v, int p) {
        ll ch = 1;
        for ( auto& e : G[v] ) {
            if ( e.to == p ) continue;
            e.ch = dfs( e.to, v );
            ch += e.ch;
        }
        for ( auto& e : G[v] ) {
            if ( e.to == p ) {
                e.ch = N - ch;
            }
        }
        return ch;
    };

    dfs(0, -1);

    const ll MOD = 1e9 + 7;
    auto Add = [&](ll& x, ll y) { x = ( x % MOD + y % MOD ) % MOD; };
    auto Mul = [&](ll& x, ll y) { x = ( x % MOD * y % MOD ) % MOD; };
    auto Pow = [&](ll x, ll n) -> ll {
        ll t = x % MOD, r = 1;
        while ( n > 0 ) {
            if ( n & 1 ) Mul(r, t);
        Mul(t, t);
        n >>= 1;
        }
        return r;
    };
    auto Inv = [&](ll a) -> ll {
        return Pow(a, MOD - 2);
    };

    ll M = 2*10e5;
    vector<ll> pow2(M+1);
    ll pw = 1;
    for ( int i = 0; i <= M; i++ ) {
        pow2[i] = pw;
        Mul(pw, 2);
    }

    ll hc = 0;
    for ( int i = 0; i < N; i++ ) {
        ll noh = 1;
        for ( auto e : G[i] ) {
            Add(noh, pow2[e.ch]);
            Add(noh, MOD - 1);
        }
        Add(hc, pow2[N-1]);
        Add(hc, MOD - noh);
    }
    ll ans = hc;
    Mul(ans, Inv(pow2[N]));
    return ans;
}

