//pow
template<typename T, typename U>
T pow(T k, U n, T unity = 1) {
    while (n > 0) {
        if (n & 1) {
            unity *= k;
        }
        k *= k;
        n >>= 1;
    }
    return unity;
}

void dfs2(int v, ll d_par, int p = -1) {
    // v における答えの計算
    ans[v] = 1;
    ans[v] -= pow(pow(mint<MOD>(2),MOD - 2), n - 1);
    for (int &u : tree[v]) {
        if (u == p) {
            ans[v] -= (pow(mint<MOD>(2),d_par) - 1)*pow(pow(mint<MOD>(2), MOD - 2), n - 1);
        }
        else {
            ans[v] -= (pow(mint<MOD>(2), dist[u]) - 1)*pow(pow(mint<MOD>(2), MOD - 2), n - 1);
        }
    }
    ans[v] *= pow(mint<MOD>(2), MOD - 2);

    // 左右からの累積演算を用いて子に送る d_par の計算
    // lf[i] : [:i-1]の演算結果
    // ri[i] : [i+1:]の演算結果
    int e = 0; // 演算の単位元 ( maxの場合 -INF )
    vector<ll> lf(tree[v].size(), e), ri(tree[v].size(), e);
    for (int i = 1; i < tree[v].size(); i++) {
        if (tree[v][i - 1] == p) lf[i] = lf[i - 1];
        else lf[i] = dist[tree[v][i - 1]] + lf[i - 1];
    }
    for (int i = tree[v].size() - 2; i >= 0; i--) {
        if (tree[v][i + 1] == p) ri[i] = ri[i + 1];
        else ri[i] = dist[tree[v][i + 1]] + ri[i + 1];
    }
    for (int i = 0; i < tree[v].size(); i++) {
        if (tree[v][i] == p) continue;
        dfs2(tree[v][i], lf[i] + ri[i] + (p >= 0 ? d_par : 0) + 1, v);
    }
}

