    dist.resize(n);
    ans.resize(n);
    for (int i = 0; i < n - 1; i++) {
        int u, v; cin >> u >> v;
        u--; v--;
        tree[u].push_back(v);
        tree[v].push_back(u);
    }
    dfs1(0);
    dfs2(0, 0);
    mint<MOD> res = 0;
    for (int i = 0; i < n; i++) {
        res += ans[i];
    }
    cout << res << endl;
    return 0;
}

