                    node.op.wsm+=node.child[i]->sm;node.op.wsm%=MOD;
                    node.op.wnm+=node.child[i]->nm;node.op.wnm%=MOD;
                    node.cl.wnm+=MOD-node.child[i]->nm;node.cl.wnm%=MOD;
                }
