            for(int i=0;i<num;++i){
                //case of white
                if(node.child[i]->no!=node.par){
                    node.cl.wsm+=node.child[i]->sm*(((nm*modinv(node.child[i]->nm+1,MOD))%MOD)+MOD-1);node.cl.wsm%=MOD;
                }
            }
            node.cl.wsm+=node.cl.wnm;node.cl.wsm%=MOD;
            node.op.wsm+=node.op.wnm;node.op.wsm%=MOD;
            node.sumation();
        }
    }
    void solve(){
