int dfs2(int v, int p = -1, int par = 0) {
    int res = modpow[N - 1] - 1;
    for (auto nv : G[v]) {
        if (nv == p)
            (res -= modpow[par] - 1) %= MOD;
        else
            (res -= modpow[dp[nv]] - 1) %= MOD;
    }

    for (auto nv : G[v]) {
        if (nv == p)
            continue;
        (res += dfs2(nv, v, dp[v] - dp[nv] + par)) %= MOD;
    }
    return res;
}

void extGCD(ll a, ll b, ll &p, ll &q) {
    if (b == 0) {
        p = 1, q = 0;
        return;
    }
    extGCD(b, a % b, q, p);
    q -= a / b * p;
}

int modinv(ll a, ll m) {
    ll p, q;
    extGCD(a, m, p, q);
    p %= m;
    if (p < 0)
        p += m;
    return p;
}

