void solve(int node , int par) {
    // all n - 1 nodes are white
    int p = fp(fp(2, n - 1), mod - 2);
    for (auto &i : g[node])
        if (i != par) {
            solve(i, node);
            // subtree of i are all white
            int p1 = fp(fp(2, sz[i]), mod - 2);
            // subtree of i has at least one black node
            p1 = (1 - p1 + mod) % mod;
            // all n - 1 - sz[i] are white
            int p2 = fp(fp(2, n - 1 - sz[i]), mod - 2);
            p = (p + (1ll * p1 * p2) % mod) % mod;
        }
