  {
    dfs(0);
    calc(0);
    for (auto i = 0; i < N; i++)
    {
      ans += tmp[i];
    }
    ans /= two.power(N);
  }

  mint answer()
  {
    return ans;
  }

private:
  void dfs(int x, int p = -1)
  {
    parent[x] = p;
    for (auto c : V[x])
    {
      if (c != p)
      {
        children[x].push_back(c);
        dfs(c, x);
      }
    }
  }

  void calc(int x)
  {
    for (auto c : children[x])
    {
      calc(c);
    }
    vector<int> L;
    int sum{0};
    for (auto c : children[x])
    {
      L.push_back(cnt[c]);
      sum += cnt[c];
    }
    cnt[x] = sum + 1;
    L.push_back(N - cnt[x]);
    mint res{two.power(N - 1) - 1};
    for (auto e : L)
    {
      res -= (two.power(e) - 1);
    }
    tmp[x] = res;
  }
};

