#define mod 1000000007
long long inv[200010];
vector<int> e[200010];
vector<int> v[200010];

void pre() {
    inv[0] = 1; inv[1] = 500000004;
    for (int i = 2; i < 200010; i++) inv[i] = inv[i-1] * inv[1] % mod;
}

int search(int curr, int prev, int n) {
    int all = 0;
    int q = 0;
    for (auto &to: e[curr]) {
        if (to == prev) continue;
        auto s = search(to, curr, n);
        v[curr].emplace_back(s);
        all += s;
    }
    if (n-1 != all) v[curr].emplace_back(n-all-1);
    return all + 1;
}

long long calc(int i, int n) {
    long long ret = inv[1] - inv[n] + mod; ret %= mod;
    for (auto &x: v[i]) {
        ret -= inv[n-x] - inv[n];
        ret = (ret + mod) % mod;
    }
    if (v[i].size() <= 1) ret = 0;
    return ret;
}

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    pre();
    int n; cin >> n;
    for (int i = 0; i < n-1; i++) {
        int a, b; cin >> a >> b; a--; b--;
        e[a].emplace_back(b); e[b].emplace_back(a);
    }
    search(0, -1, n);
    long long ans = 0;
    for (int i = 0; i < n; i++) {
        ans += calc(i, n); ans %= mod;
    }
    cout << ans << "\n";
    return 0;
}

#include <bits/stdc++.h>

using namespace std;
using int64 = long long;

constexpr int DEBUG = 0;

constexpr int64 P = 1000000007;

struct FiniteField {
 private:
  int64 x;
  static inline int64 Normalize(int64 x) {
    if (0 <= x && x < P) return x; x %= P; if (x < 0) x += P; return x;
  }
 public:
  FiniteField(int64 x) : x(Normalize(x)) {}
  FiniteField() : x(0) {}
  int64 Value() const { return x; }
  inline FiniteField operator+(FiniteField o) const {
    FiniteField r(*this); r += o; return r;
  }
  inline FiniteField operator-(FiniteField o) const {
    FiniteField r(*this); r -= o; return r;
  }
  inline FiniteField operator* (FiniteField o) const {
    FiniteField r(*this); r *= o; return r;
  }
  inline FiniteField operator/ (FiniteField o) const {
    FiniteField r(*this); r /= o; return r;
  }
  inline void operator+= (FiniteField o) { x = (x + o.x) % P; }
  inline void operator-= (FiniteField o) { x = (x + P - o.x) % P; }
  inline void operator*= (FiniteField o) { x = (x * o.x) % P; }
  void operator/=(FiniteField o) {
    int64 p = P - 2; while (p) { if (p % 2) { *this *= o; } o *= o; p /= 2; }
  }
};

ostream& operator<<(ostream& s, const FiniteField& v) { s << v.Value(); return s; }

struct Edge {
  const int from, to;
  Edge(int from, int to) : from(from), to(to) {}
};

vector<vector<Edge>> ReadUndirectedGraph(
    int n, int m, bool is_one_indexed=false) {
  vector<vector<Edge>> graph(n);
  for (int i = 0; i < m; i++) {
    int v1, v2;
    cin >> v1 >> v2;
    if (is_one_indexed) {
      v1--;
      v2--;
    }
    graph[v1].push_back(Edge(v1, v2));
    graph[v2].push_back(Edge(v2, v1));
  }
  return graph;
}

int Sum(const vector<int>& xs) {
  int r = 0;
  for (int x : xs) r += x;
  return r;
}

FiniteField Power(FiniteField x, int p) {
  if (p < 0) return FiniteField(1) / Power(x, -p);
  FiniteField value = 1;
  while (p) {
    if (p % 2) value *= x;
    x *= x;
    p /= 2;
  }
  return value;
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int n;
  cin >> n;

  auto graph = ReadUndirectedGraph(n, n - 1, true);
  vector<int> sizes(n);
  function<void(int, int)> dfs_fn = [&](int v, int p) {
    int size = 1;
    for (const auto& e : graph[v]) {
      if (e.to == p) continue;
      dfs_fn(e.to, v);
      size += sizes[e.to];
    }
    sizes[v] = size;
  };
  dfs_fn(0, -1);

  FiniteField sum = 0;
  for (int v = 0; v < n; v++) {
    vector<int> cs;
    for (const auto& e : graph[v]) {
      if (sizes[e.to] < sizes[v]) {
        cs.push_back(sizes[e.to]);
      }
    }

    if (Sum(cs) < n - 1) {
      cs.push_back(n - 1 - Sum(cs));
    }

    FiniteField a = 0;
    for (int c : cs) {
      a += Power(2, c) - 1;
    }
    a += 1;
    sum += Power(2, n - 1) - a;
  }
  cout << sum / Power(2, n) << endl;
}

