			for(auto j : a[i]){
				ans -= modint<mod>(2) ^ modint<mod>(j.second);
				ans += modint<mod>(1);
			}
			ans -= modint<mod>(1);
		}
	}

	ans /= modint<mod>(2) ^ modint<mod>(n);

	std::cout << ans << std::endl;

	delete p;
	delete q;
}

