void get_forest_size(const vector<int> &u,const vector<int> &v,vector<vector<int>> &forest){
	const int N = u.size() + 1;
	vector<int> us(N-1,0),vs(N-1,0),num(N,0),did(N-1,0);
	set<int> connect[N];
	for(int i=0;i<N-1;i++){
		connect[u[i]].insert(i);
		connect[v[i]].insert(i);
	}
	queue<int> Q;
	for(int i=0;i<N;++i)
		if(connect[i].size()==1)
			Q.push( *connect[i].begin() );
	while( Q.size() ){
		int ie = Q.front();
		Q.pop();
		int isu = connect[u[ie]].size() == 1;
		(isu?us[ie]:vs[ie]) = num[(isu?u[ie]:v[ie])] + 1;
		num[(isu?v[ie]:u[ie])] += (isu?us[ie]:vs[ie]);
		connect[(isu?u[ie]:v[ie])].clear();
		connect[(isu?v[ie]:u[ie])].erase(ie);
		if(connect[(isu?v[ie]:u[ie])].size()==1){
			Q.push( *connect[(isu?v[ie]:u[ie])].begin() );
		}
		if(not did[ie]) did[ie] = (isu?1:2);
	}
	forest.resize(N);
	for(int i=0;i<N-1;i++){
		( did[i]==1 ? vs[i] = N - us[i] : us[i] = N - vs[i] );
		forest[u[i]].push_back(vs[i]);
		forest[v[i]].push_back(us[i]);
	}
	return;
}

ll calc(ll a,ll b,ll p){//a^(b) mod p   
	if(b==0)return 1;
	ll y = calc(a,b/2,p);y=(y*y)%p;
	if(b & 1) y = (y * a) % p;
	return y;
}

int main(){
	ll N,ans=0,MOD=1000000007LL;
	cin >> N;
	vector<int> u(N-1),v(N-1);
	for(int i=0;i<N-1;i++){
		cin >> u[i] >> v[i];
		u[i]--;v[i]--;
	}
	vector<vector<int>> fs;
	get_forest_size(u,v,fs);
	for(int i=0;i<N;i++){
		ll sum = 0;
		for(auto s : fs[i]){
			sum += s;
			( ans += MOD - calc(2,s,MOD) + 1 ) %= MOD;
		}
		( ans += calc(2,sum,MOD) ) %= MOD;
		( ans += MOD - 1 ) %= MOD;
	}
	( ans *= calc(calc(2,N,MOD),MOD-2,MOD) ) %= MOD;
	cout << ans << endl;
}

