typedef long long ll;

ll fp(ll x, ll t) {
	ll ret = 1;
	for (; t; t >>= 1, x = x * x % mod) if (t & 1) ret = ret * x % mod;
	return ret;
}

ll n, ans;
ll head[200005], pre[400005], to[400005], siz[400005], sz;
ll num[200005], top;

void addedge(ll u, ll v) {
	pre[++sz] = head[u]; head[u] = sz; to[sz] = v;
} 

void dfs(ll x, ll fa) {
	siz[x] = 1;
	for (int i = head[x]; i; i = pre[i]) {
		ll y = to[i];
		if (y == fa) continue;
		dfs(y, x); siz[x] += siz[y];
	}
	top = 0; ll tmp = 1;
	for (int i = head[x]; i; i = pre[i]) {
		ll y = to[i];
		if (y != fa) {
			num[++top] = fp(d2, siz[y]);
			tmp = num[top] * tmp % mod;
		}
	}
	if (n - siz[x]) {
		num[++top] = fp(d2, n - siz[x]);
		tmp = num[top] * tmp % mod;
	}
	if (top == 1) return;
	ll ret = 0;
	for (int i = 1; i <= top; i++) {
//		if(x == 1)cout << (1 - num[top] + mod) % mod * 64 % mod << endl;
		ret = (ret + tmp * fp(num[i], mod-2) % mod * ((1 - num[i] + mod) % mod) % mod) % mod;
	}
	ret = (ret + tmp) % mod;
//	if (x == 1) cout << ret * 64 % mod<< endl;
	ans = (ans + d2 * ((1 - ret + mod) % mod) % mod) % mod;
}

