    rep(i,check.size()){
      check[i]=false;
      dist[i]=-1;
    }
  }

  int dfs(int v, int p){
    int tmp=1;
    vec ts;

    for(auto next_v : graphs[v]){
      if(p==next_v) continue;
      int t = dfs(next_v, v);
      tmp += t;
      ts.push_back(t);
    }

    if(p!=-1){
      ts.push_back(graphs.size()-tmp);
    }
    mint now = mint(2).pow(graphs.size()-1)-1;
    for(auto t:ts){
      now -= mint(2).pow(t)-1;
    }
    ans += now;
    return tmp;
  }

  void bfs(int v){
    dist[v] = 0;
    q.push(v);

    while(!q.empty()){
      int cur_v = q.front();
      q.pop();

      for(int next_v : graphs[cur_v]){
        if(dist[next_v] != -1){
          continue;
        }

        dist[next_v] = dist[cur_v] + 1;
        q.push(next_v);
      }
    }
  }

};

