    final[v] = vec;
    for(ll i=0;i<G[v].size();i++){
        ll nv = G[v][i];
        if(nv == p)continue;
        dfs_prop(nv, v);
    }
    return;
}

ll dfs_size(ll v, ll p){
    ll cnt = 1;
    vector<ll> vec;
    for(ll i=0;i<G[v].size();i++){
        ll nv = G[v][i];
        if(nv == p)continue;
        ll a = dfs_size(nv, v);
        cnt += a;
        vec.pb(a);
    }
    size[v] = cnt;
    first[v] = vec;
    return cnt;
}

vector<ll> dfs(ll v, ll p){
    vector<ll> vec;
    ll cnt = 1;
    for(ll i=0;i<G[v].size();i++){
        ll nv = G[v][i];
        if(nv == p)continue;
        ll a = dfs_size(nv, v);
        cnt += a;
        vec.pb(a);
    }
    size[v] = cnt;
    return vec;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> n;
    for(ll i=0;i<n-1;i++){
        cin >> a >> b;
        G[a].pb(b);
        G[b].pb(a);
    }
    first[1] = final[1] = dfs(1, -1);
    for(ll i=0;i<G[1].size();i++){
        ll nv = G[1][i];
        dfs_prop(nv, 1);
    }
    x[0] = 1;
    for(ll i=0;i<n;i++){
        x[i+1] = x[i] * 2;
        x[i+1] %= mod;
    }

    ll ans = 0;
    for(ll i=1;i<=n;i++){
        ll onewhite = 0;
        if(final[i].size() == 1){
            onewhite += x[final[i][0]];
        }else{
            onewhite ++;
            for(ll j=0;j<final[i].size();j++){
                onewhite += x[final[i][j]] - 1;
                onewhite %= mod;
            }
        }
        onewhite = mod - onewhite;
        onewhite += x[n-1];
        onewhite %= mod;
        ans += onewhite;
        ans %= mod;
    }
    ans *= rui(x[n], mod - 2);
    ans %= mod;
    p(ans);
    return 0;
}

