    for (auto child : children)
    {
        if (child.size() <= 1)
        {
            continue;
        }
        Mod<MOD> tmp = Mod<MOD>(1);
        tmp -= power(Mod<MOD>(1) / 2, (N - 1));
        for (auto c : child)
        {
            tmp -= Mod<MOD>(1) / power(Mod<MOD>(2), N - (c + 1)) * (Mod<MOD>(1) - power(Mod<MOD>(1) / 2, c));
        }
        ans += tmp / 2;
    }
    cout << ans << endl;
}

