class RerootingSum{
    vec2<int> edges;
    vec<vec<ll>> partials;  // partials[i]はiからEdge.to向きの部分木の部分解
    vec<set<int>> edgeMap;

    // upを上方として、downにNode情報をとる。
    ll fillFirst(int up, int down){
        if(edges.at(down).empty()){
            // 末尾
            partials.at(down) = vec<ll>(0); // TODO: 0除算はやばいかも。多分制約から大丈夫
            return 0;
        }

        vec<ll> res;
        for(auto iter: edges.at(down)){
            if(iter == up){
                continue;
            }



            res.push_back(fillFirst(down, iter));
        }

        // partials.at(down)にこの部分での結果を保存
        partials.at(down) = res;

        return accumulate(res.begin(), res.end(), 0) + 1;
    }

    // fillFirstだと子どもから親への部分木の情報がないのでそれを埋める
    void fillHoles(int up, int down){
        // downからupへの距離を追加する
        if(up != -1){
            // upでの(down向きを除いた)部分木たちの和をもとめる。
            auto res = partials.at(up);

            // resにはupからdownにいった分が余計に含まれているのでこれを削る。
            auto subRes = accumulate(partials.at(down).begin(), partials.at(down).end(), 0);

            auto resUp = accumulate(res.begin(), res.end(), 0) - subRes;


            // downのうちupむきの分がなかったのを足しこむ
            partials.at(down).push_back(resUp);
        }

        // 下に伝播
        for(auto iter: edges.at(down)){
            if(iter == up){
                continue;
            }
            fillHoles(down, iter);
        }
    }

    public:
    RerootingSum(vec2<int> edges){
        this->edges = edges;
        partials = vec<vec<ll>>(edges.size());
        fillFirst(-1, 0);
        fillHoles(-1, 0);
    }

    Zp<MOD> getResult(int pos){
        #ifdef DEBUG
        printf("*START: result\n");
        cout << pos << endl;
        for(auto iter: partials.at(pos)){
            cout << iter << ",";
        }
        cout << endl;
        printf("*END: result\n");
        #endif
        if(partials.at(pos).size() <= 1){
            return Zp<MOD>(0);
        }
        auto sum = accumulate(partials.at(pos).begin(), partials.at(pos).end(), 0);
        auto sum2 = Zp<MOD>(0);
        for(auto iter: partials.at(pos)){
            sum2 = sum2 + Zp<MOD>(2).pow(iter);
        }
        return Zp<MOD>(2).pow(sum) - (sum2 - Zp<MOD>(partials.at(pos).size()) + Zp<MOD>(1));
    }
};


void solve(long long N, std::vector<long long> A, std::vector<long long> B){
    for(int i=0; i < N-1; i++){
        A.at(i)--;
        B.at(i)--;
    }

    vec2<int> edges(N);
    for(int i=0; i < N-1; i++){
        edges.at(A.at(i)).push_back(B.at(i));
        edges.at(B.at(i)).push_back(A.at(i));
    }

    RerootingSum rs(edges);

    auto res = Zp<MOD>(0);
    for(int i=0; i < N; i++){
        res = res + rs.getResult(i);
    }
    #ifdef DEBUG
    printf("*START: numbers\n");
    cout << res.raw() << endl;
    printf("*END: numbers\n");
    #endif
    res = res / Zp<MOD>(2).pow(N);

    cout << res.raw() << endl;
}

