                            merged[i][min(NONE, OTHER)] += dp[u.to][j][d] * dp[v][i][NONE];
                            merged[i][min(ONE, OTHER)] += dp[u.to][j][d] * dp[v][i][ONE];
                            merged[i][min(OTHER, OTHER)] += dp[u.to][j][d] * dp[v][i][OTHER];
                        }
                        else {
                            merged[i + j][min(NONE + 1, OTHER)] += dp[u.to][j][d] * dp[v][i][NONE];
                            merged[i + j][min(ONE + 1, OTHER)] += dp[u.to][j][d] * dp[v][i][ONE];
                            merged[i + j][min(OTHER + 1, OTHER)] += dp[u.to][j][d] * dp[v][i][OTHER];
                        }
                    }
