int mod = 1e9 + 7;

struct mint {
    unsigned x;

    mint() : x(0) {}

    mint(signed sig) { x = sig < 0 ? sig % mod + mod : sig % mod; }

    mint(signed long long sig) { x = sig < 0 ? sig % mod + mod : sig % mod; }

    int get() const { return (int) x; }

    mint& operator+=(mint that) {
        if ((x += that.x) >= mod) x -= mod;
        return *this;
    }

    mint& operator-=(mint that) {
        if ((x += mod - that.x) >= mod) x -= mod;
        return *this;
    }

    mint& operator*=(mint that) {
        x = (unsigned long long) x * that.x % mod;
        return *this;
    }

    mint& operator/=(mint that) { return *this *= that.inverse(); }

    mint operator+(mint that) const { return mint(*this) += that; }

    mint operator-(mint that) const { return mint(*this) -= that; }

    mint operator*(mint that) const { return mint(*this) *= that; }

    mint operator/(mint that) const { return mint(*this) /= that; }

    mint inverse() const {
        long long a = x, b = mod, u = 1, v = 0;
        while (b) {
            long long t = a / b;
            a -= t * b;
            std::swap(a, b);
            u -= t * v;
            std::swap(u, v);
        }
        return mint(u);
    }

    bool operator==(mint that) const { return x == that.x; }

    bool operator!=(mint that) const { return x != that.x; }

    mint operator-() const {
        mint t;
        t.x = x == 0 ? 0 : mod - x;
        return t;
    }
};

class FSurroundedNodes {
public:
    static constexpr int kStressIterations = 0;

    static void generateTest(std::ostream& test) {
    }

    vector<vector<int>> G;
    vector<int> size;
    vector<mint> res;

    int dfs(int v, int p) {
        int s = 1;
        for (auto to : G[v]) {
            if (to == p) continue;
            s += dfs(to, v);
        }
        return size[v] = s;
    }

    void dfs2(int v, int p) {
        mint s = (mint) 1 / mint(2);

        // 全部白
        mint tmp = 1;
        int sum = 0;
        for (auto to : G[v]) {
            int sz = size[to];
            sum += sz;
            REP(i, sz) {
                tmp *= mint(1) / mint(2);
            }
        }

        // Sとなる部分木が1つ
        mint tmp2 = 0;
        for (auto to : G[v]) {
            int other = sum - size[to];
            // 他は全部白
            mint tmp3 = 1;
            REP(i, other) {
                tmp3 *= mint(1) / mint(2);
            }
            // toを含む部分木がS
            mint tmp4 = 1;
            REP(i, size[to]) {
                tmp4 *= mint(1) / mint(2);
            }
            tmp2 += tmp3 * ((mint) 1 - tmp4);
        }
        res[v] = s * ((mint) 1 - tmp - tmp2);

        int old = size[v];
        for (auto to : G[v]) {
            if (to == p) continue;
            size[v] = sum - size[to] + 1;
            dfs2(to, v);
            size[v] = old;
        }
    }

    void solve(std::istream& cin, std::ostream& cout) {
        int n;
        cin >> n;
        G.resize(n);
        size.resize(n);
        res.resize(n);
        REP(i, n - 1) {
            int a, b;
            cin >> a >> b;
            a--, b--;
            G[a].push_back(b);
            G[b].push_back(a);
        }

        dfs(0, -1);
        dfs2(0, -1);

        mint ans = 0;
        REP(i, n) ans += res[i];
        cout << ans.get() << endl;
    }
};


signed main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);
    std::istream& in(std::cin);
    std::ostream& out(std::cout);

    FSurroundedNodes solver;
    solver.solve(in, out);
    return 0;
}

