vector<ll> p(MAX,-1);
vector<int> g[MAX];

ll child(int u, int par) {
  for(auto k : g[u]) {
    if(k != par) {
      f[u] += child(k,u);
      p[k] = u;
    }
  }
  return f[u];
}

ll modinv(ll a, ll m) {
  ll b = m, u = 1, v = 0;
  while(b) {
      ll t = a / b;
      a -= t * b; swap(a, b);
      u -= t * v; swap(u, v);
  }
  u %= m;
  if(u < 0) u += m;
  return u;
}

ll Pow(ll x, ll n){
  if(n == 0) return 1;
  if(n % 2 == 0) return Pow(x*x % mod, n/2);
  else return x * Pow(x,n-1) % mod;
}

