  }
  child(0,-1);
  ll ans = 0;
  ll two = modinv((ll)2,mod);
  rep(i,n) {
    ll c = n-1;
    for(auto k : g[i]) {
      if(p[i] != k) {
        (dp[i] -= Pow(2,f[k])-f[k]-1) %= mod;
        c -= f[k];
      }
    }
    (dp[i] -= Pow(2,c)-c-1) % mod;
    (dp[i] += Pow(2,n-1) - n) %= mod;
    (ans += dp[i]) %= mod;
  }
  ans = modinv(Pow(2,n),mod)*ans % mod;
  cout << ans << endl;
