ll dfs(int node, int par) {
    parent[node] = par;
    ll ret = 0;
    for(int child: graph[node]) {
        if(child == par) continue;
        cnt_subtree_nodes[child] = dfs(child, node);
        ret += cnt_subtree_nodes[child];
    }
    return ret + 1;
}

ll modpow(ll a, ll t) {
    ll ret = 1LL;
    while(t){
        if(t & 1LL){
            ret *= a;
            ret %= MOD;
        }
        a *= a;
        a %= MOD;
        t >>= 1;
    }
    return ret;
}

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int n;
    cin >> n;
    int a, b;
    for(int i=0;i<n-1;++i) {
        cin >> a >> b;
        --a; --b;
        graph[a].push_back(b);
        graph[b].push_back(a);
    }
    cnt_subtree_nodes[0] = dfs(0, -1);

    vector<ll> all_white(N_MAX);
    for(int i=0;i<n;++i) {
        all_white[i] = modpow(2LL, cnt_subtree_nodes[i]);
    }

    ll ans = 0;
    for(int i=0;i<n;++i) {
        if(graph[i].size() <= 1) continue;
        ll tmp = (1 - modpow(modpow(2LL, n-1), MOD-2) + MOD) % MOD;
        for(int j: graph[i]) {
            if(j == parent[i]) {
                tmp = (tmp - ((modpow(2LL, n-cnt_subtree_nodes[i]) - 1) * modpow(modpow(2LL, n-1), MOD-2)) % MOD + MOD) % MOD;
                continue;
            }
            tmp = (tmp - ((all_white[j] - 1) * modpow(modpow(2LL, n-1), MOD-2)) % MOD + MOD) % MOD;
        }
        ans += tmp;
        ans %= MOD;
    }
    ans *= modpow(2LL, MOD-2);
    ans %= MOD;

    cout << ans << endl;
}

