ll pot(ll x, ll y) {
	if (y == 0) return 1;
	ll sol = pot(x, y/2);
	sol = mult(sol, sol);
	if (y%2) sol = mult(sol, x);
	return sol;
}

ll div_(ll x, ll y) {
	return mult(x, pot(y, MOD-2));
}

