	//cout <<"ovde\n";
	ll sol = 0;
	for (int i=1 ; i<=n ; i++) {
		if (deg[i] == 1) continue;
		ll ne = div_(1LL, pot(2LL, (ll)n-1));
		int br = 1;
		for (int j=0 ; j<v[i].size() ; j++) {
