vector<ll> bubunode[100010];
struct edge{ll to;};
struct graph{
    ll N;
    vector<vector<edge> > G;
    vector<bool> used;
    //vector<vector<ll>> bubunode;

    graph(ll n): N(n), G(N), used(N,false) {}

    void add_edge(ll s, ll t){
        G[s].emplace_back((edge){t});
        G[t].emplace_back((edge){s}); //無向ならON
    }

    ll dfs(ll v=0){
        used[v]=true;
        ll ct=1;
        for(auto E : G[v]){
            if(!used[E.to]){
                ll x=dfs(E.to);
                bubunode[v].emplace_back(x);
                ct+=x;
            }
        }
        ll y=N-ct;
        if(y>0) bubunode[v].emplace_back(y);
        return ct;
    }
};

