        for(auto& x: ve){
            ans2-=modpow(2,x)-1;
            ans2+=MOD;
            ans2%=MOD;
        }
        ans+=ans2;
        ans%=MOD;
    }
    ll gya=modpow(2,N);
    gya=modpow(gya);
    ans*=gya;
    ans%=MOD;
    cout<< ans <<"\n";
}

