#include <bits/stdc++.h>
using namespace std;
using Graph = vector<vector<int>>;

int64_t	modpow(int64_t a, int64_t n, const int64_t mod)
{
	int64_t	result = 1;
	while (n) {
		if (n & 1) result = result * a % mod;
		a = a * a % mod;
		n >>= 1;
	}
	return result;
}

int64_t	modinv(int64_t a, const int64_t mod)
{
	int64_t	b = mod;
	int64_t	u = 1, v = 0;
	while (b > 0) {
		int64_t	q = a / b;
		a -= q * b; swap(a, b);
		u -= q * v; swap(u, v);
	}
	if (u < 0)
		u += mod;
	return u;
}

int64_t modinvpow(int64_t a, int64_t n, const int64_t mod)
{
    return modinv(modpow(a, n, mod), mod);
}

int dfs(const Graph &graph, vector<int> &num_child, int u, int par)
{
    int num_child_u = 0;
    for (int v : graph.at(u)) {
        if (v == par) continue;
        num_child_u += dfs(graph, num_child, v, u) + 1;
    }
    num_child.at(u) = num_child_u;
    return num_child_u;
}

int64_t dfs2(int N, const Graph &graph, const vector<int> &num_child,
            int u, int par, const int64_t mod)
{
    int64_t ev = 0;
    int64_t prob;
    for (int v : graph.at(u)) {
        if (v == par) continue;
        ev = (ev + dfs2(N, graph, num_child, v, u, mod));
        int nc = num_child.at(v);
        int64_t p1 = modinvpow(2, nc + 1, mod);
        int64_t p2 = modinvpow(2, N - nc - 1, mod);
        prob = (1 - p1) * (1 - p2) % mod;
        ev = (ev + prob) % mod;
    }
    return ev;
}

int	main()
{
    const static int64_t mod = static_cast<int64_t>(1e+9) + 7;
    int N;
