    }
    vector<int> num_child(N, -1);
    dfs(graph, num_child, 0, -1);
    int64_t ev = - N * modinv(2, mod); // ev: expected value
    ev = (ev + dfs2(N, graph, num_child, 0, -1, mod)) % mod;
    ev = (ev + 1 - modinvpow(2, N, mod)) % mod;
    ev = (ev < 0) ? (ev + mod) : ev;
    cout << ev << endl;
}

