class solver{
    istream& is;
    ostream& os;

public:
    solver(istream& I, ostream& O) :is(I), os(O) {}
    int N;
    vector<vector<int>> E;
    vector<int> subn;

    bool input() {
        N = 0;
        is >> N;
        E.resize(N);
        for (int i = 0; i < N - 1; ++i) {
            int a, b;
            is >> a >> b; a--; b--;
            E[a].push_back(b);
            E[b].push_back(a);
        } // end i
        return !!is;
    }

    int calc_sub(int v, int p = -1){
        subn[v] = 1;
        for (auto &&u : E[v]) {
            if(u == p) continue;
            subn[v] += calc_sub(u, v);
        } // end i
        return subn[v];
    }

    decltype(VEC(N, 2, 2, 0_mod)) dp;

    RCR calc(int v, int p, int myc, int pc){
        if(!dp[v][myc][pc].is_nil()) return dp[v][myc][pc];

        dp[v][myc][pc] = 0_mod;
        // 自身が穴あき
        RCR all_p = (2_mod).inv().pow(subn[v]-1);
        if(myc == 0){
            dp[v][myc][pc] = 1_mod - all_p;
            if(pc == 0) {
                for (auto &&u : E[v]) {
                    if(u == p) continue;
                    RCR prob = (2_mod).inv().pow(subn[u]);
                    dp[v][myc][pc] -= all_p /prob * (1_mod-prob);
                } // end u
            }
        }
        for (auto &&u : E[v]) {
            if(u == p) continue;
            if(pc || myc) {
                dp[v][myc][pc] += calc(u, v, 0, 1) / 2_mod;
                dp[v][myc][pc] += calc(u, v, 1, 1) / 2_mod;
            }
            else {
                RCR prob = (2_mod).inv().pow(subn[u]);
                dp[v][myc][pc] += calc(u, v, 0, 0) / 2_mod
                        * all_p / prob;
                dp[v][myc][pc] += calc(u, v, 0, 1) / 2_mod
                        * (1_mod - all_p / prob);
                dp[v][myc][pc] += calc(u, v, 1, 0) / 2_mod
                                                     * all_p / prob;
                dp[v][myc][pc] += calc(u, v, 1, 1) / 2_mod
                                                     * (1_mod - all_p / prob);
            }
        } // end u
        return dp[v][myc][pc];
    }


    void run();
};

