    long long val;
    constexpr Fp(long long v = 0) noexcept : val(v % MOD) {
        if (val < 0) val += MOD;
    }
    constexpr int getmod() { return MOD; }
    constexpr Fp operator - () const noexcept {
        return val ? MOD - val : 0;
    }
    constexpr Fp operator + (const Fp& r) const noexcept { return Fp(*this) += r; }
    constexpr Fp operator - (const Fp& r) const noexcept { return Fp(*this) -= r; }
    constexpr Fp operator * (const Fp& r) const noexcept { return Fp(*this) *= r; }
    constexpr Fp operator / (const Fp& r) const noexcept { return Fp(*this) /= r; }
    constexpr Fp& operator += (const Fp& r) noexcept {
        val += r.val;
        if (val >= MOD) val -= MOD;
        return *this;
    }
    constexpr Fp& operator -= (const Fp& r) noexcept {
        val -= r.val;
        if (val < 0) val += MOD;
        return *this;
    }
    constexpr Fp& operator *= (const Fp& r) noexcept {
        val = val * r.val % MOD;
        return *this;
    }
    constexpr Fp& operator /= (const Fp& r) noexcept {
        long long a = r.val, b = MOD, u = 1, v = 0;
        while (b) {
            long long t = a / b;
            a -= t * b; swap(a, b);
            u -= t * v; swap(u, v);
        }
        val = val * u % MOD;
        if (val < 0) val += MOD;
        return *this;
    }
    constexpr bool operator == (const Fp& r) const noexcept {
        return this->val == r.val;
    }
    constexpr bool operator != (const Fp& r) const noexcept {
        return this->val != r.val;
    }
    friend constexpr ostream& operator << (ostream &os, const Fp<MOD>& x) noexcept {
        return os << x.val;
    }
    friend constexpr istream& operator >> (istream &is, Fp<MOD>& x) noexcept {
        return is >> x.val;
    }
    friend constexpr Fp<MOD> modpow(const Fp<MOD> &a, long long n) noexcept {
        if (n == 0) return 1;
        auto t = modpow(a, n / 2);
        t = t * t;
        if (n & 1) t = t * a;
        return t;
    }
};
const int MOD = 1000000007;
using mint = Fp<MOD>;

int n;
vector<int> g[200200];

vector<vector<int>> dp;

int dfs(int v, int p = -1) {
    int s = (int)g[v].size();
    int res = 0;
    dp[v].assign(s, 0);
    rep(i, s) {
        int to = g[v][i];
        if(to == p) continue;
        dp[v][i] = dfs(to, v);
        res += dp[v][i] + 1;
    }
    return res;
}

void ddfs(int v, int pval = 0, int p = -1) {
    int s = (int)g[v].size();
    rep(i, s) {
        int to = g[v][i];
        if(to == p) {
            dp[v][i] = pval;
            continue;
        }
    }
    vector<int> left(s + 1, 0), right(s + 1, 0);
    rep(i, s) {
        left[i + 1] = left[i] + dp[v][i];
        right[i + 1] = right[i] + dp[v][s - 1 - i];
    }
    rep(i, s) {
        int to = g[v][i];
        if(to == p) continue;
        ddfs(to, left[i] + right[s - 1 - i], v);
    }
}

void solve() {
	cin >> n;
    dp.assign(n, vector<int>());
    rep(i, n - 1) {
        int a, b; cin >> a >> b; --a; --b;
        g[a].pb(b);
        g[b].pb(a);
    }
    dfs(0);
    ddfs(0);
    mint res = 0;
    rep(i, n) {
        res += (mint)1;
        int s = (int)g[i].size();
        rep(j, s) {
            res += modpow((mint)2, dp[i][j] + 1);
        }
    }
    res = (mint)n * modpow((mint)2, n) - res;
    cout << res / modpow((mint)2, n) << endl;
}

