signed main() {
	INIT;

	VAR(int, n);
	VEC_ROW(int, n - 1, a, b);
	std::vector<std::vector<int>> g(n);
	REP(i, n - 1) {
		--a[i]; --b[i];
		g[a[i]].emplace_back(b[i]);
		g[b[i]].emplace_back(a[i]);
	}

	V<int> sz(n, 0);
	{
		auto rec = [&](auto && f, int v, int par) -> void {
			sz[v] = 1;
			for (auto&& to : g[v]) if (to != par) {
				f(f, to, v);
				sz[v] += sz[to];
			}
		};
		rec(rec, 0, -1);
	}

	ModInt x2 = 1;
	x2 /= 2;

	ModInt ans = 0;
	REP(i, n) {
		V<int> c;
		bool root = true;
		for (auto& to : g[i]) {
			if (sz[i] < sz[to]) {
				root = false;
				continue;
			}
			c.emplace_back(sz[to]);
		}
		if (!root) c.emplace_back(n - sz[i]);

		if (c.size() >= 2) {
			int sum = 0, sum2 = n - 1;
			REP(i, c.size() - 1) {
				sum2 -= c[i];
				ModInt x = x2;
				x *= x2 ^ sum;
				x *= -(x2 ^ c[i]) + 1;
				x *= -(x2 ^ sum2) + 1;
				ans += x;
				sum += c[i];
			}
		}
	}

	OUT(ans)BR;

	return 0;
}

