template<typename T>
Matrix<T> Pow(Matrix<T> matrix, ll x) {
    Matrix<T> res = vector<vector<T>>(matrix.size(), vector<T>(matrix.size(), 0));
    for (int i = 0; i < (int)matrix.size(); i++) {
        res[i][i] = 1;
    }
    while (x) {
        if (x & 1) {
            res = res * matrix;
        }
        matrix = matrix * matrix;
        x >>= 1;
    }
    return res;
}


