class Mint {
    using u64 = std::uint_fast64_t;
    u64 Modulus = MOD;

public:
    u64 a;

    constexpr Mint(const u64 x = 0) noexcept : a(x % Modulus) {}

    constexpr u64 &value() noexcept { return a; }

    constexpr const u64 &value() const noexcept { return a; }

    constexpr Mint operator+(const Mint rhs) const noexcept {
        return Mint(*this) += rhs;
    }

    constexpr Mint operator-(const Mint rhs) const noexcept {
        return Mint(*this) -= rhs;
    }

    constexpr Mint operator*(const Mint rhs) const noexcept {
        return Mint(*this) *= rhs;
    }

    constexpr Mint operator/(const Mint rhs) const noexcept {
        return Mint(*this) /= rhs;
    }

    constexpr Mint &operator+=(const Mint rhs) noexcept {
        a += rhs.a;
        if (a >= Modulus) {
            a -= Modulus;
        }
        return *this;
    }

    constexpr Mint &operator-=(const Mint rhs) noexcept {
        if (a < rhs.a) {
            a += Modulus;
        }
        a -= rhs.a;
        return *this;
    }

    constexpr Mint &operator*=(const Mint rhs) noexcept {
        a = a * rhs.a % Modulus;
        return *this;
    }

    constexpr Mint &operator/=(Mint rhs) noexcept {
        u64 exp = Modulus - 2;
        while (exp) {
            if (exp % 2) {
                *this *= rhs;
            }
            rhs *= rhs;
            exp /= 2;
        }
        return *this;
    }

    constexpr Mint &pow(int rhs) noexcept {
        u64 exp = static_cast<u64>(rhs);
        Mint base(a);
        a = 1;
        while (exp) {
            if (exp % 2) {
                *this *= base;
            }
            base *= base;
            exp /= 2;
        }
        return *this;
    }

};

class Solve {
public:
    Int N;
    vector<vector<Int>> tree;
    vector<vector<Int>> dp;

    Int dfs1(Int v = 0, Int p = -1) {
        if (tree[v].size() == 1 && p != -1) {
            dp[v].push_back(N - 1);
            return 1;
        }

        Int ret = 1;
        for (auto e : tree[v]) {
            if (e != p) {
                Int tmp = dfs1(e, v);
                dp[v].push_back(tmp);
                ret += tmp;
            }
        }
        if (p != -1)
            dp[v].push_back(N - ret);
        return ret;
    }

    // vの期待値
    Mint calc(Int v) {
        Mint Pro = 1;
        for (auto e : dp[v]) {
            Pro *= Mint(1) / Mint(2).pow(e);
        }


        Mint x1 = 0;
        for (auto e : dp[v]) {
            Mint tmp = Pro * (Mint(2).pow(e)) * (Mint(1) - Mint(1) / Mint(2).pow(e));
            x1 += tmp;
        }

        Mint ret = Mint(1) - Pro - x1;
        return ret;
    }

    void solve() {
        cin >> N;
        tree.resize(N);
        dp.resize(N);

        for (int i = 1; i < N; ++i) {
            int a, b;
            cin >> a >> b;
            a--, b--;
            tree[a].push_back(b);
            tree[b].push_back(a);
        }

        dfs1(0);

//        for (auto e : dp) {
//            for (auto f : e) {
//                cout << f << " ";
//            }
//            cout << endl;
//        }

        Mint ans = 0;
        for (int i = 0; i < N; ++i) {
            ans += calc(i);
        }
        ans /= 2;

        cout << ans.value() << endl;

    }
};


int main() {
