ll dfs(int idx, int par){
    ll psum = 1;
    for(auto &to: G[idx]){
        if(to == par) continue;

        psum += dfs(to, idx);
    }
    sum += (modpow(2,psum, MOD) - 1 + MOD) % MOD * ((modpow(2, N - psum, MOD) - 1 + MOD) % MOD);
    sum %= MOD;
    cerr << idx << " " << psum << " " <<  sum << endl;
    return psum;
}

