using namespace std;

struct E {
	int a;
	int b;
	int ra;
	int rb;
};

struct N {
	int r;
	vector<E*> es;
	E* pe = nullptr;
};

void assign_rank(vector<N>& ns, int n)
{
	vector<bool> is_visit(n + 1);

	stack<int> s;
	s.push(1);

	while (!s.empty()) {
		int ci = s.top();
		auto& cn = ns[ci];
		if (is_visit[ci]) {
			cn.r++;
			if (cn.pe != nullptr) {
				auto e = cn.pe;
				if (ci == e->a) {
					e->ra = cn.r;
					e->rb = n - cn.r;
					ns[e->b].r += cn.r;
				}
				else {
					e->rb = cn.r;
					e->ra = n - cn.r;
					ns[e->a].r += cn.r;
				}
			}
			s.pop();
			continue;
		}

		is_visit[ci] = true;
		for (auto e : cn.es) {
			int ni = (e->a == ci) ? e->b : e->a;
			if (!is_visit[ni]) {
				ns[ni].pe = e;
				s.push(ni);
			}
		}
	}
}

int64_t pow_rem(int64_t x, int64_t m, int64_t rem)
{
	if (m == 0) {
		return 1;
	}
	if (m == 1) {
		return x;
	}

	if (m & 1) {
		int64_t val = pow_rem(x, m / 2, rem);
		val = val * val;
		val %= rem;
		val *= x;
		val %= rem;
		return val;
	}
	else {
		int64_t val = pow_rem(x, m / 2, rem);
		val = val * val;
		val %= rem;
		return val;
	}
}

int64_t pow_remdiv(int64_t val, int64_t rem)
{
	return pow_rem(val, rem - 2, rem);
}


int64_t divide_rem(int64_t divident, int64_t dividor, int64_t rem)
{
	int64_t ret = pow_remdiv(dividor, rem);
	ret *= divident;
	ret %= rem;

	return ret;
}

static const int64_t kRem = 1000000007;

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
	cout << fixed << setprecision(20);

	int n; cin >> n;

	vector<N> ns(n + 1);
	vector<E> es(n - 1);

	FOR_LT(i, 0, n - 1) {
		int a, b; cin >> a >> b;
		es[i].a = a;
		es[i].b = b;

		ns[a].es.push_back(&es[i]);
		ns[b].es.push_back(&es[i]);
	}

	assign_rank(ns, n);

	int64_t x = 0;
	FOR_LE(i, 1, n) {
		if (ns[i].es.size() == 1) continue;

		int64_t ci = 1;
		int64_t ri = 0;
		for (auto e : ns[i].es) {
			int64_t r  = (e->a == i) ? e->rb : e->ra;
			int64_t cr = pow_rem(2, r, kRem);
			ci *= cr;
			ci %= kRem;
			ri += cr - 1;
			ri %= kRem;
		}
		x += (ci - ri - 1);
		x %= kRem;
		while (x < 0) x += kRem;
	}

	int64_t y = pow_rem(2, n, kRem);

	int64_t z = divide_rem(x, y, kRem);

	cout << z << endl;

	return 0;
}

