        pows[i+1] = pows[i] * 2LL;
        pows[i+1] %= MOD;
    }

    ll ans = 0;

    srep (v, 1, n+1) {
        ll cnt = pows[n-1];
        ll decr = pows[n-cnts[v]] - 1LL;
        if (decr < 0) decr += MOD;
        for (auto cv : children[v]) {
            decr += (pows[cnts[cv]] - 1LL);
            if (decr < 0) decr += MOD;
            decr %= MOD;
        }
        decr++;
        decr %= MOD;
        debug_printf("v=%lld cnt=%lld decr=%lld\n", v, cnt, decr);
        cnt -= decr;
        if (cnt < 0) cnt += MOD;
        ans += cnt;
        ans %= MOD;
    }

    ans *= mod_inv(pows[n], MOD);
    ans %= MOD;

    debug_printf("---- ans\n");
    cout << ans << endl;
}

