ModuloOps MOD(1e9+7);

long long calc(vector<int> &a) {
    auto all = 1ll;
    for (auto sz: a) {
        all = MOD.mul(all, MOD.div(1, MOD.binPow(2, sz)));
    }
    auto bad = all;
    for (auto sz: a) {
        auto pw = MOD.binPow(2, sz);
        MOD.inc(bad, MOD.mul(MOD.mul(all, pw), MOD.sub(1, MOD.inv(pw))));
    }
    auto res = MOD.div(MOD.sub(1, bad), 2);
    return res;
}

