            if(n_child > num_children[i]){
                n_child = n - num_children[i]; // parent node
            }
            p *= ModInt(1) / ModInt(2).pow(n_child);
        }
        ModInt p2(0);
        for(LL child: edge[i]){
            LL n_child = num_children[child];
            if(n_child > num_children[i]){
                n_child = n - num_children[i]; // parent node
            }
            p2 += p * ModInt(2).pow(n_child) * (ModInt(1) - ModInt(1) / ModInt(2).pow(n_child));
        }
        exp += ModInt(1) / ModInt(2) * (ModInt(1) - p - p2);
    }
    cout << exp << endl;
    return 0;
}

