    if (a >= mod)
        a -= mod;
    return a;
}

int sub(int a, int b, int mod = kmod)
{
    a -= b;
    if (a < 0)
        a += mod;
    return a;
}

int power(int base, int index, int mod = kmod)
{
    if (index == 0)
        return 1;
    int temp = power(base, index / 2, mod);
    temp = mul(temp, temp, mod);
    if (index & 1)
        temp = mul(temp, base, mod);
    return temp;
}

int mod_inv(int x, int mod = kmod)
{
    return power(x, kmod - 2);
}

void pre()
{
    Fact[0] = 1;
    for (int i = 1; i < _n; ++i)
        Fact[i] = mul(Fact[i - 1], i);
    Inv[_n - 1] = mod_inv(Fact[_n - 1]);
    for (int i = _n - 2; i >= 0; --i)
        Inv[i] = mul(Inv[i + 1], (1 + i));
}

int ncr(int n, int r)
{
    if (n < 0 || r < 0 || n - r < 0)
        return 0;
    return mul(Fact[n], mul(Inv[r], Inv[n - r]));
}

vector<int> treeSize, par;
vector<int> adj[NAX];

class Solution
{
private:
    int dfs(int node, int par)
    {
        ::par[node] = par;
        treeSize[node] = 1;
        for (auto &child : adj[node])
        {
            if (child == par)
                continue;
            treeSize[node] += dfs(child, node);
        }
        return treeSize[node];
    }

public:
    Solution() {}
    ~Solution() {}
    void solveCase()
    {
        int n;
        cin >> n;
        for (size_t i = 1; i < n; i++)
        {
            int u, v;
            cin >> u >> v;
            --u, --v;
            adj[u].pb(v);
            adj[v].pb(u);
        }
        treeSize.resize(n);
        par.resize(n);
        dfs(0, 0);
        int res = 0;
        vector<int> pow2(n + 1, 1);
        int inv2 = mod_inv(2);
        for (size_t i = 0; i < n; i++)
            pow2[i + 1] = mul(pow2[i], inv2);
        for (size_t i = 0; i < n; i++)
        {
            vector<int> v;
            db(i);
            for (auto &child : adj[i])
            {
                db(child, treeSize[child], par[i]);
                if (child == par[i])
                    v.pb(n - treeSize[i]);
                else
                    v.pb(treeSize[child]);
            }
            pc(v);
            int zero = pow2[n];
            int one = 0;
            for (auto &x : v)
                one = add(one, mul(pow2[n - x], sub(1, pow2[x])));
            res = add(res, sub(sub(sub(1, zero), one), inv2));
        }
        cout << res << '\n';
    }
};

