vector<lint> child_size(lint start,vector<vector<lint>>G){
	vector<lint>memo(G.size());
	auto f=[&](auto f,lint v,lint p)->lint{
		lint res=0;
		for(auto t:G[v]){
			if(t==p)continue;
			res+=f(f,t,v);
		}
		return memo[v]=res+1;
	};
	call(f,start,-1);
	return memo;
}

int main(){
	lint n;
	cin>>n;
	mat v(n);
	rep(i,n-1){
		lint s,t;
		cin>>s>>t;
		s--;t--;
		v[s].push_back(t);
		v[t].push_back(s);
	}
	auto ch=child_size(0,v);
	mint ans=0;
	auto f=[&](auto f,lint now,lint p)->void{
		mint mul=mint(2).pow(n-ch[now]);
		mint minus=mint(2).pow(n-ch[now])-1;
		for(auto to:v[now]){
			if(to==p)continue;
			f(f,to,now);
			mint tmp=mint(2).pow(ch[to]);
			mul*=tmp;
			minus+=tmp-1;
		}
		ans+=mul-minus-1;
	};
	call(f,0,-1);
	cout<<ans/mint(2).pow(n)<<endl;
}

