// 苦手分野 重複組み合わせ
// LLの数値をつかう時は最後にLLをつける癖をつけよう
// Mintの数値にしたいときは、Mint(i)みたいにキャストしてね

int n;
vector<int> v[200001];
vector<int> Tsize[200001];
int sum[200001];

int dfs(int now, int pre) {
  int res = 0;
  rep(i, 0, (int)v[now].size()) {
    int next = v[now][i];
    if (next == pre) continue;
    int tmp = dfs(next, now);
    Tsize[now].pb(tmp);
    res += tmp;
  }
  sum[now] = res;
  return res + 1;
}

