const lint MOD = 1000000007;
const lint INF = 0x3f3f3f3f3f3f3f3f;
const double PI = 3.14159265358979323846;
const double EPS = 1e-10;

// 累乗
// O(log n) 時間
long long mod_pow(long long a, long long n, long long m) {
    a %= m;
    if (a < 0) a += m;
    long long res = 1;
    while (n > 0) {
        if (n & 1) res = res * a % m;
        a = a * a % m;
        n >>= 1;
    }
    return res;
}

int N;
int A[200010], B[200010];
vector<int> G[200010];
int num[200010];
int pre[200010];

void dfs(int v, int pv) {
    pre[v] = pv;
    num[v] = 1;
    for (int nv : G[v]) if (nv != pv) {
        dfs(nv, v);
        num[v] += num[nv];
    }
}

void _main() {
    cin >> N;
    REP (i, N - 1) {
        cin >> A[i] >> B[i];
        A[i]--; B[i]--;
        G[A[i]].push_back(B[i]);
        G[B[i]].push_back(A[i]);
    }
    dfs(0, -1);
    int ans = 0;
    int inv2 = (MOD + 1) / 2;
    REP (v, N) if (G[v].size() > 1) {
        int sum = N - num[v];
        for (int nv : G[v]) if (nv != pre[v]) {
            sum += num[nv];
        }
        int sub = mod_pow(2, sum, MOD) + MOD - 1;
        for (int nv : G[v]) if (nv != pre[v]) {
            (sub += MOD - (mod_pow(2, num[nv], MOD) + MOD - 1) % MOD) %= MOD;
        }
        (sub += MOD - (mod_pow(2, N - num[v], MOD) + MOD - 1) % MOD) %= MOD;
        (ans += sub) %= MOD;
    }
    (ans *= mod_pow(inv2, N, MOD)) %= MOD;
    cout << ans << endl;
}

signed main(signed argc, char **argv) {
    if (argc > 1) {
        if (strchr(argv[1], 'i')) freopen("input.txt", "r", stdin);
        if (strchr(argv[1], 'o')) freopen("output.txt", "w", stdout);
    }
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout << fixed << setprecision(10);
    _main();
    return 0;
}

