class F {
    static const int MOD = 1'000'000'007;

    using mod = algebra::modular<MOD>;

    SimpleGraph graph;
    vector<int> sub;
    mod res = 0;
    vector<mod> P2;

    int dfs(int u, int p, int n) {
        int tot = 1;
        vector<int> aux;
        for (int ed: graph.outgoingEdges(u)) {
            int v = graph.endOfEdge(u, ed);
            if (v != p) {
                int x = dfs(v, u, n);
                aux.push_back(x);
                tot += x;
            }
        }
        aux.push_back(n - tot);
        if (aux.size() > 1) {
            mod now = 0;
            for (int x: aux) {
                now += P2[n - x].inv();
            }
            now -= P2[n].inv() * mod(aux.size() - 1);
            res += mod(2).inv() - now;
        }
        return sub[u] = tot;
    }

public:
    void solve(std::istream &in, std::ostream &out) {
        int n;
        in >> n;
        graph = SimpleGraph(n);
        P2.resize(n + 1);
        P2[0] = 1;
        for (int i = 1; i <= n; i++) {
            P2[i] = P2[i - 1] * mod(2);
        }
        sub.resize(n);
        for (int i = 1; i < n; i++) {
            int u, v;
            in >> u >> v;
            u--, v--;
            graph.addEdge(u, v);
            graph.addEdge(v, u);
        }
        dfs(0, -1, n);
        out << res << "\n";
    }

    void setup() {}
};


