long long COM(long long n, long long k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

long long r, q;
long long extGCD(long long a, long long b, long long &r, long long &q) {
    if (b == 0) {
        r = 1;
        q = 0;
        return a;
    }
    long long d = extGCD(b, a%b, q, r); // 再帰的に解く
    q -= a / b * r;
    return d;
}

