void findsub(long long u){
    sub[u] = 1;
    mark[u] = 1;
    for(auto v: adj[u]){
        if(!mark[v]){
            findsub(v);
            sub[u] += sub[v];
        }
    }
}

void findans(long long u){
    mark[u] = 0;
    long long p = (pwr(2, - n) + pwr(2, -1))% mod;
    for(auto v: adj[u]){
        if(mark[v]){
            long long soorat = (pwr(2, sub[v]) - 1 + mod) % mod;
            long long makhraj = pwr(2, - n);
            p += soorat * makhraj % mod;
            findans(v);
        }
        else{
            long long soorat = (pwr(2, n - sub[u]) - 1 + mod) % mod;
            long long makhraj = pwr(2, - n);
            p += soorat * makhraj % mod;
        }
        p %= mod;
    }
    ans += mod - p + 1;
    ans %= mod;
}

long long pwr(long long a, long long b){
    if(b < 0)
        return pwr(a, b + mod - 1);
    if(b == 0)
        return 1;
    long long c = pwr(a, b / 2);
    if(b % 2)
        return c * c % mod * a % mod;
    return c * c % mod;
}

void out(){
