    E_edges += (one - fast_pow(one / 2, x)) * (one - fast_pow(one / 2, N - x));
  }
}
int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  cin >> N;

  G.resize(N);
  size.resize(N, 1);

  for (int i = 0; i < N - 1; ++i) {
    int a, b;
    cin >> a >> b;
    --a, --b;
    G[a].push_back(b);
    G[b].push_back(a);
  }

  dfs(0, -1);
  dfs2(0, -1);

  modint E_nodes = E_edges + 1 - fast_pow(modint(1) / 2, N);
  modint ans = E_nodes - modint(N) / 2;
  cout << ans << endl;

  return 0;
}

#include <bits/stdc++.h>
using namespace std;
#define int long long
#define MOD 1000000007

int N;
vector<int> G[200100];
int memo[200100];
int ans = 0;

int mod_pow(int a, int n) {
    int res = 1;
    while (n>0) {
        if (n&1) res = res*a%MOD;
        a = a*a%MOD;
        n >>= 1;
    }
    return res;
}

int dfs(int v, int pv) {
    if (memo[v]!=-1) return memo[v];

    int res = 1;
    int add = mod_pow(2, N-1)-1;

    for (auto nv : G[v]) {
        if (nv==pv) continue;
        add -= mod_pow(2, dfs(nv, v))-1;
        res += dfs(nv, v);
    }

    add -= mod_pow(2, N-res)-1;
    ans += add;
    ans %= MOD;

    return memo[v] = res;
}

signed main() {
    cin >> N;

    for (int i=0; i<N-1; i++) {
        int ai, bi; cin >> ai >> bi;
        G[ai-1].push_back(bi-1);
        G[bi-1].push_back(ai-1);
    }

    for (int i=0; i<N; i++) memo[i] = -1;
    dfs(0, -1);

    ans *= mod_pow(mod_pow(2, N), MOD-2);
    ans %= MOD;

    cout << ans << endl;
}

