ll modpow(ll x, ll n, const ll mo) {
	ll res = 1;
	while (n > 0) {
		if (n & 1) (res *= x) %= mo;
		(x *= x) %= mo;
		n >>= 1;
	}
	return res;
}

ll inverse(ll x, const ll mo) {
	return modpow(x, mo - 2, mo);
}

