struct mint { // 出力するときだけ.xをつける
  int x;
  mint(int x=0):x((x%MOD+MOD)%MOD){}
  mint& operator+=(const mint a) {
    if ((x += a.x) >= MOD) x -= MOD;
    return *this;
  }
  mint& operator-=(const mint a) {
    if ((x += MOD-a.x) >= MOD) x -= MOD;
    return *this;
  }
  mint& operator*=(const mint a) {
    (x *= a.x) %= MOD;
    return *this;
  }
  mint operator+(const mint a) const {
    mint res(*this);
    return res+=a;
  }
  mint operator-(const mint a) const {
    mint res(*this);
    return res-=a;
  }
  mint operator*(const mint a) const {
    mint res(*this);
    return res*=a;
  }
  mint pow(int t) const {
    if (!t) return 1;
    mint a = pow(t>>1);
    a *= a;
    if (t&1) a *= *this;
    return a;
  }
  mint inv() const {
    return pow(MOD-2);
  }
  mint& operator/=(const mint a) {
    return (*this) *= a.inv();
  }
  mint operator/(const mint a) const {
    mint res(*this);
    return res/=a;
  }
};

struct TreeAna {

  VVi parII;
  VPii memot;
  Vi treeFI;

  TreeAna(int n) {
    par = Vi(n);
    dep = Vi(n);
    chi = VVi(n);
  }

  void set_parII(){
    int n = par.size();
    parII = VVi(n,Vi(20,-1));
    rep(i,0,n) parII[i][0] = par[i];
    rep(i,0,19){
      rep(j,0,n){
        if(parII[j][i] == -1) parII[j][i+1] = -1;
        else parII[j][i+1] = parII[parII[j][i]][i];
      }
    }
    return;
  }

  int lca(int u,int v) { // 頂点uと頂点vの共通の"先祖"で一番近いやつを返す
    if(dep[u] > dep[v]) swap(u,v);

    for(int i=19;i>=0;i--) {
      if(((dep[v]-dep[u])>>i)&1) v = parII[v][i];
    }
    if(u==v) return u;
    for(int i=19;i>=0;i--) {
      if(parII[u][i] != parII[v][i]){
        u = parII[u][i];
        v = parII[v][i];
      }
    }
    return parII[u][0];
  }

  void connect(int a,int b) {
    memot.pb(mp(a,b));
    memot.pb(mp(b,a));
    return;
  }

  void preset() {
    sort(ALL(memot));
    rep(i,0,memot.size()) treeFI.pb(memot[i].FI);
    return;
  }

  void make(int root) {
    int st,en,now;
    int n = par.size();
    par = Vi(n,-2);
    dep = par;
    chi = VVi(n,Vi(0));
    par[root] = -1;
    dep[root] = 0;
    queue<int> next;
    next.push(root);
    while(!next.empty()){
      now = next.front();
      next.pop();
      st = lower_bound(ALL(treeFI), now)-treeFI.begin();
      en = upper_bound(ALL(treeFI), now)-treeFI.begin();
      rep(i,st,en){
        if(par[memot[i].SE]!=-2) continue;
        next.push(memot[i].SE);
        chi[now].pb(memot[i].SE);
        par[memot[i].SE] = now;
        dep[memot[i].SE] = dep[now]+1;
      }
    }
  }

  void makechisize() {
    int n = par.size();
    chisize = Vi(n,0);
    Vi chinasi(0);
    rep(i,0,n) if(chi[i].size()==0) chinasi.pb(i);

    VVi dev(n+5);
    rep(i,0,n) {
      dev[dep[i]].pb(i);
    }
    repreq(i,n+3,0){
      rep(j,0,dev[i].size()){
        if(par[dev[i][j]]==-1) continue;
        chisize[par[dev[i][j]]] += chisize[dev[i][j]]+1;
      }
    }
    return;
  }

  void makelongest() {
    int n = par.size();
    longest = Vi(n,-1);
    Vi chinasi(0);
    rep(i,0,n) {if(chi[i].size()==0) chinasi.pb(i);}
    rep(i,0,chinasi.size()){
      int now = chinasi[i];
      int ct = 0;
      while(1) {
        if(longest[now] >= ct) break;
        else {
          longest[now] = ct;
          ct++;
          if(par[now] == -1) break;
          now = par[now];
        }
      }
    }
    return;
  }

  /* 使い方 */
  /*
  TreeAna tree(n) // 宣言 nは頂点数
  tree.connect(a,b) // 頂点aとbをつなぐ(0-index)
  tree.preset() // 頂点をつなぎ終わったら必ずこれをする！！！！！！！
  tree.make(k) // 頂点kを根としてpar,dep,chiを作り上げる
  tree.makechisize(); // 頂点が持つ子の総数の配列 Vi chisize を作り上げる
  tree.makelongest(); // 頂点から何回下にいけるかのヤツ(Vi longest)を作り上げる
  tree.set_parII() // lcaを使う前に必ずこれをする！！！！！！！
  tree.lca(a,b) // 頂点aとbの共通の"先祖"で一番近い"頂点"を返す
  */

};


