using namespace std;


ll mpow(ll x, ll n) { //x^n(mod M)
    ll ans = 1;
    while (n != 0) {
        if (n & 1) ans = ans * x % MOD;
        x = x * x % MOD;
        n = n >> 1;
    }
    return ans;
}

ll minv(ll x) {
    return mpow(x, MOD - 2);
}

int n;
vector<vector<int> > g;
ll ans;

int dfs(int par, int curr)
{
    int siz=(int)g[curr].size();
    int sum=0;
    vector<int> z;
    int i;
    for(i=0; i<siz; i++) {
        int next=g[curr][i];
        if(par==next) continue;
        int ret=dfs(curr, next);
        z.push_back(ret);
        sum+=ret;
    }
    z.push_back(n-1-sum);
    ll ans0=0;
    for(i=0; i<(int)z.size(); i++) {
        ll tmp0=mpow(2,z[i]);
        tmp0=(tmp0-1+MOD)%MOD;
        ans0=(ans0+tmp0)%MOD;
    }
    ans0=(mpow(2,n-1)-ans0-1+MOD)%MOD;
    ans=(ans+ans0)%MOD;

    sum++;
    return sum;
}

void solve()
{
    scanf("%d", &n);
    g.resize(n);
    int i;
    for (i = 0; i < n - 1; i++) {
        int a,b;
        scanf("%d%d", &a, &b); a--; b--;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    ans=0;
    int ret=dfs(-1,0);
    assert(ret==n);
    ans=ans*minv(mpow(2,n))%MOD;
    printf("%lld\n", ans);

	return;
}


