#include <stdio.h>

const int Mod = 1000000007;

typedef struct List {
	struct List *next;
	long long v, l, r;
} list;

long long div_mod(long long x, long long y, long long z)
{
	if (x % y == 0) return x / y;
	else return (div_mod((1 + x / y) * y - x, (z % y), y) * z + x) / y;
}

int main()
{
	int i, N, u, w;
	list *adj[200001] = {}, e[400001], *p;
	scanf("%d", &N);
	for (i = 0; i < N - 1; i++) {
		scanf("%d %d", &u, &w);
		e[i*2].v = w;
		e[i*2+1].v = u;
		e[i*2].next = adj[u];
		e[i*2+1].next = adj[w];
		adj[u] = &(e[i*2]);
		adj[w] = &(e[i*2+1]);
	}

	long long ans = 0, tmp, pow[200001];
	for (i = 1, pow[0] = 1; i <= N; i++) pow[i] = pow[i-1] * 2 % Mod;

	int flag[200001] = {}, q[200001], head, tail;
	flag[1] = -1;
	q[0] = 1;
	for (head = 0, tail = 1; head < tail; head++) {
		u = q[head];
		for (p = adj[u]; p != NULL; p = p->next) {
			w = p->v;
			if (flag[w] == 0) {
				flag[w] = -1;
				q[tail++] = w;
			}
		}
	}
	for (head--; head >= 0; head--) {
		u = q[head];
		flag[u] = 1;
		tmp = pow[N-1] - 1;
		for (p = adj[u]; p != NULL; p = p->next) {
			w = p->v;
			if (flag[w] != -1) {
				flag[u] += flag[w];
				tmp += Mod - pow[flag[w]] + 1;
			}
		}
		tmp += Mod - pow[N-flag[u]] + 1;
		ans += tmp;
	}

	printf("%lld\n", div_mod(ans % Mod, pow[N], Mod));
	fflush(stdout);
	return 0;
}

