    ans = (ans * inv_power2[vs])%DIVISOR;

    uint64_t blacks = (vs-2);
    blacks = (blacks * inv_power2[1])%DIVISOR;
    ans = (ans + DIVISOR - blacks)%DIVISOR;

    // ans must be less than DIVISOR < INT_MAX
    printf("%d\n", (int)ans);

    return 0;
}

