import java.io.InputStreamReader
import java.io.PrintWriter
import java.math.BigInteger
import java.util.*

/**
 * @author: pashka
 */

var res = 0
var pow2 = IntArray(0)

fun dfs(g: List<MutableList<Int>>, x: Int, p: Int) : Int {
    val n = g.size
    res += pow2[n - 1]
    res %= MOD
    var size = 1
    var num = 0
    for (y in g[x]) {
        if (y == p) continue
        var s = dfs(g, y, x)
        res -= pow2[s]
        res %= MOD
        size += s
        num++
    }
    if (p != -1) {
        var s = n - size
        res -= pow2[s]
        res %= MOD
        num++
    }
    res += num - 1
    res %= MOD
    return size
}

private val MOD = 1000000007

private fun solve() {
    var n = nextInt()
    var g = List<MutableList<Int>>(n) {i -> ArrayList()}
    for (i in 0 until n - 1) {
        var a = nextInt() - 1
        var b = nextInt() - 1
        g[a].add(b)
        g[b].add(a)
    }

    pow2 = IntArray(n + 1)
    pow2[0] = 1
    for (i in 1..n) {
        pow2[i] = (pow2[i - 1] * 2) % MOD
    }

    dfs(g, 0, -1)
    var d = BigInteger.valueOf(pow2[n].toLong()).modInverse(
            BigInteger.valueOf(MOD.toLong())
    ).toLong()

    res = ((res * d) % MOD).toInt()
    if (res < 0) res += MOD

    println(res)
}

fun main(args: Array<String>) {
    solve()
    out.close()
}

