public class Main {

  private static void solve() {
    int n = ni();
    int[] from = new int[n - 1];
    int[] to = new int[n - 1];

    for (int i = 0; i < n - 1; i++) {
      from[i] = ni() - 1;
      to[i] = ni() - 1;
    }
    int[][] g = packU(n, from, to);
    int[][] dp = new int[n][];

    dfs(0, -1, dp, g);
    dfs2(0, -1, 0, dp, g);

    int mod = (int) 1e9 + 7;

    long ret = 0;
    for (int i = 0; i < n; i++) {
      long x = pow(2, n - 1, mod);
      for (int v : dp[i]) {
        x += mod - (pow(2, v, mod) - 1);
        x %= mod;
      }
      x += mod - 1;
      x %= mod;

      ret += x;
      ret %= mod;
    }

    long y = pow(2, n, mod);
    ret = ret * invl(y, mod) % mod;
    System.out.println(ret);

  }

  public static long pow(long a, long n, long mod) {
    // a %= mod;
    long ret = 1;
    int x = 63 - Long.numberOfLeadingZeros(n);
    for (; x >= 0; x--) {
      ret = ret * ret % mod;
      if (n << 63 - x < 0)
        ret = ret * a % mod;
    }
    return ret;
  }

  public static long invl(long a, long mod) {
    long b = mod;
    long p = 1, q = 0;
    while (b > 0) {
      long c = a / b;
      long d;
      d = a;
      a = b;
      b = d % b;
      d = p;
      p = q;
      q = d - c * q;
    }
    return p < 0 ? p + mod : p;
  }


  private static void dfs2(int n, int pre, int par, int[][] dp, int[][] g) {
    int sum = 0;
    int m = g[n].length;
    for (int i = 0; i < m; i++) {
      if (g[n][i] == pre) {
        dp[n][i] = par + 1;
      }
      sum += dp[n][i];
    }
    for (int i = 0; i < m; i++) {
      int v = g[n][i];
      if (v == pre) {
        continue;
      }
      dfs2(v, n, sum - dp[n][i], dp, g);
    }
  }

  private static int dfs(int n, int pre, int[][] dp, int[][] g) {
    int m = g[n].length;
    dp[n] = new int[m];

    int ret = 1;
    for (int i = 0; i < m; i++) {
      int v = g[n][i];
      if (v == pre) {
        continue;
      }

      dp[n][i] = dfs(v, n, dp, g);
      ret += dp[n][i];
    }
    return ret;
  }



  static int[][] packU(int n, int[] from, int[] to) {
    int[][] g = new int[n][];
    int[] p = new int[n];
    for (int f : from)
      p[f]++;
    for (int t : to)
      p[t]++;
    for (int i = 0; i < n; i++)
      g[i] = new int[p[i]];
    for (int i = 0; i < from.length; i++) {
      g[from[i]][--p[from[i]]] = to[i];
      g[to[i]][--p[to[i]]] = from[i];
    }
    return g;
  }

