import java.io.*;
import java.util.*;

class Solver {
  final int n;
  final int[][] abs;

  ModCalculator mc;
  List<List<Integer>> graph;
  int[] sizes;

  Solver(int n, int[][] abs) {
    this.n = n;
    this.abs = abs;
  }

  private int calculateSize(int index, int parentIndex) {
    sizes[index] = 1;
    for (int childIndex : graph.get(index)) {
      if (childIndex == parentIndex) {
        continue;
      }
      sizes[index] += calculateSize(childIndex, index);
    }
    return sizes[index];
  }

  public long solve() {
    graph = new ArrayList<>();
    for (int i = 0; i <= n; i++) {
      graph.add(new ArrayList<>());
    }
    for (int[] ab : abs) {
      int a = ab[0];
      int b = ab[1];
      graph.get(a).add(b);
      graph.get(b).add(a);
    }

    sizes = new int[n + 1];
    calculateSize(1, 0);

    long count = 0;
    mc = new ModCalculator(1_000_000_007L);
    for (int i = 1; i <= n; i++) {
      long subCount = mc.pow(2, n - 1);
      subCount = mc.sub(subCount, 1);
      subCount = mc.sub(subCount, mc.sub(mc.pow(2, n - sizes[i]), 1));
      for (int childIndex : graph.get(i)) {
        if (sizes[childIndex] > sizes[i]) {
          continue;
        }
        subCount = mc.sub(subCount, mc.sub(mc.pow(2, sizes[childIndex]), 1));
      }
      count = mc.add(count, subCount);
    }
    return mc.div(count, mc.pow(2, n));
  }
}

