		}*/

		int[] mod2pow = new int[n+1];
		mod2pow[0]=1;
		for(int i=1; i<=n; i++){
		    mod2pow[i] = mod2pow[i-1]*2;
		    mod2pow[i] %= e97;
		}

		long ans_2n = 0;

		for(int i=0; i<n; i++){
		    if(e_on_each_dir.sizeOf(i)==1) continue;
		    ans_2n += mod2pow[n-1];
		    for(int a: e_on_each_dir.get(i)){
		        ans_2n -= mod2pow[a];
		        ans_2n %= e97;
		    }
		    ans_2n += (e_on_each_dir.sizeOf(i)-1);
		    ans_2n %= e97;
		}
		//out.println(ans_2n);

		long x1 = modinv(mod2pow[n],e97);
		x1 *= ans_2n;
		x1 %= e97;
		if(n==2) x1=0;
		out.println(x1);

		out.flush();
	}


