import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.NoSuchElementException;
import java.util.Objects;
import java.util.OptionalInt;
import java.util.PrimitiveIterator;
import java.util.function.IntBinaryOperator;
import java.util.function.IntFunction;
import java.util.function.IntPredicate;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;


public class Main {
    public static void main(String[] args) throws Exception {
        Field f = System.out.getClass().getDeclaredField("autoFlush");
        f.setAccessible(true);
        f.set(System.out, false);
        execute(System.in, System.out);
    }

    public static void execute(InputStream in, OutputStream out) {
        ExtendedScanner s = new ExtendedScanner(in);
        Out o = new Out(out);
        solve(s, o);
        o.flush();
        o.close();
    }

    public static void solve(ExtendedScanner sc, Out out) {
        int n = sc.nextInt();
        TreeBuilder tb = new TreeBuilder(n);
        for (int i = 0; i < n - 1; i++) {
            int u = sc.nextInt() - 1;
            int v = sc.nextInt() - 1;
            tb.addEdge(u, v);
        }
        Tree t = tb.build();
        int[] sub = Trees.subTreeSize(t);
        ModArithmetic ma = new ModArithmetic(TypicalMods.MOD1000000007);
        long[] pow = ma.powerMemo(n);
        long ans = 0;
        for (int i = 0; i < n; i++) {
            long s = 1;
            for (var it = t.getEdges(i).iterator(); it.hasNext();) {
                int v = it.nextInt();
                if (v == t.parent(i)) {
                    s += pow[n - sub[i]] - 1;
                } else {
                    s += pow[sub[v]] - 1;
                }
            }
            ans += ma.mod(pow[n - 1] - s);
        }
        out.writeln(ma.div(ans % ma.MOD, pow[n]));
    }
}


