	final long MOD = (long) 1e9 + 7;
	ArrayList<Integer>[] g;
	int N;
	int[] sz;
	long[] dp;
	long[] dp2;// 黒を含まない可能性

	long pow(long a, long n) {
		long ret = 1;
		for (; n > 0; n >>= 1, a = a * a % MOD) {
			if (n % 2 == 1) {
				ret = ret * a % MOD;
			}
		}
		return ret;
	}

	long inv(long a) {
		return pow(a, MOD - 2);
	}

	long expected_edges = 0;

	void dfs(int cur, int par) {
		sz[cur] = 1;
		for (int dst : g[cur]) {
			if (dst == par)
				continue;
			dfs(dst, cur);
			sz[cur] += sz[dst];
		}
		if (par != -1) {
			expected_edges += (1 - pow(inv(2), sz[cur])) * (1 - pow(inv(2), N - sz[cur])) % MOD;
			expected_edges %= MOD;
		}
	}

	void run() {
		Scanner sc = new Scanner(System.in);
		N = sc.nextInt();
