    class Pair {
        final int childCnt;
        final long res;

        public Pair(int childCnt, long res) {
            this.childCnt = childCnt;
            this.res = res;
        }
    }

    public void solve() {
        int N = in.nextInt();
        g = new ArrayList[N];
        for (int i = 0; i < N; i++) {
            g[i] = new ArrayList<>();
        }
        for (int i = 0; i < N - 1; i++) {
            int a = in.nextInt() - 1;
            int b = in.nextInt() - 1;
            g[a].add(b);
            g[b].add(a);
        }

        childCnt = new int[N];
        two = new long[N+1];
        two[0] = 1;
        for (int i = 0; i < N; i++) {
            two[i+1] = MULT(two[i], 2);
        }
        Pair pair = dfs(0, -1);
        System.out.println(DIV(pair.res, two[N]));
    }

    private Pair dfs(int u, int pre) {
        int N = g.length;
        long res = 0;
        long sub = 0;
        childCnt[u] = 1;
        int ch = 0;
        for (int v : g[u]) {
            if (v == pre) continue;

            ch++;
            Pair p = dfs(v, u);
            childCnt[u] += p.childCnt;
            sub = ADD(sub, SUB(two[p.childCnt], 1));
            res = ADD(res, p.res);
        }
        if ((ch == 1 && childCnt[u] != N) || ch >= 2) {
            sub = ADD(sub, SUB(two[N-childCnt[u]], 1));
            sub = ADD(sub, 1);
            res = ADD(res, SUB(two[N-1], sub));
        }

        return new Pair(childCnt[u], res);
    }


    /* MOD_CALCULATION */
    static int MOD = 1_000_000_007;
    static long ADD(long a, long b) {
        return (a + b) % MOD;
    }

    static long SUB(long a, long b) {
        return (a - b + MOD) % MOD;
    }

    static long MULT(long a, long b) {
        return ((a % MOD) * (b % MOD)) % MOD;
    }

    static long POW(long a, long x) {
        long res = 1;
        for ( ; x > 0; x >>= 1) {
            if (x % 2 == 1) res = MULT(res, a);
            a = MULT(a, a);
        }

        return res;
    }

    static long DIV(long a, long b) {
        return MULT(a, POW(b, MOD - 2));
    }
