public void solve() {
	int numNode = ni();
	int numEdge = numNode - 1;
	Edge edges[] = new Edge[numEdge];
	for(int i = 0; i < numEdge; i ++) {
		int a = ni() - 1;
		int b = ni() - 1;
		long c = 1;
		edges[i] = new Edge(a, b, c);
	}
	g = new Graph(numNode, numEdge, edges, false);
	weight = new int[numNode];
	fill(weight, 0);
	visited = new boolean[numNode];
	fill(visited, false);
	dfs(0);
	// errprtln(weight);
	long ans = 0;
	for(int i = 0; i < numNode; i ++) {
		long tmp = 1;
		tmp -= inv(pow_m(2, numNode - 1));
		for(Edge e : g.nodes[i].edges) {
			int w = weight[i] > weight[e.target] ? weight[e.target] : numNode - weight[i];
			long tmp2 = inv(pow_m(2, numNode - w - 1));
			tmp2 *= 1 - inv(pow_m(2, w));
			tmp2 = mod(tmp2);
			tmp -= tmp2;
		}
		tmp *= inv(2);
		tmp = mod(tmp);
		// errprtln(tmp);
		ans += tmp;
		ans = mod(ans);
	}
	prtln(ans);
}
Graph g;
int weight[];
boolean visited[];

void dfs(int x) {
	visited[x] = true;
	for(Edge e : g.nodes[x].edges) {
		if(!visited[e.target]) {
			dfs(e.target);
			weight[x] += weight[e.target];
		}
	}
	weight[x] ++;
}

