	public static void main(String[] args) throws Exception {
		FastScanner sc = new FastScanner();
		PrintWriter out = new PrintWriter(System.out);

		int n = sc.nexI();

		Graph0n tree = new Graph0n(n);

		int s1=0,g1=0;
		for(int i=1; i<n; i++){
		    s1=sc.nexI()-1;
		    g1=sc.nexI()-1;
		    tree.add(s1,g1);
		    tree.add(g1,s1);
		}

		Graph0n e_on_each_dir = new Graph0n(n);

		boolean[] is_known = new boolean[n];
		fill(is_known, false);

		int[] sum_former = new int[n];
		fill(sum_former,0);

		ArrayDeque<Integer> todo1 = new ArrayDeque<>();

		int next=-1;
		for(int i=0; i<n; i++){
		    if(tree.sizeOf(i)==1){
		        next=tree.get(i,0);
		        e_on_each_dir.add(i,n-1);
		        e_on_each_dir.add(next,1);
		        sum_former[next]++;
		        is_known[i] = true;
		        todo1.add(next);
		    }
		}   //O(n)

		while(todo1.size()>0){
		    int dw = todo1.poll();
		    if(is_known[dw]) continue;

		    next=-1;
		    for(int a : tree.get(dw)){
		        if(!is_known[a]){
		            if(next<0){
		                next=a;
		            }else{
		                next=INF;
		                break;
		            }
		        }
		    }
		    if(next<0){
		        is_known[dw]=true;
		    }else if(!isINF(next)){
    		    sum_former[dw]++;
    		    e_on_each_dir.add(dw, n-sum_former[dw]);
    		    e_on_each_dir.add(next,sum_former[dw]);
    		    sum_former[next] += sum_former[dw];
    		    is_known[dw]=true;
    		    todo1.add(next);
		    }
		}   //O(n+a)くらい？

		/*for(int i=0; i<n; i++){
		    out.print(i+1);
		    out.print(":");
		    for(int a: e_on_each_dir.get(i)){
		        out.print(" "+a);
		    }
		    out.println();
		}*/

		int[] mod2pow = new int[n+1];
		mod2pow[0]=1;
		for(int i=1; i<=n; i++){
		    mod2pow[i] = mod2pow[i-1]*2;
		    mod2pow[i] %= e97;
		}

		long ans_2n = 0;

		for(int i=0; i<n; i++){
		    if(e_on_each_dir.sizeOf(i)==1) continue;
		    ans_2n += mod2pow[n-1];
		    for(int a: e_on_each_dir.get(i)){
		        ans_2n -= mod2pow[a];
		    }
		    ans_2n += (e_on_each_dir.sizeOf(i)-1);
		    ans_2n %= e97;
		}
		//out.println(ans_2n);

		long x1 = modinv(mod2pow[n],e97);
		x1 *= ans_2n;
		x1 %= e97;
		if(n==2) x1=0;
		if(x1<0) x1+=e97;
		out.println(x1);

		out.flush();
	}


