		    int dw = todo1.poll();
		    if(is_known[dw]) continue;

		    next=-1;
		    for(int a : tree.get(dw)){
		        if(!is_known[a]){
		            if(next<0){
		                next=a;
		            }else{
		                next=INF;
		            }
		        }
		    }
		    if(next<0){
		        is_known[dw]=true;
		    }else if(!isINF(next)){
    		    int sum_former=0;
    		    for(int a : e_on_each_dir.get(dw)){
    		        sum_former+=a;
    		    }
    		    sum_former++;
    		    e_on_each_dir.add(dw, n-sum_former);
