using namespace std;
const int maxn = 2e5 + 10;
const int mod = 1e9 + 7;
int pow_mod(int a, int n, int mod) {
	if (n == 0)
		return 1;
	int ans = pow_mod(a, n / 2, mod);
	ans = ans * ans % mod;
	if (n % 2 == 1)
		ans = ans * a % mod;
	return ans;
}
//扩展GCD
int ex_gcd(int a, int b, int &x, int &y) {
	if (b == 0) {
		x = 1;
		y = 0;
		return a;
	}
	int g = ex_gcd(b, a % b, x, y);
	int temp = x;
	x = y;
	y = temp - a / b * y;
	return g;
}
//扩展欧几里得的另一种写法
void ex_gcd(int a, int b, int &d, int &x, int &y) {
	//求解ax+by=gcd(a,b)的一组解
	if (!b) {
		d = a, x = 1, y = 0;
	} else {
		ex_gcd(b, a % b, d, y, x);
		y -= x * (a / b);
	}
}
//逆元
int inv(int a, int mod) {
	int X, Y;
	int g = ex_gcd(a, mod, X, Y);
	if (g != 1)
		return -1;
	return (X % mod + mod) % mod;
}
vector<int> G[maxn];
int sz[maxn];
int fa[maxn];
void dfs(int u, int f) {
	sz[u] = 1;
	fa[u] = f;
	for (int i = 0; i < G[u].size(); i++) {
		int v = G[u][i];
		if (v == f)
			continue;
		dfs(v, u);
		sz[u] += sz[v];
	}
}
int p[maxn];
signed main() {
	int n;
	scanf("%lld", &n);
	for (int i = 1; i < n; i++) {
		int u, v;
		scanf("%lld%lld", &u, &v);
		G[u].push_back(v);
		G[v].push_back(u);
	}
	dfs(1, -1);
	int ans = 0;
	int inv2 = inv(2, mod);
	for (int i = 1; i <= n; i++) {
		int tot = G[i].size();
		if (G[i].size() == 1)
			continue;
		int now = 1;
		for (int j = 0; j < tot; j++) {
			int v = G[i][j];
			int siz = 0;
			if (v == fa[i])
				siz = n - sz[i];
			else
				siz = sz[v];
			p[j] = (1 - inv(pow_mod(2, siz, mod), mod) + mod) % mod; //点黑的概率
			now *= ((1 - p[j] + mod) % mod);
			now %= mod;
		}
		int cur = now;
		for (int j = 0; j < tot; j++) {
			cur += now * inv((1 - p[j] + mod) % mod, mod) % mod * p[j] % mod;
			cur %= mod;
		}
		ans += inv2 * (1 - cur + mod) % mod;
		ans %= mod;
	}
	cout << ans << endl;
	return 0;

}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);

    int N = scanner.nextInt();
    Node[] nodes = new Node[N];
    for (int i = 0; i < N; i++) nodes[i] = new Node();

    for (int i = 0; i < N - 1; i++) {
      int a = scanner.nextInt() - 1;
      int b = scanner.nextInt() - 1;
      nodes[a].adjacent.add(nodes[b]);
      nodes[b].adjacent.add(nodes[a]);
    }
    dfs(nodes[0], null);

    int M = 1_000_000_007;
    long res = N * modpow(2, M - 2, M) % M;
    for (Node node : nodes) {
      res += (node.adjacent.size() - 1) * modinv(modpow(2, N, M), M) % M;
      if (res >= M) res -= M;
      for (Node c : node.children) {
        res -= modinv(modpow(2, N - c.size, M), M);
        if (res < 0) res += M;
      }
      if (node.parent != null) {
        res -= modinv(modpow(2, node.size, M), M);
        if (res < 0) res += M;
      }
    }
    System.out.println(res);
  }

  private static long modinv(long a, long mod) {
    return modpow(a, mod - 2, mod);
  }

  private static long modpow(long a, long n, long mod) {
    long res = 1;
    while (n > 0) {
      if (n % 2 == 1) res = (res * a) % mod;
      a = (a * a) % mod;
      n >>= 1;
    }
    return res % mod;
  }

  private static int dfs(Node node, Node parent) {
    node.parent = parent;
    node.size = 1;
    for (Node a : node.adjacent) {
      if (a != parent) {
        node.children.add(a);
        node.size += dfs(a, node);
      }
    }
    return node.size;
  }

  private static class Node {
    private Node parent;
    private int size;
    private List<Node> children = new ArrayList<>();
    private List<Node> adjacent = new ArrayList<>();
  }
}

import java.io.*;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.StringJoiner;
import java.util.StringTokenizer;

public class Main {

    static int N;
    static int[] A, B;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        A = new int[N-1];
        B = new int[N-1];
        for (int i = 0; i < N - 1; i++) {
            A[i] = sc.nextInt()-1;
            B[i] = sc.nextInt()-1;
        }

        System.out.println(solve());
    }

    static int MOD = 1_000_000_007;

    static int solve() {
        int[] POW2 = new int[N+1];
        POW2[0] = 1;
        for (int i = 0; i < N; i++) {
            POW2[i+1] = mul(POW2[i], 2);
        }

        int[][] G = adjB(N, A, B);

        int[] nodeCount = new int[N];
        for (Node node : orderFromLeaf(N, G, 0)) {
            for (int b : G[node.a]) {
                if( b == node.parent ) continue;
                nodeCount[node.a] += nodeCount[b];
            }
            nodeCount[node.a]++;
        }

        int totalEdgeUsed = 0; // グラフ毎のedge数
        for (int i = 0; i < N - 1; i++) {
            int a = A[i];
            int b = B[i];
            int x = nodeCount[a];
            int y = nodeCount[b];
            if( x > y ) {
                x = N - y;
            } else {
                y = N - x;
            }

            // 両方とも黒ならこの辺を使う
            // 全部白でなければ黒
            int edgeUsed = mul(sub(1, div(1, POW2[x])), sub(1, div(1, POW2[y])));
            totalEdgeUsed = add(totalEdgeUsed, edgeUsed);
        }

        // edge+1がnodeの数
        // ただし空グラフの場合は増えない
        int totalNodeCnt = add(totalEdgeUsed, div(sub(POW2[N], 1), POW2[N]));

        // 半分は黒
        int totalWhiteCnt = sub(totalNodeCnt, div(N, 2));

        return totalWhiteCnt;
    }

    static Node[] orderFromLeaf(int N, int[][] G, int root) {
        ArrayDeque<Node> q = new ArrayDeque<>();
        Node[] ret = new Node[N];
        int idx = N-1;
        q.add(new Node(-1, root));
        while(!q.isEmpty()) {
            Node n = q.poll();
            ret[idx--] = n;
            for (int next : G[n.a]) {
                if( next == n.parent ) continue;

                q.add(new Node(n.a, next));
            }
        }
        return ret;
    }

    static int pow(int base, long exp) {
        if( exp == 0 ) return 1;

        int ans = 1;
        base %= MOD;
        while( exp > 0 ) {
            if( (exp & 1) == 1 ) {
                ans = mul(ans, base);
            }

            base = mul(base, base);
            exp = exp >> 1;
        }
        return ans;
    }

    static int sub(int a, int b) {
        int c = a - b;
        if( c < 0 ) c += MOD;
        return c;
    }

    static int div(int a, int b) {
        return mul(a, pow(b, MOD-2));
    }

    static int add(int a, int b) {
        int c = a + b;
        if( c >= MOD ) c %= MOD;
        return c;
    }

    static int mul(int a, int b) {
        long c = (long)a * b;
        if( c >= MOD ) c %= MOD;
        return (int)c;
    }

    static class Node {
        int parent, a;

        public Node(int parent, int a) {
            this.parent = parent;
            this.a = a;
        }
    }

    static int[][] adjB(int n, int[] from, int[] to) {
        int[][] adj = new int[n][];
        int[] cnt = new int[n];
        for (int f : from) {
            cnt[f]++;
        }
        for (int t : to) {
            cnt[t]++;
        }
        for (int i = 0; i < n; i++) {
            adj[i] = new int[cnt[i]];
        }
        for (int i = 0; i < from.length; i++) {
            adj[from[i]][--cnt[from[i]]] = to[i];
            adj[to[i]][--cnt[to[i]]] = from[i];
        }
        return adj;
    }

