					reversedNodes[i] = new Node(i);
				}

				for(Edge edge : edges) {
					nodes[edge.source].add(edge.target, edge.cost);
					if(directed) {
						reversedNodes[edge.target].add(edge.source, edge.cost);
					}else {
						nodes[edge.target].add(edge.source, edge.cost);
					}
				}
			}

			void clearNodes() {
				for(Node n : nodes) { n.clear(); }
				for(Node n : reversedNodes) { n.clear(); }
			}
		}

		class Node {
			int id;
			ArrayList<Edge> edges = new ArrayList<Edge>();

			Node(int id) {
				this.id = id;
			}
			void add(int target, long cost) {
				edges.add(new Edge(id, target, cost));
			}
			void clear() {
				edges.clear();
			}
		}

		class Edge implements Comparable<Edge> {
			int source;
			int target;
			long cost;
			Edge(int source, int target, long cost) {
				this.source = source;
				this.target = target;
				this.cost = cost;
			}

			@Override
			public int compareTo(Edge e) {
				return Long.compare(this.cost, e.cost);
			}
		}

public void solve() {
	int numNode = ni();
	int numEdge = numNode - 1;
	Edge edges[] = new Edge[numEdge];
	for(int i = 0; i < numEdge; i ++) {
		int a = ni() - 1;
		int b = ni() - 1;
		long c = 1;
		edges[i] = new Edge(a, b, c);
	}
	g = new Graph(numNode, numEdge, edges, false);
	weight = new int[numNode];
	fill(weight, 0);
	visited = new boolean[numNode];
	fill(visited, false);
	dfs(0);
	// errprtln(weight);
	long ans = 0;
	long pow[] = new long[numNode + 10];
	pow[0] = 1;
	for(int i = 1; i < pow.length; i ++) {
		pow[i] = mod(pow[i - 1] * inv(2));
	}
	for(int i = 0; i < numNode; i ++) {
		long tmp = 1;
		tmp -= pow[numNode - 1];
		for(Edge e : g.nodes[i].edges) {
			int w = weight[i] > weight[e.target] ? weight[e.target] : numNode - weight[i];
			long tmp2 = pow[numNode - w - 1];
			tmp2 *= mod(1 - pow[w]);
			tmp2 = mod(tmp2);
			tmp -= tmp2;
		}
		tmp *= pow[1];
		tmp = mod(tmp);
		// errprtln(tmp);
		ans += tmp;
		ans = mod(ans);
	}
	prtln(ans);
}
Graph g;
