boolean visited[];

void dfs(int x) {
	visited[x] = true;
	for(Edge e : g.nodes[x].edges) {
		if(!visited[e.target]) {
			dfs(e.target);
			weight[x] += weight[e.target];
		}
	}
	weight[x] ++;
}

