import java.util.*;
import java.io.*;

public class Main {
	static int mod = (int) 1e9 + 7;
	static List<ArrayList<Integer>> to;
	static int dp[];
	public static void main(String[] args) {
		FastScanner fs = new FastScanner(System.in);
		int N = fs.nextInt();
		to = new ArrayList<>();
		for(int i=0;i<N;i++) to.add(new ArrayList<Integer>());
		int edges[][] = new int[N-1][2]; //どちらが子になるかdfsするまでわからないので両方持っておく
		for(int i=0;i<N-1;i++) {
			int A = fs.nextInt()-1, B = fs.nextInt()-1;
			to.get(A).add(B);
			to.get(B).add(A);
			edges[i][0] = B;
			edges[i][1] = A;
		}
		dp = new int[N];
		rec(0, -1);
		long mulsum = 0;
		for(int e[]:edges) {
			//子の配下の頂点数を知りたいので、どちらが子頂点か調べる
			int candidate1 = e[0];
			int candidate2 = e[1];
			int child = candidate1;
			if(dp[candidate1]>dp[candidate2])child = candidate2;

			long a = dp[child];
			long b = N - a;

			//mulは、全ケース(2^n通り)における、この辺が部分木Sに含まれる回数		
			//この辺を境にしてできる部分木2つについてそれぞれ、1つ以上黒を含む確率を求めて、掛け合わせた物に
			//2^nをかけて場合の数にした
			long mul = (modpow(2, a) - 1)*(modpow(2, b) - 1)%mod;			
			mulsum += mul;
			mulsum %= mod;
		}
		long cases = modpow(2, N);
		//PN:全ケースにおける、部分木Sに含まれる頂点数の総和
		//頂点の数は、辺の数＋１であり、辺の数が０の場合でも、黒頂点１個の空グラフがSに含まれるので問題ないが、
		//全部白頂点の場合だけはSに含まれない頂点を足してしまうことになるので、そのケースの１通りを引く
		long PN = (mulsum + (cases - 1 + mod)%mod)%mod ;//全ケースの含まれる頂点の合計

		//Sに含まれる黒頂点は全頂点数の半分になる（黒頂点なら必ずSに含まれるため）
		long BN = N * modpow(2, N-1) %mod;
		//Sに含まれる白頂点は、全頂点数ー黒頂点数
		long WN = (PN - BN + mod)%mod;
		long ans = WN * modpow(cases, mod-2);
		ans %= mod;

		System.out.println(ans);
	}

	static int rec(int v, int parent) {
		int res = 1;
		for(int next:to.get(v)) {
			if(next == parent) continue;
			res += rec(next, v);
		}
		return dp[v] = res;
	}


	static long modpow(long x, long y) {
		if(y==0) return 1;
		if(y%2!=0) return x * modpow(x, y-1) % mod;
		long tmp = modpow(x, y/2);
		return tmp * tmp % mod; 
	}
}

//高速なScanner
class FastScanner {
	private BufferedReader reader = null;
	private StringTokenizer tokenizer = null;

	public FastScanner(InputStream in) {
		reader = new BufferedReader(new InputStreamReader(in));
		tokenizer = null;
	}

	public String next() {
		if (tokenizer == null || !tokenizer.hasMoreTokens()) {
			try {
				tokenizer = new StringTokenizer(reader.readLine());
			} catch (IOException e) {
				throw new RuntimeException(e);
			}
		}
		return tokenizer.nextToken();
	}

	public String nextLine() {
		if (tokenizer == null || !tokenizer.hasMoreTokens()) {
			try {
				return reader.readLine();
			} catch (IOException e) {
				throw new RuntimeException(e);
			}
		}
		return tokenizer.nextToken("\n");
	}

	public long nextLong() {
		return Long.parseLong(next());
	}

	public int nextInt() {
		return Integer.parseInt(next());
	}

	public double nextDouble() {
		return Double.parseDouble(next());
	}

	public int[] nextIntArray(int n) {
		int[] a = new int[n];
		for (int i = 0; i < n; i++)
			a[i] = nextInt();
		return a;
	}

	public long[] nextLongArray(int n) {
		long[] a = new long[n];
		for (int i = 0; i < n; i++)
			a[i] = nextLong();
		return a;
	}
}

import java.io.*;
import java.util.*;

public class Solution {
  private static InputReader in;
  private static PrintWriter out;
  public static int N,M;
  public static int[][] grid;
  public static boolean[][] vis;

  public static void main(String[] args) throws IOException {
    in = new InputReader(System.in);
    out = new PrintWriter(System.out, true);
    N = in.nextInt();
    M = in.nextInt();
    grid = new int[N][M];
    for (int i = 0; i < N; i++) for (int j = 0; j < M; j++)
      grid[i][j] = in.nextInt();

    int max = 0;
    vis = new boolean[N][M];
    for (int i = 0; i < N; i++) for (int j = 0; j < M; j++) {
      if (vis[i][j] || grid[i][j] == 0) continue;
      max = Math.max(max, dfs(i,j));
    }
    out.println(max);
    out.close();
    System.exit(0);
  }

  public static int dfs(int i, int j) {
    if (i < 0 || j < 0 || i >= N || j >= M || vis[i][j] || grid[i][j] == 0) return 0;
    int c = 1;
    vis[i][j] = true;
    c += dfs(i+1,j);
    c += dfs(i,j+1);
    c += dfs(i-1,j);
    c += dfs(i,j-1);
    c += dfs(i+1,j+1);
    c += dfs(i+1,j-1);
    c += dfs(i-1,j+1);
    c += dfs(i-1,j-1);
    return c;
  }

  static class InputReader {
    public BufferedReader reader;
    public StringTokenizer tokenizer;

    public InputReader(InputStream stream) {
      reader = new BufferedReader(new InputStreamReader(stream), 32768);
      tokenizer = null;
    }

    public String next() {
      while (tokenizer == null || !tokenizer.hasMoreTokens()) {
        try {
          tokenizer = new StringTokenizer(reader.readLine());
        } catch (IOException e) {
          throw new RuntimeException(e);
        }
      }
      return tokenizer.nextToken();
    }

    public int nextInt() {
      return Integer.parseInt(next());
    }
  }


}

import java.util.*;

class Main {
	static final int MOD = 1_000_000_007;
	Scanner sc;
	int N;
	List<Edge>[] edges;
	int[] pow2;
	long pow2Ninv;

	static class Edge {
		int from, to, c;
		Edge rev;
		Edge(int from) { this.from = from; }
	}

	@SuppressWarnings("unchecked")
	private void calc() {
		sc = new Scanner(System.in);
		N = sc.nextInt();
		edges = new List[N];
		for (int i = 0; i < N; i++) edges[i] = new ArrayList<Edge>();
		Edge f = null;
		Edge b = null;
		for (int i = 0; i < N-1; i++) {
			f = new Edge(sc.nextInt() - 1);
			b = new Edge(sc.nextInt() - 1);
			f.to = b.from; b.to = f.from;
			f.rev = b; b.rev = f;
			edges[b.to].add(f);
			edges[f.to].add(b);
		}
		pow2 = new int[N+1];
		pow2[0] = 1;
		for (int i = 1; i < N+1; i++) pow2[i] = (pow2[i-1] << 1)%MOD;
		pow2Ninv = extgcd(pow2[N], MOD)[1];

		countByDFS(f);
		countByDFS(b);

		long sum = 0;
		for (int v = 0; v < N; v++) {
			if (edges[v].size() == 1) continue;
			int s = 0;
			for (Edge e : edges[v]) s = (s -1 + pow2[e.c]) % MOD;
			sum = (sum + pow2[N-1] - s - 1 + MOD) % MOD;
		}
		System.out.println(sum*pow2Ninv%MOD);
	}

	private void countByDFS(Edge target) {
		int c = 0;
		int from = target.from;
		for (Edge e : edges[target.to]) {
			if (e.to == from) continue;
			countByDFS(e);
			c += e.c;
		}
		target.c = c + 1;
		target.rev.c = N - target.c;
	}

	static final long[] extgcd(long a, long b) {
		long aa = a, bb = b;
		long x0 = 1, x1 = 0;
		long y0 = 0, y1 = 1;

		while (b != 0) {
			long q = a / b;
			long r = a % b;
			long x2 = x0 - q * x1;
			long y2 = y0 - q * y1;

			a = b; b = r;
			x0 = x1; x1 = x2;
			y0 = y1; y1 = y2;
		}
		if (bb > 0 && x0 < 0) {
			long n = -x0/bb;
			if (-x0%bb != 0) n++;
			x0 += n*bb; y0 -= n*aa;
		}
	    return new long[]{a, x0, y0};
	}

	public static void main(String[] args) {
		new Main().calc();
	}
}

