internal partial class Solver {
    struct Edge {
        public int Id;
        public int To;
    }

    public void Run() {
        int mod = 1000000007;
        ModInt.SetModValue(mod);
        var n = ni();
        var adj = Enumerable.Range(0, n).Select(_ => new List<Edge>()).ToArray();
        int id = 0;
        for (int i = 0; i < n - 1; i++) {
            var a = ni() - 1;
            var b = ni() - 1;
            adj[a].Add(new Edge { Id = id++, To = b });
            adj[b].Add(new Edge { Id = id++, To = a });
        }

        ModInt ans = 0;

        memo = new int?[n * 2];

        var invTwo = new long[n + 1];
        invTwo[0] = 1;
        var half = (new ModInt(1) / 2).ToInt();
        for (int i = 1; i < invTwo.Length; i++) {
            invTwo[i] = invTwo[i - 1] * half % mod;
        }


        for (int i = 0; i < n; i++) {
            long sub = 0;

            var vertexes = new List<int>();
            long sum = 0;
            foreach (var edge in adj[i]) {
                var v = GetVirtexNum(adj, edge.To, i, edge.Id);
                vertexes.Add(v);
                sum += v;
            }

            // all zero
            sub += invTwo[n - 1];

            foreach (var v in vertexes) {
                var rem = sum - v;
                var vAllZero = invTwo[v];
                sub += (1 - vAllZero) * invTwo[rem];
                sub %= mod;
            }

            ans += 1 - sub;
        }

        cout.WriteLine((ans / 2).ToInt());
    }

    int?[] memo;

    int GetVirtexNum(List<Edge>[] adj, int root, int parent, int edgeId) {
        var key = edgeId;

        if (!memo[key].HasValue) {
            int val = 1;

            foreach (var edge in adj[root]) {
                if (edge.To == parent) continue;
                val += GetVirtexNum(adj, edge.To, root, edge.Id);
            }

            memo[key] = val;
        }
        return memo[key].Value;
    }
}

public struct ModInt {
    private static int mod = 0;
    private long value;

    public ModInt(long x) {
        value = x;
        Normalize();
    }

    private static long RegularMod(long x, int mod) {
        if (x >= mod) {
            if (x < 2 * mod) {
                return x - mod;
            }

            return x % mod;
        }
        if (x >= 0) {
            return x;
        }

        x = mod - RegularMod(-x, mod);
        if (x == mod) {
            return 0;
        }

        return x;
    }

    public static void SetModValue(int m) {
        ModInt.mod = m;
    }

    private void Normalize() {
        value = RegularMod(value, mod);
    }

    public override string ToString() {
        return value.ToString(CultureInfo.InvariantCulture);
    }

    public int ToInt() {
        return (int)value;
    }

    public static bool operator ==(ModInt c1, ModInt c2) {
        return c1.value == c2.value;
    }

    public static bool operator !=(ModInt c1, ModInt c2) {
        return !(c1 == c2);
    }

    public static ModInt operator +(ModInt x, ModInt y) {
        return new ModInt(x.value + y.value);
    }
    public static ModInt operator -(ModInt x, ModInt y) {
        return new ModInt(x.value - y.value);
    }
    public static ModInt operator *(ModInt x, ModInt y) {
        return new ModInt(x.value * y.value);
    }
    public static ModInt operator /(ModInt x, ModInt y) {
        return new ModInt(x.value * Inverse(y.value, mod));
    }
    public static ModInt operator ++(ModInt x) {
        return x + 1;
    }
    public static ModInt operator --(ModInt x) {
        return x - 1;
    }
    public static ModInt Pow(ModInt x, long n) {
        ModInt r = 1;
        while (n > 0) {
            if ((n & 1) != 0) r *= x;
            x *= x;
            n >>= 1;
        }
        return r;
    }
    private static long ExtendedGcd(long a, long b, ref long x, ref long y) {
        if (b == 0) {
            x = 1; y = 0;
            return a;
        } else {
            long d = ExtendedGcd(b, a % b, ref y, ref x);
            y -= a / b * x;
            return d;
        }
    }

    private static long Inverse(long a, long mod) {
        long x = 0, y = 0;
        if (ExtendedGcd(a, mod, ref x, ref y) == 1) {
            return (x + mod) % mod;
        } else {
            throw new Exception("Invalid inverse " + a + " " + mod);
        }
    }

    public static implicit operator ModInt(long x) {
        return new ModInt(x);
    }

    public override bool Equals(object obj) {
        if (obj == null) {
            return false;
        }
        return value.Equals(((ModInt)obj).value);
    }

    public override int GetHashCode() {
        return value.GetHashCode();
    }
}
