		var rs = new int[n - 1].Select(_ => Console.ReadLine().Split().Select(int.Parse).ToArray()).ToArray();
		map = rs.Concat(rs.Select(r => new[] { r[1], r[0] })).ToLookup(r => r[0], r => r[1]).ToDictionary(g => g.Key, g => g.ToArray());

		tour = new int[n + 1].Select(_ => new List<int>()).ToArray();
		Dfs(1, 0);

