            if (n - 1 - sum > 0) vertexes.Add(n - 1 - sum);
            // all zero
            sub += invTwo[n - 1];

            foreach (var v in vertexes) {
                var rem = n - 1 - v;
                var vAllZero = invTwo[v];
                sub += (1 - vAllZero) * invTwo[rem];
                sub %= mod;
            }

            ans += 1 - sub;
        }
        cout.WriteLine((ans / 2).ToInt());
    }

    class BFSResult {
        public int[] ChildNum;
        public int[] Parent;
    }

    BFSResult GetChildNumTable(List<int>[] adj, int root) {
        var n = adj.Length;
        var child = new int[n];
        var parents = new int[n];
        var visited = new bool[n];
        var queue = new Queue<int>();
        queue.Enqueue(root);
        queue.Enqueue(-1);
        var perm = new List<int>();
        while (queue.Count > 0) {
            var current = queue.Dequeue();
            var parent = queue.Dequeue();
            if (visited[current]) continue;
            visited[current] = true;
            parents[current] = parent;
            perm.Add(current);
            foreach (var next in adj[current]) {
                if (next == parent) continue;
                if (visited[next]) continue;
                queue.Enqueue(next);
                queue.Enqueue(current);
            }
        }

        for (int i = n - 1; i >= 0; i--) {
            child[perm[i]] = 1;
            foreach (var next in adj[perm[i]]) {
                if (next == parents[perm[i]]) continue;
                child[perm[i]] += child[next];
            }
        }

        return new BFSResult {
            ChildNum = child,
            Parent = parents,
        };
    }
}

public struct ModInt {
    private static int mod = 0;
    private long value;

    public ModInt(long x) {
        value = x;
        Normalize();
    }

    private static long RegularMod(long x, int mod) {
        if (x >= mod) {
            if (x < 2 * mod) {
                return x - mod;
            }

            return x % mod;
        }
        if (x >= 0) {
            return x;
        }

        x = mod - RegularMod(-x, mod);
        if (x == mod) {
            return 0;
        }

        return x;
    }

    public static void SetModValue(int m) {
        ModInt.mod = m;
    }

    private void Normalize() {
        value = RegularMod(value, mod);
    }

    public override string ToString() {
        return value.ToString(CultureInfo.InvariantCulture);
    }

    public int ToInt() {
        return (int)value;
    }

    public static bool operator ==(ModInt c1, ModInt c2) {
        return c1.value == c2.value;
    }

    public static bool operator !=(ModInt c1, ModInt c2) {
        return !(c1 == c2);
    }

    public static ModInt operator +(ModInt x, ModInt y) {
        return new ModInt(x.value + y.value);
    }
    public static ModInt operator -(ModInt x, ModInt y) {
        return new ModInt(x.value - y.value);
    }
    public static ModInt operator *(ModInt x, ModInt y) {
        return new ModInt(x.value * y.value);
    }
    public static ModInt operator /(ModInt x, ModInt y) {
        return new ModInt(x.value * Inverse(y.value, mod));
    }
    public static ModInt operator ++(ModInt x) {
        return x + 1;
    }
    public static ModInt operator --(ModInt x) {
        return x - 1;
    }
    public static ModInt Pow(ModInt x, long n) {
        ModInt r = 1;
        while (n > 0) {
            if ((n & 1) != 0) r *= x;
            x *= x;
            n >>= 1;
        }
        return r;
    }
    private static long ExtendedGcd(long a, long b, ref long x, ref long y) {
        if (b == 0) {
            x = 1; y = 0;
            return a;
        } else {
            long d = ExtendedGcd(b, a % b, ref y, ref x);
            y -= a / b * x;
            return d;
        }
    }

    private static long Inverse(long a, long mod) {
        long x = 0, y = 0;
        if (ExtendedGcd(a, mod, ref x, ref y) == 1) {
            return (x + mod) % mod;
        } else {
            throw new Exception("Invalid inverse " + a + " " + mod);
        }
    }

    public static implicit operator ModInt(long x) {
        return new ModInt(x);
    }

    public override bool Equals(object obj) {
        if (obj == null) {
            return false;
        }
        return value.Equals(((ModInt)obj).value);
    }

    public override int GetHashCode() {
        return value.GetHashCode();
    }
}
