public class Program
{
    [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.Never)] private ConsoleReader cr; public Program(ConsoleReader consoleReader) { this.cr = consoleReader; }
    static void Main() => Console.WriteLine(new Program(new ConsoleReader(Console.OpenStandardInput())).Result());
    #endregion
    public string Result() { var obj = Calc(); if (obj is bool) return (bool)obj ? "Yes" : "No"; if (obj is double) return ((double)obj).ToString("0.####################"); return obj.ToString(); }
    private object Calc()
    {
        N = cr;
        gb = new GraphBuilder(N, cr, N - 1, false);
        graph = gb.ToTree(0);
        size = new int[N];
        Mod sum = 0;
        var Nx = Mod.Pow(2, N - 1);
        for (int i = 0; i < N; i++)
        {
            var list = new List<int>();
            list.Add(N - Size(i));
            foreach (var child in graph[i].children)
                list.Add(Size(child));
            Mod cur = Nx - 1;
            foreach (var c in list)
                cur -= Mod.Pow(2, c) - 1;
            sum += cur;
        }
        return sum / (Nx * 2);
    }


    int Size(int v)
    {
        if (size[v] > 0) return size[v];
        foreach (var child in graph[v].children)
        {
            size[v] += Size(child);
        }
        return ++size[v];
    }

    int N;
    int[] size;
    GraphBuilder gb;
    TreeNode[] graph;
}

class GraphBuilder { private List<int>[] roots; private List<int>[] children; public GraphBuilder(int count, bool isOriented) { this.roots = new List<int>[count]; this.children = new List<int>[count]; for (var i = 0; i < count; i++) { if (isOriented) { this.roots[i] = new List<int>(); this.children[i] = new List<int>(); } else { this.roots[i] = this.children[i] = new List<int>(); } } } public GraphBuilder(int count, ConsoleReader cr, int edgeCount, bool isOriented) : this(count, isOriented) { for (var i = 0; i < edgeCount; i++) this.Add(cr.Int0, cr.Int0); } public void Add(int from, int to) { children[from].Add(to); roots[to].Add(from); } public TreeNode[] ToTree(int root) { if (this.roots[0] != this.children[0]) throw new Exception("木には無向グラフをしたほうが良い"); var res = new TreeNode[this.children.Length]; res[root] = new TreeNode(root, -1, 0, this.children[root].ToArray()); var queue = new Queue<int>(); foreach (var child in res[root].children) { res[child] = new TreeNode(child, root, 1, Array.Empty<int>()); queue.Enqueue(child); } while (queue.Count > 0) { var from = queue.Dequeue(); if (res[from].root == -1) res[from].children = this.children[from].ToArray(); else { var children = new List<int>(this.children[from].Count); foreach (var c in this.children[from]) if (c != res[from].root) children.Add(c); res[from].children = children.ToArray(); } foreach (var child in res[from].children) { res[child] = new TreeNode(child, from, res[from].depth + 1, Array.Empty<int>()); queue.Enqueue(child); } } return res; } public Node[] ToArray() => Enumerable.Zip(roots, children, (r, c) => Tuple.Create(r, c)).Select((t, i) => new Node(i, t.Item1.ToArray(), t.Item2.ToArray())).ToArray(); }
class TreeNode { public TreeNode(int i, int root, int depth, int[] children) { this.index = i; this.root = root; this.children = children; this.depth = depth; } public readonly int index; public readonly int root; public readonly int depth; public int[] children; public override string ToString() => $"children: {string.Join(",", children)}"; public override bool Equals(object obj) { if (obj is TreeNode) return this.Equals((TreeNode)obj); else return false; } public bool Equals(TreeNode other) => this.index == other.index; public override int GetHashCode() => this.index; }
class Node { public Node(int i, int[] roots, int[] children) { this.index = i; this.roots = roots; this.children = children; } public readonly int index; public readonly int[] roots; public readonly int[] children; public override string ToString() => $"children: {string.Join(",", children)}"; public override bool Equals(object obj) { if (obj is Node) return this.Equals((Node)obj); else return false; } public bool Equals(Node other) => this.index == other.index; public override int GetHashCode() => this.index; }
struct Mod : IEquatable<Mod> { public const long mod = 1000000007; public static readonly Mod invalid = new Mod(-1, false); public readonly long val; private Mod(long val, bool isValid) : this(val) { if (!isValid) this.val = val; } public Mod(long val) { this.val = val % mod; if (this.val < 0) this.val += mod; } public override bool Equals(object obj) => (obj is Mod) ? this == ((Mod)obj) : false; public bool Equals(Mod obj) => this == obj; public override int GetHashCode() => val.GetHashCode(); public override string ToString() => val.ToString(); public static implicit operator Mod(long x) => new Mod(x); public static Mod operator -(Mod x) => x; public static Mod operator +(Mod x, Mod y) => (x.val + y.val) % mod; public static Mod operator -(Mod x, Mod y) => x.val >= y.val ? (x.val - y.val) % mod : (x.val - y.val) % mod + mod; public static Mod operator *(Mod x, Mod y) => (x.val * y.val) % mod; public static Mod operator /(Mod x, Mod y) => x * y.Inverse(); public static bool operator ==(Mod x, Mod y) => x.val == y.val; public static bool operator !=(Mod x, Mod y) => x.val != y.val; public Mod Inverse() { long a = val, b = mod, u = 1, v = 0; while (b > 0) { long t = a / b; var b2 = a - t * b; a = b; b = b2; var v2 = u - t * v; u = v; v = v2; } u %= mod; if (u < 0) u += mod; return u; } public static Mod Pow(Mod x, int y) { Mod res = 1; for (; y > 0; y >>= 1) { if ((y & 1) == 1) res *= x; x *= x; } return res; } public static Factor CreateFactor(int max) => new Factor(max); public class Factor { private readonly Mod[] fac, finv; public Factor(int max) { ++max; var inv = new Mod[max]; fac = new Mod[max]; finv = new Mod[max]; fac[0] = fac[1] = 1; finv[0] = finv[1] = 1; inv[1] = 1; for (var i = 2; i < max; i++) { fac[i] = fac[i - 1] * i; inv[i] = mod - inv[mod % i].val * (mod / i) % mod; finv[i] = finv[i - 1] * inv[i]; } } /** <summary>組み合わせ関数(二項係数)</summary> */ public Mod Combine(int n, int k) { if (n < k) return 0; if (n < 0 || k < 0) return 0; return fac[n] * finv[k] * finv[n - k]; } public Mod Factorial(int n) => fac[n]; public Mod FactorialInvers(int n) => finv[n]; } }

using System;
using System.Collections.Generic;
using CompLib.Mathematics;
using CompLib.Util;

public class Program
{
    private int N;
    private List<int>[] Edge;
    private int[] Cnt;


    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        Edge = new List<int>[N];
        for (int i = 0; i < N; i++)
        {
            Edge[i] = new List<int>();
        }

        for (int i = 0; i < N - 1; i++)
        {
            int s = sc.NextInt() - 1;
            int t = sc.NextInt() - 1;
            Edge[s].Add(t);
            Edge[t].Add(s);
        }

        // 全方位木DP

        // 頂点iが含まれる確率 
        // iが黒 or iの子の2つ以上に黒がある

        Cnt = new int[N];

        DFS(0, -1);

        Console.WriteLine(DFS2(0, -1, 0) - N * ((ModInt.Mod + 1) / 2));
    }

    // 現在地、親、親側の部分木の頂点数
    public ModInt DFS2(int n, int p, int pp)
    {
        // Console.WriteLine(n);
        // 1-　iが白 and iの子の1つ以下に黒がある

        ModInt h = (ModInt.Mod + 1) / 2;
        // iが白の確率 = 1/2
        ModInt a = h;

        // 全部白
        var t = ModInt.Pow(h, N - 1);
        ModInt b = t;
        foreach (int i in Edge[n])
        {
            if (p == i) continue;
            b += t * ModInt.Inverse(ModInt.Pow(h, Cnt[i])) * (1 - ModInt.Pow(h, Cnt[i]));
        }

        b += t * ModInt.Inverse(ModInt.Pow(h, pp)) * (1 - ModInt.Pow(h, pp));

        ModInt result = 1 - (a * b);
        // Console.WriteLine($"{n} {result}");
        foreach (int i in Edge[n])
        {
            if (p == i) continue;
            result += DFS2(i, n, N - Cnt[i]);
        }

        return result;
    }

    // 現在地、親、
    public void DFS(int n, int p)
    {
        int cnt = 1;
        foreach (int to in Edge[n])
        {
            if (to == p) continue;
            DFS(to, n);
            cnt += Cnt[to];
        }

        Cnt[n] = cnt;
    }

    public static void Main(string[] args) => new Program().Solve();
}

