                    if (x != parent) { dp[vtx][x] = yzval; acc = f(acc, fun(x, vtx)); }
                    if (y != parent) { dp[vtx][y] = xzval; acc = f(acc, fun(y, vtx)); }
                    if (z != parent) { dp[vtx][z] = xyval; acc = f(acc, fun(z, vtx)); }
                }
                else if (path[vtx].Count == 4)
