    class Program
    {
        private const long MOD = 1000000007;
        private const long Z_VALUE = 500000004;

        class LongClass
        {
            public long? LongValue = null;
        }

        class Node : SortedList<int, LongClass>
        {
            public long? _value { get; private set; } = null;
            private SortedList<int, Node> _parent = null;
            private int _myNode = 0;
            public Node(int myNode, SortedList<int, Node> parent)
            {
                _parent = parent;
                _myNode = myNode;
            }
            public void AddNode(int node)
            {
                this.Add(node, new LongClass());
            }

            public void SetZValue()
            {

                foreach (var child in this)
                {
                    child.Value.LongValue = _parent[child.Key].GetZValue(_myNode);
                }
            }

            public long GetZValue(int direction)
            {
                long value = Z_VALUE;
                foreach (var child in this)
                {
                    if (child.Key == direction)
                    {
                        continue;
                    }
                    else
                    {
                        long tmp = 0;
                        if (!child.Value.LongValue.HasValue)
                        {
                            child.Value.LongValue = _parent[child.Key].GetZValue(_myNode);
                        }
                        value = (value * child.Value.LongValue.Value) % MOD;
                    }
                }
                return value;
            }

            public long GetExpectedValue()
            {
                long value = 1;
                if (this.Count < 2)
                {
                    return 0;
                }
                else if(this.Count == 2)
                {
                    foreach (var item in this)
                    {
                        var tmp = MOD + 1 - item.Value.LongValue.Value;
                        value = (value * tmp) % MOD;
                    }
                }
                else 
                {
                    foreach(var item in this)
                    {
                        value = (value * item.Value.LongValue.Value) % MOD;
                    }
                    var org = value;
                    foreach (var item in this)
                    {
                        var inv = modinv(item.Value.LongValue.Value, MOD);
                        var tmp = (org * inv) % MOD;
                        tmp = (tmp * (MOD + 1 - item.Value.LongValue.Value)) % MOD;
                        value = (value + tmp) % MOD;
                    }
                    value = MOD + 1 - value;
                }
                value = (Z_VALUE * value) % MOD;
                return value;
            }

            static long modinv(long a, long m)
            {
                long b = m, u = 1, v = 0;
                while (b != 0)
                {
                    long t = a / b;
                    a -= t * b;
                    Swap(ref a, ref b);
                    u -= t * v;
                    Swap(ref u, ref v);
                }
                u %= m;
                if (u < 0)
                {
                    u += m;
                }
                return u;
            }

            static void Swap<T>(ref T lhs, ref T rhs)
            {
                T temp;
                temp = lhs;
                lhs = rhs;
                rhs = temp;
            }
        }
        static void Main(string[] args)
        {
