        N = sc.NextInt();
        Edge = new List<int>[N];
        for (int i = 0; i < N; i++)
        {
            Edge[i] = new List<int>();
        }

        for (int i = 0; i < N - 1; i++)
        {
            int s = sc.NextInt() - 1;
            int t = sc.NextInt() - 1;
            Edge[s].Add(t);
            Edge[t].Add(s);
        }

        // sの頂点の個数 - 黒の頂点の個数

        // 黒の頂点の個数の期待値 N/2
        // sの頂点の個数 = sの辺+1

        Cnt = new List<int>();
        int o;
        Calc(0, -1, out o);
        // 各辺がsに含まれるか?
        // 
        ModInt h = (ModInt.Mod + 1) / 2;
        ModInt sEdge = 0;
        foreach (var i in Cnt)
        {
            sEdge += (1 - ModInt.Pow(h, i)) * (1 - ModInt.Pow(h, N - i));
        }

        // 全部白 辺の個数0だけど頂点も0
        sEdge -= ModInt.Pow(h, N);

        Console.WriteLine(sEdge + 1 - N * h);
    }

    // 現在地、親、
    public void Calc(int n, int p, out int cnt)
    {
        cnt = 1;
        foreach (var to in Edge[n])
        {
            if (to == p) continue;
            int o;
            Calc(to, n, out o);
            Cnt.Add(o);
            cnt += o;
        }
    }

    public static void Main(string[] args) => new Program().Solve();
}

