        var n = ni();
        var adj = Enumerable.Range(0, n).Select(_ => new List<Edge>()).ToArray();
        int id = 0;
        for (int i = 0; i < n - 1; i++) {
            var a = ni() - 1;
            var b = ni() - 1;
            adj[a].Add(new Edge { Id = id++, To = b });
            adj[b].Add(new Edge { Id = id++, To = a });
        }

        ModInt ans = 0;

        memo = new int?[n * 2];

        var invTwo = new ModInt[n + 1];
        invTwo[0] = 1;
        var half = new ModInt(1) / 2;
        for (int i = 1; i < invTwo.Length; i++) {
            invTwo[i] = invTwo[i - 1] * half;
        }


        for (int i = 0; i < n; i++) {
            ModInt sub = 0;

            var vertexes = new List<int>();
            long sum = 0;
            foreach (var edge in adj[i]) {
                var v = GetVirtexNum(adj, edge.To, i, edge.Id);
                vertexes.Add(v);
                sum += v;
            }

            // all zero
            sub += invTwo[n - 1];

            foreach (var v in vertexes) {
                var rem = sum - v;
                var vAllZero = invTwo[v];
                sub += (1 - vAllZero) * invTwo[rem];
            }

            ans += 1 - sub;
        }

        cout.WriteLine((ans / 2).ToInt());
    }

    int?[] memo;

    int GetVirtexNum(List<Edge>[] adj, int root, int parent, int edgeId) {
        var key = edgeId;

        if (!memo[key].HasValue) {
            int val = 1;

            foreach (var edge in adj[root]) {
                if (edge.To == parent) continue;
                val += GetVirtexNum(adj, edge.To, root, edge.Id);
            }

            memo[key] = val;
        }
        return memo[key].Value;
    }
