    class AC
    {
        const int MOD = 1000000007;
        //const int MOD = 998244353;
        const int INF = int.MaxValue / 2;
        const long SINF = long.MaxValue / 2;
        const double EPS = 1e-8;
        static readonly int[] dI = { 0, 1, 0, -1, 1, -1, -1, 1 };
        static readonly int[] dJ = { 1, 0, -1, 0, 1, 1, -1, -1 };
        static List<List<int>> G = new List<List<int>>();
        //static List<List<Edge>> G = new List<List<Edge>>();
        //static List<Edge> E = new List<Edge>();
        static void Main(string[] args)
        {
            //var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
            //Console.SetOut(sw);
            var cin = new IO_ShortCut();

            int N = cin.Int;
            for (var i = 0; i < N; i++) G.Add(new List<int>());
            for(var i = 0; i < N - 1; i++)
            {
                int a, b;
                cin.Input(out a, out b);
                a--;b--;
                G[a].Add(b);
                G[b].Add(a);
            }
            var dfs = new Stack<Tuple<int, int>>();
            var size = new long[N];
            var used = new bool[N];

            Initialize(ref size, -1);
            dfs.Push(new Tuple<int, int>(0, -1));
            while (dfs.Any())
            {
                var t = dfs.Pop();
                int v = t.Item1;
                int prev = t.Item2;
                long sum = 1;

                used[v] |= (G[v].Count() == 1 && G[v][0] == prev);
                if (!used[v]) { dfs.Push(new Tuple<int, int>(v, prev)); }
                foreach(var nx in G[v])
                {
                    if (nx == prev) continue;
                    sum += size[nx];
                    if (size[nx] == -1)
                    {
                        dfs.Push(new Tuple<int, int>(nx, v));
                    }
                }
                if (!used[v]) { used[v] = true;continue; }
                size[v] = sum;
            }
            long ans = 0;
            var md = new Modulo(N, MOD);
            //cin.Out_Sep(size);

            dfs.Push(new Tuple<int, int>(0, -1));
            var p2 = new long[N + 1];
            p2[0] = 1;
            for (var i = 0; i < N; i++) p2[i + 1] = md.Mul(p2[i], 2);
            dfs.Clear();
            dfs.Push(new Tuple<int, int>(0, -1));
            while (dfs.Any())
            {
                var t = dfs.Pop();
                int v = t.Item1;
                int prev = t.Item2;
                ans += p2[N];
                ans = (ans - p2[N - 1] - 1 + MOD) % MOD;
                foreach(var nx in G[v])
                {
                    if (nx == prev)
                    {
                        ans = (ans - p2[N - size[v]] + 1 + MOD) % MOD;
                    }
                    else
                    {
                        ans = (ans - p2[size[nx]] + 1 + MOD) % MOD;
                        dfs.Push(new Tuple<int, int>(nx, v));
                    }
                }
            }
            ans = md.Div(ans, p2[N]);

            cin.OutL(ans);


            //Console.Out.Flush();
        }

