                }
            }
        }
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public TreeDPResult<T> BuildTreeDP<T>(Func<long, T> idxToVal, Func<T, T, T> f)
        {
            var dp = Enumerable.Repeat(0, (int)N).Select(_ => new Dictionary<long, T>()).ToArray();
            foreach (var item in BFSFromLeaf(0))
            {
                var acc = idxToVal(item.node);
                foreach (var item2 in path[item.node])
                {
                    if (item2 == item.parent) continue;
                    acc = f(acc, dp[item2][item.node]);
                }
                dp[item.node][item.parent] = acc;
            }
            Func<long, long, LIB_SlidingWindowAggregation<T>, T> fun = null;
            fun = (vtx, parent, swag) =>
            {
                var acc = idxToVal(vtx);
                if (path[vtx].Count == 1)
                {
                    if (path[vtx][0] != parent)
                    {
                        dp[vtx][path[vtx][0]] = acc;
                        acc = f(acc, fun(path[vtx][0], vtx, swag));
                    }
                }
                else if (path[vtx].Count == 2)
                {
                    var x = path[vtx][0];
                    var y = path[vtx][1];
                    var xval = f(acc, dp[x][vtx]);
                    var yval = f(acc, dp[y][vtx]);
                    if (x != parent)
                    {
                        dp[vtx][x] = yval;
                        acc = f(acc, fun(x, vtx, swag));
                    }
                    if (y != parent)
                    {
                        dp[vtx][y] = xval;
                        acc = f(acc, fun(y, vtx, swag));
                    }
                }
                else
                {
                    var nextswag = new LIB_SlidingWindowAggregation<T>(f);
                    swag.Clear();
                    foreach (var item in path[vtx]) swag.PushBack(dp[item][vtx]);
                    swag.PushBack(acc);
                    foreach (var item in path[vtx])
                    {
                        swag.PopFront();
                        if (item != parent)
                        {
                            dp[vtx][item] = swag.Aggregate();
                            acc = f(acc, fun(item, vtx, nextswag));
                        }
                        swag.PushBack(dp[item][vtx]);
                    }
                }
                return dp[vtx][parent] = acc;
            };
            fun(0, -1, new LIB_SlidingWindowAggregation<T>(f));
            return new TreeDPResult<T>(dp);
        }
