            adj[a].Add(b);
            adj[b].Add(a);
        }

        ModInt ans = 0;
        memo.Clear();

        var invTwo = new ModInt[n + 1];
        invTwo[0] = 1;
        var half = new ModInt(1) / 2;
        for (int i = 1; i < invTwo.Length; i++) {
            invTwo[i] = invTwo[i - 1] * half;
        }


        for (int i = 0; i < n; i++) {
            ModInt sub = 0;

            var vertexes = new List<int>();
            long sum = 0;
            foreach (var child in adj[i]) {
                var v = GetVirtexNum(adj, child, i);
                vertexes.Add(v);
                sum += v;
            }

            // all zero
            sub += invTwo[n - 1];

            foreach (var v in vertexes) {
                var rem = sum - v;
                var vAllZero = invTwo[v];
                sub += (1 - vAllZero) * invTwo[rem];
            }

            ans += 1 - sub;
        }

        cout.WriteLine((ans / 2).ToInt());
