	static void Dfs(int p, int p0, ILookup<int, int> map, List<int>[] tour)
	{
		foreach (var x in map[p])
		{
			if (x == p0) continue;
			tour[x].Add(++c);
			Dfs(x, p, map, tour);
			tour[p].Add(++c);
		}
