func DFS(T, ST *[][]int, u, v int) int {
  N := len((*T))
  if len((*T)[v]) == 1 {
    (*ST)[v] = append((*ST)[v], N - 1)
    return 1
  }
  for _, adj := range (*T)[v] {
    if adj == u { continue }
    d := DFS(T, ST, v, adj)
    (*ST)[v] = append((*ST)[v], d)
  }
  s := Sum((*ST)[v]) + 1
  if u != -1 {
    (*ST)[v] = append((*ST)[v], N - s)
  }
  return s
}

