func NextLine() string {
  buffer := make([]byte, 0)
  for true {
    line, isPrefix, err := reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer, line...)
    if !isPrefix { break }
  }
  return string(buffer)
}
func NextInt() int {
  n, _ := strconv.Atoi(NextLine())
  return n
}
func NextIntVec() []int {
  L := strings.Split(NextLine(), " ")
  N := make([]int, len(L))
  for i := range N {
    N[i], _ = strconv.Atoi(L[i])
  }
  return N
}
func Write(s interface{}) {
  fmt.Fprintln(writer, s)
}
func Output() {
  _ = writer.Flush()
}

func Sum(A []int) int {
  sum := 0
  for _, a := range A {
    sum += a
  }
  return sum
}

const p = 1000000007
const p2 = 500000004

func main() {
  N := NextInt()
  T := make([][]int, N)
  for i := 1; i < N; i++ {
    AB := NextIntVec()
    A, B := AB[0] - 1, AB[1] - 1
    T[A] = append(T[A], B)
    T[B] = append(T[B], A)
  }
  P := make([]int, N)
  for i := range P {
    if 0 < i { P[i] = -1 }
  }
  Q := make([]int, N)
  pos := 1
  for _, q := range Q {
    for _, adj := range T[q] {
      if 0 <= P[adj] { continue }
      P[adj] = q
      Q[pos] = adj
      pos++
    }
  }
  ST := make([][]int, N)
  for i := range ST {
    ST[i] = make([]int, len(T[i]) + 1)
  }
  ST[0] = ST[0][1:]
  STP := make([]int, N)
  for i := N - 1; 0 < i; i-- {
    q := Q[i]
    s := Sum(ST[q]) + 1
    ST[P[q]][STP[P[q]]] = s
    STP[P[q]]++
    ST[q][STP[q]] = N - s
    STP[q]++
  }
  B := make([]int, N)
  B[0] = 1
  for i := 1; i < N; i++ {
    B[i] = B[i - 1] * p2 % p
  }
  ans := 0
  for _, S := range ST {
    R := make([]int, N)
    for i, s := range S {
      R[i] = B[N - 1 - s] * (p + 1 - B[s]) % p
    }
    cnt := 1 - B[N - 1] - Sum(R)
    if cnt < 0 { cnt += (-cnt / p) * p }
    if cnt < 0 { cnt += p }
    ans += p2 * cnt % p
    ans %= p
  }
  Write(ans)
  Output()
}

