class power(object):
	def __init__(self, con):
		self.power = [0] * 19
		self.power[0] = 2
		for i in range(1, 19):
			self.power[i] = (self.power[i - 1] ** 2) % con

	def calc(self, M, con):
		ans = 1
		for i in range(19):
			if M & 1 == 1:
				ans = (ans * self.power[i]) % con
			M = M >> 1
			if M == 0:
				break

		return ans

