def MF(n,d): return ModFraction(n,d)

class ModFraction():
    def __init__(self, n, d):
        self.n = n
        self.d = d

    def __add__(self, x):
        xf = ModFraction.xf(x)
        a = self.n * xf.d % mod
        b = xf.n * self.d % mod
        c = self.d * xf.d % mod
        return ModFraction((a+b) % mod, c)

    def __sub__(self, x):
        xf = ModFraction.xf(x)
        a = self.n * xf.d % mod
        b = -xf.n * self.d % mod
        c = self.d * xf.d % mod
        return ModFraction((a+b) % mod, c)

    def __mul__(self, x):
        xf = ModFraction.xf(x)
        a = self.n * xf.n % mod
        b = self.d * xf.d % mod
        return ModFraction(a, b)

    def __truediv__(self, x):
        xf = ModFraction.xf(x)
        a = self.n * xf.d % mod
        b = self.d * xf.n % mod
        return ModFraction(a, b)

    @classmethod
    def xf(cls, x):
        if isinstance(x, int):
            return ModFraction(x, 1)
        return x

    @classmethod
    def inv(cls, x):
        return pow(x, mod - 2, mod)

    def int(self):
        return self.n * ModFraction.inv(self.d) % mod

    def __str__(self):
        return "{} / {}".format(self.n, self.d)


def main():
    n = I()
    e = collections.defaultdict(list)
    for _ in range(n-1):
        a,b = LI_()
        e[a].append(b)
        e[b].append(a)

    m = {}
    def f(i,p):
        k = i*n+p
        if k in m:
            return m[k]
        r = 1
        for c in e[i]:
            if c == p:
                continue
            r += f(c,i)
        m[k] = r
        m[p*n+i] = n - r
        return r

    pw = [1]
    for i in range(n):
        pw.append(pw[-1]*2%mod)

    r = 0
    for i in range(n):
        cs = []
        for c in e[i]:
            cs.append(f(c,i))
        t = sum(cs)
        for i in range(len(cs)-1):
            t -= cs[i]
            k = pw[cs[i]] - 1
            l = pw[t] - 1
            r += k * l % mod
            r %= mod

    rf = MF(r, pw[n])

    return rf.int()


