def resolve():
    n = int(input())
    E = [[] for _ in range(n)]
    for _ in range(n - 1):
        u, v = map(int,input().split())
        u -= 1; v -= 1;
        E[u].append(v)
        E[v].append(u)

    size = [1] * n
    stack = [(0, -1)]
    while stack:
        v, p = stack.pop()
        if v >= 0:
            for nv in E[v]:
                if nv == p:
                    continue
                stack.append((~nv, v))
                stack.append((nv, v))
        else:
            size[p] += size[~v]

    def rerooting(v, p):
        if p == -1:
            return
        size[p] -= size[v]
        size[v] += size[p]

    res = [None] * n
    stack = [(0, -1)]
    while stack:
        v, p = stack.pop()
        if v >= 0:
            rerooting(v, p)
            if res[v] is None:
                cnt = pow(2, n - 1, MOD)
                cnt -= 1
                for nv in E[v]:
                    cnt -= pow(2, size[nv], MOD) - 1
                res[v] = cnt % MOD
            for nv in E[v]:
                if nv == p:
                    continue
                stack.append((~nv, v))
                stack.append((nv, v))
        else:
            rerooting(p, ~v)

    print(sum(res) * pow(2, n * (MOD - 2) % (MOD - 1), MOD) % MOD)
resolve()

