use std::cell::Cell;

const MOD: i32 = 1000000007;

fn main() {
	let mut s = String::new();
	use std::io::Read;
	std::io::stdin().read_to_string(&mut s).unwrap();
	let mut s = s.split_whitespace();
	let n: usize = s.next().unwrap().parse().unwrap();
	let mut edges = vec![vec![]; n];
	for _ in 0..n - 1 {
		let a = s.next().unwrap().parse::<u32>().unwrap() - 1;
		let b = s.next().unwrap().parse::<u32>().unwrap() - 1;
		edges[a as usize].push(b);
		edges[b as usize].push(a);
	}
	let tree = Tree::new(edges);
	tree.dfs();
	let y = tree.calc();
	let x = mod_pow(tree.two_power[n] as i64, MOD as u32 - 2, MOD as i64);
	println!("{}", y as i64 * x % MOD as i64);
}

struct Tree {
	edges: Vec<Vec<u32>>,
	children: Vec<Cell<u32>>,
	parent: Vec<Cell<u32>>,
	two_power: Vec<i32>,
}

impl Tree {
	fn new(edges: Vec<Vec<u32>>) -> Tree {
		let n = edges.len();
		let pow: Vec<_> = (0..n + 1)
			.scan(1, |s, _| {
				let a = *s;
				*s = a * 2 % MOD;
				Some(a)
			})
			.collect();
		Tree { edges: edges, children: vec![Cell::new(0); n], parent: vec![Cell::new(0); n], two_power: pow }
	}

	fn dfs(&self) {
		let mut q1 = vec![(0, std::u32::MAX)];
		let mut q2 = vec![];
		while let Some(p) = q1.pop() {
			q2.push(p);
			for e in self.edges[p.0 as usize].iter() {
				if *e == p.1 {
					continue;
				}
				q1.push((*e, p.0));
			}
		}
		while let Some(p) = q2.pop() {
			let mut c = 0;
			self.parent[p.0 as usize].set(p.1 as u32);
			for e in self.edges[p.0 as usize].iter() {
				if *e == p.1 {
					continue;
				}
				c += self.children[*e as usize].get() + 1;
			}
			self.children[p.0 as usize].set(c);
		}
	}

	fn calc(&self) -> i32 {
		let n = self.edges.len();
		let mut r = 0;
		for i in 0..n {
			let mut csum = 0;
			let mut pat = 0;
			for e in self.edges[i].iter() {
				if *e == self.parent[i].get() {
					continue;
				}
				let c = self.children[*e as usize].get() + 1;
				pat = (pat + self.two_power[c as usize] - 1) % MOD;
				csum += c;
			}
			pat = (pat + self.two_power[n - 1 - csum as usize] - 1 + 1) % MOD;
			pat = (self.two_power[n - 1] + MOD - pat) % MOD;
			r = (r + pat) % MOD;
		}
		r
	}
}

fn mod_pow(a: i64, n: u32, m: i64) -> i64 {
	let mut r = 1;
	let mut a = a;
	let mut n = n;
	while n > 0 {
		if n & 1 != 0 {
			r = r * a % m;
		}
		a = a * a % m;
		n >>= 1;
	}
	r
}

