impl ModInt {
    pub fn new(n: u32) -> ModInt {
        ModInt(n % MOD)
    }
    pub fn zero() -> ModInt {
        ModInt(0)
    }
    pub fn one() -> ModInt {
        ModInt(1)
    }
    pub fn pow(self, mut n: u32) -> ModInt {
        let mut t = ModInt::one();
        let mut s = self;
        while n > 0 {
            if n & 1 == 1 {
                t *= s;
            }
            s *= s;
            n >>= 1;
        }
        t
    }
    pub fn inv(self) -> ModInt {
        self.pow(MOD - 2)
    }
}

fn solve() {
	let n = read!(usize);
	let e = read!([usize];n-1);
	let mut edge = vec![vec![];n];
	for i in 0..n-1 {
		let s = e[i][0]-1;
		let t = e[i][1]-1;
		edge[s].push(t);
		edge[t].push(s);
	}	
	let mut nodes = vec![vec![];n];
	dfs(n as i32,0,n,&edge,&mut nodes);
	let mut wp = vec![ModInt(1);n];
	let mut tmp = ModInt(1);
	for i in 0..n {
		wp[i] = tmp;
		tmp *= ModInt(2).inv();
	}
	let mut ans = ModInt(0);
	for i in 0..n {
		let mut sum = ModInt(0);
		if nodes[i].len()==1 {
			continue;
		}
		for j in 0..nodes[i].len() {
			let mut tmp = ModInt(1);
			for k in 0..nodes[i].len() {
				if j==k {
					tmp *= (ModInt(1)-wp[nodes[i][k] as usize]);
				}
				else{
					tmp *= wp[nodes[i][k] as usize];
				}
			}
			sum += tmp;
		}
		let mut tmp = ModInt(1);
		for j in 0..nodes[i].len() {
			tmp *= wp[nodes[i][j] as usize];
		}
		sum += tmp;
		ans += (ModInt(1)-sum)*ModInt(2).inv();
	}
	println!("{}", ans.0);
}

fn dfs(n: i32, cur: usize, p: usize, edge: &Vec<Vec<usize>>, mut nodes: &mut Vec<Vec<i32>>) -> i32{
	let mut sum = 0;
	for &e in &edge[cur]{
		if p==e {continue;}
		let tmp = dfs(n,e,cur,&edge,&mut nodes);
		nodes[cur].push(tmp);
		sum += tmp;
	}
	let res: i32 = n-sum-1;
	if res!=0 {nodes[cur].push(res)};
	return sum+1;
}

fn run() {
    solve();
}

