fn dfs(v: usize, p: usize, t: &Vec<Vec<usize>>, mem: &mut Vec<HashMap<usize, usize>>) -> usize {
    let mut size = 1;
    for &c in &t[v] {
        if c == p {
            continue;
        }
        let sub = dfs(c, v, t, mem);
        mem[v].insert(c, sub);
        size += sub;
    }
    size
}

fn dfs2(v: usize, p: usize, t: &Vec<Vec<usize>>, mem: &mut Vec<HashMap<usize, usize>>) {
    let n = t.len();
    for &c in &t[v] {
        if c == p {
            continue;
        }
        let sub = *mem[v].get(&c).unwrap();
        mem[c].insert(v, n - sub);
        dfs2(c, v, t, mem);
    }
}

fn pow_m(n: usize, mut p: usize, d: usize) -> usize {
    let mut r = n;
    let mut ret = 1;
    while p > 0 {
        if p % 2 == 0 {
            r = r * r % d;
            p /= 2;
        } else {
            ret = ret * r % d;
            p -= 1;
        }
    }
    ret
}

fn inv_m(n: usize, d: usize) -> usize {
    pow_m(n, d - 2, d)
}

