macro_rules! parse {
    ($it: ident ) => {};
    ($it: ident, ) => {};
    ($it: ident, $var:ident : $t:tt $($r:tt)*) => {
        let $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
    ($it: ident, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = parse_val!($it, $t);
        parse!($it $($r)*);
    };
}

#[allow(unused_macros)]
macro_rules! parse_val {
    ($it: ident, [$t:tt; $len:expr]) => {
        (0..$len).map(|_| parse_val!($it, $t)).collect::<Vec<_>>();
    };
    ($it: ident, ($($t: ty),*)) => {
        ($(parse_val!($it, $t)),*)
    };
    ($it: ident, $t: ty) => {
        $it.next().unwrap().parse::<$t>().unwrap()
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, n: usize);
    let mut g = vec![vec![]; n];
    for _ in 0..(n - 1) {
        parse!(it, a: usize, b: usize);
        g[a - 1].push(b - 1);
        g[b - 1].push(a - 1);
    }
    let mut stack = vec![];
    stack.push((0, 0));
    let mut ret = Mint(0);
    dfs(&g, 0, 0, &mut ret, n);
    ret -= 1;
    ret /= Mint(2).pow(n);
    ret += 1;
    ret -= Mint(n) / 2;
    println!("{}", ret);
}

fn dfs(g: &Vec<Vec<usize>>, u: usize, p: usize, ret: &mut Mint<usize>, n: usize) -> usize {
    let mut a = 1;
    for &v in g[u].iter() {
        if v != p {
            a += dfs(g, v, u, ret, n);
        }
    }
    *ret += (Mint(2).pow(a) - 1) * (Mint(2).pow(n - a) - 1);
    a
}

