fn solve() {
    let out = stdout();
    let mut out = BufWriter::new(out.lock());
    input!{
        n:usize,
        ab:[(usize,usize);n-1],
    }
    let mut rr = ReRooting::<F>::new(n);
    for (a,b) in ab {
        rr.connect(a-1, b-1, 1, 1);
    }
    rr.build();
    let mut totok: Mod = 0.into();
    let mut two: Mod = 2.into();
    for u in 0..n {
        let mut adj = vec![];
        for i in 0..rr.g[u].len() {
            let e = rr.g[u][i];
            adj.push(e.dp as i64);
        }
        if adj.len() < 2 {
            continue;
        }
        let mut ng: Mod = 0.into();
        // 全白
        ng += 1;
        // 一つ黒含みで他全白
        for i in 0..adj.len() {
            // 全通りから全白を抜く
            ng += two.pow(adj[i]) - 1;
        }
        totok += two.pow((n-1) as i64) - ng;
    }
    // dbg!(totok);

    // 2^n x x = totok (mod M)
    let y = mod_inverse(two.pow(n as i64).0, 1_000_000_007);
    let x = totok * y;
    println!("{}", x);
}
