fn main() {
    let n = read::<usize>();
    let mut edges = vec![vec![]; n];
    for i in 0..n - 1 {
        let v = read_vec::<usize>();
        let (a, b) = (v[0] - 1, v[1] - 1);
        edges[a].push(b);
        edges[b].push(a);
    }

    let mut tree: Vec<Vec<usize>> = vec![Vec::new(); n];
    let mut parent_dict: HashMap<usize, usize> = HashMap::new();
    make_tree(0, n, &edges, &mut tree, &mut parent_dict);
    let mut topological_sorted_indexes = vec![0];
    topological_dfs(0, &tree, &mut topological_sorted_indexes);

    let mut num_childs = vec![1i64; n];
    for &ti in topological_sorted_indexes.iter().rev() {
        for &ci in tree[ti].iter() {
            num_childs[ti] += num_childs[ci];
        }
    }
    let mut denom = Modulo::new(0);
    for ti in 0..n {
        let mut elements = tree[ti]
            .iter()
            .map(|&ci| num_childs[ci])
            .collect::<Vec<_>>();
        if ti != 0 {
            let from_parent = n as i64 - 1 - tree[ti].iter().map(|&ci| num_childs[ci]).sum::<i64>();
            elements.push(from_parent);
        }
        denom += Modulo::new(2).pow(n as i64 - 1);
        for num in elements {
            denom -= Modulo::new(2).pow(num) - 1;
        }
        denom -= 1;
    }
    let norm = Modulo::new(2).pow(n as i64).inv();
    println!("{}", denom * norm);
}

fn extgcd(a: i64, b: i64, x: &mut i64, y: &mut i64) -> i64 {
    let mut d = a;
    if b == 0 {
        *x = 1;
        *y = 0;
    } else {
        d = extgcd(b, a % b, y, x);
        *y -= (a / b) * (*x);
    }
    return d;
}

fn mod_inverse(a: i64, m: i64) -> i64 {
    let mut x: i64 = 0;
    let mut y: i64 = 0;
    extgcd(a, m, &mut x, &mut y);
    (m + x % m) % m
}

fn make_tree(
    cur_idx: usize,
    parent_idx: usize,
    edges: &Vec<Vec<usize>>,
    tree: &mut Vec<Vec<usize>>,
    parent_dict: &mut HashMap<usize, usize>,
) {
    for child_idx in edges[cur_idx].iter() {
        if *child_idx == parent_idx {
            continue;
        }
        tree[cur_idx].push(*child_idx);
        parent_dict.insert(*child_idx, cur_idx);
        make_tree(*child_idx, cur_idx, edges, tree, parent_dict);
    }
}

fn topological_dfs(cur_idx: usize, tree: &Vec<Vec<usize>>, result: &mut Vec<usize>) {
    for child_idx in tree[cur_idx].iter() {
        result.push(*child_idx);
        topological_dfs(*child_idx, tree, result);
    }
}

