use self::mod_int::ModInt;
use std::collections::VecDeque;

const MOD: usize = 1e9 as usize + 7;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let mut graph = vec![vec![]; n];
    for _ in 1..n {
        let a = sc.read::<usize>() - 1;
        let b = sc.read::<usize>() - 1;
        graph[a].push(b);
        graph[b].push(a);
    }

    let mut ans = vec![ModInt(0); n];
    dfs(0, 0, &graph, &mut ans);
    let mut sum = ModInt(0);
    for i in 0..n {
        sum += ans[i];
    }
    println!("{}", sum.0);
}

fn dfs(v: usize, p: usize, graph: &Vec<Vec<usize>>, ans: &mut Vec<ModInt<usize>>) -> usize {
    let n = graph.len();
    let mut sum = 0;
    let mut branches = vec![];
    for &next in graph[v].iter() {
        if p == next {
            continue;
        }
        let child = dfs(next, v, graph, ans);
        sum += child;
        branches.push(child);
    }

    let upper = n - sum - 1;
    if upper > 0 {
        branches.push(upper);
    }

    let all_white = ModInt(1) / ModInt(2).pow(n - 1);
    let mut one_black = ModInt(0);
    for &branch in branches.iter() {
        let white = ModInt(1) / ModInt(2).pow(branch);
        let black = ModInt(1) - white;
        one_black += all_white / white * black;
    }

    ans[v] = ModInt(1) - all_white - one_black;
    ans[v] /= 2;
    sum + 1
}

