pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

use std::cell::Cell;
use std::io::BufRead;

const MOD: i64 = 1000000007;

#[derive(Debug)]
struct Graph {
    n: usize,
    es: Vec<Vec<usize>>,
    p2: Vec<i64>,
    total: Cell<i64>,
}

impl Graph {
    fn new(n: usize) -> Graph {
        let mut p2 = vec![];
        let mut x = 1;
        for _ in 0..n + 1 {
            p2.push(x);
            x = x * 2 % MOD;
        }
        Graph {
            n: n,
            es: vec![vec![]; n],
            p2: p2,
            total: Cell::new(0),
        }
    }

    fn dfs(&self, u: usize, p: usize) -> usize {
        let mut chd = vec![];
        let mut tsz = 1;
        for v in &self.es[u] {
            if *v == p { continue; }
            let sz = self.dfs(*v, u);
            chd.push(sz);
            tsz += sz;
        }

        if u != p {
            chd.push(self.n - tsz);
        }

        if chd.len() > 1 {
            let mut sum = 1i64;
            for sz in &chd {
                sum += self.p2[*sz] - 1;
            }
            self.total.set((self.total.get() + (self.p2[self.n - 1] - sum)) % MOD);
        }
        tsz
    }
}

fn read_line(mut buf: &mut String) -> &str {
    buf.clear();
    std::io::stdin().read_line(&mut buf).unwrap();
    buf.trim_right()
}

fn main() {
    let mut buf = String::new();
    let n: usize = read_line(&mut buf).parse::<usize>().unwrap();

    let mut g = Graph::new(n);
    for _ in 0..n - 1 {
        let mut it = read_line(&mut buf).split_whitespace().map(|x| x.parse::<usize>().unwrap() - 1);
        let a = it.next().unwrap();
        let b = it.next().unwrap();
        g.es[a].push(b);
        g.es[b].push(a);
    }
    g.dfs(0, 0);

    let mut ans = g.total.get();
    for _ in 0..n {
        ans = ans * ((MOD + 1) / 2) % MOD;
    }
    ans = (ans + MOD) % MOD;
    println!("{}", ans);
}

use std::cell::Cell;

const MOD: i32 = 1000000007;

fn main() {
	let mut s = String::new();
	use std::io::Read;
	std::io::stdin().read_to_string(&mut s).unwrap();
	let mut s = s.split_whitespace();
	let n: usize = s.next().unwrap().parse().unwrap();
	let mut edges = vec![vec![]; n];
	for _ in 0..n - 1 {
		let a = s.next().unwrap().parse::<usize>().unwrap() - 1;
		let b = s.next().unwrap().parse::<usize>().unwrap() - 1;
		edges[a].push(b);
		edges[b].push(a);
	}
	let tree = Tree::new(edges);
	tree.dfs(0, std::usize::MAX);
	let y = tree.calc(0, std::usize::MAX);
	let x = mod_pow(tree.two_power[n] as i64, MOD as u32 - 2, MOD as i64);
	println!("{}", y as i64 * x % MOD as i64);
}

struct Tree {
	edges: Vec<Vec<usize>>,
	children: Vec<Cell<u32>>,
	two_power: Vec<i32>,
}

impl Tree {
	fn new(edges: Vec<Vec<usize>>) -> Tree {
		let n = edges.len();
		let pow: Vec<_> = (0..n + 1)
			.scan(1, |s, _| {
				let a = *s;
				*s = a * 2 % MOD;
				Some(a)
			})
			.collect();
		Tree { edges: edges, children: vec![Cell::new(0); n], two_power: pow }
	}

	fn dfs(&self, v: usize, p: usize) -> u32 {
		let mut c = 0;
		for e in self.edges[v].iter() {
			if *e == p {
				continue;
			}
			c += self.dfs(*e, v);
		}
		self.children[v].set(c);
		c + 1
	}

	fn calc(&self, v: usize, p: usize) -> i32 {
		let mut r = 0;
		let mut pat = 0;
		let mut csum = 0;
		for e in self.edges[v].iter() {
			if *e == p {
				continue;
			}
			r = (r + self.calc(*e, v)) % MOD;
			let c = self.children[*e].get() + 1;
			pat = (pat + self.two_power[c as usize] - 1) % MOD;
			csum += c;
		}
		let n = self.edges.len();
		pat = (pat + self.two_power[n - 1 - csum as usize] - 1 + 1) % MOD;
		pat = (self.two_power[n - 1] + MOD - pat) % MOD;
		(r + pat) % MOD
	}
}

fn mod_pow(a: i64, n: u32, m: i64) -> i64 {
	let mut r = 1;
	let mut a = a;
	let mut n = n;
	while n > 0 {
		if n & 1 != 0 {
			r = r * a % m;
		}
		a = a * a % m;
		n >>= 1;
	}
	r
}

