struct Tree {
    n: usize,
    neighbors: Vec<Vec<usize>>,
    visited: Vec<bool>,
    counts: Vec<Vec<usize>>,
}

impl Tree {
    fn new(n: usize) -> Self {
        Tree {
            n: n,
            neighbors: vec![Vec::new(); n],
            visited: vec![false; n],
            counts: vec![Vec::new(); n],
        }
    }
    fn add_edge(&mut self, i: usize, j: usize) {
        self.neighbors[i].push(j);
        self.neighbors[j].push(i);
    }
    fn visit(&mut self, i: usize) -> usize {
        if self.visited[i] {
            return 0;
        }
        self.visited[i] = true;
        let mut ans = 1;
        for j in 0..self.neighbors[i].len() {
            let i1 = self.neighbors[i][j];
            let k = self.visit(i1);
            if k > 0 {
                self.counts[i].push(k);
                ans += k;
            }
        }
        self.counts[i].push(self.n - ans);
        ans
    }
    fn solve(&mut self) -> usize {
        self.visit(0);
        let power_of_two: Vec<usize> = {
            let mut power_of_two = vec![0; self.n + 1];
            power_of_two[0] = 1;
            for i in 0..self.n {
                power_of_two[i + 1] = power_of_two[i] * 2 % MODULO;
            }
            power_of_two
        };
        let mut ans = 0;
        for i in 0..self.n {
            let l = self.counts[i].len();
            if l == 1 {
                continue;
            }
            ans = (ans + power_of_two[self.n - 1]) % MODULO;
            for j in 0..l {
                let k = self.counts[i][j];
                ans = (ans + neg(power_of_two[k])) % MODULO;
            }
            ans = (ans + l - 1) % MODULO;
        }
        ans * inverse(power_of_two[self.n]) % MODULO
    }
}

const MODULO: usize = 1_000_000_007;

fn power(mut base: usize, mut exponent: usize) -> usize {
    let mut prod = 1;
    while exponent != 0 {
        if exponent & 1 == 1 {
            prod = prod * base % MODULO;
        }
        base = base * base % MODULO;
        exponent >>= 1;
    }
    prod
}

fn inverse(x: usize) -> usize {
    power(x, MODULO - 2)
}

fn neg(x: usize) -> usize {
    if x == 0 {
        0
    } else {
        MODULO - x
    }
}

use std::cell::Cell;
use std::io::BufRead;

const MOD: i64 = 1000000007;

#[derive(Debug)]
struct Graph {
    n: usize,
    es: Vec<Vec<usize>>,
    p2: Vec<i64>,
    total: Cell<i64>,
}

impl Graph {
    fn new(n: usize) -> Graph {
        let mut p2 = vec![];
        let mut x = 1;
        for _ in 0..n + 1 {
            p2.push(x);
            x = x * 2 % MOD;
        }
        Graph {
            n,
            es: vec![vec![]; n],
            p2,
            total: Cell::new(0),
        }
    }

    fn dfs(&self, u: usize, p: usize) -> usize {
        let mut chd = vec![];
        let mut tsz = 1;
        for v in &self.es[u] {
            if *v == p { continue; }
            let sz = self.dfs(*v, u);
            chd.push(sz);
            tsz += sz;
        }

        if u != p {
            chd.push(self.n - tsz);
        }

        if chd.len() > 1 {
            let mut sum = 1i64;
            for sz in &chd {
                sum += self.p2[*sz] - 1;
            }
            self.total.set((self.total.get() + (self.p2[self.n - 1] - sum)) % MOD);
        }
        tsz
    }
}

