struct DFS {
    n: usize,
    g: Vec<Vec<usize>>,
    dp: Vec<Vec<usize>>,
}

impl DFS {
    fn new(n: usize) -> DFS {
        DFS {
            n,
            g: vec![Vec::new(); n],
            dp: vec![Vec::new(); n],
        }
    }

    fn add_edge(&mut self, from: usize, to: usize) {
        self.g[from].push(to);
        self.dp[from].push(to);
    }

    fn search(&mut self, par: usize, from: usize) -> usize {
        let mut sum = 0;
        let mut par_i = !0;
        for (i, &to) in self.g[from].clone().iter().enumerate() {
            if to == par {
                par_i = i;
                continue;
            }
            self.dp[from][i] = self.search(from, to);
            sum += self.dp[from][i];
        }
        if par_i != !0 {
            self.dp[from][par_i] = self.n - (sum + 1);
        }
        sum + 1
    }
}

fn main() {
    const MOD: usize = 1_000_000_007;

    let n: usize = {
        let mut buf = String::new();
        std::io::stdin().read_line(&mut buf).unwrap();
        buf.trim_end().parse().unwrap()
    };

    let mut dfs = DFS::new(n);
    for _ in 0..(n - 1) {
        let (a, b) = {
            let mut buf = String::new();
            std::io::stdin().read_line(&mut buf).unwrap();
            let mut iter = buf.split_whitespace();
            (
                iter.next().unwrap().parse::<usize>().unwrap() - 1,
                iter.next().unwrap().parse::<usize>().unwrap() - 1,
            )
        };

        dfs.add_edge(a, b);
        dfs.add_edge(b, a);
    }
    dfs.search(!0, 0);

    let pow = |mut a, mut n| {
        let mut res = 1;
        while n > 0 {
            if n & 1 > 0 {
                res = res * a % MOD;
            }
            a = a * a % MOD;
            n >>= 1;
        }
        res
    };

    let mut ans = 0;
    for i in 0..n {
        let mut res = 1;
        res = (res + MOD - pow(pow(2, n - 1), MOD - 2)) % MOD;
        let mut sum = 0;
        for &x in dfs.dp[i].iter() {
            let p = pow(pow(2, n - 1 - x), MOD - 2);
            let q = (1 + MOD - pow(pow(2, x), MOD - 2)) % MOD;
            sum = (sum + (p * q % MOD)) % MOD;
        }
        res = (res + MOD - sum) % MOD;
        ans = (ans + res * pow(2, MOD - 2)) % MOD;
    }
    println!("{}", ans);
}

