pub mod modular {
    const M: i64 = 1000000007;

    #[derive(Debug, Clone, Copy, Default, PartialOrd, Ord, PartialEq, Eq)]
    pub struct Mod(i64);

    impl ::std::fmt::Display for Mod {
        fn fmt(&self, f: &mut ::std::fmt::Formatter) -> ::std::fmt::Result {
            write!(f, "{}", self.0)
        }
    }

    impl Mod {
        pub fn new(v: i64) -> Mod {
            Mod(v % M)
        }

        pub fn pow(self, mut r: i64) -> Mod {
            let mut k = self;
            let mut ret = 1.into();

            while r > 0 {
                if r % 2 != 0 {
                    ret = ret * k;
                }
                r /= 2;
                k = k * k;
            }

            ret
        }

        // This requires M is prime
        pub fn recip(self) -> Mod {
            self.pow(M - 2)
        }
    }

    use std::ops::*;

    impl<T: Into<Mod>> Add<T> for Mod {
        type Output = Mod;
        fn add(self, rhs: T) -> Self::Output {
            Mod::new(self.0 + rhs.into().0)
        }
    }
    impl<T: Into<Mod>> AddAssign<T> for Mod {
        fn add_assign(&mut self, rhs: T) {
            *self = *self + rhs;
        }
    }

    impl<T: Into<Mod>> Sub<T> for Mod {
        type Output = Mod;
        fn sub(self, rhs: T) -> Self::Output {
            Mod::new(self.0 - rhs.into().0 + M)
        }
    }
    impl<T: Into<Mod>> SubAssign<T> for Mod {
        fn sub_assign(&mut self, rhs: T) {
            *self = *self - rhs;
        }
    }

    impl<T: Into<Mod>> Mul<T> for Mod {
        type Output = Mod;
        fn mul(self, rhs: T) -> Self::Output {
            Mod::new(self.0 * rhs.into().0)
        }
    }
    impl<T: Into<Mod>> MulAssign<T> for Mod {
        fn mul_assign(&mut self, rhs: T) {
            *self = *self * rhs;
        }
    }

    impl<T: Into<Mod>> Div<T> for Mod {
        type Output = Mod;
        fn div(self, rhs: T) -> Self::Output {
            self * rhs.into().recip()
        }
    }
    impl<T: Into<Mod>> DivAssign<T> for Mod {
        fn div_assign(&mut self, rhs: T) {
            *self = *self / rhs;
        }
    }

    impl Neg for Mod {
        type Output = Mod;
        fn neg(self) -> Self::Output {
            Mod(0) - self
        }
    }

    impl<T: ::std::convert::Into<i64>> ::std::convert::From<T> for Mod {
        fn from(v: T) -> Self {
            Mod::new(v.into())
        }
    }
}

use modular::Mod;

fn main() {
    input! {
        n: usize,
        es: [(usize1, usize1); n-1],
    }

    let mut g = vec![vec![]; n];

    for (u, v) in es.into_iter() {
        g[u].push(v);
        g[v].push(u);
    }

    let mut ans = Mod::new(0);
    solve(0, None, &g, &mut ans);

    println!("{}", ans);
}

fn solve(cur: usize, prev: Option<usize>, g: &Vec<Vec<usize>>, ans: &mut Mod) -> usize {
    let n = g.len();
    let mut ret = 0;
    let mut one_black_prec = Mod::new(0);
    let mut all_white_prec = Mod::new(1);
    let mut csum = 0;

    let mut css = vec![];

    for &next in g[cur].iter() {
        if Some(next) == prev {
            continue;
        }

        let csize = solve(next, Some(cur), g, ans);
        css.push(csize);
        csum += csize;
    }

    if prev != None {
        let csize = n - 1 - csum;
        css.push(csize);
    }

    for &csize in css.iter() {
        all_white_prec *= (Mod::new(1) / Mod::new(2)).pow(csize as i64);
    }

    for &csize in css.iter() {
        let wp = (Mod::new(1) / Mod::new(2)).pow(csize as i64);
        one_black_prec += all_white_prec / wp * (Mod::new(1) - wp);
    }

    if css.len() > 1 {
        *ans += (Mod::new(1) - (all_white_prec + one_black_prec)) / Mod::new(2);
    }

    csum + 1
}
